def build_epk_substrate_mode_gap_audit(
    *,
    epk_heteromeric_peptide_acceptor_identity_probe: dict[str, Any],
    epk_heteromeric_source_expansion_peptide_role_axis_audit: dict[str, Any],
    epk_5hvk_protein_substrate_axis_generalization_audit: dict[str, Any],
    epk_heteromeric_peptide_external_hard_negative_probe: dict[str, Any],
) -> dict[str, Any]:
    """Summarize why peptide and protein-substrate ePK modes remain unmerged."""

    peptide_meta = epk_heteromeric_peptide_acceptor_identity_probe.get(
        "metadata", {}
    )
    if not isinstance(peptide_meta, dict):
        peptide_meta = {}
    source_expansion_meta = (
        epk_heteromeric_source_expansion_peptide_role_axis_audit.get(
            "metadata", {}
        )
    )
    if not isinstance(source_expansion_meta, dict):
        source_expansion_meta = {}
    protein_meta = epk_5hvk_protein_substrate_axis_generalization_audit.get(
        "metadata", {}
    )
    if not isinstance(protein_meta, dict):
        protein_meta = {}
    external_meta = epk_heteromeric_peptide_external_hard_negative_probe.get(
        "metadata", {}
    )
    if not isinstance(external_meta, dict):
        external_meta = {}

    target_fingerprint_id = str(
        peptide_meta.get("target_fingerprint_id")
        or source_expansion_meta.get("target_fingerprint_id")
        or protein_meta.get("target_fingerprint_id")
        or external_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    current_peptide_hit_ids = _sorted_strings(
        row.get("pdb_id")
        for row in epk_heteromeric_peptide_acceptor_identity_probe.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and row.get("row_type") == "heteromeric_peptide_acceptor_identity_candidate"
        and bool(row.get("peptide_like_acceptor_identity_rule_hit"))
    )
    current_nonaccepted_false_hit_count = int(
        peptide_meta.get("nonaccepted_control_false_hit_count") or 0
    )
    current_sibling_false_hit_count = int(
        peptide_meta.get("sibling_control_false_hit_count") or 0
    )

    source_expansion_hit_ids = _sorted_strings(
        source_expansion_meta.get("source_valid_expansion_peptide_role_hit_pdb_ids")
        or []
    )
    source_expansion_false_hit_count = int(
        source_expansion_meta.get(
            "nonpositive_source_expansion_control_false_hit_count"
        )
        or 0
    )
    source_expansion_general_ready_count = int(
        source_expansion_meta.get("general_substrate_identity_ready_count") or 0
    )

    protein_positive_count = int(
        protein_meta.get("combined_protein_substrate_positive_like_count") or 0
    )
    protein_feature_admissible = bool(
        protein_meta.get("feature_admissible_for_production_scoring")
    )
    protein_sibling_false_hit_count = int(
        protein_meta.get("sibling_control_false_hit_count") or 0
    )
    protein_external_non_abstention_count = int(
        protein_meta.get("imported_external_hard_negative_non_abstention_count")
        or 0
    )
    external_non_abstention_count = int(
        external_meta.get(
            "review_only_external_hard_negative_feature_non_abstention_count"
        )
        or 0
    )

    combined_peptide_hit_ids = _sorted_strings(
        [*current_peptide_hit_ids, *source_expansion_hit_ids]
    )
    combined_peptide_false_hit_count = (
        current_nonaccepted_false_hit_count
        + current_sibling_false_hit_count
        + source_expansion_false_hit_count
    )
    peptide_modes_pass_current_controls = (
        len(combined_peptide_hit_ids) >= 5
        and combined_peptide_false_hit_count == 0
        and external_non_abstention_count == 0
    )
    protein_mode_passes_current_controls = (
        protein_positive_count >= 3
        and protein_sibling_false_hit_count == 0
        and protein_external_non_abstention_count == 0
    )
    unified_source_free_substrate_identity_ready = (
        source_expansion_general_ready_count > 0 and protein_feature_admissible
    )
    audit_status = (
        "passes_review_only_modes_but_unified_substrate_identity_missing"
        if peptide_modes_pass_current_controls
        and protein_mode_passes_current_controls
        and not unified_source_free_substrate_identity_ready
        else "blocked_review_only_substrate_mode_controls_incomplete"
    )

    rows = [
        {
            "row_type": "peptide_mode_summary",
            "review_only": True,
            "pdb_ids": combined_peptide_hit_ids,
            "current_source_pdb_ids": current_peptide_hit_ids,
            "source_expansion_pdb_ids": source_expansion_hit_ids,
            "positive_hit_count": len(combined_peptide_hit_ids),
            "false_hit_count": combined_peptide_false_hit_count,
            "external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "mode_passes_current_controls": peptide_modes_pass_current_controls,
            "feature_admissible_for_production_scoring": False,
        },
        {
            "row_type": "protein_substrate_mode_summary",
            "review_only": True,
            "positive_like_count": protein_positive_count,
            "sibling_control_false_hit_count": protein_sibling_false_hit_count,
            "external_hard_negative_non_abstention_count": (
                protein_external_non_abstention_count
            ),
            "mode_passes_current_controls": protein_mode_passes_current_controls,
            "feature_admissible_for_production_scoring": protein_feature_admissible,
        },
        {
            "row_type": "substrate_mode_gap_decision",
            "review_only": True,
            "peptide_modes_pass_current_controls": (
                peptide_modes_pass_current_controls
            ),
            "protein_mode_passes_current_controls": (
                protein_mode_passes_current_controls
            ),
            "unified_source_free_substrate_identity_ready": (
                unified_source_free_substrate_identity_ready
            ),
            "decision": audit_status,
            "blocker": (
                "peptide_and_protein_substrate_modes_lack_unified_source_free_identity"
            ),
        },
    ]

    return {
        "metadata": {
            "method": "epk_substrate_mode_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_peptide_acceptor_identity_probe_method": (
                peptide_meta.get("method")
            ),
            "source_epk_heteromeric_source_expansion_peptide_role_axis_audit_method": (
                source_expansion_meta.get("method")
            ),
            "source_epk_5hvk_protein_substrate_axis_generalization_audit_method": (
                protein_meta.get("method")
            ),
            "source_epk_heteromeric_peptide_external_hard_negative_probe_method": (
                external_meta.get("method")
            ),
            "substrate_mode_gap_status": audit_status,
            "current_peptide_mode_positive_pdb_ids": current_peptide_hit_ids,
            "source_expansion_peptide_mode_positive_pdb_ids": (
                source_expansion_hit_ids
            ),
            "combined_peptide_mode_positive_pdb_ids": combined_peptide_hit_ids,
            "combined_peptide_mode_positive_count": len(combined_peptide_hit_ids),
            "combined_peptide_mode_false_hit_count": (
                combined_peptide_false_hit_count
            ),
            "peptide_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "protein_substrate_mode_positive_like_count": protein_positive_count,
            "protein_substrate_sibling_false_hit_count": (
                protein_sibling_false_hit_count
            ),
            "protein_substrate_external_hard_negative_non_abstention_count": (
                protein_external_non_abstention_count
            ),
            "peptide_modes_pass_current_controls": (
                peptide_modes_pass_current_controls
            ),
            "protein_mode_passes_current_controls": (
                protein_mode_passes_current_controls
            ),
            "unified_source_free_substrate_identity_ready": (
                unified_source_free_substrate_identity_ready
            ),
            "source_expansion_general_substrate_identity_ready_count": (
                source_expansion_general_ready_count
            ),
            "protein_substrate_feature_admissible_for_production_scoring": (
                protein_feature_admissible
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "next_actions": [
                "design a unified source-free substrate identity rule spanning peptide and protein-substrate modes",
                "keep threshold selection closed until the unified mode rule and sibling controls are calibrated",
                "run the real external hard-negative scored re-audit only after an ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Substrate-mode gap audit is review-only; it does not score "
                "ePK, select thresholds, edit registries, or import labels."
            )
        ],
    }


def build_epk_unified_substrate_identity_rule_probe(
    *,
    epk_substrate_mode_gap_audit: dict[str, Any],
    epk_heteromeric_peptide_acceptor_identity_probe: dict[str, Any],
    epk_heteromeric_source_expansion_peptide_role_axis_audit: dict[str, Any],
    epk_protein_substrate_acceptor_candidate_audit: dict[str, Any],
    epk_heteromeric_chain_topology_signal_audit: dict[str, Any],
    epk_heteromeric_peptide_external_hard_negative_probe: dict[str, Any],
) -> dict[str, Any]:
    """Probe one source-free substrate-identity rule across current ePK modes."""

    substrate_meta = epk_substrate_mode_gap_audit.get("metadata", {})
    if not isinstance(substrate_meta, dict):
        substrate_meta = {}
    peptide_meta = epk_heteromeric_peptide_acceptor_identity_probe.get(
        "metadata", {}
    )
    if not isinstance(peptide_meta, dict):
        peptide_meta = {}
    source_expansion_meta = (
        epk_heteromeric_source_expansion_peptide_role_axis_audit.get(
            "metadata", {}
        )
    )
    if not isinstance(source_expansion_meta, dict):
        source_expansion_meta = {}
    protein_meta = epk_protein_substrate_acceptor_candidate_audit.get(
        "metadata", {}
    )
    if not isinstance(protein_meta, dict):
        protein_meta = {}
    topology_meta = epk_heteromeric_chain_topology_signal_audit.get(
        "metadata", {}
    )
    if not isinstance(topology_meta, dict):
        topology_meta = {}
    external_meta = epk_heteromeric_peptide_external_hard_negative_probe.get(
        "metadata", {}
    )
    if not isinstance(external_meta, dict):
        external_meta = {}

    target_fingerprint_id = str(
        substrate_meta.get("target_fingerprint_id")
        or peptide_meta.get("target_fingerprint_id")
        or source_expansion_meta.get("target_fingerprint_id")
        or protein_meta.get("target_fingerprint_id")
        or topology_meta.get("target_fingerprint_id")
        or external_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    rule_id = "epk_unified_polymer_substrate_identity_rule_v0_review_only"
    rows: list[dict[str, Any]] = []
    positive_hit_pdb_ids: list[str] = []
    peptide_positive_pdb_ids: list[str] = []
    source_expansion_positive_pdb_ids: list[str] = []
    protein_positive_pdb_ids: list[str] = []
    heteromeric_protein_positive_pdb_ids: list[str] = []
    control_false_hit_pdb_ids: list[str] = []
    ligand_analog_excluded_entry_ids: list[str] = []
    external_by_entry_id: dict[str, dict[str, Any]] = {}
    source_row_type_counts: Counter[str] = Counter()

    def _nearest_gamma_distance_from_row(source_row: dict[str, Any]) -> Any:
        for key in (
            "nearest_gamma_distance_angstrom",
            "nearest_gamma_to_candidate_acceptor_distance_angstrom",
            "source_valid_5hvk_distance_angstrom",
        ):
            if source_row.get(key) is not None:
                return source_row.get(key)
        for nested_key in ("hit_evaluations", "heteromeric_candidate_hits"):
            nested_rows = source_row.get(nested_key, [])
            if not isinstance(nested_rows, list):
                continue
            for nested_row in nested_rows:
                if not isinstance(nested_row, dict):
                    continue
                for key in (
                    "nearest_gamma_distance_angstrom",
                    "source_recorded_nearest_gamma_distance_angstrom",
                ):
                    if nested_row.get(key) is not None:
                        return nested_row.get(key)
        return None

    def _add_probe_row(
        *,
        source_row: dict[str, Any],
        row_type: str,
        probe_decision: str,
        rule_hit: bool,
        mode: str,
        control_family_id: str | None = None,
    ) -> None:
        source_row_type_counts[str(source_row.get("row_type") or row_type)] += 1
        pdb_id = source_row.get("pdb_id")
        rows.append(
            {
                "row_type": row_type,
                "source_row_type": source_row.get("row_type"),
                "source_method": source_row.get("source_method"),
                "entry_id": source_row.get("entry_id"),
                "pdb_id": pdb_id,
                "family_id": control_family_id or source_row.get("family_id"),
                "source_pair_id": source_row.get("source_pair_id"),
                "substrate_mode": mode,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "rule_id": rule_id,
                "unified_substrate_identity_rule_hit": rule_hit,
                "unified_substrate_identity_probe_decision": probe_decision,
                "candidate_threshold_angstrom": (
                    source_row.get("candidate_threshold_angstrom")
                    or substrate_meta.get("candidate_threshold_angstrom")
                ),
                "candidate_acceptor_residue_code": source_row.get(
                    "candidate_acceptor_residue_code"
                ),
                "candidate_acceptor_chain_name": source_row.get(
                    "candidate_acceptor_chain_name"
                ),
                "nearest_gamma_to_acceptor_distance_angstrom": (
                    _nearest_gamma_distance_from_row(source_row)
                ),
                "acceptor_chain_lacks_local_nucleotide_or_metal": (
                    source_row.get("acceptor_chain_lacks_local_nucleotide_or_metal")
                ),
                "peptide_like_acceptor_chain": source_row.get(
                    "peptide_like_acceptor_chain"
                ),
                "non_catalytic_chain_acceptor": source_row.get(
                    "non_catalytic_chain_acceptor"
                ),
                "heteromeric_chain_entity_signal_hit": source_row.get(
                    "heteromeric_chain_entity_signal_hit"
                ),
                "ligand_analog_acceptor": bool(
                    source_row.get("ligand_analog_acceptor")
                ),
                "source_feature_decision": (
                    source_row.get("peptide_acceptor_identity_rule_status")
                    or source_row.get("source_free_peptide_role_axis_rule_status")
                    or source_row.get("feature_audit_decision")
                    or source_row.get("known_review_context_class")
                ),
                "production_scoring_admissible": False,
                "ready_for_label_import": False,
                "ready_for_production_scoring": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "rule_is_review_only_not_calibrated_scorer",
                    "broader_substrate_identity_controls_not_exhaustive",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
                "countable_label_candidate": False,
            }
        )

    for source_row in epk_heteromeric_peptide_acceptor_identity_probe.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        row_type = str(source_row.get("row_type") or "")
        rule_hit = bool(source_row.get("peptide_like_acceptor_identity_rule_hit"))
        pdb_id = str(source_row.get("pdb_id") or "")
        if row_type == "heteromeric_peptide_acceptor_identity_candidate":
            if rule_hit:
                positive_hit_pdb_ids.append(pdb_id)
                peptide_positive_pdb_ids.append(pdb_id)
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_current_peptide_positive",
                probe_decision=(
                    "positive_unified_substrate_identity_hit_review_only"
                    if rule_hit
                    else "positive_unified_substrate_identity_miss_review_only"
                ),
                rule_hit=rule_hit,
                mode="short_peptide_substrate",
            )
        elif row_type in {
            "heteromeric_nonaccepted_peptide_identity_control",
            "sibling_peptide_identity_control",
        }:
            if rule_hit:
                control_false_hit_pdb_ids.append(pdb_id)
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_peptide_control",
                probe_decision=(
                    "control_unified_substrate_identity_false_hit_review_only"
                    if rule_hit
                    else "control_blocked_by_unified_substrate_identity_review_only"
                ),
                rule_hit=rule_hit,
                mode="peptide_mode_control",
                control_family_id=source_row.get("family_id"),
            )

    for source_row in epk_heteromeric_source_expansion_peptide_role_axis_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        row_type = str(source_row.get("row_type") or "")
        rule_hit = bool(source_row.get("source_free_peptide_role_axis_rule_hit"))
        pdb_id = str(source_row.get("pdb_id") or "")
        if row_type == "source_expansion_peptide_role_positive_candidate":
            if rule_hit:
                positive_hit_pdb_ids.append(pdb_id)
                source_expansion_positive_pdb_ids.append(pdb_id)
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_source_expansion_peptide_positive",
                probe_decision=(
                    "positive_unified_substrate_identity_hit_review_only"
                    if rule_hit
                    else "positive_unified_substrate_identity_miss_review_only"
                ),
                rule_hit=rule_hit,
                mode="short_peptide_source_expansion",
            )
        elif row_type == "source_expansion_peptide_role_nonpositive_control":
            if rule_hit:
                control_false_hit_pdb_ids.append(pdb_id)
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_source_expansion_nonpositive_control",
                probe_decision=(
                    "control_unified_substrate_identity_false_hit_review_only"
                    if rule_hit
                    else "control_blocked_by_unified_substrate_identity_review_only"
                ),
                rule_hit=rule_hit,
                mode="source_expansion_nonpositive_control",
            )

    for source_row in epk_protein_substrate_acceptor_candidate_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        source_type = str(source_row.get("row_type") or "")
        entry_id = str(source_row.get("entry_id") or "")
        pdb_id = str(source_row.get("pdb_id") or "")
        rule_hit = bool(source_row.get("candidate_feature_hit")) and bool(
            source_row.get("non_catalytic_chain_acceptor")
        ) and not bool(source_row.get("ligand_analog_acceptor"))
        if source_type == "current_epk_positive_prototype":
            if bool(source_row.get("ligand_analog_acceptor")):
                ligand_analog_excluded_entry_ids.append(entry_id)
                decision = "ligand_analog_positive_excluded_from_unified_identity_rule"
            elif rule_hit:
                positive_hit_pdb_ids.append(pdb_id)
                protein_positive_pdb_ids.append(pdb_id)
                decision = "positive_unified_substrate_identity_hit_review_only"
            else:
                decision = "positive_unified_substrate_identity_miss_review_only"
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_current_protein_substrate_positive",
                probe_decision=decision,
                rule_hit=rule_hit,
                mode="protein_substrate",
            )
        elif source_type == "imported_external_hard_negative":
            external_by_entry_id[entry_id] = {
                "entry_id": entry_id,
                "accession": entry_id.split(":", 1)[-1] if ":" in entry_id else entry_id,
                "source_methods": ["epk_protein_substrate_acceptor_candidate_audit"],
                "feature_non_abstention": rule_hit,
            }
        elif "negative_control" in source_type or "control" in source_type:
            if rule_hit:
                control_false_hit_pdb_ids.append(pdb_id)
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_protein_substrate_control",
                probe_decision=(
                    "control_unified_substrate_identity_false_hit_review_only"
                    if rule_hit
                    else "control_blocked_by_unified_substrate_identity_review_only"
                ),
                rule_hit=rule_hit,
                mode="protein_substrate_control",
                control_family_id=source_row.get("family_id"),
            )

    for source_row in epk_heteromeric_chain_topology_signal_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        if source_row.get("row_type") != "heteromeric_chain_topology_hit_control":
            continue
        review_class = str(source_row.get("known_review_context_class") or "")
        rule_hit = bool(source_row.get("heteromeric_chain_entity_signal_hit"))
        pdb_id = str(source_row.get("pdb_id") or "")
        if review_class == "cross_accession_source_valid_positive_like":
            if rule_hit:
                positive_hit_pdb_ids.append(pdb_id)
                heteromeric_protein_positive_pdb_ids.append(pdb_id)
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_heteromeric_protein_positive",
                probe_decision=(
                    "positive_unified_substrate_identity_hit_review_only"
                    if rule_hit
                    else "positive_unified_substrate_identity_miss_review_only"
                ),
                rule_hit=rule_hit,
                mode="heteromeric_protein_substrate",
            )
        elif review_class:
            if rule_hit:
                control_false_hit_pdb_ids.append(pdb_id)
            _add_probe_row(
                source_row=source_row,
                row_type="unified_identity_heteromeric_topology_control",
                probe_decision=(
                    "control_unified_substrate_identity_false_hit_review_only"
                    if rule_hit
                    else "control_blocked_by_unified_substrate_identity_review_only"
                ),
                rule_hit=rule_hit,
                mode="heteromeric_topology_control",
            )

    for source_row in epk_heteromeric_peptide_external_hard_negative_probe.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        entry_id = str(source_row.get("entry_id") or "")
        if not entry_id:
            continue
        previous = external_by_entry_id.setdefault(
            entry_id,
            {
                "entry_id": entry_id,
                "accession": source_row.get("accession"),
                "source_methods": [],
                "feature_non_abstention": False,
            },
        )
        previous["source_methods"] = _sorted_strings(
            [
                *previous.get("source_methods", []),
                "epk_heteromeric_peptide_external_hard_negative_probe",
            ]
        )
        previous["feature_non_abstention"] = bool(
            previous.get("feature_non_abstention")
        ) or bool(source_row.get("review_only_feature_non_abstention"))

    external_non_abstention_entry_ids: list[str] = []
    for entry_id, external_row in sorted(external_by_entry_id.items()):
        feature_non_abstention = bool(external_row.get("feature_non_abstention"))
        if feature_non_abstention:
            external_non_abstention_entry_ids.append(entry_id)
        rows.append(
            {
                "row_type": "unified_identity_imported_external_hard_negative",
                "entry_id": entry_id,
                "accession": external_row.get("accession"),
                "substrate_mode": "imported_external_hard_negative",
                "source_methods": external_row.get("source_methods", []),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "rule_id": rule_id,
                "unified_substrate_identity_rule_hit": feature_non_abstention,
                "unified_substrate_identity_feature_non_abstention": (
                    feature_non_abstention
                ),
                "unified_substrate_identity_probe_decision": (
                    "external_hard_negative_unified_identity_non_abstention_review_only"
                    if feature_non_abstention
                    else "external_hard_negative_abstain_under_unified_identity_review_only"
                ),
                "production_scoring_admissible": False,
                "ready_for_label_import": False,
                "ready_for_production_scoring": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "countable_label_candidate": False,
                "clean_heldout_performance_claim_permitted": False,
                "remaining_blockers": [
                    "not_a_real_scored_external_reaudit",
                    "threshold_not_calibrated_against_negative_controls",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    positive_hit_pdb_ids = _sorted_strings(positive_hit_pdb_ids)
    control_false_hit_pdb_ids = _sorted_strings(control_false_hit_pdb_ids)
    external_non_abstention_entry_ids = _sorted_strings(
        external_non_abstention_entry_ids
    )
    ligand_analog_excluded_entry_ids = _sorted_strings(
        ligand_analog_excluded_entry_ids
    )
    positive_hit_count = len(positive_hit_pdb_ids)
    control_false_hit_count = len(control_false_hit_pdb_ids)
    external_non_abstention_count = len(external_non_abstention_entry_ids)
    passes_current_controls = (
        positive_hit_count > 0
        and control_false_hit_count == 0
        and external_non_abstention_count == 0
    )
    status = (
        "passes_current_controls_unified_substrate_identity_review_only"
        if passes_current_controls
        else "blocked_review_only_unified_substrate_identity_controls_incomplete"
    )

    return {
        "metadata": {
            "method": "epk_unified_substrate_identity_rule_probe",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "rule_id": rule_id,
            "source_epk_substrate_mode_gap_audit_method": substrate_meta.get(
                "method"
            ),
            "source_epk_heteromeric_peptide_acceptor_identity_probe_method": (
                peptide_meta.get("method")
            ),
            "source_epk_heteromeric_source_expansion_peptide_role_axis_audit_method": (
                source_expansion_meta.get("method")
            ),
            "source_epk_protein_substrate_acceptor_candidate_audit_method": (
                protein_meta.get("method")
            ),
            "source_epk_heteromeric_chain_topology_signal_audit_method": (
                topology_meta.get("method")
            ),
            "source_epk_heteromeric_peptide_external_hard_negative_probe_method": (
                external_meta.get("method")
            ),
            "unified_substrate_identity_rule_status": status,
            "unified_substrate_identity_passes_current_review_controls": (
                passes_current_controls
            ),
            "unified_source_free_substrate_identity_ready_review_only": (
                passes_current_controls
            ),
            "unified_source_free_substrate_identity_production_admissible": False,
            "positive_hit_count": positive_hit_count,
            "positive_hit_pdb_ids": positive_hit_pdb_ids,
            "current_peptide_positive_hit_count": len(
                _sorted_strings(peptide_positive_pdb_ids)
            ),
            "current_peptide_positive_pdb_ids": _sorted_strings(
                peptide_positive_pdb_ids
            ),
            "source_expansion_peptide_positive_hit_count": len(
                _sorted_strings(source_expansion_positive_pdb_ids)
            ),
            "source_expansion_peptide_positive_pdb_ids": _sorted_strings(
                source_expansion_positive_pdb_ids
            ),
            "protein_substrate_positive_hit_count": len(
                _sorted_strings(protein_positive_pdb_ids)
            ),
            "protein_substrate_positive_pdb_ids": _sorted_strings(
                protein_positive_pdb_ids
            ),
            "heteromeric_protein_substrate_positive_hit_count": len(
                _sorted_strings(heteromeric_protein_positive_pdb_ids)
            ),
            "heteromeric_protein_substrate_positive_pdb_ids": _sorted_strings(
                heteromeric_protein_positive_pdb_ids
            ),
            "ligand_analog_excluded_positive_count": len(
                ligand_analog_excluded_entry_ids
            ),
            "ligand_analog_excluded_positive_entry_ids": (
                ligand_analog_excluded_entry_ids
            ),
            "control_false_hit_count": control_false_hit_count,
            "control_false_hit_pdb_ids": control_false_hit_pdb_ids,
            "imported_external_hard_negative_row_count": len(external_by_entry_id),
            "external_hard_negative_feature_non_abstention_count": (
                external_non_abstention_count
            ),
            "external_hard_negative_feature_non_abstention_entry_ids": (
                external_non_abstention_entry_ids
            ),
            "source_row_type_counts": dict(sorted(source_row_type_counts.items())),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "unified_substrate_identity_rule_probe_executed",
            "blocker_not_removed": [
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
                "rule_not_frozen_as_production_scorer",
            ],
            "review_only_rule": (
                "This probe unifies the current peptide and protein-substrate "
                "review surfaces using local polymer substrate topology: "
                "a hydroxyl acceptor on a non-nucleotide/metal acceptor polymer "
                "chain or entity distinct from the nucleotide-associated kinase "
                "polymer. It remains a diagnostic rule, not a calibrated score."
            ),
            "next_actions": [
                "stress the unified substrate-identity rule against broader heteromeric and sibling controls",
                "calibrate thresholds only after the rule is frozen as a real scorer input",
                "run the real external hard-negative scored re-audit only after threshold calibration",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                str(row.get("entry_id") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Unified substrate-identity rule probe is review-only. It does "
                "not score ePK, select thresholds, edit registries, or authorize "
                "label import."
            )
        ],
    }


def build_epk_substrate_acceptor_counteraxis_prototype(
    *,
    epk_review_only_scoring_prototype: dict[str, Any],
    epk_counteraxis_sufficiency_decision: dict[str, Any],
) -> dict[str, Any]:
    """Apply a review-only substrate-acceptor counteraxis rule to ePK rows."""

    prototype_meta = epk_review_only_scoring_prototype.get("metadata", {})
    if not isinstance(prototype_meta, dict):
        prototype_meta = {}
    decision_meta = epk_counteraxis_sufficiency_decision.get("metadata", {})
    if not isinstance(decision_meta, dict):
        decision_meta = {}
    target_fingerprint_id = str(
        prototype_meta.get("target_fingerprint_id")
        or decision_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    rule_id = "epk_substrate_acceptor_counteraxis_rule_v0_review_only"
    rows: list[dict[str, Any]] = []
    rule_decision_counts: Counter[str] = Counter()
    blocked_counteraxis_rows = 0
    positive_like_rows = 0
    external_abstention_rows = 0

    for source_row in epk_review_only_scoring_prototype.get("rows", []) or []:
        if not isinstance(source_row, dict):
            continue
        row_type = str(source_row.get("row_type") or "")
        axis_values = source_row.get("prototype_axis_values", {})
        if not isinstance(axis_values, dict):
            axis_values = {}
        axis_values_copy = dict(axis_values)
        required_positive_axes = [
            "local_adenine_nucleotide_ligand",
            "local_metal_ligand",
            "catalytic_acid_base_residue",
            "gamma_to_acceptor_distance_within_candidate_cutoff",
            "source_supported_hydroxyl_acceptor_identity",
        ]
        missing_required_axes = [
            axis_id
            for axis_id in required_positive_axes
            if int(axis_values.get(axis_id) or 0) != 1
        ]
        if row_type == "current_epk_positive_prototype" and not missing_required_axes:
            rule_decision = "positive_like_acceptor_axis_review_only"
            positive_like_rows += 1
            blocker = None
            rule_hit = "epk_substrate_acceptor_axis_present"
        elif row_type == "current_epk_positive_prototype":
            rule_decision = "abstain_missing_substrate_acceptor_axis_review_only"
            blocker = "current_epk_positive_missing_required_acceptor_axis"
            rule_hit = "missing_required_positive_axis"
        elif row_type == "sibling_homolog_negative_control":
            rule_decision = "blocked_by_non_hydroxyl_phosphohistidine_counteraxis"
            blocker = "ndk_phosphohistidine_axis_not_substrate_hydroxyl_acceptor"
            rule_hit = "phosphohistidine_counteraxis"
            blocked_counteraxis_rows += 1
        elif row_type == "sibling_family_specific_negative_control":
            rule_decision = "blocked_by_sibling_family_acceptor_counteraxis"
            blocker = "sibling_family_control_lacks_source_supported_epk_acceptor_identity"
            rule_hit = "sibling_family_specific_counteraxis"
            blocked_counteraxis_rows += 1
        elif row_type == "imported_external_hard_negative":
            rule_decision = "external_hard_negative_abstain_missing_epk_acceptor_axes"
            blocker = "external_epk_specific_axes_not_materialized"
            rule_hit = "external_abstain_no_epk_axes"
            external_abstention_rows += 1
        else:
            rule_decision = "abstain_unknown_row_type_review_only"
            blocker = "unknown_review_only_row_type"
            rule_hit = "unknown_row_type"
        rule_decision_counts[rule_decision] += 1
        rows.append(
            {
                "row_type": row_type,
                "entry_id": source_row.get("entry_id"),
                "pdb_id": source_row.get("pdb_id"),
                "family_id": source_row.get("family_id"),
                "family_name": source_row.get("family_name"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only")
                ),
                "rule_id": rule_id,
                "source_prototype_decision": source_row.get("prototype_decision"),
                "source_review_only_prototype_score": source_row.get(
                    "review_only_prototype_score"
                ),
                "source_axis_values": axis_values_copy,
                "missing_required_positive_axes": missing_required_axes,
                "counteraxis_rule_hit": rule_hit,
                "counteraxis_rule_decision": rule_decision,
                "counteraxis_blocker": blocker,
                "gamma_geometry_scope": source_row.get("gamma_geometry_scope"),
                "acceptor_context_type": source_row.get("acceptor_context_type"),
                "nearest_gamma_to_acceptor_distance_angstrom": source_row.get(
                    "nearest_gamma_to_hydroxyl_distance_angstrom"
                )
                or source_row.get("nearest_gamma_to_family_acid_base_distance_angstrom")
                or source_row.get("nearest_gamma_to_mapped_histidine_distance_angstrom"),
                "epk_score_computed": False,
                "remaining_blockers": [
                    "rule_is_review_only_not_calibrated_scorer",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    weak_axes = [
        "source_supported_acceptor_axis_is_review_context_not_predictive",
        "external_epk_specific_axes_not_materialized",
        "threshold_not_calibrated_against_negative_controls",
        "label_factory_gate_not_extended_for_epk",
    ]
    return {
        "metadata": {
            "method": "epk_substrate_acceptor_counteraxis_prototype",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_review_only_scoring_prototype_method": (
                prototype_meta.get("method")
            ),
            "source_epk_counteraxis_sufficiency_decision_method": (
                decision_meta.get("method")
            ),
            "rule_id": rule_id,
            "row_count": len(rows),
            "positive_like_acceptor_axis_row_count": positive_like_rows,
            "blocked_counteraxis_row_count": blocked_counteraxis_rows,
            "external_hard_negative_abstention_row_count": external_abstention_rows,
            "counteraxis_rule_decision_counts": dict(
                sorted(rule_decision_counts.items())
            ),
            "decision_surface_changed": True,
            "prototype_gate_status": "fail_closed_review_only",
            "prototype_failed_closed": True,
            "weak_axes": weak_axes,
            "threshold_selection_decision": "do_not_select_threshold",
            "negative_control_distance_distribution_ready": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact applies a concrete fail-closed substrate-acceptor "
                "counteraxis to the review-only ePK prototype. It changes the "
                "diagnostic decision surface by blocking phosphohistidine and "
                "sibling-family ATP controls, but it is not a calibrated ePK "
                "score, production fingerprint, registry edit, external "
                "hard-negative re-audit, or label import."
            ),
            "next_actions": [
                "replace review-context acceptor support with a text-free predictive acceptor feature before production scoring",
                "run external hard-negative re-audit only after a calibrated ePK score exists",
                "keep registry and label-factory extension closed until gates pass",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("family_id") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The substrate-acceptor counteraxis is a review-only prototype "
                "and must not be treated as held-out performance or countable "
                "fingerprint evidence."
            )
        ],
    }


def build_epk_external_hard_negative_counteraxis_review(
    *,
    epk_substrate_acceptor_counteraxis_prototype: dict[str, Any],
    imported_external_entry_ids: list[str] | None = None,
) -> dict[str, Any]:
    """Summarize imported external hard negatives against the review-only ePK rule."""

    prototype_meta = epk_substrate_acceptor_counteraxis_prototype.get("metadata", {})
    if not isinstance(prototype_meta, dict):
        prototype_meta = {}
    target_fingerprint_id = str(
        prototype_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    expected_external_ids = set(
        imported_external_entry_ids
        or ["uniprot:P06744", "uniprot:P78549", "uniprot:Q3LXA3"]
    )
    source_external_rows = [
        row
        for row in epk_substrate_acceptor_counteraxis_prototype.get("rows", []) or []
        if isinstance(row, dict)
        and row.get("row_type") == "imported_external_hard_negative"
        and str(row.get("entry_id") or "") in expected_external_ids
    ]
    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    for source_row in source_external_rows:
        entry_id = str(source_row.get("entry_id") or "")
        decision = str(source_row.get("counteraxis_rule_decision") or "")
        if decision == "external_hard_negative_abstain_missing_epk_acceptor_axes":
            status = "review_only_external_hard_negative_abstention"
        else:
            status = "review_only_external_hard_negative_non_abstention"
        status_counts[status] += 1
        rows.append(
            {
                "entry_id": entry_id,
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only")
                ),
                "source_counteraxis_rule_decision": decision,
                "review_status": status,
                "review_only_counteraxis_non_abstention": (
                    status
                    == "review_only_external_hard_negative_non_abstention"
                ),
                "source_axis_values": source_row.get("source_axis_values", {}),
                "missing_required_positive_axes": source_row.get(
                    "missing_required_positive_axes", []
                ),
                "counteraxis_blocker": source_row.get("counteraxis_blocker"),
                "epk_score_computed": False,
                "remaining_blockers": [
                    "not_a_real_scored_external_reaudit",
                    "threshold_not_calibrated_against_negative_controls",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    missing_expected_ids = sorted(
        expected_external_ids - {str(row.get("entry_id") or "") for row in rows}
    )
    false_non_abstention_count = status_counts.get(
        "review_only_external_hard_negative_non_abstention", 0
    )
    return {
        "metadata": {
            "method": "epk_external_hard_negative_counteraxis_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_substrate_acceptor_counteraxis_prototype_method": (
                prototype_meta.get("method")
            ),
            "expected_external_hard_negative_entry_ids": sorted(
                expected_external_ids
            ),
            "missing_expected_external_hard_negative_entry_ids": missing_expected_ids,
            "row_count": len(rows),
            "external_hard_negative_counteraxis_status_counts": dict(
                sorted(status_counts.items())
            ),
            "review_only_external_hard_negative_abstention_count": status_counts.get(
                "review_only_external_hard_negative_abstention", 0
            ),
            "review_only_external_hard_negative_non_abstention_count": (
                false_non_abstention_count
            ),
            "review_only_external_hard_negative_check_complete": (
                not missing_expected_ids and len(rows) == len(expected_external_ids)
            ),
            "clean_heldout_performance_claim_permitted": False,
            "external_hard_negative_reaudit_scored": False,
            "threshold_calibrated": False,
            "epk_score_computed": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact checks imported external hard negatives against "
                "the review-only ePK substrate-acceptor counteraxis. It records "
                "abstentions for diagnostic safety only and does not claim clean "
                "held-out performance, compute a calibrated ePK score, edit "
                "registries, or import labels."
            ),
            "next_actions": [
                "run a real external hard-negative scored re-audit only after a calibrated ePK scorer exists",
                "preserve these rows as imported out-of-scope hard negatives",
                "keep clean held-out performance claims closed for repaired/development lanes",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: _entry_id_sort_key(str(row.get("entry_id") or "")),
        ),
        "warnings": [
            (
                "Review-only external hard-negative abstentions are not clean "
                "held-out performance evidence."
            )
        ],
    }


def build_epk_text_free_acceptor_feature_gap_audit(
    *,
    epk_review_only_scoring_prototype: dict[str, Any],
    epk_sibling_control_homolog_gamma_distance_sample: dict[str, Any],
    epk_family_specific_homolog_gamma_distance_sample: dict[str, Any]
    | list[dict[str, Any]]
    | None = None,
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Audit a structural-only ePK acceptor feature against sibling controls."""

    prototype_meta = epk_review_only_scoring_prototype.get("metadata", {})
    if not isinstance(prototype_meta, dict):
        prototype_meta = {}
    homolog_meta = epk_sibling_control_homolog_gamma_distance_sample.get(
        "metadata", {}
    )
    if not isinstance(homolog_meta, dict):
        homolog_meta = {}
    family_distance_samples = (
        epk_family_specific_homolog_gamma_distance_sample
        if isinstance(epk_family_specific_homolog_gamma_distance_sample, list)
        else (
            [epk_family_specific_homolog_gamma_distance_sample]
            if isinstance(epk_family_specific_homolog_gamma_distance_sample, dict)
            else []
        )
    )
    family_distance_metas: list[dict[str, Any]] = []
    for sample in family_distance_samples:
        if not isinstance(sample, dict):
            continue
        meta = sample.get("metadata", {})
        if isinstance(meta, dict):
            family_distance_metas.append(meta)

    target_fingerprint_id = str(
        prototype_meta.get("target_fingerprint_id")
        or homolog_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(candidate_threshold_angstrom)
    except (TypeError, ValueError):
        threshold = 6.0

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    positive_hit_count = 0
    positive_row_count = 0
    control_false_hit_count = 0
    control_row_count = 0

    def _float_or_none(value: Any) -> float | None:
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    for source_row in epk_review_only_scoring_prototype.get("rows", []) or []:
        if not isinstance(source_row, dict):
            continue
        if source_row.get("row_type") != "current_epk_positive_prototype":
            continue
        positive_row_count += 1
        distance = _float_or_none(
            source_row.get("nearest_gamma_to_hydroxyl_distance_angstrom")
        )
        feature_hit = distance is not None and distance <= threshold
        if feature_hit:
            decision = "positive_text_free_nearest_oxygen_hit_review_only"
            positive_hit_count += 1
        else:
            decision = "positive_text_free_nearest_oxygen_miss_review_only"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "current_epk_positive_prototype",
                "entry_id": source_row.get("entry_id"),
                "pdb_id": source_row.get("pdb_id"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "candidate_feature_id": (
                    "nearest_gamma_to_oxygen_within_candidate_cutoff_v0"
                ),
                "candidate_threshold_angstrom": threshold,
                "nearest_gamma_to_candidate_oxygen_distance_angstrom": distance,
                "candidate_feature_hit": feature_hit,
                "feature_audit_decision": decision,
                "acceptor_context_type": source_row.get("acceptor_context_type"),
                "gamma_geometry_scope": source_row.get("gamma_geometry_scope"),
                "epk_score_computed": False,
                "remaining_blockers": [
                    "feature_not_disambiguated_against_sibling_controls",
                    "threshold_not_calibrated_against_negative_controls",
                    "source_supported_acceptor_axis_not_replaced",
                ],
            }
        )

    homolog_rows = [
        row
        for row in epk_sibling_control_homolog_gamma_distance_sample.get("rows", [])
        or []
        if isinstance(row, dict)
        and row.get("measurement_status")
        == "homolog_gamma_to_mapped_histidine_distance_measured_review_only"
    ]
    for source_row in homolog_rows:
        control_row_count += 1
        distance = _float_or_none(
            source_row.get("nearest_gamma_to_same_chain_hydroxyl_distance_angstrom")
        )
        feature_hit = distance is not None and distance <= threshold
        if feature_hit:
            decision = "control_false_hit_blocks_text_free_feature"
            control_false_hit_count += 1
        else:
            decision = "control_nonhit_review_only"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "sibling_homolog_negative_control",
                "entry_id": None,
                "pdb_id": source_row.get("pdb_id"),
                "family_id": source_row.get("family_id"),
                "family_name": source_row.get("family_name"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "candidate_feature_id": (
                    "nearest_gamma_to_oxygen_within_candidate_cutoff_v0"
                ),
                "candidate_threshold_angstrom": threshold,
                "nearest_gamma_to_candidate_oxygen_distance_angstrom": distance,
                "candidate_feature_hit": feature_hit,
                "feature_audit_decision": decision,
                "homolog_control_axis": (
                    "mapped_phosphohistidine_site_not_hydroxyl_acceptor"
                ),
                "epk_score_computed": False,
                "remaining_blockers": [
                    "sibling_control_nearest_hydroxyl_false_hit",
                    "feature_not_disambiguated_against_sibling_controls",
                    "threshold_not_calibrated_against_negative_controls",
                ],
            }
        )

    for sample in family_distance_samples:
        if not isinstance(sample, dict):
            continue
        for source_row in sample.get("rows", []) or []:
            if not isinstance(source_row, dict):
                continue
            if (
                source_row.get("measurement_status")
                != "family_specific_gamma_to_acid_base_distance_measured_review_only"
            ):
                continue
            control_row_count += 1
            distance = _float_or_none(
                source_row.get(
                    "nearest_gamma_to_same_chain_hydroxyl_distance_angstrom"
                )
            )
            feature_hit = distance is not None and distance <= threshold
            if feature_hit:
                decision = "control_false_hit_blocks_text_free_feature"
                control_false_hit_count += 1
            else:
                decision = "control_nonhit_review_only"
            decision_counts[decision] += 1
            rows.append(
                {
                    "row_type": "sibling_family_specific_negative_control",
                    "entry_id": None,
                    "pdb_id": source_row.get("pdb_id"),
                    "family_id": source_row.get("family_id"),
                    "family_name": source_row.get("family_name"),
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "text_free_inputs_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "candidate_feature_id": (
                        "nearest_gamma_to_oxygen_within_candidate_cutoff_v0"
                    ),
                    "candidate_threshold_angstrom": threshold,
                    "nearest_gamma_to_candidate_oxygen_distance_angstrom": distance,
                    "candidate_feature_hit": feature_hit,
                    "feature_audit_decision": decision,
                    "homolog_control_axis": (
                        "family_specific_sibling_acid_base_counteraxis_not_epk_label"
                    ),
                    "epk_score_computed": False,
                    "remaining_blockers": [
                        "sibling_control_nearest_hydroxyl_false_hit",
                        "feature_not_disambiguated_against_sibling_controls",
                        "threshold_not_calibrated_against_negative_controls",
                    ],
                }
            )

    feature_false_hit_rate = (
        round(control_false_hit_count / control_row_count, 4)
        if control_row_count
        else None
    )
    feature_positive_hit_rate = (
        round(positive_hit_count / positive_row_count, 4)
        if positive_row_count
        else None
    )
    feature_admissible = (
        positive_row_count > 0
        and positive_hit_count == positive_row_count
        and control_false_hit_count == 0
    )
    false_hit_rows = [
        row
        for row in rows
        if row.get("feature_audit_decision")
        == "control_false_hit_blocks_text_free_feature"
    ]
    false_hit_family_counts = Counter(
        str(row.get("family_id"))
        for row in false_hit_rows
        if row.get("family_id")
    )
    return {
        "metadata": {
            "method": "epk_text_free_acceptor_feature_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_review_only_scoring_prototype_method": (
                prototype_meta.get("method")
            ),
            "source_epk_sibling_control_homolog_gamma_distance_sample_method": (
                homolog_meta.get("method")
            ),
            "source_epk_family_specific_homolog_gamma_distance_sample_methods": (
                _sorted_strings(
                    meta.get("method")
                    for meta in family_distance_metas
                    if meta.get("method")
                )
            ),
            "candidate_feature_id": (
                "nearest_gamma_to_oxygen_within_candidate_cutoff_v0"
            ),
            "candidate_threshold_angstrom": threshold,
            "row_count": len(rows),
            "current_positive_row_count": positive_row_count,
            "current_positive_feature_hit_count": positive_hit_count,
            "current_positive_feature_hit_rate": feature_positive_hit_rate,
            "negative_control_row_count": control_row_count,
            "negative_control_false_hit_count": control_false_hit_count,
            "negative_control_false_hit_rate": feature_false_hit_rate,
            "negative_control_false_hit_family_ids": _sorted_strings(
                row.get("family_id") for row in false_hit_rows
            ),
            "negative_control_false_hit_family_counts": dict(
                sorted(false_hit_family_counts.items())
            ),
            "negative_control_false_hit_pdb_ids": _sorted_strings(
                row.get("pdb_id") for row in false_hit_rows
            ),
            "feature_audit_decision_counts": dict(sorted(decision_counts.items())),
            "candidate_feature_status": (
                "admissible_review_only"
                if feature_admissible
                else "blocked_review_only"
            ),
            "feature_admissible_for_scoring": feature_admissible,
            "feature_gap_identified": not feature_admissible,
            "primary_blocker": (
                "nearest_oxygen_feature_false_hits_sibling_controls"
                if control_false_hit_count
                else None
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact audits a text-free nearest-gamma-to-oxygen "
                "acceptor feature against current ePK positives and sibling "
                "ATP-family controls. False hits are negative evidence and do "
                "not authorize threshold selection, scoring, registry edits, "
                "external hard-negative claims, or label import."
            ),
            "next_actions": [
                "add a text-free disambiguation feature beyond nearest oxygen distance",
                "test chain/substrate context or ligand-class constraints against the same sibling controls",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("family_id") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The nearest-oxygen acceptor feature is a failed review-only "
                "candidate feature and must not be treated as ePK scoring "
                "evidence."
            )
        ],
    }


def build_epk_chain_ligand_acceptor_disambiguation_audit(
    *,
    epk_review_only_scoring_prototype: dict[str, Any],
    epk_acceptor_identity_review: dict[str, Any],
    epk_m_csa640_alternate_gamma_geometry_review: dict[str, Any],
    epk_sibling_control_homolog_gamma_distance_sample: dict[str, Any],
    epk_family_specific_homolog_gamma_distance_sample: dict[str, Any]
    | list[dict[str, Any]]
    | None = None,
    epk_negative_control_gamma_distance_distribution: dict[str, Any] | None = None,
    epk_sibling_negative_control_alternate_gamma_distance_sample: dict[str, Any]
    | None = None,
    imported_external_entry_ids: list[str] | None = None,
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Audit a stricter chain/ligand-context ePK acceptor feature."""

    prototype_meta = epk_review_only_scoring_prototype.get("metadata", {})
    if not isinstance(prototype_meta, dict):
        prototype_meta = {}
    identity_meta = epk_acceptor_identity_review.get("metadata", {})
    if not isinstance(identity_meta, dict):
        identity_meta = {}
    alternate_meta = epk_m_csa640_alternate_gamma_geometry_review.get(
        "metadata", {}
    )
    if not isinstance(alternate_meta, dict):
        alternate_meta = {}
    homolog_meta = epk_sibling_control_homolog_gamma_distance_sample.get(
        "metadata", {}
    )
    if not isinstance(homolog_meta, dict):
        homolog_meta = {}
    selected_negative_meta = (
        epk_negative_control_gamma_distance_distribution.get("metadata", {})
        if isinstance(epk_negative_control_gamma_distance_distribution, dict)
        else {}
    )
    if not isinstance(selected_negative_meta, dict):
        selected_negative_meta = {}
    alternate_negative_meta = (
        epk_sibling_negative_control_alternate_gamma_distance_sample.get(
            "metadata", {}
        )
        if isinstance(
            epk_sibling_negative_control_alternate_gamma_distance_sample, dict
        )
        else {}
    )
    if not isinstance(alternate_negative_meta, dict):
        alternate_negative_meta = {}
    family_distance_samples = (
        epk_family_specific_homolog_gamma_distance_sample
        if isinstance(epk_family_specific_homolog_gamma_distance_sample, list)
        else (
            [epk_family_specific_homolog_gamma_distance_sample]
            if isinstance(epk_family_specific_homolog_gamma_distance_sample, dict)
            else []
        )
    )
    family_distance_metas: list[dict[str, Any]] = []
    for sample in family_distance_samples:
        if not isinstance(sample, dict):
            continue
        meta = sample.get("metadata", {})
        if isinstance(meta, dict):
            family_distance_metas.append(meta)

    target_fingerprint_id = str(
        prototype_meta.get("target_fingerprint_id")
        or identity_meta.get("target_fingerprint_id")
        or alternate_meta.get("target_fingerprint_id")
        or homolog_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(candidate_threshold_angstrom)
    except (TypeError, ValueError):
        threshold = 6.0

    def _float_or_none(value: Any) -> float | None:
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    identity_by_entry = {
        str(row.get("entry_id")): row
        for row in epk_acceptor_identity_review.get("rows", []) or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    alternate_by_entry = {
        str(row.get("entry_id")): row
        for row in epk_m_csa640_alternate_gamma_geometry_review.get("rows", [])
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    imported_external_ids = set(
        imported_external_entry_ids
        or ["uniprot:P06744", "uniprot:P78549", "uniprot:Q3LXA3"]
    )

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    positive_row_count = 0
    positive_hit_count = 0
    control_row_count = 0
    control_same_chain_block_count = 0
    control_broader_chain_context_block_count = 0
    control_false_hit_count = 0
    external_abstention_count = 0
    feature_id = "gamma_acceptor_non_catalytic_chain_or_ligand_analog_v0"

    for source_row in epk_review_only_scoring_prototype.get("rows", []) or []:
        if not isinstance(source_row, dict):
            continue
        row_type = str(source_row.get("row_type") or "")
        entry_id = str(source_row.get("entry_id") or "")
        if row_type == "current_epk_positive_prototype":
            positive_row_count += 1
            identity_row = identity_by_entry.get(entry_id, {})
            alternate_row = alternate_by_entry.get(entry_id, {})
            nearest_hydroxyl = identity_row.get("nearest_measured_hydroxyl")
            if not isinstance(nearest_hydroxyl, dict):
                nearest_hydroxyl = {}
            distance = _float_or_none(
                source_row.get("nearest_gamma_to_hydroxyl_distance_angstrom")
                or nearest_hydroxyl.get("distance_angstrom")
                or alternate_row.get("gamma_to_acceptor_distance_angstrom")
            )
            non_catalytic_chain_acceptor = bool(
                nearest_hydroxyl.get("on_non_catalytic_chain")
            )
            ligand_analog_acceptor = bool(
                alternate_row.get("acceptor_like_ligand_present")
                and alternate_row.get("within_candidate_threshold")
            )
            feature_hit = bool(
                distance is not None
                and distance <= threshold
                and (non_catalytic_chain_acceptor or ligand_analog_acceptor)
            )
            if feature_hit:
                decision = (
                    "positive_chain_ligand_acceptor_context_hit_review_only"
                )
                positive_hit_count += 1
            else:
                decision = (
                    "positive_chain_ligand_acceptor_context_missing_review_only"
                )
            decision_counts[decision] += 1
            rows.append(
                {
                    "row_type": "current_epk_positive_prototype",
                    "entry_id": entry_id,
                    "pdb_id": source_row.get("pdb_id"),
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "text_free_inputs_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "candidate_feature_id": feature_id,
                    "candidate_threshold_angstrom": threshold,
                    "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                        distance
                    ),
                    "candidate_feature_hit": feature_hit,
                    "feature_audit_decision": decision,
                    "non_catalytic_chain_acceptor": non_catalytic_chain_acceptor,
                    "ligand_analog_acceptor": ligand_analog_acceptor,
                    "acceptor_context_type": source_row.get(
                        "acceptor_context_type"
                    ),
                    "gamma_geometry_scope": source_row.get("gamma_geometry_scope"),
                    "predictive_use_status": (
                        "review_only_candidate_axis_not_production_score"
                    ),
                    "epk_score_computed": False,
                    "remaining_blockers": [
                        "feature_not_calibrated_or_generalized",
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                        "registry_and_label_factory_extension_not_implemented",
                    ],
                }
            )
        elif (
            row_type == "imported_external_hard_negative"
            and entry_id in imported_external_ids
        ):
            decision = (
                "external_hard_negative_abstain_missing_chain_ligand_axes"
            )
            decision_counts[decision] += 1
            external_abstention_count += 1
            rows.append(
                {
                    "row_type": "imported_external_hard_negative",
                    "entry_id": entry_id,
                    "pdb_id": source_row.get("pdb_id"),
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "text_free_inputs_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "candidate_feature_id": feature_id,
                    "candidate_threshold_angstrom": threshold,
                    "nearest_gamma_to_candidate_acceptor_distance_angstrom": None,
                    "candidate_feature_hit": False,
                    "feature_audit_decision": decision,
                    "non_catalytic_chain_acceptor": False,
                    "ligand_analog_acceptor": False,
                    "predictive_use_status": (
                        "review_only_abstention_not_external_reaudit"
                    ),
                    "epk_score_computed": False,
                    "remaining_blockers": [
                        "external_epk_specific_axes_not_materialized",
                        "external_hard_negative_reaudit_not_real_scorer",
                        "threshold_not_calibrated_against_negative_controls",
                    ],
                }
            )

    def _append_control_row(source_row: dict[str, Any], row_type: str) -> None:
        nonlocal control_row_count, control_same_chain_block_count
        nonlocal control_false_hit_count
        control_row_count += 1
        distance = _float_or_none(
            source_row.get("nearest_gamma_to_same_chain_hydroxyl_distance_angstrom")
        )
        same_chain_nearest_hydroxyl_hit = bool(
            distance is not None and distance <= threshold
        )
        if same_chain_nearest_hydroxyl_hit:
            decision = "control_blocked_same_chain_hydroxyl_context"
            control_same_chain_block_count += 1
        else:
            decision = "control_nonhit_review_only"
        feature_hit = False
        if feature_hit:
            control_false_hit_count += 1
            decision = "control_false_hit_blocks_chain_ligand_feature"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": row_type,
                "entry_id": None,
                "pdb_id": source_row.get("pdb_id"),
                "family_id": source_row.get("family_id"),
                "family_name": source_row.get("family_name"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "candidate_feature_id": feature_id,
                "candidate_threshold_angstrom": threshold,
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    distance
                ),
                "candidate_feature_hit": feature_hit,
                "same_chain_nearest_hydroxyl_hit": (
                    same_chain_nearest_hydroxyl_hit
                ),
                "feature_audit_decision": decision,
                "non_catalytic_chain_acceptor": False,
                "ligand_analog_acceptor": False,
                "homolog_control_axis": source_row.get("homolog_control_axis")
                or source_row.get("control_use_status"),
                "predictive_use_status": (
                    "review_only_control_context_not_production_score"
                ),
                "epk_score_computed": False,
                "remaining_blockers": [
                    "review_only_counteraxis_not_calibrated_scorer",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    def _append_broader_control_row(
        source_row: dict[str, Any],
        row_type: str,
        measurement_source: str,
    ) -> None:
        nonlocal control_row_count, control_broader_chain_context_block_count
        nonlocal control_false_hit_count
        control_row_count += 1
        distance = _float_or_none(
            source_row.get("nearest_gamma_to_hydroxyl_distance_angstrom")
        )
        unresolved_chain_context_hit = bool(
            distance is not None and distance <= threshold
        )
        if unresolved_chain_context_hit:
            decision = (
                "broader_control_blocked_missing_non_catalytic_or_ligand_context"
            )
            control_broader_chain_context_block_count += 1
        else:
            decision = "control_nonhit_review_only"
        feature_hit = False
        if feature_hit:
            control_false_hit_count += 1
            decision = "control_false_hit_blocks_chain_ligand_feature"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": row_type,
                "entry_id": source_row.get("entry_id"),
                "pdb_id": source_row.get("pdb_id"),
                "family_id": source_row.get("family_id"),
                "family_name": source_row.get("family_name"),
                "measurement_source": measurement_source,
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "candidate_feature_id": feature_id,
                "candidate_threshold_angstrom": threshold,
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    distance
                ),
                "candidate_feature_hit": feature_hit,
                "same_or_unresolved_chain_nearest_hydroxyl_hit": (
                    unresolved_chain_context_hit
                ),
                "feature_audit_decision": decision,
                "non_catalytic_chain_acceptor": False,
                "ligand_analog_acceptor": False,
                "homolog_control_axis": source_row.get("control_use_status"),
                "predictive_use_status": (
                    "review_only_broader_control_context_not_production_score"
                ),
                "epk_score_computed": False,
                "remaining_blockers": [
                    "broader_control_chain_context_unresolved",
                    "review_only_counteraxis_not_calibrated_scorer",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    for source_row in epk_sibling_control_homolog_gamma_distance_sample.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        if (
            source_row.get("measurement_status")
            != "homolog_gamma_to_mapped_histidine_distance_measured_review_only"
        ):
            continue
        _append_control_row(source_row, "sibling_homolog_negative_control")

    for sample in family_distance_samples:
        if not isinstance(sample, dict):
            continue
        for source_row in sample.get("rows", []) or []:
            if not isinstance(source_row, dict):
                continue
            if (
                source_row.get("measurement_status")
                != "family_specific_gamma_to_acid_base_distance_measured_review_only"
            ):
                continue
            _append_control_row(
                source_row, "sibling_family_specific_negative_control"
            )

    if isinstance(epk_negative_control_gamma_distance_distribution, dict):
        for source_row in (
            epk_negative_control_gamma_distance_distribution.get("rows", []) or []
        ):
            if not isinstance(source_row, dict):
                continue
            if (
                source_row.get("measurement_status")
                != "selected_structure_gamma_to_hydroxyl_distance_measured_review_only"
            ):
                continue
            _append_broader_control_row(
                source_row,
                "sibling_selected_structure_negative_control",
                "selected_structure",
            )

    if isinstance(epk_sibling_negative_control_alternate_gamma_distance_sample, dict):
        for source_row in (
            epk_sibling_negative_control_alternate_gamma_distance_sample.get(
                "rows", []
            )
            or []
        ):
            if not isinstance(source_row, dict):
                continue
            if (
                source_row.get("measurement_status")
                != "alternate_gamma_to_hydroxyl_distance_measured_review_only"
            ):
                continue
            _append_broader_control_row(
                source_row,
                "sibling_alternate_structure_negative_control",
                "alternate_structure",
            )

    positive_hit_rate = (
        round(positive_hit_count / positive_row_count, 4)
        if positive_row_count
        else None
    )
    false_hit_rate = (
        round(control_false_hit_count / control_row_count, 4)
        if control_row_count
        else None
    )
    passes_current_review_controls = (
        positive_row_count > 0
        and positive_hit_count == positive_row_count
        and control_false_hit_count == 0
    )
    false_hit_rows = [
        row
        for row in rows
        if row.get("feature_audit_decision")
        == "control_false_hit_blocks_chain_ligand_feature"
    ]
    same_chain_block_rows = [
        row
        for row in rows
        if row.get("feature_audit_decision")
        == "control_blocked_same_chain_hydroxyl_context"
    ]
    same_chain_family_counts = Counter(
        str(row.get("family_id"))
        for row in same_chain_block_rows
        if row.get("family_id")
    )
    return {
        "metadata": {
            "method": "epk_chain_ligand_acceptor_disambiguation_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_review_only_scoring_prototype_method": (
                prototype_meta.get("method")
            ),
            "source_epk_acceptor_identity_review_method": (
                identity_meta.get("method")
            ),
            "source_epk_m_csa640_alternate_gamma_geometry_review_method": (
                alternate_meta.get("method")
            ),
            "source_epk_sibling_control_homolog_gamma_distance_sample_method": (
                homolog_meta.get("method")
            ),
            "source_epk_negative_control_gamma_distance_distribution_method": (
                selected_negative_meta.get("method")
            ),
            "source_epk_sibling_negative_control_alternate_gamma_distance_sample_method": (
                alternate_negative_meta.get("method")
            ),
            "source_epk_family_specific_homolog_gamma_distance_sample_methods": (
                _sorted_strings(
                    meta.get("method")
                    for meta in family_distance_metas
                    if meta.get("method")
                )
            ),
            "candidate_feature_id": feature_id,
            "candidate_threshold_angstrom": threshold,
            "row_count": len(rows),
            "current_positive_row_count": positive_row_count,
            "current_positive_feature_hit_count": positive_hit_count,
            "current_positive_feature_hit_rate": positive_hit_rate,
            "negative_control_row_count": control_row_count,
            "negative_control_same_chain_block_count": (
                control_same_chain_block_count
            ),
            "negative_control_broader_chain_context_block_count": (
                control_broader_chain_context_block_count
            ),
            "negative_control_chain_context_block_count": (
                control_same_chain_block_count
                + control_broader_chain_context_block_count
            ),
            "negative_control_same_chain_block_family_counts": dict(
                sorted(same_chain_family_counts.items())
            ),
            "negative_control_false_hit_count": control_false_hit_count,
            "negative_control_false_hit_rate": false_hit_rate,
            "negative_control_false_hit_family_ids": _sorted_strings(
                row.get("family_id") for row in false_hit_rows
            ),
            "external_hard_negative_abstention_row_count": (
                external_abstention_count
            ),
            "feature_audit_decision_counts": dict(sorted(decision_counts.items())),
            "candidate_feature_status": (
                "passes_current_review_controls_review_only"
                if passes_current_review_controls
                else "blocked_review_only"
            ),
            "feature_passes_current_review_controls": (
                passes_current_review_controls
            ),
            "feature_admissible_for_production_scoring": False,
            "feature_gap_identified": not passes_current_review_controls,
            "decision_surface_changed": True,
            "primary_blocker": (
                None
                if passes_current_review_controls
                else "chain_ligand_acceptor_context_false_hits_or_misses"
            ),
            "production_blockers": [
                "chain_ligand_context_generalization_not_calibrated",
                "ligand_analog_policy_review_only",
                "external_hard_negative_reaudit_not_scored",
                "threshold_not_calibrated_against_negative_controls",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact tests a stricter text-free ePK acceptor "
                "disambiguation feature: nearest gamma oxygen plus "
                "non-catalytic-chain acceptor or acceptor-like ligand analog "
                "context. It is a review-only counteraxis experiment and does "
                "not authorize production scoring, registry edits, external "
                "hard-negative claims, or label import."
            ),
            "next_actions": [
                "calibrate and generalize the chain/ligand acceptor feature against broader controls",
                "resolve ligand-analog production admissibility before using m_csa:640 as scoring evidence",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("family_id") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The chain/ligand acceptor feature is review-only; passing the "
                "current sibling controls is not a calibrated ePK score or a "
                "clean held-out performance claim."
            )
        ],
    }


def build_epk_chain_ligand_external_hard_negative_feature_screen(
    *,
    epk_chain_ligand_acceptor_disambiguation_audit: dict[str, Any],
    imported_external_entry_ids: list[str] | None = None,
) -> dict[str, Any]:
    """Screen imported external hard negatives with the review-only feature."""

    audit_meta = epk_chain_ligand_acceptor_disambiguation_audit.get(
        "metadata", {}
    )
    if not isinstance(audit_meta, dict):
        audit_meta = {}
    target_fingerprint_id = str(
        audit_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    expected_external_ids = set(
        imported_external_entry_ids
        or ["uniprot:P06744", "uniprot:P78549", "uniprot:Q3LXA3"]
    )
    source_rows = {
        str(row.get("entry_id") or ""): row
        for row in epk_chain_ligand_acceptor_disambiguation_audit.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and row.get("row_type") == "imported_external_hard_negative"
    }

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    for entry_id in sorted(expected_external_ids, key=_entry_id_sort_key):
        source_row = source_rows.get(entry_id, {})
        feature_hit = bool(source_row.get("candidate_feature_hit"))
        feature_score = 1.0 if feature_hit else 0.0
        if not source_row:
            status = "review_only_external_hard_negative_missing_from_feature_audit"
            blockers = [
                "external_row_missing_from_chain_ligand_feature_audit",
                "not_a_real_scored_external_reaudit",
            ]
        elif feature_hit:
            status = "review_only_external_hard_negative_feature_non_abstention"
            blockers = [
                "review_only_feature_non_abstention_requires_scorer_redesign",
                "not_a_real_scored_external_reaudit",
                "threshold_not_calibrated_against_negative_controls",
            ]
        else:
            status = "review_only_external_hard_negative_feature_abstention"
            blockers = [
                "not_a_real_scored_external_reaudit",
                "threshold_not_calibrated_against_negative_controls",
                "registry_and_label_factory_extension_not_implemented",
            ]
        status_counts[status] += 1
        rows.append(
            {
                "entry_id": entry_id,
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "candidate_feature_id": audit_meta.get("candidate_feature_id"),
                "candidate_feature_hit": feature_hit,
                "review_only_feature_score": feature_score,
                "feature_screen_status": status,
                "review_only_feature_non_abstention": feature_hit,
                "source_feature_audit_decision": source_row.get(
                    "feature_audit_decision"
                ),
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "clean_heldout_performance_claim_permitted": False,
                "remaining_blockers": blockers,
            }
        )

    missing_count = status_counts.get(
        "review_only_external_hard_negative_missing_from_feature_audit", 0
    )
    non_abstention_count = status_counts.get(
        "review_only_external_hard_negative_feature_non_abstention", 0
    )
    return {
        "metadata": {
            "method": "epk_chain_ligand_external_hard_negative_feature_screen",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_chain_ligand_acceptor_disambiguation_audit_method": (
                audit_meta.get("method")
            ),
            "candidate_feature_id": audit_meta.get("candidate_feature_id"),
            "expected_external_hard_negative_entry_ids": sorted(
                expected_external_ids,
                key=_entry_id_sort_key,
            ),
            "row_count": len(rows),
            "external_hard_negative_feature_screen_status_counts": dict(
                sorted(status_counts.items())
            ),
            "review_only_external_hard_negative_feature_abstention_count": (
                status_counts.get(
                    "review_only_external_hard_negative_feature_abstention", 0
                )
            ),
            "review_only_external_hard_negative_feature_non_abstention_count": (
                non_abstention_count
            ),
            "missing_expected_external_hard_negative_count": missing_count,
            "review_only_feature_screen_complete": (
                missing_count == 0 and len(rows) == len(expected_external_ids)
            ),
            "review_only_feature_screen_passed": (
                missing_count == 0 and non_abstention_count == 0
            ),
            "clean_heldout_performance_claim_permitted": False,
            "external_hard_negative_reaudit_scored": False,
            "threshold_calibrated": False,
            "epk_score_computed": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact screens imported external hard negatives with "
                "the review-only chain/ligand acceptor feature. It records a "
                "diagnostic feature score only and is not a calibrated ePK "
                "score, clean held-out performance claim, registry edit, or "
                "label import."
            ),
            "next_actions": [
                "run a real external hard-negative scored re-audit only after a calibrated ePK scorer exists",
                "keep imported external rows under the existing out-of-scope label contract",
                "treat this feature screen as development evidence only",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Review-only feature abstentions are not a clean held-out "
                "performance claim or production ePK re-audit."
            )
        ],
    }


def build_epk_protein_substrate_acceptor_candidate_audit(
    *,
    epk_chain_ligand_acceptor_disambiguation_audit: dict[str, Any],
    imported_external_entry_ids: list[str] | None = None,
) -> dict[str, Any]:
    """Test the chain/ligand feature without ligand-analog positive evidence."""

    audit_meta = epk_chain_ligand_acceptor_disambiguation_audit.get(
        "metadata", {}
    )
    if not isinstance(audit_meta, dict):
        audit_meta = {}
    target_fingerprint_id = str(
        audit_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    expected_external_ids = set(
        imported_external_entry_ids
        or ["uniprot:P06744", "uniprot:P78549", "uniprot:Q3LXA3"]
    )
    feature_id = "protein_substrate_non_catalytic_chain_acceptor_v0"

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    positive_row_count = 0
    positive_hit_count = 0
    positive_miss_count = 0
    ligand_analog_only_positive_miss_count = 0
    control_row_count = 0
    control_false_hit_count = 0
    external_abstention_count = 0

    for source_row in epk_chain_ligand_acceptor_disambiguation_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        row_type = str(source_row.get("row_type") or "")
        entry_id = str(source_row.get("entry_id") or "")
        source_feature_hit = bool(source_row.get("candidate_feature_hit"))
        non_catalytic_chain_acceptor = bool(
            source_row.get("non_catalytic_chain_acceptor")
        )
        ligand_analog_acceptor = bool(source_row.get("ligand_analog_acceptor"))
        protein_substrate_feature_hit = bool(
            source_feature_hit
            and non_catalytic_chain_acceptor
            and not ligand_analog_acceptor
        )

        if row_type == "current_epk_positive_prototype":
            positive_row_count += 1
            if protein_substrate_feature_hit:
                decision = "positive_protein_substrate_acceptor_hit_review_only"
                positive_hit_count += 1
            elif source_feature_hit and ligand_analog_acceptor:
                decision = (
                    "positive_ligand_analog_only_miss_blocks_production_candidate"
                )
                positive_miss_count += 1
                ligand_analog_only_positive_miss_count += 1
            else:
                decision = "positive_protein_substrate_acceptor_miss_review_only"
                positive_miss_count += 1
        elif row_type == "imported_external_hard_negative":
            if entry_id not in expected_external_ids:
                continue
            if protein_substrate_feature_hit:
                decision = (
                    "external_hard_negative_protein_substrate_feature_non_abstention"
                )
            else:
                decision = "external_hard_negative_protein_substrate_feature_abstention"
                external_abstention_count += 1
        elif row_type.endswith("negative_control"):
            control_row_count += 1
            if protein_substrate_feature_hit:
                decision = (
                    "control_false_hit_blocks_protein_substrate_acceptor_candidate"
                )
                control_false_hit_count += 1
            else:
                decision = "control_nonhit_review_only"
        else:
            continue

        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": row_type,
                "entry_id": source_row.get("entry_id"),
                "pdb_id": source_row.get("pdb_id"),
                "family_id": source_row.get("family_id"),
                "family_name": source_row.get("family_name"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "candidate_feature_id": feature_id,
                "source_candidate_feature_id": source_row.get("candidate_feature_id"),
                "source_candidate_feature_hit": source_feature_hit,
                "candidate_feature_hit": protein_substrate_feature_hit,
                "feature_audit_decision": decision,
                "non_catalytic_chain_acceptor": non_catalytic_chain_acceptor,
                "ligand_analog_acceptor": ligand_analog_acceptor,
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    source_row.get(
                        "nearest_gamma_to_candidate_acceptor_distance_angstrom"
                    )
                ),
                "source_feature_audit_decision": source_row.get(
                    "feature_audit_decision"
                ),
                "predictive_use_status": (
                    "review_only_production_candidate_not_calibrated"
                ),
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "positive_coverage_gap_or_uncalibrated_candidate_feature",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "threshold_not_calibrated_against_negative_controls",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    missing_expected_external_ids = sorted(
        expected_external_ids
        - {
            str(row.get("entry_id") or "")
            for row in rows
            if row.get("row_type") == "imported_external_hard_negative"
        },
        key=_entry_id_sort_key,
    )
    positive_hit_rate = (
        round(positive_hit_count / positive_row_count, 4)
        if positive_row_count
        else None
    )
    false_hit_rate = (
        round(control_false_hit_count / control_row_count, 4)
        if control_row_count
        else None
    )
    feature_passes_current_review_controls = (
        positive_row_count > 0
        and positive_hit_count == positive_row_count
        and control_false_hit_count == 0
        and not missing_expected_external_ids
    )
    false_hit_rows = [
        row
        for row in rows
        if row.get("feature_audit_decision")
        == "control_false_hit_blocks_protein_substrate_acceptor_candidate"
    ]
    ligand_analog_miss_rows = [
        row
        for row in rows
        if row.get("feature_audit_decision")
        == "positive_ligand_analog_only_miss_blocks_production_candidate"
    ]
    candidate_status = (
        "passes_current_review_controls_review_only"
        if feature_passes_current_review_controls
        else "blocked_review_only_positive_coverage_gap"
        if positive_miss_count
        else "blocked_review_only_control_false_hit"
    )
    primary_blocker = (
        "protein_substrate_feature_misses_ligand_analog_positive"
        if ligand_analog_only_positive_miss_count
        else "protein_substrate_feature_false_hits_sibling_controls"
        if control_false_hit_count
        else None
    )

    return {
        "metadata": {
            "method": "epk_protein_substrate_acceptor_candidate_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_chain_ligand_acceptor_disambiguation_audit_method": (
                audit_meta.get("method")
            ),
            "source_chain_ligand_candidate_feature_id": audit_meta.get(
                "candidate_feature_id"
            ),
            "candidate_feature_id": feature_id,
            "candidate_threshold_angstrom": audit_meta.get(
                "candidate_threshold_angstrom"
            ),
            "row_count": len(rows),
            "current_positive_row_count": positive_row_count,
            "current_positive_feature_hit_count": positive_hit_count,
            "current_positive_feature_hit_rate": positive_hit_rate,
            "current_positive_feature_miss_count": positive_miss_count,
            "ligand_analog_only_positive_miss_count": (
                ligand_analog_only_positive_miss_count
            ),
            "ligand_analog_only_positive_miss_entry_ids": [
                row.get("entry_id") for row in ligand_analog_miss_rows
            ],
            "negative_control_row_count": control_row_count,
            "negative_control_false_hit_count": control_false_hit_count,
            "negative_control_false_hit_rate": false_hit_rate,
            "negative_control_false_hit_family_ids": _sorted_strings(
                row.get("family_id") for row in false_hit_rows
            ),
            "external_hard_negative_feature_abstention_count": (
                external_abstention_count
            ),
            "missing_expected_external_hard_negative_entry_ids": (
                missing_expected_external_ids
            ),
            "feature_audit_decision_counts": dict(sorted(decision_counts.items())),
            "candidate_feature_status": candidate_status,
            "feature_passes_current_review_controls": (
                feature_passes_current_review_controls
            ),
            "feature_admissible_for_production_scoring": False,
            "decision_surface_changed": True,
            "primary_blocker": primary_blocker,
            "production_blockers": [
                "protein_substrate_feature_positive_coverage_gap",
                "external_hard_negative_reaudit_not_scored",
                "threshold_not_calibrated_against_negative_controls",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact tightens the chain/ligand ePK acceptor feature "
                "to protein-substrate non-catalytic-chain acceptor context only. "
                "It deliberately excludes ligand-analog rescue evidence and must "
                "fail closed unless positive coverage and controls both pass."
            ),
            "next_actions": [
                "resolve whether ligand-analog acceptor evidence can ever become production-admissible",
                "seek another protein-substrate ePK positive or a text-free analog policy before scorer calibration",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("family_id") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The protein-substrate acceptor candidate is a stricter "
                "review-only negative result and is not production ePK scoring "
                "evidence."
            )
        ],
    }


def build_epk_ligand_analog_policy_blocker_decision(
    *,
    epk_protein_substrate_acceptor_candidate_audit: dict[str, Any],
    epk_chain_ligand_acceptor_disambiguation_audit: dict[str, Any],
    epk_m_csa640_alternate_gamma_geometry_review: dict[str, Any],
) -> dict[str, Any]:
    """Record whether ligand-analog acceptor evidence can support ePK scoring."""

    protein_meta = epk_protein_substrate_acceptor_candidate_audit.get(
        "metadata", {}
    )
    if not isinstance(protein_meta, dict):
        protein_meta = {}
    chain_meta = epk_chain_ligand_acceptor_disambiguation_audit.get(
        "metadata", {}
    )
    if not isinstance(chain_meta, dict):
        chain_meta = {}
    alternate_meta = epk_m_csa640_alternate_gamma_geometry_review.get(
        "metadata", {}
    )
    if not isinstance(alternate_meta, dict):
        alternate_meta = {}

    target_fingerprint_id = str(
        protein_meta.get("target_fingerprint_id")
        or chain_meta.get("target_fingerprint_id")
        or alternate_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    chain_rows_by_entry = {
        str(row.get("entry_id")): row
        for row in epk_chain_ligand_acceptor_disambiguation_audit.get(
            "rows", []
        )
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    alternate_rows_by_entry = {
        str(row.get("entry_id")): row
        for row in epk_m_csa640_alternate_gamma_geometry_review.get(
            "rows", []
        )
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }

    rows: list[dict[str, Any]] = []
    for source_row in epk_protein_substrate_acceptor_candidate_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        if (
            source_row.get("feature_audit_decision")
            != "positive_ligand_analog_only_miss_blocks_production_candidate"
        ):
            continue
        entry_id = str(source_row.get("entry_id") or "")
        chain_row = chain_rows_by_entry.get(entry_id, {})
        alternate_row = alternate_rows_by_entry.get(entry_id, {})
        production_admissible = False
        decision = "do_not_use_ligand_analog_as_production_acceptor_evidence"
        blockers = [
            "ligand_analog_policy_not_pre_registered",
            "analog_context_not_generalized_against_external_epk_like_controls",
            "external_hard_negative_reaudit_not_real_scorer",
            "threshold_not_calibrated_against_negative_controls",
        ]
        rows.append(
            {
                "entry_id": entry_id,
                "pdb_id": source_row.get("pdb_id") or alternate_row.get("pdb_id"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "chain_ligand_feature_hit": bool(
                    chain_row.get("candidate_feature_hit")
                ),
                "protein_substrate_feature_hit": bool(
                    source_row.get("candidate_feature_hit")
                ),
                "ligand_analog_acceptor": bool(
                    source_row.get("ligand_analog_acceptor")
                    or chain_row.get("ligand_analog_acceptor")
                    or alternate_row.get("acceptor_like_ligand_present")
                ),
                "acceptor_ligand_code": alternate_row.get("acceptor_ligand_code"),
                "gamma_to_acceptor_distance_angstrom": (
                    alternate_row.get("gamma_to_acceptor_distance_angstrom")
                    or source_row.get(
                        "nearest_gamma_to_candidate_acceptor_distance_angstrom"
                    )
                ),
                "alternate_gamma_geometry_review_status": alternate_row.get(
                    "alternate_gamma_geometry_review_status"
                ),
                "ligand_analog_policy_decision": decision,
                "ligand_analog_evidence_admissible_for_production_scoring": (
                    production_admissible
                ),
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": blockers,
            }
        )

    ligand_analog_dependency_count = len(rows)
    production_admissible_count = sum(
        1
        for row in rows
        if row.get("ligand_analog_evidence_admissible_for_production_scoring")
    )
    policy_decision = (
        "do_not_use_ligand_analog_as_production_acceptor_evidence"
        if ligand_analog_dependency_count
        else "no_ligand_analog_dependency_detected"
    )

    return {
        "metadata": {
            "method": "epk_ligand_analog_policy_blocker_decision",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_acceptor_candidate_audit_method": (
                protein_meta.get("method")
            ),
            "source_epk_chain_ligand_acceptor_disambiguation_audit_method": (
                chain_meta.get("method")
            ),
            "source_epk_m_csa640_alternate_gamma_geometry_review_method": (
                alternate_meta.get("method")
            ),
            "ligand_analog_dependency_count": ligand_analog_dependency_count,
            "ligand_analog_dependency_entry_ids": [
                row.get("entry_id") for row in rows
            ],
            "ligand_analog_production_admissible_count": production_admissible_count,
            "ligand_analog_policy_decision": policy_decision,
            "ligand_analog_policy_status": (
                "blocked_review_only"
                if ligand_analog_dependency_count
                else "not_applicable_review_only"
            ),
            "protein_substrate_positive_coverage_gap": bool(
                ligand_analog_dependency_count
            ),
            "feature_admissible_for_production_scoring": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact records the current policy decision for ePK "
                "ligand-analog acceptor evidence. Ligand analogs stay review-only "
                "and cannot rescue production positive coverage until a future "
                "pre-registered policy and scored re-audit exist."
            ),
            "next_actions": [
                "source another ePK protein-substrate positive or pre-register a ligand-analog admissibility policy",
                "do not use m_csa:640 ligand-analog evidence as production scoring support",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: _entry_id_sort_key(str(row.get("entry_id") or "")),
        ),
        "warnings": [
            (
                "Ligand-analog acceptor context is review-only policy evidence, "
                "not production ePK scoring evidence."
            )
        ],
    }


def build_epk_protein_substrate_positive_source_triage(
    *,
    active_learning_queue: dict[str, Any],
    geometry_features: dict[str, Any],
    geometry_retrieval: dict[str, Any],
    epk_positive_fingerprint_readiness_packet: dict[str, Any],
    epk_protein_substrate_acceptor_candidate_audit: dict[str, Any],
    max_rows: int = 10,
) -> dict[str, Any]:
    """Triage additional review-only ePK rows for protein-substrate coverage."""

    queue_meta = active_learning_queue.get("metadata", {})
    if not isinstance(queue_meta, dict):
        queue_meta = {}
    geometry_meta = geometry_features.get("metadata", {})
    if not isinstance(geometry_meta, dict):
        geometry_meta = {}
    retrieval_meta = geometry_retrieval.get("metadata", {})
    if not isinstance(retrieval_meta, dict):
        retrieval_meta = {}
    readiness_meta = epk_positive_fingerprint_readiness_packet.get(
        "metadata", {}
    )
    if not isinstance(readiness_meta, dict):
        readiness_meta = {}
    protein_meta = epk_protein_substrate_acceptor_candidate_audit.get(
        "metadata", {}
    )
    if not isinstance(protein_meta, dict):
        protein_meta = {}

    target_fingerprint_id = str(
        readiness_meta.get("target_fingerprint_id")
        or protein_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    known_epk_entry_ids = {
        str(row.get("entry_id"))
        for row in epk_positive_fingerprint_readiness_packet.get("rows", [])
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    known_epk_entry_ids.update(
        str(row.get("entry_id"))
        for row in epk_protein_substrate_acceptor_candidate_audit.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and row.get("row_type") == "current_epk_positive_prototype"
        and row.get("entry_id")
    )

    geometry_by_entry = {
        str(entry.get("entry_id")): entry
        for entry in geometry_features.get("entries", []) or []
        if isinstance(entry, dict) and entry.get("entry_id")
    }
    retrieval_by_entry = {
        str(result.get("entry_id")): result
        for result in geometry_retrieval.get("results", []) or []
        if isinstance(result, dict) and result.get("entry_id")
    }

    nucleotide_codes = {"ATP", "ANP", "DTP", "ACP", "ADP", "AMP", "DGP"}
    gamma_capable_codes = {"ATP", "ANP", "DTP", "ACP"}

    def _rank_value(row: dict[str, Any]) -> tuple[int, float]:
        rank = row.get("rank")
        try:
            rank_int = int(rank)
        except (TypeError, ValueError):
            rank_int = 1_000_000
        try:
            review_score = -float(row.get("review_score") or 0.0)
        except (TypeError, ValueError):
            review_score = 0.0
        return rank_int, review_score

    candidate_queue_rows = [
        row
        for row in active_learning_queue.get("rows", []) or []
        if isinstance(row, dict)
        and row.get("atp_phosphoryl_transfer_family_id") == "epk"
        and str(row.get("entry_id") or "") not in known_epk_entry_ids
    ]
    candidate_queue_rows.sort(key=_rank_value)

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    for queue_row in candidate_queue_rows[: max(0, int(max_rows))]:
        entry_id = str(queue_row.get("entry_id") or "")
        geometry_row = geometry_by_entry.get(entry_id, {})
        retrieval_row = retrieval_by_entry.get(entry_id, {})
        ligand_context = geometry_row.get("ligand_context", {})
        if not isinstance(ligand_context, dict):
            ligand_context = {}
        ligand_codes = _sorted_strings(ligand_context.get("ligand_codes", []))
        structure_ligand_codes = _sorted_strings(
            ligand_context.get("structure_ligand_codes", [])
        )
        cofactor_families = _sorted_strings(
            ligand_context.get("cofactor_families", [])
        )
        all_ligand_codes = set(ligand_codes) | set(structure_ligand_codes)
        has_local_nucleotide = bool(set(ligand_codes) & nucleotide_codes)
        has_gamma_capable_local_nucleotide = bool(
            set(ligand_codes) & gamma_capable_codes
        )
        has_product_state_nucleotide = bool(
            "ADP" in set(ligand_codes) and not has_gamma_capable_local_nucleotide
        )
        has_local_metal = "metal_ion" in cofactor_families
        snippets = queue_row.get("mechanism_text_snippets", []) or []
        snippets_text = " ".join(str(snippet).lower() for snippet in snippets)
        protein_substrate_review_context = any(
            token in snippets_text
            for token in ["protein", "serine", "threonine", "tyrosine", "ser "]
        )
        top_fingerprints = retrieval_row.get("top_fingerprints", [])
        top1 = top_fingerprints[0] if top_fingerprints else {}
        if not isinstance(top1, dict):
            top1 = {}

        if has_gamma_capable_local_nucleotide and has_local_metal:
            triage_decision = (
                "candidate_needs_acceptor_geometry_review_before_measurement"
            )
            priority_bucket = "highest_existing_gamma_metal_context"
        elif has_product_state_nucleotide and has_local_metal:
            triage_decision = "product_state_atp_repair_candidate_review_only"
            priority_bucket = "first_alternate_atp_state_repair_target"
        elif all_ligand_codes:
            triage_decision = "selected_structure_ligand_axis_missing_review_only"
            priority_bucket = "needs_active_state_ligand_source"
        else:
            triage_decision = "selected_structure_no_ligand_axis_review_only"
            priority_bucket = "needs_structure_or_ligand_source"
        measurement_ready = False
        decision_counts[triage_decision] += 1

        rows.append(
            {
                "entry_id": entry_id,
                "entry_name": queue_row.get("entry_name"),
                "rank": queue_row.get("rank"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "text_free_predictive_use_ready": False,
                "review_context_only_used_for_sourcing": True,
                "mechanism_text_snippets": snippets,
                "mechanism_text_used_for_sourcing_only": bool(snippets),
                "protein_substrate_review_context": protein_substrate_review_context,
                "geometry_status": geometry_row.get("status"),
                "pdb_id": geometry_row.get("pdb_id"),
                "resolved_residue_count": geometry_row.get("resolved_residue_count"),
                "local_ligand_codes": ligand_codes,
                "structure_ligand_codes": structure_ligand_codes,
                "local_cofactor_families": cofactor_families,
                "has_local_nucleotide": has_local_nucleotide,
                "has_gamma_capable_local_nucleotide": (
                    has_gamma_capable_local_nucleotide
                ),
                "has_product_state_nucleotide": has_product_state_nucleotide,
                "has_local_metal": has_local_metal,
                "top1_fingerprint_id": top1.get("fingerprint_id")
                or queue_row.get("top1_fingerprint_id"),
                "top1_score": top1.get("score"),
                "top1_counterevidence_reasons": top1.get(
                    "counterevidence_reasons",
                    [],
                ),
                "triage_decision": triage_decision,
                "priority_bucket": priority_bucket,
                "measurement_ready": measurement_ready,
                "epk_score_computed": False,
                "remaining_blockers": [
                    "not_in_current_epk_readiness_packet",
                    "active_state_gamma_geometry_not_measured",
                    "acceptor_identity_not_reviewed",
                    "external_hard_negative_reaudit_not_real_scorer",
                ],
            }
        )

    product_state_candidates = [
        row
        for row in rows
        if row.get("triage_decision")
        == "product_state_atp_repair_candidate_review_only"
    ]
    measurement_ready_count = sum(1 for row in rows if row.get("measurement_ready"))
    return {
        "metadata": {
            "method": "epk_protein_substrate_positive_source_triage",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_active_learning_queue_method": queue_meta.get("method"),
            "source_geometry_features_artifact": geometry_meta.get("artifact")
            or geometry_meta.get("method"),
            "source_geometry_retrieval_method": retrieval_meta.get("method"),
            "source_epk_positive_fingerprint_readiness_packet_method": (
                readiness_meta.get("method")
            ),
            "source_epk_protein_substrate_acceptor_candidate_audit_method": (
                protein_meta.get("method")
            ),
            "known_epk_readiness_entry_ids": sorted(
                known_epk_entry_ids, key=_entry_id_sort_key
            ),
            "candidate_row_count": len(rows),
            "measurement_ready_candidate_count": measurement_ready_count,
            "product_state_repair_candidate_count": len(product_state_candidates),
            "product_state_repair_candidate_entry_ids": [
                row.get("entry_id") for row in product_state_candidates
            ],
            "triage_decision_counts": dict(sorted(decision_counts.items())),
            "recommended_next_entry_id": (
                product_state_candidates[0].get("entry_id")
                if product_state_candidates
                else (rows[0].get("entry_id") if rows else None)
            ),
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact triages additional active-learning ePK-family rows "
                "only as source candidates for the protein-substrate coverage gap. "
                "Mechanism text is review context for sourcing, not predictive "
                "scoring evidence."
            ),
            "next_actions": [
                "review the product-state ADP/Mg candidate for alternate ATP-state gamma geometry first",
                "keep all source-triage rows non-countable until active-site geometry and gates pass",
                "do not use mechanism text as predictive ePK scoring evidence",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("priority_bucket") or ""),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
            ),
        ),
        "warnings": [
            (
                "Source triage rows are not ePK labels, scores, or held-out "
                "performance evidence."
            )
        ],
    }


def build_epk_m_csa760_atp_state_repair_scan(
    *,
    epk_protein_substrate_positive_source_triage: dict[str, Any],
    review_debt_remediation: dict[str, Any],
    entry_id: str = "m_csa:760",
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Scan the m_csa:760 alternate structures for combined ATP/substrate context."""

    triage_meta = epk_protein_substrate_positive_source_triage.get("metadata", {})
    if not isinstance(triage_meta, dict):
        triage_meta = {}
    remediation_meta = review_debt_remediation.get("metadata", {})
    if not isinstance(remediation_meta, dict):
        remediation_meta = {}
    target_fingerprint_id = str(
        triage_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_text_by_pdb = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }

    triage_by_entry = {
        str(row.get("entry_id")): row
        for row in epk_protein_substrate_positive_source_triage.get("rows", [])
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    remediation_by_entry = {
        str(row.get("entry_id")): row
        for row in review_debt_remediation.get("rows", []) or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    triage_row = triage_by_entry.get(entry_id, {})
    remediation_row = remediation_by_entry.get(entry_id, {})

    selected_pdb_id = str(
        remediation_row.get("selected_pdb_id")
        or triage_row.get("pdb_id")
        or ""
    ).upper()
    candidate_pdb_ids = _sorted_strings(
        remediation_row.get("candidate_pdb_structure_ids", [])
    )
    if selected_pdb_id and selected_pdb_id not in candidate_pdb_ids:
        candidate_pdb_ids = [selected_pdb_id, *candidate_pdb_ids]
    if not candidate_pdb_ids and triage_row.get("pdb_id"):
        candidate_pdb_ids = [str(triage_row.get("pdb_id")).upper()]

    residue_positions_by_pdb = {
        str(pdb_id).upper(): _review_debt_normalized_residue_positions(positions)
        for pdb_id, positions in (
            remediation_row.get("candidate_pdb_residue_positions", {}) or {}
        ).items()
        if isinstance(positions, list)
    }
    substrate_acceptor_hint = _epk_substrate_acceptor_hint_from_text(
        triage_row.get("mechanism_text_snippets", [])
    )
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    nucleotide_codes = gamma_capable_codes | {"ADP", "AMP", "DGP"}

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    for pdb_id in candidate_pdb_ids:
        pdb_id_upper = str(pdb_id).upper()
        row_base: dict[str, Any] = {
            "entry_id": entry_id,
            "entry_name": triage_row.get("entry_name")
            or remediation_row.get("entry_name"),
            "pdb_id": pdb_id_upper,
            "is_selected_structure": pdb_id_upper == selected_pdb_id,
            "target_fingerprint_id": target_fingerprint_id,
            "review_only": True,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "substrate_acceptor_hint": substrate_acceptor_hint,
            "mechanism_text_used_for_review_context_only": bool(
                substrate_acceptor_hint
            ),
        }
        cif_text = cif_text_by_pdb.get(pdb_id_upper)
        fetch_status = "provided_cif_text" if cif_text is not None else "fetched_rcsb_cif"
        try:
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id_upper)
            atoms = parse_atom_site_loop(cif_text)
        except Exception as exc:
            decision = "structure_fetch_failed_review_only"
            decision_counts[decision] += 1
            rows.append(
                {
                    **row_base,
                    "fetch_status": "failed",
                    "fetch_error": str(exc),
                    "structure_ligand_codes": [],
                    "local_ligand_codes": [],
                    "local_cofactor_families": [],
                    "residue_position_source": "none",
                    "local_resolved_residue_count": 0,
                    "has_local_gamma_capable_nucleotide": False,
                    "has_local_product_state_nucleotide": False,
                    "has_local_metal": False,
                    "has_non_catalytic_substrate_acceptor_hint": False,
                    "non_catalytic_substrate_acceptor_hint_chains": [],
                    "measurement_ready": False,
                    "repair_scan_decision": decision,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue

        inventory = structure_ligand_inventory_from_atoms(atoms)
        explicit_positions = residue_positions_by_pdb.get(pdb_id_upper, [])
        remap_result = {"positions": [], "basis": None, "warnings": []}
        residue_position_source = "none"
        active_positions = explicit_positions
        if explicit_positions:
            residue_position_source = "mcsa_explicit"
        elif _review_debt_reference_residue_positions(
            residue_positions_by_pdb, selected_pdb_id
        ):
            remap_result = _review_debt_infer_residue_positions(
                atoms,
                residue_positions_by_pdb,
                selected_pdb_id=selected_pdb_id,
            )
            active_positions = _review_debt_normalized_residue_positions(
                remap_result.get("positions", []) or []
            )
            if active_positions:
                residue_position_source = "selected_position_remap"

        local_positions_by_pdb = dict(residue_positions_by_pdb)
        if active_positions:
            local_positions_by_pdb[pdb_id_upper] = active_positions
        local_context = _review_debt_local_ligand_context(
            atoms,
            pdb_id_upper,
            local_positions_by_pdb,
        )
        local_ligand_codes = _sorted_strings(local_context.get("ligand_codes", []))
        local_cofactor_families = _sorted_strings(
            local_context.get("cofactor_families", [])
        )
        catalytic_chains = _sorted_strings(
            position.get("chain_name") for position in active_positions
        )
        acceptor_chains = _epk_substrate_acceptor_hint_chains(
            atoms,
            substrate_acceptor_hint,
            catalytic_chains=set(catalytic_chains),
        )
        has_gamma = bool(set(local_ligand_codes) & gamma_capable_codes)
        has_product_state = bool(
            "ADP" in set(local_ligand_codes) and not has_gamma
        )
        has_local_nucleotide = bool(set(local_ligand_codes) & nucleotide_codes)
        has_metal = "metal_ion" in set(local_cofactor_families)
        has_acceptor = bool(acceptor_chains)
        measurement_ready = bool(
            has_gamma
            and has_metal
            and has_acceptor
            and int(local_context.get("resolved_residue_count", 0) or 0) >= 2
        )
        if measurement_ready:
            decision = "measurement_ready_review_only"
            blockers: list[str] = [
                "distance_measurement_not_yet_materialized",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_gamma and has_metal:
            decision = "atp_metal_state_without_protein_substrate_acceptor_review_only"
            blockers = [
                "protein_substrate_acceptor_not_resolved_in_atp_state_structure",
                "gamma_to_acceptor_distance_not_measurable",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_product_state and has_acceptor:
            decision = "substrate_acceptor_product_state_no_gamma_review_only"
            blockers = [
                "product_state_adp_lacks_gamma_phosphate",
                "active_state_gamma_geometry_not_measurable",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_product_state:
            decision = "product_state_no_gamma_review_only"
            blockers = [
                "product_state_adp_lacks_gamma_phosphate",
                "protein_substrate_acceptor_not_resolved",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_acceptor:
            decision = "substrate_acceptor_without_local_atp_metal_review_only"
            blockers = [
                "local_atp_metal_context_missing",
                "gamma_to_acceptor_distance_not_measurable",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        else:
            decision = "no_combined_atp_substrate_evidence_review_only"
            blockers = [
                "combined_atp_metal_and_protein_substrate_context_missing",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        decision_counts[decision] += 1

        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "structure_ligand_codes": _sorted_strings(
                    inventory.get("ligand_codes", [])
                ),
                "structure_cofactor_families": _sorted_strings(
                    inventory.get("cofactor_families", [])
                ),
                "local_ligand_codes": local_ligand_codes,
                "local_cofactor_families": local_cofactor_families,
                "local_resolved_residue_count": local_context.get(
                    "resolved_residue_count", 0
                ),
                "residue_position_source": residue_position_source,
                "residue_position_remap_basis": remap_result.get("basis"),
                "residue_position_remap_warnings": remap_result.get("warnings", []),
                "catalytic_residue_chains": catalytic_chains,
                "has_local_nucleotide": has_local_nucleotide,
                "has_local_gamma_capable_nucleotide": has_gamma,
                "has_local_product_state_nucleotide": has_product_state,
                "has_local_metal": has_metal,
                "has_non_catalytic_substrate_acceptor_hint": has_acceptor,
                "non_catalytic_substrate_acceptor_hint_chains": acceptor_chains,
                "measurement_ready": measurement_ready,
                "repair_scan_decision": decision,
                "remaining_blockers": blockers,
            }
        )

    atp_state_rows = [
        row
        for row in rows
        if row.get("has_local_gamma_capable_nucleotide") and row.get("has_local_metal")
    ]
    acceptor_rows = [
        row for row in rows if row.get("has_non_catalytic_substrate_acceptor_hint")
    ]
    combined_rows = [
        row
        for row in rows
        if row.get("has_local_gamma_capable_nucleotide")
        and row.get("has_local_metal")
        and row.get("has_non_catalytic_substrate_acceptor_hint")
    ]
    measurement_ready_rows = [row for row in rows if row.get("measurement_ready")]
    split_state_blocker = bool(atp_state_rows and acceptor_rows and not combined_rows)
    repair_status = (
        "measurement_ready_review_only"
        if measurement_ready_rows
        else "blocked_review_only_split_atp_and_substrate_context"
        if split_state_blocker
        else "blocked_review_only_no_combined_active_state_context"
    )

    return {
        "metadata": {
            "method": "epk_m_csa760_atp_state_repair_scan",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_positive_source_triage_method": (
                triage_meta.get("method")
            ),
            "source_review_debt_remediation_method": remediation_meta.get("method"),
            "entry_id": entry_id,
            "selected_pdb_id": selected_pdb_id or None,
            "candidate_pdb_count": len(rows),
            "candidate_pdb_ids": [row.get("pdb_id") for row in rows],
            "atp_metal_state_candidate_count": len(atp_state_rows),
            "atp_metal_state_candidate_pdb_ids": [
                row.get("pdb_id") for row in atp_state_rows
            ],
            "protein_substrate_acceptor_context_candidate_count": len(acceptor_rows),
            "protein_substrate_acceptor_context_candidate_pdb_ids": [
                row.get("pdb_id") for row in acceptor_rows
            ],
            "combined_atp_metal_substrate_context_candidate_count": len(
                combined_rows
            ),
            "combined_atp_metal_substrate_context_candidate_pdb_ids": [
                row.get("pdb_id") for row in combined_rows
            ],
            "measurement_ready_candidate_count": len(measurement_ready_rows),
            "measurement_ready_candidate_pdb_ids": [
                row.get("pdb_id") for row in measurement_ready_rows
            ],
            "split_state_blocker_detected": split_state_blocker,
            "repair_status": repair_status,
            "ready_to_measure_gamma_acceptor_distance": bool(measurement_ready_rows),
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "repair_scan_decision_counts": dict(sorted(decision_counts.items())),
            "review_only_rule": (
                "This artifact uses m_csa:760 alternate structures only to test "
                "whether product-state ADP/Mg evidence can be repaired into a "
                "combined ATP/Mg plus protein-substrate acceptor geometry. "
                "Mechanism text may identify a substrate-residue hint for review "
                "context, but no ePK score, registry edit, label import, or "
                "held-out claim is produced."
            ),
            "next_actions": [
                "do not count m_csa:760 until a combined ATP/Mg plus protein-substrate acceptor structure or pre-registered analog policy exists",
                "if no combined m_csa:760 structure is sourced, pivot protein-substrate coverage repair to m_csa:757 or m_csa:756",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                0 if row.get("is_selected_structure") else 1,
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "m_csa:760 ATP-state repair evidence is review-only and cannot "
                "be used as production ePK scoring evidence."
            )
        ],
    }


def _epk_homomeric_same_residue_position_candidates(
    atoms: list[dict[str, Any]],
    source_positions: list[dict[str, Any]],
) -> list[list[dict[str, Any]]]:
    if not source_positions:
        return []
    chain_residue_keys: set[tuple[str, str, str]] = set()
    for atom in atoms:
        if atom.get("group_PDB") != "ATOM":
            continue
        chain = atom.get("auth_asym_id") or atom.get("label_asym_id")
        if chain in {None, "", ".", "?"}:
            continue
        code = str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
        if not code:
            continue
        for seq_id in [atom.get("auth_seq_id"), atom.get("label_seq_id")]:
            if seq_id in {None, "", ".", "?"}:
                continue
            chain_residue_keys.add((str(chain), code, str(seq_id)))

    candidates: list[list[dict[str, Any]]] = []
    for chain in sorted({key[0] for key in chain_residue_keys}):
        positions: list[dict[str, Any]] = []
        for source_position in source_positions:
            code = str(source_position.get("code") or "").upper()
            resid = str(source_position.get("resid") or "")
            if not code or not resid:
                positions = []
                break
            if (chain, code, resid) not in chain_residue_keys:
                positions = []
                break
            positions.append({**source_position, "chain_name": chain})
        if positions:
            candidates.append(positions)
    return candidates


def _epk_select_positions_by_ligand_context(
    atoms: list[dict[str, Any]],
    pdb_id: str,
    candidate_positions: list[list[dict[str, Any]]],
    gamma_capable_codes: set[str],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    best_positions: list[dict[str, Any]] = []
    best_context: dict[str, Any] = {}
    best_score: tuple[int, int, int, int] | None = None
    for positions in candidate_positions:
        context = _review_debt_local_ligand_context(
            atoms,
            pdb_id,
            {pdb_id: positions},
        )
        ligand_codes = set(context.get("ligand_codes", []))
        cofactor_families = set(context.get("cofactor_families", []))
        score = (
            int(bool(ligand_codes & gamma_capable_codes)),
            int("metal_ion" in cofactor_families),
            len(ligand_codes),
            int(context.get("resolved_residue_count", 0) or 0),
        )
        if best_score is None or score > best_score:
            best_score = score
            best_positions = positions
            best_context = context
    return best_positions, best_context


def build_epk_m_csa757_active_state_repair_scan(
    *,
    epk_protein_substrate_positive_source_triage: dict[str, Any],
    review_debt_remediation: dict[str, Any],
    entry_id: str = "m_csa:757",
    max_pdbs: int | None = 25,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Scan m_csa:757 alternates for active-state ePK source-repair evidence."""

    triage_meta = epk_protein_substrate_positive_source_triage.get("metadata", {})
    if not isinstance(triage_meta, dict):
        triage_meta = {}
    remediation_meta = review_debt_remediation.get("metadata", {})
    if not isinstance(remediation_meta, dict):
        remediation_meta = {}
    target_fingerprint_id = str(
        triage_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_text_by_pdb = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    triage_by_entry = {
        str(row.get("entry_id")): row
        for row in epk_protein_substrate_positive_source_triage.get("rows", [])
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    remediation_by_entry = {
        str(row.get("entry_id")): row
        for row in review_debt_remediation.get("rows", []) or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    triage_row = triage_by_entry.get(entry_id, {})
    remediation_row = remediation_by_entry.get(entry_id, {})
    selected_pdb_id = str(
        remediation_row.get("selected_pdb_id")
        or triage_row.get("pdb_id")
        or ""
    ).upper()
    all_candidate_pdb_ids = _sorted_strings(
        remediation_row.get("candidate_pdb_structure_ids", [])
    )
    if selected_pdb_id and selected_pdb_id not in all_candidate_pdb_ids:
        all_candidate_pdb_ids = [selected_pdb_id, *all_candidate_pdb_ids]
    if not all_candidate_pdb_ids and triage_row.get("pdb_id"):
        all_candidate_pdb_ids = [str(triage_row.get("pdb_id")).upper()]
    candidate_pdb_ids = (
        all_candidate_pdb_ids[:max_pdbs]
        if max_pdbs is not None and max_pdbs >= 0
        else all_candidate_pdb_ids
    )
    residue_positions_by_pdb = {
        str(pdb_id).upper(): _review_debt_normalized_residue_positions(positions)
        for pdb_id, positions in (
            remediation_row.get("candidate_pdb_residue_positions", {}) or {}
        ).items()
        if isinstance(positions, list)
    }
    source_positions = _review_debt_reference_residue_positions(
        residue_positions_by_pdb,
        selected_pdb_id,
    )
    substrate_acceptor_hint = _epk_substrate_acceptor_hint_from_text(
        triage_row.get("mechanism_text_snippets", [])
    )
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    nucleotide_codes = gamma_capable_codes | {"ADP", "AMP", "DGP"}
    phosphoacceptor_like_codes = {"SEP", "TPO", "PTR"}

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    for pdb_id in candidate_pdb_ids:
        pdb_id_upper = str(pdb_id).upper()
        row_base: dict[str, Any] = {
            "entry_id": entry_id,
            "entry_name": triage_row.get("entry_name")
            or remediation_row.get("entry_name"),
            "pdb_id": pdb_id_upper,
            "is_selected_structure": pdb_id_upper == selected_pdb_id,
            "target_fingerprint_id": target_fingerprint_id,
            "review_only": True,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "substrate_acceptor_hint": substrate_acceptor_hint,
            "mechanism_text_used_for_review_context_only": bool(
                substrate_acceptor_hint
            ),
        }
        cif_text = cif_text_by_pdb.get(pdb_id_upper)
        fetch_status = "provided_cif_text" if cif_text is not None else "fetched_rcsb_cif"
        try:
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id_upper)
            atoms = parse_atom_site_loop(cif_text)
        except Exception as exc:
            decision = "structure_fetch_failed_review_only"
            decision_counts[decision] += 1
            rows.append(
                {
                    **row_base,
                    "fetch_status": "failed",
                    "fetch_error": str(exc),
                    "structure_ligand_codes": [],
                    "local_ligand_codes": [],
                    "local_cofactor_families": [],
                    "local_resolved_residue_count": 0,
                    "residue_position_source": "none",
                    "residue_position_remap_basis": None,
                    "residue_position_remap_warnings": [],
                    "homomeric_mapping_ambiguous": False,
                    "has_local_gamma_capable_nucleotide": False,
                    "has_local_metal": False,
                    "has_structure_phosphoacceptor_like_context": False,
                    "has_mapped_protein_substrate_acceptor": False,
                    "measurement_ready": False,
                    "repair_scan_decision": decision,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue

        inventory = structure_ligand_inventory_from_atoms(atoms)
        explicit_positions = residue_positions_by_pdb.get(pdb_id_upper, [])
        remap_result = {"positions": [], "basis": None, "warnings": []}
        residue_position_source = "none"
        active_positions = explicit_positions
        homomeric_mapping_ambiguous = False
        homomeric_candidate_count = 0
        precomputed_local_context: dict[str, Any] | None = None
        if explicit_positions:
            residue_position_source = "mcsa_explicit"
        elif source_positions:
            remap_result = _review_debt_infer_residue_positions(
                atoms,
                residue_positions_by_pdb,
                selected_pdb_id=selected_pdb_id,
            )
            active_positions = _review_debt_normalized_residue_positions(
                remap_result.get("positions", []) or []
            )
            if active_positions:
                residue_position_source = "selected_position_remap"
        if not active_positions and source_positions:
            homomeric_candidates = _epk_homomeric_same_residue_position_candidates(
                atoms,
                source_positions,
            )
            homomeric_candidate_count = len(homomeric_candidates)
            if homomeric_candidates:
                active_positions, precomputed_local_context = (
                    _epk_select_positions_by_ligand_context(
                        atoms,
                        pdb_id_upper,
                        homomeric_candidates,
                        gamma_capable_codes,
                    )
                )
                residue_position_source = (
                    "homomeric_same_residue_id_ligand_context"
                )
                homomeric_mapping_ambiguous = len(homomeric_candidates) > 1
                remap_result = {
                    "positions": active_positions,
                    "basis": "homomeric_same_residue_id_ligand_context",
                    "warnings": [
                        "homomeric_chain_choice_review_only_not_production_mapping"
                    ],
                }

        local_positions_by_pdb = dict(residue_positions_by_pdb)
        if active_positions:
            local_positions_by_pdb[pdb_id_upper] = active_positions
        local_context = precomputed_local_context or _review_debt_local_ligand_context(
            atoms,
            pdb_id_upper,
            local_positions_by_pdb,
        )
        local_ligand_codes = _sorted_strings(local_context.get("ligand_codes", []))
        local_cofactor_families = _sorted_strings(
            local_context.get("cofactor_families", [])
        )
        structure_ligand_codes = _sorted_strings(inventory.get("ligand_codes", []))
        structure_cofactor_families = _sorted_strings(
            inventory.get("cofactor_families", [])
        )
        catalytic_chains = _sorted_strings(
            position.get("chain_name") for position in active_positions
        )
        acceptor_chains = _epk_substrate_acceptor_hint_chains(
            atoms,
            substrate_acceptor_hint,
            catalytic_chains=set(catalytic_chains),
        )
        has_local_gamma = bool(set(local_ligand_codes) & gamma_capable_codes)
        has_local_nucleotide = bool(set(local_ligand_codes) & nucleotide_codes)
        has_local_metal = "metal_ion" in set(local_cofactor_families)
        has_structure_gamma = bool(set(structure_ligand_codes) & gamma_capable_codes)
        has_structure_metal = "metal_ion" in set(structure_cofactor_families)
        structure_phosphoacceptor_codes = _sorted_strings(
            set(structure_ligand_codes) & phosphoacceptor_like_codes
        )
        has_structure_phosphoacceptor = bool(structure_phosphoacceptor_codes)
        has_mapped_acceptor = bool(acceptor_chains)
        measurement_ready = bool(
            has_local_gamma
            and has_local_metal
            and has_mapped_acceptor
            and not homomeric_mapping_ambiguous
            and int(local_context.get("resolved_residue_count", 0) or 0) >= 2
        )
        if measurement_ready:
            decision = "measurement_ready_review_only"
            blockers = [
                "distance_measurement_not_yet_materialized",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif homomeric_mapping_ambiguous and has_local_gamma and has_local_metal:
            decision = (
                "homomeric_active_state_mapping_ambiguous_no_substrate_acceptor_review_only"
            )
            blockers = [
                "homomeric_chain_mapping_not_production_admissible",
                "protein_substrate_acceptor_not_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_local_gamma and has_local_metal and has_structure_phosphoacceptor:
            decision = (
                "active_state_atp_metal_with_structure_phosphoacceptor_not_substrate_mapped_review_only"
            )
            blockers = [
                "structure_phosphoacceptor_context_not_mapped_to_substrate_chain",
                "gamma_to_protein_substrate_acceptor_distance_not_measurable",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_local_gamma and has_local_metal:
            decision = "active_state_atp_metal_without_protein_substrate_acceptor_review_only"
            blockers = [
                "protein_substrate_acceptor_not_mapped",
                "gamma_to_protein_substrate_acceptor_distance_not_measurable",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_structure_gamma and has_structure_metal:
            decision = "structure_active_state_ligand_mapping_unresolved_review_only"
            blockers = [
                "active_site_residue_mapping_not_conservative",
                "protein_substrate_acceptor_not_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif has_structure_phosphoacceptor:
            decision = "phosphoacceptor_context_without_active_atp_metal_review_only"
            blockers = [
                "local_atp_metal_context_missing",
                "phosphoacceptor_context_not_mapped_to_substrate_chain",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        else:
            decision = "no_active_state_repair_signal_review_only"
            blockers = [
                "local_atp_metal_context_missing",
                "protein_substrate_acceptor_not_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        decision_counts[decision] += 1

        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "structure_ligand_codes": structure_ligand_codes,
                "structure_cofactor_families": structure_cofactor_families,
                "local_ligand_codes": local_ligand_codes,
                "local_cofactor_families": local_cofactor_families,
                "local_resolved_residue_count": local_context.get(
                    "resolved_residue_count", 0
                ),
                "residue_position_source": residue_position_source,
                "residue_position_remap_basis": remap_result.get("basis"),
                "residue_position_remap_warnings": remap_result.get("warnings", []),
                "homomeric_candidate_chain_count": homomeric_candidate_count,
                "homomeric_mapping_ambiguous": homomeric_mapping_ambiguous,
                "catalytic_residue_chains": catalytic_chains,
                "has_local_nucleotide": has_local_nucleotide,
                "has_local_gamma_capable_nucleotide": has_local_gamma,
                "has_local_metal": has_local_metal,
                "has_structure_gamma_capable_nucleotide": has_structure_gamma,
                "has_structure_metal": has_structure_metal,
                "has_structure_phosphoacceptor_like_context": (
                    has_structure_phosphoacceptor
                ),
                "structure_phosphoacceptor_like_codes": (
                    structure_phosphoacceptor_codes
                ),
                "has_mapped_protein_substrate_acceptor": has_mapped_acceptor,
                "mapped_protein_substrate_acceptor_chains": acceptor_chains,
                "measurement_ready": measurement_ready,
                "repair_scan_decision": decision,
                "remaining_blockers": blockers,
            }
        )

    active_state_rows = [
        row
        for row in rows
        if row.get("has_local_gamma_capable_nucleotide") and row.get("has_local_metal")
    ]
    conservative_active_state_rows = [
        row
        for row in active_state_rows
        if not row.get("homomeric_mapping_ambiguous")
    ]
    homomeric_active_state_rows = [
        row for row in active_state_rows if row.get("homomeric_mapping_ambiguous")
    ]
    phosphoacceptor_rows = [
        row for row in rows if row.get("has_structure_phosphoacceptor_like_context")
    ]
    mapped_acceptor_rows = [
        row for row in rows if row.get("has_mapped_protein_substrate_acceptor")
    ]
    measurement_ready_rows = [row for row in rows if row.get("measurement_ready")]
    repair_status = (
        "measurement_ready_review_only"
        if measurement_ready_rows
        else "blocked_review_only_active_state_without_mapped_substrate_acceptor"
        if active_state_rows
        else "blocked_review_only_no_active_state_atp_metal_context"
    )
    return {
        "metadata": {
            "method": "epk_m_csa757_active_state_repair_scan",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_positive_source_triage_method": (
                triage_meta.get("method")
            ),
            "source_review_debt_remediation_method": remediation_meta.get("method"),
            "entry_id": entry_id,
            "selected_pdb_id": selected_pdb_id or None,
            "candidate_pdb_count": len(all_candidate_pdb_ids),
            "scanned_candidate_pdb_count": len(rows),
            "scan_limit": max_pdbs,
            "scanned_candidate_pdb_ids": [row.get("pdb_id") for row in rows],
            "active_state_atp_metal_candidate_count": len(active_state_rows),
            "active_state_atp_metal_candidate_pdb_ids": [
                row.get("pdb_id") for row in active_state_rows
            ],
            "conservative_active_state_atp_metal_candidate_count": len(
                conservative_active_state_rows
            ),
            "conservative_active_state_atp_metal_candidate_pdb_ids": [
                row.get("pdb_id") for row in conservative_active_state_rows
            ],
            "homomeric_mapping_ambiguous_active_state_candidate_count": len(
                homomeric_active_state_rows
            ),
            "homomeric_mapping_ambiguous_active_state_candidate_pdb_ids": [
                row.get("pdb_id") for row in homomeric_active_state_rows
            ],
            "structure_phosphoacceptor_context_candidate_count": len(
                phosphoacceptor_rows
            ),
            "structure_phosphoacceptor_context_candidate_pdb_ids": [
                row.get("pdb_id") for row in phosphoacceptor_rows
            ],
            "mapped_protein_substrate_acceptor_candidate_count": len(
                mapped_acceptor_rows
            ),
            "mapped_protein_substrate_acceptor_candidate_pdb_ids": [
                row.get("pdb_id") for row in mapped_acceptor_rows
            ],
            "measurement_ready_candidate_count": len(measurement_ready_rows),
            "measurement_ready_candidate_pdb_ids": [
                row.get("pdb_id") for row in measurement_ready_rows
            ],
            "repair_status": repair_status,
            "ready_to_measure_gamma_acceptor_distance": bool(measurement_ready_rows),
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "repair_scan_decision_counts": dict(sorted(decision_counts.items())),
            "review_only_rule": (
                "This artifact scans a bounded m_csa:757 alternate-structure "
                "surface for active-state ATP/Mg evidence after m_csa:760 "
                "failed closed. Homomeric chain choices, structure-level "
                "phosphoacceptor-like residues, and mechanism text remain "
                "review-only and cannot support ePK scoring, registry edits, "
                "label import, or held-out claims."
            ),
            "next_actions": [
                "do not count m_csa:757 until a mapped protein-substrate acceptor and gamma distance exist",
                "if no m_csa:757 combined structure is sourced, pivot protein-substrate coverage repair to m_csa:756",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                0 if row.get("is_selected_structure") else 1,
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "m_csa:757 active-state repair evidence is review-only and "
                "cannot be used as production ePK scoring evidence."
            )
        ],
    }


def build_epk_m_csa756_active_state_repair_scan(
    *,
    epk_protein_substrate_positive_source_triage: dict[str, Any],
    review_debt_remediation: dict[str, Any],
    entry_id: str = "m_csa:756",
    max_pdbs: int | None = 15,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Scan m_csa:756 alternates with the same fail-closed active-state policy."""

    scan = build_epk_m_csa757_active_state_repair_scan(
        epk_protein_substrate_positive_source_triage=(
            epk_protein_substrate_positive_source_triage
        ),
        review_debt_remediation=review_debt_remediation,
        entry_id=entry_id,
        max_pdbs=max_pdbs,
        cif_text_by_pdb=cif_text_by_pdb,
        cif_fetcher=cif_fetcher,
    )
    metadata = scan["metadata"]
    metadata["method"] = "epk_m_csa756_active_state_repair_scan"
    metadata["review_only_rule"] = (
        "This artifact scans the bounded m_csa:756 alternate-structure surface "
        "after m_csa:757 remained blocked. It can identify active-state ATP/Mg "
        "or product-state leads, but homomeric chain choices, structure-level "
        "phosphoacceptor-like residues, and mechanism text remain review-only "
        "and cannot support ePK scoring, registry edits, label import, or "
        "held-out claims."
    )
    metadata["next_actions"] = [
        "do not count m_csa:756 until a mapped protein-substrate acceptor and gamma distance exist",
        "if no m_csa:756 combined structure is sourced, pause protein-substrate source repair and pre-register an analog/product-state policy before more scorer work",
        "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
    ]
    scan["warnings"] = [
        (
            "m_csa:756 active-state repair evidence is review-only and cannot "
            "be used as production ePK scoring evidence."
        )
    ]
    return scan


def build_epk_m_csa756_5li1_residue_evidence_audit(
    *,
    epk_m_csa756_active_state_repair_scan: dict[str, Any],
    review_debt_remediation: dict[str, Any],
    entry_id: str = "m_csa:756",
    pdb_id: str = "5LI1",
    candidate_residue_positions: list[dict[str, Any]] | None = None,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Audit the specific 5LI1 residue-position clue without reopening broad scans."""

    scan_meta = epk_m_csa756_active_state_repair_scan.get("metadata", {})
    if not isinstance(scan_meta, dict):
        scan_meta = {}
    remediation_meta = review_debt_remediation.get("metadata", {})
    if not isinstance(remediation_meta, dict):
        remediation_meta = {}
    target_fingerprint_id = str(
        scan_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    pdb_id_upper = str(pdb_id or "5LI1").upper()
    cif_text_by_pdb = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    if candidate_residue_positions is None:
        candidate_residue_positions = [
            {
                "chain_name": "A",
                "code": "Lys",
                "resid": 380,
                "roles": ["phosphate_binding_basic_residue_review_hint"],
            },
            {
                "chain_name": "A",
                "code": "Asp",
                "resid": 382,
                "roles": ["candidate_catalytic_base_review_hint"],
            },
            {
                "chain_name": "A",
                "code": "Asn",
                "resid": 383,
                "roles": ["metal_or_transition_state_context_review_hint"],
            },
        ]
    normalized_positions = _review_debt_normalized_residue_positions(
        candidate_residue_positions
    )

    remediation_rows = [
        row
        for row in review_debt_remediation.get("rows", []) or []
        if isinstance(row, dict) and str(row.get("entry_id") or "") == entry_id
    ]
    remediation_row = remediation_rows[0] if remediation_rows else {}
    selected_pdb_id = str(remediation_row.get("selected_pdb_id") or "").upper()
    selected_position_count = int(
        (
            remediation_row.get("candidate_pdb_residue_position_counts", {}) or {}
        ).get(selected_pdb_id, 0)
        or 0
    )
    target_position_count = int(
        (
            remediation_row.get("candidate_pdb_residue_position_counts", {}) or {}
        ).get(pdb_id_upper, 0)
        or 0
    )

    rows: list[dict[str, Any]] = []
    warnings: list[str] = []
    try:
        cif_text = cif_text_by_pdb.get(pdb_id_upper)
        fetch_status = "provided_cif_text" if cif_text is not None else "fetched_rcsb_cif"
        if cif_text is None:
            cif_text = cif_fetcher(pdb_id_upper)
        atoms = parse_atom_site_loop(cif_text)
    except Exception as exc:
        return {
            "metadata": {
                "method": "epk_m_csa756_5li1_residue_evidence_audit",
                "review_only": True,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "source_epk_m_csa756_active_state_repair_scan_method": (
                    scan_meta.get("method")
                ),
                "source_review_debt_remediation_method": remediation_meta.get(
                    "method"
                ),
                "entry_id": entry_id,
                "pdb_id": pdb_id_upper,
                "fetch_status": "failed",
                "fetch_error": str(exc),
                "candidate_residue_count": len(normalized_positions),
                "candidate_residue_resolved_count": 0,
                "active_site_residue_evidence_found": False,
                "explicit_residue_source_authority_sufficient": False,
                "mapped_protein_substrate_acceptor_candidate_count": 0,
                "measurement_ready_candidate_count": 0,
                "repair_status": "blocked_review_only_structure_fetch_failed",
                "ready_to_run_epk_scorer": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "ready_to_expand_positive_fingerprint_universe": False,
                "ready_for_label_import": False,
                "fingerprint_registry_edited": False,
                "curated_label_registry_edited": False,
                "countable_label_candidate_count": 0,
            },
            "rows": [],
            "warnings": ["5LI1 residue-evidence audit could not fetch structure."],
        }

    inventory = structure_ligand_inventory_from_atoms(atoms)
    local_context = _review_debt_local_ligand_context(
        atoms,
        pdb_id_upper,
        {pdb_id_upper: normalized_positions},
    )
    local_ligand_codes = _sorted_strings(local_context.get("ligand_codes", []))
    local_cofactor_families = _sorted_strings(
        local_context.get("cofactor_families", [])
    )
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    has_local_gamma = bool(set(local_ligand_codes) & gamma_capable_codes)
    has_local_metal = "metal_ion" in set(local_cofactor_families)
    resolved_count = int(local_context.get("resolved_residue_count") or 0)
    active_site_evidence_found = (
        resolved_count == len(normalized_positions)
        and has_local_gamma
        and has_local_metal
    )

    gamma_atoms = [
        atom
        for atom in atoms
        if atom.get("group_PDB") == "HETATM"
        and str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
        in gamma_capable_codes
        and str(atom.get("auth_atom_id") or atom.get("label_atom_id") or "").upper()
        == "PG"
    ]
    terminal_gamma_atom_detected = bool(gamma_atoms)
    noncanonical_terminal_atoms = [
        atom
        for atom in atoms
        if atom.get("group_PDB") == "HETATM"
        and str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
        in gamma_capable_codes
        and str(atom.get("auth_atom_id") or atom.get("label_atom_id") or "").upper()
        in {"PB", "P3B", "P2B"}
    ]
    noncanonical_terminal_atom_names = _sorted_strings(
        atom.get("auth_atom_id") or atom.get("label_atom_id")
        for atom in noncanonical_terminal_atoms
    )
    metal_atoms = [
        atom
        for atom in atoms
        if atom.get("group_PDB") == "HETATM"
        and _ligand_code_family(
            str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
        )
        == "metal_ion"
    ]

    for position in normalized_positions:
        residue_atoms = select_residue_atoms(
            atoms,
            chain_name=position.get("chain_name"),
            resid=position.get("resid"),
            code=position.get("code"),
        )
        gamma_distances = []
        for gamma_atom in gamma_atoms:
            gamma_point = _atom_point(gamma_atom)
            for residue_atom in residue_atoms:
                gamma_distances.append(
                    round(_point_distance(gamma_point, _atom_point(residue_atom)), 3)
                )
        metal_distances = []
        for metal_atom in metal_atoms:
            metal_point = _atom_point(metal_atom)
            for residue_atom in residue_atoms:
                metal_distances.append(
                    round(_point_distance(metal_point, _atom_point(residue_atom)), 3)
                )
        noncanonical_terminal_distances = []
        for terminal_atom in noncanonical_terminal_atoms:
            terminal_point = _atom_point(terminal_atom)
            for residue_atom in residue_atoms:
                noncanonical_terminal_distances.append(
                    round(
                        _point_distance(terminal_point, _atom_point(residue_atom)),
                        3,
                    )
                )
        residue_resolved = bool(residue_atoms)
        if residue_resolved and gamma_distances and metal_distances:
            residue_status = "resolved_near_terminal_gamma_and_metal_review_hint"
        elif residue_resolved and noncanonical_terminal_distances and metal_distances:
            residue_status = (
                "resolved_near_metal_noncanonical_terminal_atom_review_hint"
            )
        elif residue_resolved and metal_distances and not terminal_gamma_atom_detected:
            residue_status = "resolved_near_metal_no_terminal_gamma_atom_review_hint"
        elif residue_resolved:
            residue_status = "resolved_but_active_state_distance_context_incomplete"
        else:
            residue_status = "not_resolved"
        rows.append(
            {
                "row_type": "candidate_active_site_residue",
                "entry_id": entry_id,
                "pdb_id": pdb_id_upper,
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "residue_code": position.get("code"),
                "chain_name": position.get("chain_name"),
                "resid": position.get("resid"),
                "roles": position.get("roles", []),
                "residue_resolved": residue_resolved,
                "nearest_gamma_atom_distance_angstrom": (
                    min(gamma_distances) if gamma_distances else None
                ),
                "nearest_noncanonical_terminal_atom_distance_angstrom": (
                    min(noncanonical_terminal_distances)
                    if noncanonical_terminal_distances
                    else None
                ),
                "nearest_metal_atom_distance_angstrom": (
                    min(metal_distances) if metal_distances else None
                ),
                "residue_evidence_status": residue_status,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
            }
        )

    catalytic_chains = {
        str(position.get("chain_name"))
        for position in normalized_positions
        if position.get("chain_name")
    }
    phosphoacceptor_codes = {"SEP", "TPO", "PTR"}
    phosphoacceptor_rows: list[dict[str, Any]] = []
    for code in sorted(phosphoacceptor_codes):
        residue_keys: set[tuple[str, str]] = set()
        for atom in atoms:
            atom_code = str(
                atom.get("auth_comp_id") or atom.get("label_comp_id") or ""
            ).upper()
            if atom_code != code:
                continue
            chain = str(atom.get("auth_asym_id") or atom.get("label_asym_id") or "")
            resid = str(atom.get("auth_seq_id") or atom.get("label_seq_id") or "")
            if not chain or not resid:
                continue
            residue_keys.add((chain, resid))
        for chain, resid in sorted(residue_keys):
            phosphoacceptor_rows.append(
                {
                    "row_type": "structure_phosphoacceptor_like_context",
                    "entry_id": entry_id,
                    "pdb_id": pdb_id_upper,
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "residue_code": code,
                    "chain_name": chain,
                    "resid": resid,
                    "non_catalytic_chain": chain not in catalytic_chains,
                    "mapped_as_protein_substrate_acceptor": False,
                    "mapping_status": "structure_level_phosphoacceptor_not_source_mapped",
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                }
            )
    rows.extend(phosphoacceptor_rows)
    if phosphoacceptor_rows:
        warnings.append(
            "5LI1 has structure-level SEP/TPO context, but it is not source-mapped "
            "as a protein-substrate acceptor for ePK scoring."
        )
    if target_position_count == 0:
        warnings.append(
            "5LI1 still lacks committed source residue positions; review-hint "
            "residues are not production scoring evidence."
        )

    explicit_source_authority_sufficient = target_position_count > 0
    mapped_acceptor_count = 0
    measurement_ready = (
        active_site_evidence_found
        and explicit_source_authority_sufficient
        and mapped_acceptor_count > 0
    )
    if measurement_ready:
        repair_status = "measurement_ready_review_only"
    elif active_site_evidence_found and not terminal_gamma_atom_detected:
        repair_status = (
            "blocked_review_only_residue_evidence_lacks_terminal_gamma_atom_no_mapped_acceptor"
        )
    elif active_site_evidence_found:
        repair_status = (
            "blocked_review_only_residue_evidence_not_source_authoritative_no_mapped_acceptor"
        )
    else:
        repair_status = "blocked_review_only_active_site_residue_evidence_incomplete"

    return {
        "metadata": {
            "method": "epk_m_csa756_5li1_residue_evidence_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_m_csa756_active_state_repair_scan_method": (
                scan_meta.get("method")
            ),
            "source_review_debt_remediation_method": remediation_meta.get("method"),
            "entry_id": entry_id,
            "pdb_id": pdb_id_upper,
            "selected_pdb_id": selected_pdb_id or None,
            "fetch_status": fetch_status,
            "structure_ligand_codes": _sorted_strings(
                inventory.get("ligand_codes", [])
            ),
            "structure_cofactor_families": _sorted_strings(
                inventory.get("cofactor_families", [])
            ),
            "local_ligand_codes": local_ligand_codes,
            "local_cofactor_families": local_cofactor_families,
            "candidate_residue_count": len(normalized_positions),
            "candidate_residue_resolved_count": resolved_count,
            "selected_structure_source_residue_position_count": selected_position_count,
            "target_structure_source_residue_position_count": target_position_count,
            "local_gamma_capable_nucleotide_detected": has_local_gamma,
            "terminal_gamma_atom_detected": terminal_gamma_atom_detected,
            "noncanonical_terminal_atom_names_detected": (
                noncanonical_terminal_atom_names
            ),
            "noncanonical_terminal_atom_policy_admissible": False,
            "local_metal_detected": has_local_metal,
            "active_site_residue_evidence_found": active_site_evidence_found,
            "explicit_residue_source_authority_sufficient": (
                explicit_source_authority_sufficient
            ),
            "structure_phosphoacceptor_like_context_count": len(phosphoacceptor_rows),
            "mapped_protein_substrate_acceptor_candidate_count": mapped_acceptor_count,
            "measurement_ready_candidate_count": 1 if measurement_ready else 0,
            "repair_status": repair_status,
            "ready_to_measure_gamma_acceptor_distance": measurement_ready,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "active_state_terminal_gamma_atom_not_materialized"
                if not terminal_gamma_atom_detected
                else "gamma_atom_present_but_acceptor_not_mapped",
                "5li1_residue_positions_not_source_authoritative"
                if not explicit_source_authority_sufficient
                else "source_residue_position_authority_requires_review",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
                "threshold_not_calibrated_against_negative_controls",
            ],
            "review_only_rule": (
                "This artifact audits the specific 5LI1 residue-position clue "
                "after the broad m_csa:756 scan failed. It can preserve local "
                "active-state residue evidence, but review-hint residues and "
                "structure-level phosphoacceptor context are not production "
                "ePK scoring evidence."
            ),
            "next_actions": [
                "obtain source-authoritative 5LI1 residue positions before any m_csa:756 rescue",
                "map a protein-substrate acceptor chain or leave m_csa:756 excluded",
                "keep analog/product-state policy inactive until scored controls pass",
            ],
        },
        "rows": rows,
        "warnings": warnings,
    }


def build_epk_protein_substrate_source_repair_terminal_decision(
    *,
    epk_protein_substrate_positive_source_triage: dict[str, Any],
    epk_m_csa760_atp_state_repair_scan: dict[str, Any],
    epk_m_csa757_active_state_repair_scan: dict[str, Any],
    epk_m_csa756_active_state_repair_scan: dict[str, Any],
    epk_ligand_analog_policy_blocker_decision: dict[str, Any],
) -> dict[str, Any]:
    """Consolidate exhausted ePK protein-substrate source repairs."""

    triage_meta = epk_protein_substrate_positive_source_triage.get("metadata", {})
    if not isinstance(triage_meta, dict):
        triage_meta = {}
    analog_meta = epk_ligand_analog_policy_blocker_decision.get("metadata", {})
    if not isinstance(analog_meta, dict):
        analog_meta = {}
    target_fingerprint_id = str(
        triage_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    source_scans = [
        epk_m_csa760_atp_state_repair_scan,
        epk_m_csa757_active_state_repair_scan,
        epk_m_csa756_active_state_repair_scan,
    ]
    rows: list[dict[str, Any]] = []
    measurement_ready_total = 0
    active_state_lead_total = 0
    mapped_acceptor_total = 0
    for scan in source_scans:
        meta = scan.get("metadata", {}) if isinstance(scan, dict) else {}
        if not isinstance(meta, dict) or not meta.get("method"):
            continue
        measurement_ready_count = int(
            meta.get("measurement_ready_candidate_count") or 0
        )
        active_state_count = int(
            meta.get("active_state_atp_metal_candidate_count")
            or meta.get("atp_metal_state_candidate_count")
            or 0
        )
        mapped_acceptor_count = int(
            meta.get("mapped_protein_substrate_acceptor_candidate_count")
            or meta.get("protein_substrate_acceptor_context_candidate_count")
            or 0
        )
        measurement_ready_total += measurement_ready_count
        active_state_lead_total += active_state_count
        mapped_acceptor_total += mapped_acceptor_count
        entry_id = str(meta.get("entry_id") or "")
        if measurement_ready_count:
            decision = "measurement_ready_follow_up_required_review_only"
        elif entry_id == "m_csa:760" and meta.get("split_state_blocker_detected"):
            decision = "terminal_split_state_blocked_review_only"
        elif active_state_count and not mapped_acceptor_count:
            decision = "terminal_active_state_without_mapped_acceptor_review_only"
        elif active_state_count:
            decision = "terminal_active_state_not_measurement_ready_review_only"
        else:
            decision = "terminal_no_conservative_active_state_context_review_only"
        rows.append(
            {
                "entry_id": entry_id,
                "source_method": meta.get("method"),
                "repair_status": meta.get("repair_status"),
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "active_state_or_atp_metal_candidate_count": active_state_count,
                "mapped_or_context_acceptor_candidate_count": mapped_acceptor_count,
                "measurement_ready_candidate_count": measurement_ready_count,
                "decision": decision,
                "remaining_blockers": [
                    "protein_substrate_acceptor_geometry_not_measurement_ready",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "threshold_not_calibrated_against_negative_controls",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    current_source_candidates_exhausted = bool(rows) and measurement_ready_total == 0
    terminal_decision = (
        "current_source_candidates_exhausted_review_only"
        if current_source_candidates_exhausted
        else "measurement_ready_source_repair_requires_distance_review"
    )
    return {
        "metadata": {
            "method": "epk_protein_substrate_source_repair_terminal_decision",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_positive_source_triage_method": (
                triage_meta.get("method")
            ),
            "source_epk_ligand_analog_policy_blocker_decision_method": (
                analog_meta.get("method")
            ),
            "source_candidate_entry_ids": [row["entry_id"] for row in rows],
            "source_candidate_count": len(rows),
            "active_state_or_atp_metal_candidate_count": active_state_lead_total,
            "mapped_or_context_acceptor_candidate_count": mapped_acceptor_total,
            "measurement_ready_candidate_count": measurement_ready_total,
            "current_source_candidates_exhausted": current_source_candidates_exhausted,
            "terminal_decision": terminal_decision,
            "recommended_next_experiment": (
                "pre_register_ligand_analog_or_product_state_policy_or_source_new_epk_positive"
                if current_source_candidates_exhausted
                else "measure_ready_source_repair_distances"
            ),
            "ligand_analog_policy_decision": analog_meta.get(
                "ligand_analog_policy_decision"
            ),
            "ligand_analog_production_admissible_count": analog_meta.get(
                "ligand_analog_production_admissible_count"
            ),
            "ready_to_measure_gamma_acceptor_distance": measurement_ready_total > 0,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact closes the current bounded ePK protein-substrate "
                "source-repair loop as a negative result only. It does not make "
                "clean held-out claims, select a threshold, score external hard "
                "negatives, edit registries, or import labels."
            ),
            "next_actions": [
                "do not repeat m_csa:760, m_csa:757, or m_csa:756 scans without new evidence",
                "pre-register any ligand-analog or product-state admissibility policy before using it in scorer calibration",
                "source a new ePK protein-substrate positive only if it adds clear scientific value",
            ],
        },
        "rows": sorted(rows, key=lambda row: _entry_id_sort_key(row["entry_id"])),
        "warnings": [
            (
                "The current source-repair loop is negative review evidence, not "
                "production ePK scoring evidence."
            )
        ],
    }


def _epk_uniprot_protein_phosphotransfer_comment(
    comment: dict[str, Any],
) -> bool:
    reaction = str(comment.get("reaction") or "").lower()
    return (
        "protein" in reaction
        and "atp" in reaction
        and ("phospho" in reaction or "phosphoryl" in reaction)
    )


def _epk_uniprot_acceptor_terms(comments: list[dict[str, Any]]) -> list[str]:
    terms: set[str] = set()
    for comment in comments:
        reaction = str(comment.get("reaction") or "").lower()
        if "l-seryl-[protein]" in reaction:
            terms.add("seryl_protein")
        if "l-threonyl-[protein]" in reaction:
            terms.add("threonyl_protein")
        if "l-tyrosyl-[protein]" in reaction:
            terms.add("tyrosyl_protein")
        if "[protein]" in reaction and not terms:
            terms.add("protein_acceptor_unspecified")
    return sorted(terms)


def _epk_uniprot_evidence_codes(items: list[dict[str, Any]]) -> list[str]:
    codes: set[str] = set()
    for item in items:
        for evidence in item.get("evidence", []) or []:
            if isinstance(evidence, dict) and evidence.get("evidence_code"):
                codes.add(str(evidence["evidence_code"]))
    return sorted(codes)


def build_epk_external_protein_substrate_source_scout(
    *,
    epk_protein_substrate_source_repair_terminal_decision: dict[str, Any],
    query_payloads_by_lane: dict[str, dict[str, Any]],
    entry_records_by_accession: dict[str, dict[str, Any]],
    existing_label_records: list[dict[str, Any]] | None = None,
    max_candidates: int = 8,
) -> dict[str, Any]:
    """Scout external ePK positive source rows without opening count growth."""

    if max_candidates < 1:
        raise ValueError("max_candidates must be positive")

    terminal_meta = epk_protein_substrate_source_repair_terminal_decision.get(
        "metadata", {}
    )
    if not isinstance(terminal_meta, dict):
        terminal_meta = {}
    target_fingerprint_id = str(
        terminal_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    existing_label_entry_ids = {
        str(record.get("entry_id"))
        for record in existing_label_records or []
        if isinstance(record, dict) and record.get("entry_id")
    }
    normalized_entry_records = {
        str(accession).upper(): record
        for accession, record in entry_records_by_accession.items()
        if accession and isinstance(record, dict)
    }

    rows: list[dict[str, Any]] = []
    seen_accessions: set[str] = set()
    blocker_counts: Counter[str] = Counter()
    status_counts: Counter[str] = Counter()
    fetched_record_count = 0
    entry_fetch_available_count = 0
    query_metadata: list[dict[str, Any]] = []

    for lane_id in sorted(query_payloads_by_lane):
        payload = query_payloads_by_lane[lane_id] or {}
        metadata = payload.get("metadata", {})
        if not isinstance(metadata, dict):
            metadata = {}
        query_metadata.append(
            {
                "lane_id": lane_id,
                "query": metadata.get("query"),
                "record_count": metadata.get("record_count")
                or len(payload.get("records", []) or []),
            }
        )
        for sample_row in payload.get("records", []) or []:
            if not isinstance(sample_row, dict):
                continue
            accession = str(sample_row.get("accession") or "").upper()
            if not accession or accession in seen_accessions:
                continue
            seen_accessions.add(accession)
            fetched_record_count += 1
            entry_id = f"uniprot:{accession}"
            record = normalized_entry_records.get(accession)
            if record:
                entry_fetch_available_count += 1

            active_features = [
                feature
                for feature in (record or {}).get("active_site_features", []) or []
                if isinstance(feature, dict)
            ]
            binding_features = [
                feature
                for feature in (record or {}).get("binding_site_features", []) or []
                if isinstance(feature, dict)
            ]
            catalytic_comments = [
                comment
                for comment in (record or {}).get("catalytic_activity_comments", [])
                or []
                if isinstance(comment, dict)
            ]
            cofactor_comments = [
                comment
                for comment in (record or {}).get("cofactor_comments", []) or []
                if isinstance(comment, dict)
            ]
            atp_binding_features = [
                feature
                for feature in binding_features
                if "atp"
                in " ".join(
                    str(feature.get(key) or "")
                    for key in ("description", "ligand_name", "ligand_note")
                ).lower()
            ]
            metal_binding_features = [
                feature
                for feature in binding_features
                if any(
                    token
                    in " ".join(
                        str(feature.get(key) or "")
                        for key in ("description", "ligand_name", "ligand_note")
                    ).lower()
                    for token in ("mg", "mn", "metal", "magnesium", "manganese")
                )
            ]
            protein_phosphotransfer_comments = [
                comment
                for comment in catalytic_comments
                if _epk_uniprot_protein_phosphotransfer_comment(comment)
            ]
            acceptor_terms = _epk_uniprot_acceptor_terms(
                protein_phosphotransfer_comments
            )
            active_site_evidence_codes = _epk_uniprot_evidence_codes(
                active_features
            )
            atp_binding_evidence_codes = _epk_uniprot_evidence_codes(
                atp_binding_features
            )
            phosphotransfer_evidence_codes = _epk_uniprot_evidence_codes(
                protein_phosphotransfer_comments
            )
            all_source_evidence_codes = sorted(
                set(active_site_evidence_codes)
                | set(atp_binding_evidence_codes)
                | set(phosphotransfer_evidence_codes)
            )
            direct_experimental_evidence_codes = sorted(
                code for code in all_source_evidence_codes if code == "ECO:0000269"
            )
            source_evidence_strength_status = (
                "direct_experimental_source_context_present"
                if direct_experimental_evidence_codes
                else "homology_or_rule_based_source_context_review_only"
                if all_source_evidence_codes
                else "source_evidence_codes_missing"
            )
            has_structure_reference = bool(
                sample_row.get("pdb_ids") or sample_row.get("alphafold_ids")
            )
            reviewed = str(sample_row.get("reviewed") or "").lower() == "reviewed"

            blockers: list[str] = []
            if entry_id in existing_label_entry_ids:
                blockers.append("existing_curated_label_entry")
            if not reviewed:
                blockers.append("reviewed_swissprot_record_required")
            if not has_structure_reference:
                blockers.append("structure_reference_missing")
            if not record:
                blockers.append("uniprot_entry_feature_not_fetched")
            if record and not active_features:
                blockers.append("uniprot_active_site_feature_missing")
            if record and not atp_binding_features:
                blockers.append("atp_binding_feature_missing")
            if record and not protein_phosphotransfer_comments:
                blockers.append("protein_phosphotransfer_catalytic_activity_missing")
            if record and protein_phosphotransfer_comments and not acceptor_terms:
                blockers.append("protein_acceptor_scope_missing")

            if not blockers:
                sourcing_status = "sourced_pending_structure_mapping_review"
                next_action = (
                    "map UniProt active-site and ATP-binding residue positions "
                    "onto a selected structure before any distance measurement"
                )
            elif "existing_curated_label_entry" in blockers:
                sourcing_status = "excluded_existing_curated_label"
                next_action = "do not use an existing countable/external label as a new source"
            elif "uniprot_entry_feature_not_fetched" in blockers:
                sourcing_status = "blocked_uniprot_feature_fetch"
                next_action = "fetch normalized UniProt feature JSON before source review"
            elif "uniprot_active_site_feature_missing" in blockers:
                sourcing_status = "blocked_active_site_source_missing"
                next_action = "do not advance without explicit active-site residue evidence"
            elif "protein_phosphotransfer_catalytic_activity_missing" in blockers:
                sourcing_status = "blocked_protein_phosphotransfer_source_missing"
                next_action = "do not advance without protein phosphotransfer reaction evidence"
            elif "structure_reference_missing" in blockers:
                sourcing_status = "blocked_structure_reference_missing"
                next_action = "source a row with PDB or AlphaFold structure context"
            else:
                sourcing_status = "blocked_source_scout_criteria"
                next_action = "clear source-level blockers before mapping"

            blocker_counts.update(blockers)
            status_counts[sourcing_status] += 1
            rows.append(
                {
                    "accession": accession,
                    "entry_id": entry_id,
                    "lane_id": lane_id,
                    "protein_name": sample_row.get("protein_name"),
                    "uniprot_entry_name": (record or {}).get("entry_name")
                    or sample_row.get("entry_name"),
                    "uniprot_review_status": (record or {}).get("entry_type"),
                    "reviewed": sample_row.get("reviewed"),
                    "ec_numbers": sample_row.get("ec_numbers", []),
                    "pdb_ids": sample_row.get("pdb_ids", []),
                    "alphafold_ids": sample_row.get("alphafold_ids", []),
                    "active_site_feature_count": len(active_features),
                    "active_site_positions": [
                        feature.get("begin") for feature in active_features
                    ],
                    "active_site_evidence_codes": active_site_evidence_codes,
                    "atp_binding_feature_count": len(atp_binding_features),
                    "atp_binding_positions": [
                        feature.get("begin") for feature in atp_binding_features
                    ],
                    "atp_binding_evidence_codes": atp_binding_evidence_codes,
                    "metal_binding_feature_count": len(metal_binding_features),
                    "metal_binding_positions": [
                        feature.get("begin") for feature in metal_binding_features
                    ],
                    "catalytic_activity_count": len(catalytic_comments),
                    "protein_phosphotransfer_catalytic_activity_count": len(
                        protein_phosphotransfer_comments
                    ),
                    "protein_phosphotransfer_evidence_codes": (
                        phosphotransfer_evidence_codes
                    ),
                    "protein_acceptor_terms": acceptor_terms,
                    "cofactor_comment_count": len(cofactor_comments),
                    "source_evidence_strength_status": (
                        source_evidence_strength_status
                    ),
                    "direct_experimental_source_evidence_codes": (
                        direct_experimental_evidence_codes
                    ),
                    "target_family_id": "epk",
                    "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                    "target_label_type_if_future_gated": "seed_fingerprint",
                    "sourcing_status": sourcing_status,
                    "source_evidence_blockers": sorted(set(blockers)),
                    "candidate_priority_rank": None,
                    "measurement_ready": False,
                    "ready_to_measure_gamma_acceptor_distance": False,
                    "ready_to_run_epk_scorer": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "ready_to_expand_positive_fingerprint_universe": False,
                    "ready_for_label_import": False,
                    "countable_label_candidate": False,
                    "next_action": next_action,
                }
            )

    rows.sort(
        key=lambda row: (
            0
            if row["sourcing_status"] == "sourced_pending_structure_mapping_review"
            else 1,
            str(row.get("lane_id") or ""),
            str(row.get("accession") or ""),
        )
    )
    sourced_seen = 0
    filtered_rows: list[dict[str, Any]] = []
    for row in rows:
        if row["sourcing_status"] == "sourced_pending_structure_mapping_review":
            sourced_seen += 1
            if sourced_seen > max_candidates:
                continue
            row["candidate_priority_rank"] = sourced_seen
        filtered_rows.append(row)
    rows = filtered_rows
    status_counts = Counter(row["sourcing_status"] for row in rows)
    blocker_counts = Counter(
        blocker for row in rows for blocker in row["source_evidence_blockers"]
    )
    evidence_strength_counts = Counter(
        str(row.get("source_evidence_strength_status") or "not_applicable")
        for row in rows
    )
    sourced_rows = [
        row
        for row in rows
        if row["sourcing_status"] == "sourced_pending_structure_mapping_review"
    ]
    sourced_lane_counts = Counter(str(row.get("lane_id") or "") for row in sourced_rows)
    blocker_not_removed = [
        "external_positive_structure_mapping_required",
        "gamma_to_acceptor_distance_measurement_required",
        "threshold_not_calibrated_against_negative_controls",
        "external_hard_negative_reaudit_not_real_scorer",
        "registry_and_label_factory_extension_not_implemented",
        "no_countable_external_positive_labels",
    ]
    if not sourced_rows:
        blocker_not_removed.append("no_external_positive_source_candidates")

    return {
        "metadata": {
            "method": "epk_external_protein_substrate_source_scout",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_source_repair_terminal_decision_method": (
                terminal_meta.get("method")
            ),
            "current_source_candidates_exhausted": bool(
                terminal_meta.get("current_source_candidates_exhausted")
            ),
            "blocker_removed": "external_epk_positive_source_scout_started",
            "blocker_not_removed": blocker_not_removed,
            "query_lane_count": len(query_payloads_by_lane),
            "query_metadata": query_metadata,
            "fetched_candidate_record_count": fetched_record_count,
            "entry_feature_record_available_count": entry_fetch_available_count,
            "emitted_row_count": len(rows),
            "max_candidates": max_candidates,
            "sourced_candidate_count": len(sourced_rows),
            "sourced_candidate_accessions": [
                row["accession"] for row in sourced_rows
            ],
            "sourced_candidate_lane_counts": dict(sorted(sourced_lane_counts.items())),
            "source_scout_status_counts": dict(sorted(status_counts.items())),
            "source_evidence_strength_status_counts": dict(
                sorted(evidence_strength_counts.items())
            ),
            "source_evidence_blocker_counts": dict(sorted(blocker_counts.items())),
            "existing_label_entry_count_checked": len(existing_label_entry_ids),
            "existing_external_label_entry_ids_checked": sorted(
                entry_id
                for entry_id in existing_label_entry_ids
                if entry_id.startswith("uniprot:")
            ),
            "ready_to_measure_gamma_acceptor_distance": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This scout starts a new external ePK positive-source surface "
                "after current M-CSA source repair failed closed. UniProt names, "
                "EC labels, and reaction prose are source triage context only; "
                "no score, threshold, registry edit, label import, or held-out "
                "claim is produced."
            ),
            "next_actions": [
                "map source active-site and ATP-binding positions onto selected structures for top sourced rows",
                "measure gamma-to-protein-acceptor distances only after mapping succeeds",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "External ePK source scouting is review-only and cannot make "
                "countable positive labels without mapping, thresholds, gates, "
                "and external hard-negative re-audit."
            )
        ],
    }


def _epk_uniprot_direct_position_matches(
    atoms: list[dict[str, Any]],
    positions: list[dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:
    matches_by_position: dict[str, dict[tuple[str, str, str, str], dict[str, Any]]] = {
        str(position["position"]): {} for position in positions
    }
    wanted = set(matches_by_position)
    for atom in atoms:
        if atom.get("group_PDB") != "ATOM":
            continue
        auth_seq = str(atom.get("auth_seq_id") or "")
        label_seq = str(atom.get("label_seq_id") or "")
        hit_positions = sorted({auth_seq, label_seq} & wanted)
        if not hit_positions:
            continue
        chain = str(atom.get("auth_asym_id") or atom.get("label_asym_id") or "")
        code = str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
        if not chain or not code:
            continue
        key = (chain, code, auth_seq, label_seq)
        for position in hit_positions:
            basis = []
            if auth_seq == position:
                basis.append("auth_seq_id")
            if label_seq == position:
                basis.append("label_seq_id")
            matches_by_position[position].setdefault(
                key,
                {
                    "position": position,
                    "chain_name": chain,
                    "code": code,
                    "auth_seq_id": auth_seq,
                    "label_seq_id": label_seq,
                    "match_basis": sorted(basis),
                    "roles": [],
                },
            )
    role_by_position = {
        str(position["position"]): list(position.get("roles", []))
        for position in positions
    }
    return {
        position: [
            {
                **match,
                "roles": role_by_position.get(position, []),
            }
            for match in sorted(matches.values(), key=lambda item: (
                item["chain_name"],
                item["code"],
                item["auth_seq_id"],
                item["label_seq_id"],
            ))
        ]
        for position, matches in matches_by_position.items()
    }


def _epk_resolve_single_chain_direct_positions(
    matches_by_position: dict[str, list[dict[str, Any]]],
) -> tuple[list[dict[str, Any]], str, list[str]]:
    if not matches_by_position:
        return [], "no_positions_requested", ["no_uniprot_positions_to_map"]
    missing_positions = [
        position for position, matches in matches_by_position.items() if not matches
    ]
    if missing_positions:
        return [], "missing_direct_position_matches", [
            "missing_uniprot_direct_position_matches"
        ]

    candidate_chains = sorted(
        {
            str(match.get("chain_name"))
            for matches in matches_by_position.values()
            for match in matches
            if match.get("chain_name")
        }
    )
    resolved_by_chain: list[tuple[str, list[dict[str, Any]]]] = []
    for chain in candidate_chains:
        positions: list[dict[str, Any]] = []
        for position, matches in matches_by_position.items():
            chain_matches = [
                match for match in matches if str(match.get("chain_name")) == chain
            ]
            if len(chain_matches) != 1:
                positions = []
                break
            match = chain_matches[0]
            positions.append(
                {
                    "chain_name": chain,
                    "code": match.get("code"),
                    "resid": match.get("auth_seq_id") or match.get("label_seq_id"),
                    "roles": match.get("roles", []),
                    "uniprot_position": position,
                    "mapping_basis": "+".join(match.get("match_basis", [])),
                }
            )
        if positions:
            resolved_by_chain.append((chain, positions))
    if len(resolved_by_chain) == 1:
        return (
            _review_debt_normalized_residue_positions(resolved_by_chain[0][1]),
            "single_chain_direct_uniprot_position_mapping",
            [],
        )
    if len(resolved_by_chain) > 1:
        return [], "ambiguous_multi_chain_direct_position_mapping", [
            "multiple_chains_match_uniprot_positions"
        ]
    return [], "ambiguous_or_conflicting_direct_position_mapping", [
        "direct_position_matches_do_not_form_single_chain_mapping"
    ]


def _epk_mmcif_loop_rows(cif_text: str, prefix: str) -> list[dict[str, Any]]:
    import shlex

    rows: list[dict[str, Any]] = []
    lines = cif_text.splitlines()
    index = 0
    while index < len(lines):
        if lines[index].strip() != "loop_":
            index += 1
            continue
        index += 1
        headers: list[str] = []
        while index < len(lines) and lines[index].strip().startswith("_"):
            headers.append(lines[index].strip())
            index += 1
        if not headers or not all(header.startswith(prefix) for header in headers):
            continue
        while index < len(lines):
            line = lines[index].strip()
            if not line or line == "#":
                break
            if line == "loop_" or line.startswith("_") or line.startswith("data_"):
                break
            values = shlex.split(line)
            if len(values) >= len(headers):
                rows.append(
                    {
                        header.replace(prefix, ""): (
                            None if value in {".", "?"} else value
                        )
                        for header, value in zip(headers, values)
                    }
                )
            index += 1
    return rows


def _epk_mmcif_single_category_rows(cif_text: str, prefix: str) -> list[dict[str, Any]]:
    import shlex

    rows: list[dict[str, Any]] = []
    current: dict[str, Any] = {}
    in_category = False
    for raw_line in cif_text.splitlines():
        line = raw_line.strip()
        if line == "#":
            if current:
                rows.append(current)
                current = {}
            in_category = False
            continue
        if not line.startswith(prefix):
            if in_category and line.startswith("_") and current:
                rows.append(current)
                current = {}
                in_category = False
            continue
        in_category = True
        parts = shlex.split(line)
        if len(parts) >= 2:
            key = parts[0].replace(prefix, "")
            value = parts[1]
            current[key] = None if value in {".", "?"} else value
    if current:
        rows.append(current)
    return rows


def _epk_mmcif_rows(cif_text: str, prefix: str) -> list[dict[str, Any]]:
    loop_rows = _epk_mmcif_loop_rows(cif_text, prefix)
    if loop_rows:
        return loop_rows
    return _epk_mmcif_single_category_rows(cif_text, prefix)


def _first_present_value(rows: list[dict[str, Any]], key: str) -> str | None:
    for row in rows:
        value = row.get(key)
        if value not in {None, "", ".", "?"}:
            return str(value)
    return None


def _unwrap_uniprot_entry_record(entry: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(entry, dict):
        return {}
    record = entry.get("record")
    if isinstance(record, dict):
        return record
    return entry


def _epk_atom_code(atom: dict[str, Any]) -> str:
    return str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()


def _epk_atom_name(atom: dict[str, Any]) -> str:
    return str(atom.get("auth_atom_id") or atom.get("label_atom_id") or "").upper()


def _epk_atom_distance(left: dict[str, Any], right: dict[str, Any]) -> float:
    return (
        (float(left["Cartn_x"]) - float(right["Cartn_x"])) ** 2
        + (float(left["Cartn_y"]) - float(right["Cartn_y"])) ** 2
        + (float(left["Cartn_z"]) - float(right["Cartn_z"])) ** 2
    ) ** 0.5


def _epk_struct_ref_seq_rows(cif_text: str) -> list[dict[str, Any]]:
    prefix = "_struct_ref_seq."
    return _epk_mmcif_rows(cif_text, prefix)


def _epk_struct_ref_seq_mapped_positions(
    atoms: list[dict[str, Any]],
    cif_text: str,
    accession: str,
    positions: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    accession_upper = accession.upper()
    mapped: list[dict[str, Any]] = []
    rows = [
        row
        for row in _epk_struct_ref_seq_rows(cif_text)
        if str(row.get("pdbx_db_accession") or "").upper() == accession_upper
    ]
    for position in positions:
        position_value = str(position.get("position") or "")
        try:
            uniprot_position = int(position_value)
        except ValueError:
            continue
        position_matches: list[dict[str, Any]] = []
        for row in rows:
            try:
                db_begin = int(str(row.get("db_align_beg")))
                db_end = int(str(row.get("db_align_end")))
                auth_begin = int(str(row.get("pdbx_auth_seq_align_beg")))
            except (TypeError, ValueError):
                continue
            if not db_begin <= uniprot_position <= db_end:
                continue
            auth_resid = str(auth_begin + (uniprot_position - db_begin))
            chain = str(row.get("pdbx_strand_id") or "")
            residue_atoms = [
                atom
                for atom in atoms
                if atom.get("group_PDB") == "ATOM"
                and chain in _label_atom_chain_ids(atom)
                and str(atom.get("auth_seq_id") or "") == auth_resid
            ]
            codes = _sorted_strings(
                atom.get("auth_comp_id") or atom.get("label_comp_id")
                for atom in residue_atoms
            )
            if len(codes) != 1:
                continue
            position_matches.append(
                {
                    "chain_name": chain,
                    "code": codes[0],
                    "resid": auth_resid,
                    "roles": position.get("roles", []),
                    "uniprot_position": position_value,
                    "mapping_basis": "struct_ref_seq_alignment",
                }
            )
        if len(position_matches) != 1:
            return []
        mapped.append(position_matches[0])
    return _review_debt_normalized_residue_positions(mapped)


def _epk_struct_ref_seq_mapped_position_candidates(
    atoms: list[dict[str, Any]],
    cif_text: str,
    accession: str,
    positions: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Map UniProt positions onto all matching chains instead of requiring one."""

    accession_upper = accession.upper()
    rows = [
        row
        for row in _epk_struct_ref_seq_rows(cif_text)
        if str(row.get("pdbx_db_accession") or "").upper() == accession_upper
    ]
    mapped_by_key: dict[tuple[str, str, str, str], dict[str, Any]] = {}
    for position in positions:
        position_value = str(position.get("position") or "")
        try:
            uniprot_position = int(position_value)
        except ValueError:
            continue
        for row in rows:
            try:
                db_begin = int(str(row.get("db_align_beg")))
                db_end = int(str(row.get("db_align_end")))
                auth_begin = int(str(row.get("pdbx_auth_seq_align_beg")))
            except (TypeError, ValueError):
                continue
            if not db_begin <= uniprot_position <= db_end:
                continue
            auth_resid = str(auth_begin + (uniprot_position - db_begin))
            chain = str(row.get("pdbx_strand_id") or "")
            residue_atoms = [
                atom
                for atom in atoms
                if atom.get("group_PDB") == "ATOM"
                and chain in _label_atom_chain_ids(atom)
                and str(atom.get("auth_seq_id") or "") == auth_resid
            ]
            codes = _sorted_strings(
                atom.get("auth_comp_id") or atom.get("label_comp_id")
                for atom in residue_atoms
            )
            if len(codes) != 1:
                continue
            key = (accession_upper, position_value, chain, auth_resid)
            mapped_by_key[key] = {
                "accession": accession_upper,
                "chain_name": chain,
                "code": codes[0],
                "resid": auth_resid,
                "roles": position.get("roles", []),
                "uniprot_position": position_value,
                "mapping_basis": "struct_ref_seq_alignment",
                "source_description": position.get("description"),
                "source_evidence_codes": position.get("evidence_codes", []),
            }
    return sorted(
        _review_debt_normalized_residue_positions(list(mapped_by_key.values())),
        key=lambda item: (
            str(item.get("accession") or ""),
            int(str(item.get("uniprot_position") or "0")),
            str(item.get("chain_name") or ""),
            str(item.get("resid") or ""),
        ),
    )


def _epk_uniprot_phosphoacceptor_features(record: dict[str, Any]) -> list[dict[str, Any]]:
    features: list[dict[str, Any]] = []
    for feature in record.get("modified_residue_features", []) or []:
        if not isinstance(feature, dict):
            continue
        description = str(feature.get("description") or "")
        lowered = description.lower()
        if not any(
            token in lowered
            for token in ("phosphoserine", "phosphothreonine", "phosphotyrosine")
        ):
            continue
        begin = feature.get("begin")
        if begin in {None, "", ".", "?"}:
            continue
        features.append(
            {
                "position": begin,
                "roles": ["source_phosphoacceptor"],
                "description": description,
                "evidence_codes": _epk_uniprot_evidence_codes([feature]),
            }
        )
    return sorted(
        features,
        key=lambda feature: int(str(feature.get("position") or "0")),
    )


def build_epk_external_source_structure_mapping_review(
    *,
    epk_external_protein_substrate_source_scout: dict[str, Any],
    max_candidates: int = 4,
    max_pdbs_per_candidate: int = 3,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Attempt direct UniProt-position mapping for sourced external ePK rows."""

    if max_candidates < 1:
        raise ValueError("max_candidates must be positive")
    if max_pdbs_per_candidate < 1:
        raise ValueError("max_pdbs_per_candidate must be positive")

    scout_meta = epk_external_protein_substrate_source_scout.get("metadata", {})
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    target_fingerprint_id = str(
        scout_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_text_by_pdb = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    inactive_analog_codes = {"AGS"}

    sourced_rows = [
        row
        for row in epk_external_protein_substrate_source_scout.get("rows", []) or []
        if isinstance(row, dict)
        and row.get("sourcing_status")
        == "sourced_pending_structure_mapping_review"
    ]
    sourced_rows.sort(
        key=lambda row: (
            row.get("candidate_priority_rank") or 9999,
            str(row.get("accession") or ""),
        )
    )
    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    for source_row in sourced_rows[:max_candidates]:
        accession = str(source_row.get("accession") or "")
        active_positions = [
            {
                "position": str(position),
                "roles": ["uniprot_active_site_feature"],
            }
            for position in source_row.get("active_site_positions", []) or []
            if position not in {None, "", ".", "?"}
        ]
        atp_positions = [
            {
                "position": str(position),
                "roles": ["uniprot_atp_binding_feature"],
            }
            for position in source_row.get("atp_binding_positions", []) or []
            if position not in {None, "", ".", "?"}
        ]
        requested_positions = active_positions + atp_positions
        for pdb_id in [
            str(pdb_id).upper()
            for pdb_id in (source_row.get("pdb_ids", []) or [])[
                :max_pdbs_per_candidate
            ]
            if pdb_id
        ]:
            row_base = {
                "accession": accession,
                "entry_id": source_row.get("entry_id"),
                "pdb_id": pdb_id,
                "lane_id": source_row.get("lane_id"),
                "target_family_id": "epk",
                "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                "review_only": True,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
            }
            try:
                cif_text = cif_text_by_pdb.get(pdb_id)
                fetch_status = (
                    "provided_cif_text" if cif_text is not None else "fetched_rcsb_cif"
                )
                if cif_text is None:
                    cif_text = cif_fetcher(pdb_id)
                atoms = parse_atom_site_loop(cif_text)
            except Exception as exc:
                status = "structure_fetch_failed_review_only"
                status_counts[status] += 1
                rows.append(
                    {
                        **row_base,
                        "fetch_status": "failed",
                        "fetch_error": str(exc),
                        "requested_uniprot_position_count": len(requested_positions),
                        "direct_position_mapping_basis": None,
                        "direct_position_mapping_warnings": ["structure_fetch_failed"],
                        "direct_position_mapping_ready": False,
                        "local_ligand_codes": [],
                        "local_cofactor_families": [],
                        "structure_ligand_codes": [],
                        "structure_cofactor_families": [],
                        "has_local_gamma_capable_nucleotide": False,
                        "has_inactive_analog_ligand": False,
                        "has_local_metal": False,
                        "mapping_review_status": status,
                        "remaining_blockers": ["structure_fetch_failed"],
                    }
                )
                continue

            inventory = structure_ligand_inventory_from_atoms(atoms)
            struct_ref_positions = _epk_struct_ref_seq_mapped_positions(
                atoms,
                cif_text,
                accession,
                requested_positions,
            )
            matches_by_position = _epk_uniprot_direct_position_matches(
                atoms, requested_positions
            )
            if struct_ref_positions:
                resolved_positions = struct_ref_positions
                mapping_basis = "struct_ref_seq_uniprot_position_mapping"
                mapping_warnings: list[str] = []
            else:
                resolved_positions, mapping_basis, mapping_warnings = (
                    _epk_resolve_single_chain_direct_positions(matches_by_position)
                )
            local_context = (
                _review_debt_local_ligand_context(
                    atoms,
                    pdb_id,
                    {pdb_id: resolved_positions},
                )
                if resolved_positions
                else {
                    "ligand_codes": [],
                    "cofactor_families": [],
                    "resolved_residue_count": 0,
                }
            )
            local_ligand_codes = _sorted_strings(local_context.get("ligand_codes", []))
            local_cofactor_families = _sorted_strings(
                local_context.get("cofactor_families", [])
            )
            structure_ligand_codes = _sorted_strings(inventory.get("ligand_codes", []))
            structure_cofactor_families = _sorted_strings(
                inventory.get("cofactor_families", [])
            )
            has_gamma = bool(set(local_ligand_codes) & gamma_capable_codes)
            has_inactive_analog = bool(
                set(local_ligand_codes) & inactive_analog_codes
            )
            has_metal = "metal_ion" in set(local_cofactor_families)
            direct_mapping_ready = bool(resolved_positions)
            if direct_mapping_ready and has_gamma and has_metal:
                status = "active_state_mapping_ready_needs_acceptor_source_review_only"
                blockers = [
                    "protein_substrate_acceptor_not_source_mapped",
                    "gamma_to_acceptor_distance_not_measured",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            elif direct_mapping_ready and has_inactive_analog and has_metal:
                status = "analog_state_mapping_policy_blocked_review_only"
                blockers = [
                    "analog_ligand_policy_not_active",
                    "protein_substrate_acceptor_not_source_mapped",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            elif direct_mapping_ready:
                status = "direct_position_mapping_ready_ligand_context_incomplete_review_only"
                blockers = [
                    "local_gamma_metal_context_missing",
                    "protein_substrate_acceptor_not_source_mapped",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            else:
                status = "blocked_direct_position_mapping_ambiguous_or_missing_review_only"
                blockers = [
                    *mapping_warnings,
                    "source_structure_mapping_not_conservative",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            status_counts[status] += 1
            rows.append(
                {
                    **row_base,
                    "fetch_status": fetch_status,
                    "requested_uniprot_position_count": len(requested_positions),
                    "requested_active_site_position_count": len(active_positions),
                    "requested_atp_binding_position_count": len(atp_positions),
                    "direct_position_match_counts": {
                        position: len(matches)
                        for position, matches in matches_by_position.items()
                    },
                    "direct_position_mapping_basis": mapping_basis,
                    "direct_position_mapping_warnings": mapping_warnings,
                    "direct_position_mapping_ready": direct_mapping_ready,
                    "mapped_residue_positions": resolved_positions,
                    "local_ligand_codes": local_ligand_codes,
                    "local_cofactor_families": local_cofactor_families,
                    "local_resolved_residue_count": local_context.get(
                        "resolved_residue_count", 0
                    ),
                    "structure_ligand_codes": structure_ligand_codes,
                    "structure_cofactor_families": structure_cofactor_families,
                    "has_local_gamma_capable_nucleotide": has_gamma,
                    "has_inactive_analog_ligand": has_inactive_analog,
                    "has_local_metal": has_metal,
                    "mapping_review_status": status,
                    "remaining_blockers": blockers,
                }
            )

    active_state_ready_rows = [
        row
        for row in rows
        if row.get("mapping_review_status")
        == "active_state_mapping_ready_needs_acceptor_source_review_only"
    ]
    direct_ready_rows = [row for row in rows if row.get("direct_position_mapping_ready")]
    analog_blocked_rows = [
        row
        for row in rows
        if row.get("mapping_review_status")
        == "analog_state_mapping_policy_blocked_review_only"
    ]
    return {
        "metadata": {
            "method": "epk_external_source_structure_mapping_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_external_protein_substrate_source_scout_method": (
                scout_meta.get("method")
            ),
            "scouted_candidate_count": len(sourced_rows),
            "reviewed_candidate_count": min(len(sourced_rows), max_candidates),
            "max_candidates": max_candidates,
            "max_pdbs_per_candidate": max_pdbs_per_candidate,
            "structure_row_count": len(rows),
            "direct_position_mapping_ready_structure_count": len(direct_ready_rows),
            "active_state_mapping_ready_structure_count": len(active_state_ready_rows),
            "active_state_mapping_ready_accessions": _sorted_strings(
                row.get("accession") for row in active_state_ready_rows
            ),
            "active_state_mapping_ready_pdb_ids": _sorted_strings(
                row.get("pdb_id") for row in active_state_ready_rows
            ),
            "analog_policy_blocked_structure_count": len(analog_blocked_rows),
            "mapping_review_status_counts": dict(sorted(status_counts.items())),
            "measurement_ready_candidate_count": 0,
            "ready_to_measure_gamma_acceptor_distance": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "external_epk_source_structure_mapping_started",
            "blocker_not_removed": [
                "protein_substrate_acceptor_not_source_mapped",
                "gamma_to_acceptor_distance_not_measured",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact attempts direct UniProt-position-to-PDB mapping "
                "for external ePK source candidates. Direct active-state mapping "
                "is only a source-repair lead; it is not protein-substrate "
                "acceptor evidence, a calibrated score, or a countable label."
            ),
            "next_actions": [
                "for active-state mapped rows, source protein-substrate acceptor evidence before distance measurement",
                "treat analog-only mapped rows as blocked until an analog policy is frozen and passes controls",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "External ePK structure mapping remains review-only and cannot "
                "support countable fingerprint expansion without acceptor "
                "mapping, thresholds, gates, and external re-audit."
            )
        ],
    }


def build_epk_external_source_acceptor_gap_audit(
    *,
    epk_external_source_structure_mapping_review: dict[str, Any],
    candidate_threshold_angstrom: float = 6.0,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Audit mapped external ePK leads for source-usable acceptor geometry."""

    mapping_meta = epk_external_source_structure_mapping_review.get("metadata", {})
    if not isinstance(mapping_meta, dict):
        mapping_meta = {}
    target_fingerprint_id = str(
        mapping_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_text_by_pdb = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    acceptor_atoms = {("SER", "OG"), ("THR", "OG1"), ("TYR", "OH")}

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    active_ready_rows = [
        row
        for row in epk_external_source_structure_mapping_review.get("rows", []) or []
        if isinstance(row, dict)
        and row.get("mapping_review_status")
        == "active_state_mapping_ready_needs_acceptor_source_review_only"
    ]
    for mapping_row in active_ready_rows:
        pdb_id = str(mapping_row.get("pdb_id") or "").upper()
        accession = str(mapping_row.get("accession") or "")
        row_base = {
            "accession": accession,
            "entry_id": mapping_row.get("entry_id"),
            "pdb_id": pdb_id,
            "target_family_id": "epk",
            "target_fingerprint_id_if_future_gated": target_fingerprint_id,
            "review_only": True,
            "ready_for_label_import": False,
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
        }
        try:
            cif_text = cif_text_by_pdb.get(pdb_id)
            fetch_status = (
                "provided_cif_text" if cif_text is not None else "fetched_rcsb_cif"
            )
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id)
            atoms = parse_atom_site_loop(cif_text)
        except Exception as exc:
            status = "structure_fetch_failed_review_only"
            status_counts[status] += 1
            rows.append(
                {
                    **row_base,
                    "fetch_status": "failed",
                    "fetch_error": str(exc),
                    "candidate_threshold_angstrom": candidate_threshold_angstrom,
                    "terminal_gamma_atom_count": 0,
                    "nearest_same_chain_hydroxyl_distance_angstrom": None,
                    "nearest_non_catalytic_chain_hydroxyl_distance_angstrom": None,
                    "source_mapped_acceptor_count": 0,
                    "measurement_ready": False,
                    "acceptor_gap_status": status,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue

        mapped_positions = [
            position
            for position in mapping_row.get("mapped_residue_positions", []) or []
            if isinstance(position, dict)
        ]
        catalytic_chains = {
            str(position.get("chain_name"))
            for position in mapped_positions
            if position.get("chain_name")
        }
        gamma_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "HETATM"
            and str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
            in gamma_capable_codes
            and str(atom.get("auth_atom_id") or atom.get("label_atom_id") or "").upper()
            == "PG"
        ]
        hydroxyl_hits: list[dict[str, Any]] = []
        for atom in atoms:
            if atom.get("group_PDB") != "ATOM":
                continue
            code = str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
            atom_name = str(atom.get("auth_atom_id") or atom.get("label_atom_id") or "").upper()
            if (code, atom_name) not in acceptor_atoms:
                continue
            chain = str(atom.get("auth_asym_id") or atom.get("label_asym_id") or "")
            if not gamma_atoms:
                continue
            nearest = min(
                round(_point_distance(_atom_point(gamma_atom), _atom_point(atom)), 3)
                for gamma_atom in gamma_atoms
            )
            if nearest <= max(candidate_threshold_angstrom, 8.0):
                hydroxyl_hits.append(
                    {
                        "chain_name": chain,
                        "residue_code": code,
                        "auth_seq_id": atom.get("auth_seq_id"),
                        "label_seq_id": atom.get("label_seq_id"),
                        "atom_name": atom_name,
                        "nearest_gamma_distance_angstrom": nearest,
                        "non_catalytic_chain": chain not in catalytic_chains,
                    }
                )
        same_chain_hits = [
            hit for hit in hydroxyl_hits if not hit.get("non_catalytic_chain")
        ]
        non_catalytic_hits = [
            hit for hit in hydroxyl_hits if hit.get("non_catalytic_chain")
        ]
        threshold_same_chain_hits = [
            hit
            for hit in same_chain_hits
            if float(hit["nearest_gamma_distance_angstrom"])
            <= candidate_threshold_angstrom
        ]
        threshold_non_catalytic_hits = [
            hit
            for hit in non_catalytic_hits
            if float(hit["nearest_gamma_distance_angstrom"])
            <= candidate_threshold_angstrom
        ]
        source_mapped_acceptor_count = 0
        measurement_ready = False
        if not gamma_atoms:
            status = "blocked_no_terminal_gamma_atom_review_only"
            blockers = [
                "active_state_terminal_gamma_atom_not_materialized",
                "protein_substrate_acceptor_not_source_mapped",
            ]
        elif threshold_non_catalytic_hits:
            status = "acceptor_like_geometry_not_source_mapped_review_only"
            blockers = [
                "protein_substrate_acceptor_not_source_mapped",
                "acceptor_identity_not_source_authoritative",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif threshold_same_chain_hits:
            status = "same_chain_hydroxyl_not_substrate_source_mapped_review_only"
            blockers = [
                "same_chain_hydroxyl_not_protein_substrate_mapping",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        else:
            status = "no_acceptor_like_hydroxyl_within_threshold_review_only"
            blockers = [
                "protein_substrate_acceptor_not_source_mapped",
                "gamma_to_acceptor_distance_not_measurable",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        status_counts[status] += 1
        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "catalytic_chains": sorted(catalytic_chains),
                "terminal_gamma_atom_count": len(gamma_atoms),
                "hydroxyl_candidate_count_within_8_angstrom": len(hydroxyl_hits),
                "same_chain_hydroxyl_candidate_count_within_threshold": len(
                    threshold_same_chain_hits
                ),
                "non_catalytic_chain_hydroxyl_candidate_count_within_threshold": (
                    len(threshold_non_catalytic_hits)
                ),
                "nearest_same_chain_hydroxyl_distance_angstrom": (
                    min(
                        hit["nearest_gamma_distance_angstrom"]
                        for hit in same_chain_hits
                    )
                    if same_chain_hits
                    else None
                ),
                "nearest_non_catalytic_chain_hydroxyl_distance_angstrom": (
                    min(
                        hit["nearest_gamma_distance_angstrom"]
                        for hit in non_catalytic_hits
                    )
                    if non_catalytic_hits
                    else None
                ),
                "hydroxyl_candidates": sorted(
                    hydroxyl_hits,
                    key=lambda hit: (
                        float(hit["nearest_gamma_distance_angstrom"]),
                        str(hit.get("chain_name") or ""),
                        str(hit.get("auth_seq_id") or ""),
                    ),
                )[:25],
                "source_mapped_acceptor_count": source_mapped_acceptor_count,
                "measurement_ready": measurement_ready,
                "acceptor_gap_status": status,
                "remaining_blockers": blockers,
            }
        )

    measurement_ready_count = sum(1 for row in rows if row.get("measurement_ready"))
    return {
        "metadata": {
            "method": "epk_external_source_acceptor_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_external_source_structure_mapping_review_method": (
                mapping_meta.get("method")
            ),
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "active_state_mapping_ready_input_count": len(active_ready_rows),
            "audited_structure_count": len(rows),
            "source_mapped_acceptor_count": sum(
                int(row.get("source_mapped_acceptor_count") or 0) for row in rows
            ),
            "measurement_ready_candidate_count": measurement_ready_count,
            "acceptor_gap_status_counts": dict(sorted(status_counts.items())),
            "ready_to_measure_gamma_acceptor_distance": measurement_ready_count > 0,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "external_epk_source_acceptor_gap_audited",
            "blocker_not_removed": [
                "protein_substrate_acceptor_not_source_mapped",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact tests whether active-state mapped external ePK "
                "source leads have source-usable acceptor geometry. Nearby "
                "same-chain hydroxyls or unsourced non-catalytic hydroxyls are "
                "not production acceptor evidence."
            ),
            "next_actions": [
                "source protein-substrate acceptor evidence for Q8IVT5 before any distance claim",
                "if no source-mapped acceptor exists, continue external source mapping to the next scout accession",
                "keep the ePK scorer and external hard-negative re-audit closed",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "External active-state mapping does not become measurement-ready "
                "until the protein-substrate acceptor is source-mapped."
            )
        ],
    }


def build_epk_external_source_next_experiment_queue(
    *,
    epk_external_source_structure_mapping_review: dict[str, Any],
    epk_external_source_acceptor_gap_audit: dict[str, Any],
) -> dict[str, Any]:
    """Rank the next review-only experiment for each external ePK source row."""

    mapping_meta = epk_external_source_structure_mapping_review.get("metadata", {})
    if not isinstance(mapping_meta, dict):
        mapping_meta = {}
    acceptor_meta = epk_external_source_acceptor_gap_audit.get("metadata", {})
    if not isinstance(acceptor_meta, dict):
        acceptor_meta = {}
    target_fingerprint_id = str(
        mapping_meta.get("target_fingerprint_id")
        or acceptor_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    acceptor_rows_by_key = {
        (str(row.get("accession") or ""), str(row.get("pdb_id") or "").upper()): row
        for row in epk_external_source_acceptor_gap_audit.get("rows", []) or []
        if isinstance(row, dict)
    }

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    for mapping_row in epk_external_source_structure_mapping_review.get("rows", []) or []:
        if not isinstance(mapping_row, dict):
            continue
        accession = str(mapping_row.get("accession") or "")
        pdb_id = str(mapping_row.get("pdb_id") or "").upper()
        mapping_status = str(mapping_row.get("mapping_review_status") or "")
        acceptor_row = acceptor_rows_by_key.get((accession, pdb_id), {})
        acceptor_status = str(acceptor_row.get("acceptor_gap_status") or "")
        if mapping_status == "active_state_mapping_ready_needs_acceptor_source_review_only":
            if acceptor_status == "acceptor_like_geometry_not_source_mapped_review_only":
                priority_rank = 1
                next_experiment = "source_map_nearby_candidate_acceptor"
                queue_status = "highest_value_acceptor_source_mapping_review_only"
                blockers = [
                    "acceptor_like_geometry_without_source_authority",
                    "protein_substrate_acceptor_not_source_mapped",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            elif acceptor_status == "no_acceptor_like_hydroxyl_within_threshold_review_only":
                priority_rank = 2
                next_experiment = "source_alternate_active_state_substrate_cocomplex"
                queue_status = "active_state_no_acceptor_candidate_review_only"
                blockers = [
                    "protein_substrate_acceptor_not_source_mapped",
                    "active_state_acceptor_geometry_missing",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            else:
                priority_rank = 3
                next_experiment = "rerun_acceptor_gap_audit"
                queue_status = "active_state_acceptor_audit_missing_review_only"
                blockers = [
                    "acceptor_gap_audit_missing",
                    "protein_substrate_acceptor_not_source_mapped",
                ]
        elif mapping_status == "direct_position_mapping_ready_ligand_context_incomplete_review_only":
            priority_rank = 4
            next_experiment = "source_active_gamma_metal_structure_for_mapped_accession"
            queue_status = "mapped_structure_ligand_context_incomplete_review_only"
            blockers = [
                "local_gamma_metal_context_missing",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        else:
            priority_rank = 5
            next_experiment = "source_alternate_structure_or_resolve_residue_mapping"
            queue_status = "structure_mapping_unresolved_review_only"
            blockers = [
                "source_structure_mapping_not_conservative",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        status_counts[queue_status] += 1
        rows.append(
            {
                "accession": accession,
                "entry_id": mapping_row.get("entry_id"),
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                "review_only": True,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "priority_rank": priority_rank,
                "queue_status": queue_status,
                "next_experiment": next_experiment,
                "mapping_review_status": mapping_status,
                "acceptor_gap_status": acceptor_status or None,
                "direct_position_mapping_ready": bool(
                    mapping_row.get("direct_position_mapping_ready")
                ),
                "local_ligand_codes": mapping_row.get("local_ligand_codes", []),
                "local_cofactor_families": mapping_row.get(
                    "local_cofactor_families", []
                ),
                "mapped_residue_count": len(
                    mapping_row.get("mapped_residue_positions", []) or []
                ),
                "nearest_non_catalytic_chain_hydroxyl_distance_angstrom": (
                    acceptor_row.get(
                        "nearest_non_catalytic_chain_hydroxyl_distance_angstrom"
                    )
                ),
                "source_mapped_acceptor_count": int(
                    acceptor_row.get("source_mapped_acceptor_count") or 0
                ),
                "measurement_ready": False,
                "remaining_blockers": blockers,
            }
        )

    rows.sort(
        key=lambda row: (
            int(row.get("priority_rank") or 999),
            str(row.get("accession") or ""),
            str(row.get("pdb_id") or ""),
        )
    )
    return {
        "metadata": {
            "method": "epk_external_source_next_experiment_queue",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_external_source_structure_mapping_review_method": (
                mapping_meta.get("method")
            ),
            "source_epk_external_source_acceptor_gap_audit_method": (
                acceptor_meta.get("method")
            ),
            "queued_structure_count": len(rows),
            "queue_status_counts": dict(sorted(status_counts.items())),
            "top_priority_next_experiment": (
                rows[0]["next_experiment"] if rows else None
            ),
            "top_priority_accession": rows[0]["accession"] if rows else None,
            "top_priority_pdb_id": rows[0]["pdb_id"] if rows else None,
            "measurement_ready_candidate_count": 0,
            "ready_to_measure_gamma_acceptor_distance": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "external_epk_next_experiment_ranked",
            "blocker_not_removed": [
                "protein_substrate_acceptor_not_source_mapped",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact ranks next experiments for external ePK source "
                "leads. It does not promote scores, labels, registry rows, or "
                "held-out performance evidence."
            ),
            "next_actions": [
                "source-map the 7JUW nearby Ser acceptor candidate before any distance claim",
                "if acceptor source authority fails, source alternate active-state substrate co-complexes",
                "only after measurement-ready positives exist, rerun calibrated scorer controls and hard negatives",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Every queued experiment remains fail-closed because no "
                "source-mapped protein-substrate acceptor exists."
            )
        ],
    }


def build_epk_external_source_alternate_cocomplex_review(
    *,
    epk_external_protein_substrate_source_scout: dict[str, Any],
    epk_external_source_acceptor_source_mapping_review: dict[str, Any] | None = None,
    target_accession: str = "Q8IVT5",
    acceptor_entry_records_by_accession: dict[str, dict[str, Any]] | None = None,
    candidate_threshold_angstrom: float = 6.0,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Review alternate active-state co-complexes for source-mapped acceptors."""

    if candidate_threshold_angstrom <= 0:
        raise ValueError("candidate_threshold_angstrom must be positive")

    scout_meta = epk_external_protein_substrate_source_scout.get("metadata", {})
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    source_mapping_meta = (
        epk_external_source_acceptor_source_mapping_review or {}
    ).get("metadata", {})
    if not isinstance(source_mapping_meta, dict):
        source_mapping_meta = {}
    target_fingerprint_id = str(
        scout_meta.get("target_fingerprint_id")
        or source_mapping_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    target_accession = target_accession.upper()
    cif_text_by_pdb = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    acceptor_entry_records_by_accession = {
        str(accession).upper(): record
        for accession, record in (acceptor_entry_records_by_accession or {}).items()
        if accession and isinstance(record, dict)
    }
    acceptor_features_by_accession = {
        accession: _epk_uniprot_phosphoacceptor_features(record)
        for accession, record in acceptor_entry_records_by_accession.items()
    }
    acceptor_accessions = sorted(acceptor_features_by_accession)
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    acceptor_atoms = {("SER", "OG"), ("THR", "OG1"), ("TYR", "OH")}

    target_source_rows = [
        row
        for row in epk_external_protein_substrate_source_scout.get("rows", []) or []
        if isinstance(row, dict)
        and str(row.get("accession") or "").upper() == target_accession
        and row.get("sourcing_status") == "sourced_pending_structure_mapping_review"
    ]
    target_source_row = target_source_rows[0] if target_source_rows else {}
    target_positions = [
        {
            "position": str(position),
            "roles": ["uniprot_active_site_feature"],
        }
        for position in target_source_row.get("active_site_positions", []) or []
        if position not in {None, "", ".", "?"}
    ] + [
        {
            "position": str(position),
            "roles": ["uniprot_atp_binding_feature"],
        }
        for position in target_source_row.get("atp_binding_positions", []) or []
        if position not in {None, "", ".", "?"}
    ]
    target_position_ids = {
        str(position.get("position") or "")
        for position in target_positions
        if position.get("position") not in {None, "", ".", "?"}
    }
    pdb_ids = _sorted_strings(target_source_row.get("pdb_ids", []))

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    all_distance_hits: list[dict[str, Any]] = []
    for pdb_id in pdb_ids:
        row_base = {
            "accession": target_accession,
            "entry_id": f"uniprot:{target_accession}",
            "pdb_id": pdb_id,
            "target_family_id": "epk",
            "target_fingerprint_id_if_future_gated": target_fingerprint_id,
            "review_only": True,
            "ready_for_label_import": False,
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
        }
        try:
            cif_text = cif_text_by_pdb.get(pdb_id)
            fetch_status = (
                "provided_cif_text" if cif_text is not None else "fetched_rcsb_cif"
            )
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id)
            atoms = parse_atom_site_loop(cif_text)
        except Exception as exc:
            status = "structure_fetch_failed_review_only"
            status_counts[status] += 1
            rows.append(
                {
                    **row_base,
                    "fetch_status": "failed",
                    "fetch_error": str(exc),
                    "candidate_threshold_angstrom": candidate_threshold_angstrom,
                    "structure_ligand_codes": [],
                    "structure_cofactor_families": [],
                    "terminal_gamma_atom_count": 0,
                    "has_active_state_gamma_metal": False,
                    "target_mapping_chain_count": 0,
                    "target_mapping_complete": False,
                    "source_mapped_phosphoacceptor_candidate_count": 0,
                    "source_phosphoacceptor_within_threshold_count": 0,
                    "nearest_source_phosphoacceptor_distance_angstrom": None,
                    "source_phosphoacceptor_distance_candidates": [],
                    "measurement_ready": False,
                    "alternate_cocomplex_status": status,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue

        inventory = structure_ligand_inventory_from_atoms(atoms)
        structure_ligand_codes = _sorted_strings(inventory.get("ligand_codes", []))
        structure_cofactor_families = _sorted_strings(
            inventory.get("cofactor_families", [])
        )
        gamma_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "HETATM"
            and str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
            in gamma_capable_codes
            and str(atom.get("auth_atom_id") or atom.get("label_atom_id") or "").upper()
            == "PG"
        ]
        has_metal = "metal_ion" in set(structure_cofactor_families)
        target_mapping_candidates = _epk_struct_ref_seq_mapped_position_candidates(
            atoms,
            cif_text,
            target_accession,
            target_positions,
        )
        target_mapped_position_ids = {
            str(candidate.get("uniprot_position") or "")
            for candidate in target_mapping_candidates
        }
        target_mapping_chains = _sorted_strings(
            candidate.get("chain_name") for candidate in target_mapping_candidates
        )
        target_mapping_complete = bool(target_position_ids) and (
            target_position_ids <= target_mapped_position_ids
        )

        source_distance_candidates: list[dict[str, Any]] = []
        for acceptor_accession in acceptor_accessions:
            acceptor_positions = acceptor_features_by_accession.get(
                acceptor_accession, []
            )
            mapped_acceptors = _epk_struct_ref_seq_mapped_position_candidates(
                atoms,
                cif_text,
                acceptor_accession,
                acceptor_positions,
            )
            for mapped_acceptor in mapped_acceptors:
                acceptor_atom_hits = [
                    atom
                    for atom in atoms
                    if atom.get("group_PDB") == "ATOM"
                    and str(atom.get("auth_asym_id") or atom.get("label_asym_id") or "")
                    == str(mapped_acceptor.get("chain_name") or "")
                    and str(atom.get("auth_seq_id") or "")
                    == str(mapped_acceptor.get("resid") or "")
                    and (
                        str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper(),
                        str(atom.get("auth_atom_id") or atom.get("label_atom_id") or "").upper(),
                    )
                    in acceptor_atoms
                ]
                for atom in acceptor_atom_hits:
                    distances = [
                        round(
                            _point_distance(_atom_point(atom), _atom_point(gamma_atom)),
                            3,
                        )
                        for gamma_atom in gamma_atoms
                    ]
                    nearest = min(distances) if distances else None
                    hit = {
                        "acceptor_accession": acceptor_accession,
                        "acceptor_uniprot_position": int(
                            str(mapped_acceptor.get("uniprot_position") or "0")
                        ),
                        "source_description": mapped_acceptor.get(
                            "source_description"
                        ),
                        "source_evidence_codes": mapped_acceptor.get(
                            "source_evidence_codes", []
                        ),
                        "candidate_chain_name": mapped_acceptor.get("chain_name"),
                        "candidate_auth_seq_id": mapped_acceptor.get("resid"),
                        "candidate_residue_code": mapped_acceptor.get("code"),
                        "candidate_atom_name": str(
                            atom.get("auth_atom_id") or atom.get("label_atom_id") or ""
                        ).upper(),
                        "nearest_gamma_distance_angstrom": nearest,
                        "within_candidate_threshold": (
                            nearest is not None
                            and nearest <= candidate_threshold_angstrom
                        ),
                    }
                    source_distance_candidates.append(hit)
                    all_distance_hits.append({**hit, "pdb_id": pdb_id})

        within_threshold_count = sum(
            1
            for hit in source_distance_candidates
            if hit.get("within_candidate_threshold")
        )
        has_active_state_gamma_metal = bool(gamma_atoms) and has_metal
        target_mapping_unambiguous = target_mapping_complete and (
            len(target_mapping_chains) == 1
        )
        measurement_ready = bool(
            has_active_state_gamma_metal
            and target_mapping_unambiguous
            and within_threshold_count > 0
        )
        blockers: list[str] = []
        if not has_active_state_gamma_metal:
            status = "inactive_or_incomplete_active_state_review_only"
            blockers.extend(
                [
                    "active_state_terminal_gamma_or_metal_missing",
                    "protein_substrate_acceptor_not_source_mapped",
                ]
            )
        elif not target_mapping_candidates:
            status = "target_source_mapping_unresolved_review_only"
            blockers.extend(
                [
                    "source_structure_mapping_not_conservative",
                    "protein_substrate_acceptor_not_source_mapped",
                ]
            )
        elif not source_distance_candidates:
            status = "source_phosphoacceptor_absent_from_structure_review_only"
            blockers.extend(
                [
                    "source_phosphoacceptor_not_materialized_in_structure",
                    "protein_substrate_acceptor_not_source_mapped",
                ]
            )
        elif within_threshold_count > 0 and target_mapping_unambiguous:
            status = "measurement_ready_review_only"
            blockers.extend(
                [
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            )
        elif within_threshold_count > 0:
            status = "source_phosphoacceptor_geometry_hit_mapping_ambiguous_review_only"
            blockers.extend(
                [
                    "target_mapping_multiple_chains_review_only",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            )
        else:
            status = "source_phosphoacceptor_geometry_outside_threshold_review_only"
            blockers.extend(
                [
                    "source_phosphoacceptor_geometry_outside_candidate_threshold",
                    "protein_substrate_acceptor_not_source_mapped",
                    "external_hard_negative_reaudit_not_real_scorer",
                ]
            )
        if target_mapping_candidates and not target_mapping_unambiguous:
            blockers.append("target_mapping_multiple_chains_review_only")
        status_counts[status] += 1
        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "structure_ligand_codes": structure_ligand_codes,
                "structure_cofactor_families": structure_cofactor_families,
                "terminal_gamma_atom_count": len(gamma_atoms),
                "has_active_state_gamma_metal": has_active_state_gamma_metal,
                "target_requested_position_count": len(target_position_ids),
                "target_mapped_position_count": len(target_mapped_position_ids),
                "target_mapping_chain_count": len(target_mapping_chains),
                "target_mapping_chains": target_mapping_chains,
                "target_mapping_complete": target_mapping_complete,
                "target_mapping_unambiguous": target_mapping_unambiguous,
                "acceptor_accessions_reviewed": acceptor_accessions,
                "source_mapped_phosphoacceptor_candidate_count": len(
                    source_distance_candidates
                ),
                "source_phosphoacceptor_within_threshold_count": (
                    within_threshold_count
                ),
                "nearest_source_phosphoacceptor_distance_angstrom": (
                    min(
                        hit["nearest_gamma_distance_angstrom"]
                        for hit in source_distance_candidates
                        if hit.get("nearest_gamma_distance_angstrom") is not None
                    )
                    if any(
                        hit.get("nearest_gamma_distance_angstrom") is not None
                        for hit in source_distance_candidates
                    )
                    else None
                ),
                "source_phosphoacceptor_distance_candidates": sorted(
                    source_distance_candidates,
                    key=lambda hit: (
                        float(hit.get("nearest_gamma_distance_angstrom") or 9999),
                        str(hit.get("acceptor_accession") or ""),
                        int(hit.get("acceptor_uniprot_position") or 0),
                        str(hit.get("candidate_chain_name") or ""),
                    ),
                )[:25],
                "measurement_ready": measurement_ready,
                "alternate_cocomplex_status": status,
                "remaining_blockers": sorted(set(blockers)),
            }
        )

    measurement_ready_count = sum(1 for row in rows if row.get("measurement_ready"))
    within_threshold_total = sum(
        1 for hit in all_distance_hits if hit.get("within_candidate_threshold")
    )
    distance_values = [
        float(hit["nearest_gamma_distance_angstrom"])
        for hit in all_distance_hits
        if hit.get("nearest_gamma_distance_angstrom") is not None
    ]
    return {
        "metadata": {
            "method": "epk_external_source_alternate_cocomplex_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_external_protein_substrate_source_scout_method": (
                scout_meta.get("method")
            ),
            "source_epk_external_source_acceptor_source_mapping_review_method": (
                source_mapping_meta.get("method")
            ),
            "target_accession": target_accession,
            "acceptor_accessions_reviewed": acceptor_accessions,
            "source_phosphoacceptor_positions_by_accession": {
                accession: [
                    int(str(feature.get("position") or "0"))
                    for feature in features
                ]
                for accession, features in acceptor_features_by_accession.items()
            },
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "reviewed_pdb_count": len(rows),
            "active_state_structure_count": sum(
                1 for row in rows if row.get("has_active_state_gamma_metal")
            ),
            "target_mapping_unambiguous_structure_count": sum(
                1 for row in rows if row.get("target_mapping_unambiguous")
            ),
            "source_mapped_phosphoacceptor_candidate_count": len(all_distance_hits),
            "source_phosphoacceptor_within_threshold_count": within_threshold_total,
            "nearest_source_phosphoacceptor_distance_angstrom": (
                min(distance_values) if distance_values else None
            ),
            "measurement_ready_candidate_count": measurement_ready_count,
            "alternate_cocomplex_status_counts": dict(sorted(status_counts.items())),
            "gamma_to_source_acceptor_distances_measured": bool(all_distance_hits),
            "ready_to_measure_gamma_acceptor_distance": measurement_ready_count > 0,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "alternate_active_state_substrate_cocomplex_review_executed",
            "blocker_not_removed": [
                "protein_substrate_acceptor_not_source_mapped",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact tests exact source phosphoacceptor residues in "
                "alternate Q8IVT5 co-complex structures. It records negative "
                "geometry evidence only; it does not score ePK, edit registries, "
                "import labels, or create held-out performance evidence."
            ),
            "next_actions": [
                "treat Q8IVT5 exact phosphoacceptor geometry as terminally not measurement-ready unless new source structures appear",
                "continue to lower-priority mapped accessions with active gamma/metal sourcing",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Alternate co-complex source evidence remains review-only and "
                "cannot promote an ePK fingerprint without calibrated controls."
            )
        ],
    }


def build_epk_ligand_specific_5hvk_source_validity_review(
    *,
    epk_ligand_specific_5hvk_review_priority: dict[str, Any],
    kinase_uniprot_entry: dict[str, Any] | None = None,
    acceptor_uniprot_entry: dict[str, Any] | None = None,
    pdb_id: str = "5HVK",
    kinase_accession: str = "P53667",
    acceptor_accession: str = "P23528",
    candidate_threshold_angstrom: float = 6.0,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Review the ligand-specific 5HVK kinase/substrate source lead."""

    if candidate_threshold_angstrom <= 0:
        raise ValueError("candidate_threshold_angstrom must be positive")

    priority_meta = epk_ligand_specific_5hvk_review_priority.get("metadata", {})
    if not isinstance(priority_meta, dict):
        priority_meta = {}
    target_fingerprint_id = str(
        priority_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    pdb_id = str(pdb_id or "").upper()
    kinase_accession = str(kinase_accession or "").upper()
    acceptor_accession = str(acceptor_accession or "").upper()
    cif_text_by_pdb = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    kinase_record = _unwrap_uniprot_entry_record(kinase_uniprot_entry)
    acceptor_record = _unwrap_uniprot_entry_record(acceptor_uniprot_entry)

    priority_rows = [
        row
        for row in epk_ligand_specific_5hvk_review_priority.get("rows", []) or []
        if isinstance(row, dict)
    ]
    priority_source_rows = [
        row
        for row in priority_rows
        if str(row.get("pdb_id") or "").upper() == pdb_id
        and str(row.get("accession") or "").upper() == kinase_accession
    ]
    priority_acceptor_rows = [
        row
        for row in priority_rows
        if str(row.get("pdb_id") or "").upper() == pdb_id
        and str(row.get("accession") or "").upper() == acceptor_accession
    ]

    fetch_status = "not_attempted"
    fetch_error = None
    cif_text = cif_text_by_pdb.get(pdb_id)
    try:
        if cif_text is None:
            cif_text = cif_fetcher(pdb_id)
        fetch_status = "fetched"
    except Exception as exc:  # pragma: no cover - network failure is data.
        cif_text = ""
        fetch_status = "fetch_failed"
        fetch_error = str(exc)

    atoms = parse_atom_site_loop(cif_text) if cif_text else []
    entity_rows = _epk_mmcif_rows(cif_text, "_entity.") if cif_text else []
    struct_rows = _epk_mmcif_rows(cif_text, "_struct.") if cif_text else []
    keyword_rows = _epk_mmcif_rows(cif_text, "_struct_keywords.") if cif_text else []
    citation_rows = _epk_mmcif_rows(cif_text, "_citation.") if cif_text else []
    struct_ref_rows = _epk_struct_ref_seq_rows(cif_text) if cif_text else []

    structure_title = _first_present_value(struct_rows, "title")
    citation_titles = _sorted_strings(
        row.get("title")
        for row in citation_rows
        if row.get("title") not in {None, "", ".", "?"}
    )
    keyword_text = " ".join(
        _sorted_strings(
            value
            for row in keyword_rows
            for value in (row.get("pdbx_keywords"), row.get("text"))
            if value not in {None, "", ".", "?"}
        )
    )
    entity_descriptions = _sorted_strings(
        row.get("pdbx_description")
        for row in entity_rows
        if row.get("pdbx_description") not in {None, "", ".", "?"}
    )
    source_text = " ".join(
        [structure_title or "", keyword_text]
        + citation_titles
        + entity_descriptions
    ).lower()
    structure_pair_evidence_present = (
        "limk1" in source_text
        and "cofilin" in source_text
        and ("kinase substrate" in source_text or "lim kinases" in source_text)
    )

    refs_by_accession: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in struct_ref_rows:
        accession = str(row.get("pdbx_db_accession") or "").upper()
        if accession:
            refs_by_accession[accession].append(row)
    kinase_chain_ids = _sorted_strings(
        row.get("pdbx_strand_id") for row in refs_by_accession.get(kinase_accession, [])
    )
    acceptor_chain_ids = _sorted_strings(
        row.get("pdbx_strand_id")
        for row in refs_by_accession.get(acceptor_accession, [])
    )
    structure_has_both_accessions = bool(kinase_chain_ids and acceptor_chain_ids)

    kinase_catalytic_reactions = _sorted_strings(
        row.get("reaction") for row in kinase_record.get("catalytic_activity_comments", [])
    )
    kinase_has_protein_ser_thr_activity = any(
        ("l-seryl-[protein]" in reaction.lower() or "l-threonyl-[protein]" in reaction.lower())
        and "atp" in reaction.lower()
        for reaction in kinase_catalytic_reactions
    )
    kinase_has_atp_binding_feature = any(
        "atp" in str(feature.get("ligand_name") or "").lower()
        or "chebi:30616" in str(feature.get("ligand_id") or "").lower()
        for feature in kinase_record.get("binding_site_features", []) or []
        if isinstance(feature, dict)
    )
    kinase_has_active_site_feature = bool(
        kinase_record.get("active_site_features", []) or []
    )

    phosphoacceptor_features = _epk_uniprot_phosphoacceptor_features(acceptor_record)
    acceptor_ser3_features = [
        feature
        for feature in phosphoacceptor_features
        if str(feature.get("position") or "") == "3"
        and "phosphoserine" in str(feature.get("description") or "").lower()
    ]
    acceptor_ser3_source_present = bool(acceptor_ser3_features)
    acceptor_position_requests = acceptor_ser3_features or [
        {
            "position": "3",
            "roles": ["candidate_source_phosphoacceptor"],
            "description": "Ser3 phosphoacceptor candidate from 5HVK priority artifact",
            "evidence_codes": [],
        }
    ]
    acceptor_mapped_candidates = (
        _epk_struct_ref_seq_mapped_position_candidates(
            atoms, cif_text, acceptor_accession, acceptor_position_requests
        )
        if atoms and cif_text
        else []
    )

    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    gamma_atoms = [
        atom
        for atom in atoms
        if atom.get("group_PDB") == "HETATM"
        and _epk_atom_code(atom) in gamma_capable_codes
        and _epk_atom_name(atom) == "PG"
    ]
    acceptor_distance_hits: list[dict[str, Any]] = []
    for candidate in acceptor_mapped_candidates:
        residue_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "ATOM"
            and candidate.get("chain_name") in _label_atom_chain_ids(atom)
            and str(atom.get("auth_seq_id") or "") == str(candidate.get("resid") or "")
            and _epk_atom_code(atom) == "SER"
            and _epk_atom_name(atom) == "OG"
        ]
        for acceptor_atom in residue_atoms:
            nearest_gamma = None
            nearest_distance = None
            for gamma_atom in gamma_atoms:
                distance = _epk_atom_distance(acceptor_atom, gamma_atom)
                if nearest_distance is None or distance < nearest_distance:
                    nearest_distance = distance
                    nearest_gamma = gamma_atom
            if nearest_gamma is not None and nearest_distance is not None:
                acceptor_distance_hits.append(
                    {
                        "acceptor_accession": acceptor_accession,
                        "acceptor_uniprot_position": 3,
                        "candidate_chain_name": candidate.get("chain_name"),
                        "candidate_auth_seq_id": candidate.get("resid"),
                        "candidate_residue_code": candidate.get("code"),
                        "acceptor_atom_name": _epk_atom_name(acceptor_atom),
                        "gamma_ligand_code": _epk_atom_code(nearest_gamma),
                        "gamma_atom_name": _epk_atom_name(nearest_gamma),
                        "gamma_chain_name": str(
                            nearest_gamma.get("auth_asym_id")
                            or nearest_gamma.get("label_asym_id")
                            or ""
                        ),
                        "gamma_auth_seq_id": str(
                            nearest_gamma.get("auth_seq_id")
                            or nearest_gamma.get("label_seq_id")
                            or ""
                        ),
                        "nearest_gamma_distance_angstrom": round(nearest_distance, 3),
                        "within_candidate_threshold": (
                            nearest_distance <= candidate_threshold_angstrom
                        ),
                        "mapping_basis": candidate.get("mapping_basis"),
                        "source_description": candidate.get("source_description"),
                        "source_evidence_codes": candidate.get(
                            "source_evidence_codes", []
                        ),
                    }
                )

    within_threshold_hits = [
        hit for hit in acceptor_distance_hits if hit.get("within_candidate_threshold")
    ]
    source_valid = all(
        [
            bool(priority_source_rows),
            bool(priority_acceptor_rows),
            fetch_status == "fetched",
            structure_has_both_accessions,
            structure_pair_evidence_present,
            kinase_has_protein_ser_thr_activity,
            kinase_has_atp_binding_feature,
            kinase_has_active_site_feature,
            acceptor_ser3_source_present,
            bool(within_threshold_hits),
        ]
    )
    if source_valid:
        source_validity_status = "accepted_source_valid_kinase_substrate_cocomplex_review_only"
        measurement_ready = True
        blockers = [
            "threshold_not_calibrated_against_negative_controls",
            "external_hard_negative_reaudit_not_real_scorer",
            "registry_and_label_factory_extension_not_implemented",
        ]
    elif fetch_status != "fetched":
        source_validity_status = "source_validity_unresolved_fetch_failed_review_only"
        measurement_ready = False
        blockers = [
            "5hvk_cif_fetch_failed",
            "manual_source_review_required",
            "external_hard_negative_reaudit_not_real_scorer",
        ]
    elif not bool(within_threshold_hits):
        source_validity_status = "terminal_not_ready_no_source_mapped_acceptor_geometry_review_only"
        measurement_ready = False
        blockers = [
            "source_mapped_acceptor_not_within_candidate_threshold",
            "external_hard_negative_reaudit_not_real_scorer",
        ]
    else:
        source_validity_status = "source_validity_unresolved_missing_source_axis_review_only"
        measurement_ready = False
        blockers = [
            "manual_source_review_required",
            "source_axis_incomplete",
            "external_hard_negative_reaudit_not_real_scorer",
        ]

    measurement_ready_count = 1 if measurement_ready else 0
    return {
        "metadata": {
            "method": "epk_ligand_specific_5hvk_source_validity_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_ligand_specific_5hvk_review_priority_method": (
                priority_meta.get("method")
            ),
            "pdb_id": pdb_id,
            "kinase_accession": kinase_accession,
            "acceptor_accession": acceptor_accession,
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "fetch_status": fetch_status,
            "fetch_error": fetch_error,
            "structure_title": structure_title,
            "citation_titles": citation_titles,
            "entity_descriptions": entity_descriptions,
            "keyword_text": keyword_text,
            "structure_pair_evidence_present": structure_pair_evidence_present,
            "structure_has_both_accessions": structure_has_both_accessions,
            "kinase_chain_ids": kinase_chain_ids,
            "acceptor_chain_ids": acceptor_chain_ids,
            "kinase_has_protein_ser_thr_activity": (
                kinase_has_protein_ser_thr_activity
            ),
            "kinase_has_atp_binding_feature": kinase_has_atp_binding_feature,
            "kinase_has_active_site_feature": kinase_has_active_site_feature,
            "kinase_catalytic_reactions": kinase_catalytic_reactions,
            "acceptor_ser3_source_present": acceptor_ser3_source_present,
            "acceptor_ser3_source_descriptions": _sorted_strings(
                feature.get("description") for feature in acceptor_ser3_features
            ),
            "acceptor_ser3_source_evidence_codes": _sorted_strings(
                code
                for feature in acceptor_ser3_features
                for code in feature.get("evidence_codes", [])
            ),
            "terminal_gamma_atom_count": len(gamma_atoms),
            "source_mapped_acceptor_candidate_count": len(acceptor_mapped_candidates),
            "source_phosphoacceptor_within_threshold_count": len(
                within_threshold_hits
            ),
            "nearest_source_phosphoacceptor_distance_angstrom": (
                min(
                    float(hit["nearest_gamma_distance_angstrom"])
                    for hit in acceptor_distance_hits
                )
                if acceptor_distance_hits
                else None
            ),
            "source_validity_status": source_validity_status,
            "source_validated_kinase_substrate_pair": source_valid,
            "measurement_ready_candidate_count": measurement_ready_count,
            "ready_to_measure_gamma_acceptor_distance": measurement_ready,
            "ready_to_rerun_controls": measurement_ready,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": (
                "5hvk_source_validity_review_executed"
                if fetch_status == "fetched"
                else None
            ),
            "blocker_not_removed": blockers,
            "review_only_rule": (
                "This artifact validates the 5HVK LIMK1/cofilin source lead "
                "as review-only evidence. Even when the source pair is accepted, "
                "it only authorizes rerunning measurement and controls; it does "
                "not score ePK, import labels, edit registries, or claim held-out "
                "performance."
            ),
            "next_actions": (
                [
                    "rerun the ligand-specific acceptor geometry/control surface with 5HVK included as source-valid review evidence",
                    "rerun sibling-family and imported external hard-negative controls before any score or threshold decision",
                    "keep registry and label-factory extension closed until calibrated gates pass",
                ]
                if measurement_ready
                else [
                    "do not use 5HVK as measurement-ready evidence unless the missing source axis is repaired",
                    "continue ligand-specific substrate/co-complex sourcing with a new query axis",
                    "keep ePK scorer and external hard-negative scored re-audit closed",
                ]
            ),
        },
        "rows": [
            {
                "row_id": "5hvk_ligand_specific_source_validity_review",
                "pdb_id": pdb_id,
                "kinase_accession": kinase_accession,
                "acceptor_accession": acceptor_accession,
                "target_family_id": "epk",
                "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                "review_only": True,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "source_validity_status": source_validity_status,
                "source_validated_kinase_substrate_pair": source_valid,
                "measurement_ready": measurement_ready,
                "structure_pair_evidence_present": structure_pair_evidence_present,
                "kinase_has_protein_ser_thr_activity": (
                    kinase_has_protein_ser_thr_activity
                ),
                "acceptor_ser3_source_present": acceptor_ser3_source_present,
                "acceptor_distance_hits": sorted(
                    acceptor_distance_hits,
                    key=lambda hit: (
                        float(hit.get("nearest_gamma_distance_angstrom") or 9999),
                        str(hit.get("candidate_chain_name") or ""),
                    ),
                ),
                "remaining_blockers": blockers,
            }
        ],
        "warnings": [
            (
                "5HVK source validity is review-only and cannot activate an "
                "ePK scorer or label import without calibrated controls."
            )
        ],
    }


def build_epk_ligand_specific_5hvk_control_rerun_queue(
    *,
    epk_ligand_specific_5hvk_source_validity_review: dict[str, Any],
    epk_review_only_scoring_prototype: dict[str, Any],
    epk_review_only_external_hard_negative_score_probe: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Queue the next review-only control rerun after 5HVK source validation."""

    source_meta = epk_ligand_specific_5hvk_source_validity_review.get(
        "metadata", {}
    )
    if not isinstance(source_meta, dict):
        source_meta = {}
    prototype_meta = epk_review_only_scoring_prototype.get("metadata", {})
    if not isinstance(prototype_meta, dict):
        prototype_meta = {}
    external_probe_meta = (
        epk_review_only_external_hard_negative_score_probe.get("metadata", {})
        if isinstance(epk_review_only_external_hard_negative_score_probe, dict)
        else {}
    )
    if not isinstance(external_probe_meta, dict):
        external_probe_meta = {}

    prototype_rows = [
        row
        for row in epk_review_only_scoring_prototype.get("rows", []) or []
        if isinstance(row, dict)
    ]
    current_positive_rows = [
        row
        for row in prototype_rows
        if row.get("row_type") == "current_epk_positive_prototype"
    ]
    sibling_control_rows = [
        row
        for row in prototype_rows
        if row.get("row_type")
        in {
            "sibling_homolog_negative_control",
            "sibling_family_specific_negative_control",
        }
    ]
    imported_external_rows = [
        row
        for row in prototype_rows
        if row.get("row_type") == "imported_external_hard_negative"
    ]

    source_ready = bool(
        source_meta.get("source_validated_kinase_substrate_pair")
    ) and int(source_meta.get("measurement_ready_candidate_count") or 0) > 0
    prototype_ready = (
        prototype_meta.get("method") == "epk_review_only_scoring_prototype"
        and bool(prototype_rows)
    )
    control_surface_available = bool(
        sibling_control_rows and imported_external_rows
    )
    queue_ready = source_ready and prototype_ready and control_surface_available
    queue_status = (
        "ready_for_review_only_control_rerun"
        if queue_ready
        else "blocked_review_only_control_rerun_inputs_incomplete"
    )

    blocker_not_removed = [
        "threshold_not_calibrated_against_negative_controls",
        "external_hard_negative_reaudit_not_real_scorer",
        "registry_and_label_factory_extension_not_implemented",
    ]
    if not source_ready:
        blocker_not_removed.insert(0, "5hvk_source_validity_not_measurement_ready")
    if not prototype_ready:
        blocker_not_removed.insert(0, "review_only_prototype_surface_missing")
    if not control_surface_available:
        blocker_not_removed.insert(0, "review_only_control_surface_missing")

    rows = [
        {
            "task_id": "add_5hvk_source_valid_candidate_to_review_only_prototype",
            "task_type": "candidate_positive_rerun",
            "pdb_id": source_meta.get("pdb_id"),
            "kinase_accession": source_meta.get("kinase_accession"),
            "acceptor_accession": source_meta.get("acceptor_accession"),
            "nearest_source_phosphoacceptor_distance_angstrom": source_meta.get(
                "nearest_source_phosphoacceptor_distance_angstrom"
            ),
            "source_validated_kinase_substrate_pair": bool(
                source_meta.get("source_validated_kinase_substrate_pair")
            ),
            "measurement_ready": source_ready,
            "review_only": True,
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "queue_status": (
                "ready_review_only"
                if source_ready
                else "blocked_source_not_measurement_ready"
            ),
        },
        {
            "task_id": "rerun_current_sibling_control_surface",
            "task_type": "sibling_control_rerun",
            "carried_control_row_count": len(sibling_control_rows),
            "carried_control_decision_counts": dict(
                sorted(
                    Counter(
                        str(row.get("prototype_decision") or "")
                        for row in sibling_control_rows
                    ).items()
                )
            ),
            "review_only": True,
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "queue_status": (
                "ready_review_only"
                if sibling_control_rows
                else "blocked_no_sibling_control_rows"
            ),
        },
        {
            "task_id": "rerun_imported_external_hard_negative_controls",
            "task_type": "imported_external_hard_negative_control_rerun",
            "imported_external_hard_negative_row_count": len(imported_external_rows),
            "review_only_external_score_probe_method": external_probe_meta.get(
                "method"
            ),
            "review_only_score_probe_non_abstention_count": external_probe_meta.get(
                "review_only_score_probe_non_abstention_count"
            ),
            "not_a_real_scored_reaudit": bool(
                external_probe_meta.get("not_a_real_scored_reaudit")
            ),
            "review_only": True,
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "queue_status": (
                "ready_review_only_not_real_scored_reaudit"
                if imported_external_rows
                else "blocked_no_imported_external_rows"
            ),
        },
    ]

    return {
        "metadata": {
            "method": "epk_ligand_specific_5hvk_control_rerun_queue",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": (
                source_meta.get("target_fingerprint_id")
                or prototype_meta.get("target_fingerprint_id")
                or "epk_atp_gamma_phosphoryl_transfer"
            ),
            "source_epk_ligand_specific_5hvk_source_validity_review_method": (
                source_meta.get("method")
            ),
            "source_epk_review_only_scoring_prototype_method": (
                prototype_meta.get("method")
            ),
            "source_epk_review_only_external_hard_negative_score_probe_method": (
                external_probe_meta.get("method")
            ),
            "control_rerun_queue_status": queue_status,
            "source_validated_kinase_substrate_pair": bool(
                source_meta.get("source_validated_kinase_substrate_pair")
            ),
            "source_measurement_ready_candidate_count": source_meta.get(
                "measurement_ready_candidate_count"
            ),
            "nearest_source_phosphoacceptor_distance_angstrom": source_meta.get(
                "nearest_source_phosphoacceptor_distance_angstrom"
            ),
            "prototype_row_count": len(prototype_rows),
            "current_positive_prototype_row_count": len(current_positive_rows),
            "sibling_control_row_count": len(sibling_control_rows),
            "imported_external_hard_negative_row_count": len(imported_external_rows),
            "review_only_score_probe_non_abstention_count": external_probe_meta.get(
                "review_only_score_probe_non_abstention_count"
            ),
            "not_a_real_scored_reaudit": bool(
                external_probe_meta.get("not_a_real_scored_reaudit")
            ),
            "ready_for_review_only_control_rerun": queue_ready,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_not_removed": blocker_not_removed,
            "next_actions": [
                "add the source-valid 5HVK lead to the review-only ePK prototype surface",
                "rerun sibling-family controls under the same candidate decision surface",
                "rerun imported external hard negatives only as review-only diagnostics until a real calibrated scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "This queue is a review-only control-rerun plan. It does not "
                "compute a calibrated ePK score or a real external hard-negative "
                "scored re-audit."
            )
        ],
    }


def build_epk_ligand_specific_5hvk_prototype_control_rerun(
    *,
    epk_ligand_specific_5hvk_source_validity_review: dict[str, Any],
    epk_ligand_specific_5hvk_control_rerun_queue: dict[str, Any],
    epk_review_only_scoring_prototype: dict[str, Any],
    epk_review_only_external_hard_negative_score_probe: dict[str, Any] | None = None,
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Run the queued 5HVK review-only prototype/control diagnostic."""

    source_meta = epk_ligand_specific_5hvk_source_validity_review.get(
        "metadata", {}
    )
    if not isinstance(source_meta, dict):
        source_meta = {}
    queue_meta = epk_ligand_specific_5hvk_control_rerun_queue.get("metadata", {})
    if not isinstance(queue_meta, dict):
        queue_meta = {}
    prototype_meta = epk_review_only_scoring_prototype.get("metadata", {})
    if not isinstance(prototype_meta, dict):
        prototype_meta = {}
    external_probe_meta = (
        epk_review_only_external_hard_negative_score_probe.get("metadata", {})
        if isinstance(epk_review_only_external_hard_negative_score_probe, dict)
        else {}
    )
    if not isinstance(external_probe_meta, dict):
        external_probe_meta = {}

    target_fingerprint_id = str(
        source_meta.get("target_fingerprint_id")
        or queue_meta.get("target_fingerprint_id")
        or prototype_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    source_ready = bool(
        source_meta.get("source_validated_kinase_substrate_pair")
    ) and int(source_meta.get("measurement_ready_candidate_count") or 0) > 0
    queue_ready = bool(queue_meta.get("ready_for_review_only_control_rerun"))

    prototype_rows = [
        row
        for row in epk_review_only_scoring_prototype.get("rows", []) or []
        if isinstance(row, dict)
    ]
    current_positive_rows = [
        row
        for row in prototype_rows
        if row.get("row_type") == "current_epk_positive_prototype"
    ]
    sibling_control_rows = [
        row
        for row in prototype_rows
        if row.get("row_type")
        in {
            "sibling_homolog_negative_control",
            "sibling_family_specific_negative_control",
        }
    ]
    imported_external_rows = [
        row
        for row in prototype_rows
        if row.get("row_type") == "imported_external_hard_negative"
    ]

    decision_counts: Counter[str] = Counter()
    rows: list[dict[str, Any]] = []
    for row in current_positive_rows:
        decision = str(
            row.get("prototype_decision")
            or "candidate_positive_signal_review_only_not_calibrated"
        )
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "carried_current_epk_positive_prototype",
                "entry_id": row.get("entry_id"),
                "entry_name": row.get("entry_name"),
                "pdb_id": row.get("pdb_id"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "prototype_axis_values": row.get("prototype_axis_values", {}),
                "review_only_prototype_score": row.get(
                    "review_only_prototype_score"
                ),
                "prototype_decision": decision,
                "rerun_surface_role": "carried_current_positive",
                "remaining_blockers": row.get("remaining_blockers", []),
            }
        )

    source_distance = source_meta.get(
        "nearest_source_phosphoacceptor_distance_angstrom"
    )
    try:
        source_gamma_axis_present = (
            source_distance is not None
            and float(source_distance) <= float(candidate_threshold_angstrom)
        )
    except (TypeError, ValueError):
        source_gamma_axis_present = False
    try:
        terminal_gamma_atom_count = int(source_meta.get("terminal_gamma_atom_count") or 0)
    except (TypeError, ValueError):
        terminal_gamma_atom_count = 0
    source_entity_descriptions = source_meta.get("entity_descriptions", [])
    if not isinstance(source_entity_descriptions, list):
        source_entity_descriptions = []
    source_axis_values = {
        "local_adenine_nucleotide_ligand": int(terminal_gamma_atom_count > 0),
        "local_metal_ligand": int("MAGNESIUM ION" in source_entity_descriptions),
        "source_kinase_active_site_feature": int(
            bool(source_meta.get("kinase_has_active_site_feature"))
        ),
        "gamma_to_acceptor_distance_within_candidate_cutoff": int(
            source_gamma_axis_present
        ),
        "source_validated_protein_substrate_acceptor_identity": int(source_ready),
    }
    source_all_axes = all(value == 1 for value in source_axis_values.values())
    source_decision = (
        "source_valid_5hvk_positive_signal_review_only_not_calibrated"
        if source_all_axes
        else "source_valid_5hvk_abstain_missing_required_axis_review_only"
    )
    decision_counts[source_decision] += 1
    rows.append(
        {
            "row_type": "ligand_specific_5hvk_source_valid_positive_candidate",
            "entry_id": None,
            "pdb_id": source_meta.get("pdb_id"),
            "kinase_accession": source_meta.get("kinase_accession"),
            "acceptor_accession": source_meta.get("acceptor_accession"),
            "target_fingerprint_id": target_fingerprint_id,
            "review_only": True,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "prototype_axis_values": source_axis_values,
            "review_only_prototype_score": round(
                sum(source_axis_values.values()) / len(source_axis_values), 4
            ),
            "prototype_decision": source_decision,
            "nearest_gamma_to_source_phosphoacceptor_distance_angstrom": (
                source_distance
            ),
            "acceptor_context_type": "source_validated_protein_substrate_serine",
            "source_validity_status": source_meta.get("source_validity_status"),
            "predictive_use_status": (
                "review_only_source_validity_not_production_scoring_input"
            ),
            "text_free_inputs_only": False,
            "rerun_surface_role": "new_source_valid_positive_lead",
            "remaining_blockers": [
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
        }
    )

    for row in sibling_control_rows:
        decision = str(
            row.get("prototype_decision") or "sibling_control_blocked_review_only"
        )
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": row.get("row_type"),
                "pdb_id": row.get("pdb_id"),
                "family_id": row.get("family_id"),
                "family_name": row.get("family_name"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "prototype_axis_values": row.get("prototype_axis_values", {}),
                "review_only_prototype_score": row.get(
                    "review_only_prototype_score", 0.0
                ),
                "prototype_decision": decision,
                "candidate_feature_hit": False,
                "rerun_surface_role": "carried_sibling_control",
                "remaining_blockers": row.get("remaining_blockers", []),
            }
        )

    for row in imported_external_rows:
        decision = str(
            row.get("prototype_decision")
            or "external_hard_negative_abstain_missing_epk_axes_review_only"
        )
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "imported_external_hard_negative",
                "entry_id": row.get("entry_id"),
                "accession": row.get("accession"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "prototype_axis_values": row.get("prototype_axis_values", {}),
                "review_only_prototype_score": row.get(
                    "review_only_prototype_score", 0.0
                ),
                "prototype_decision": decision,
                "candidate_feature_hit": False,
                "rerun_surface_role": "carried_imported_external_hard_negative",
                "not_a_real_scored_reaudit": True,
                "remaining_blockers": row.get("remaining_blockers", []),
            }
        )

    sibling_false_hit_count = sum(
        1
        for row in rows
        if row.get("rerun_surface_role") == "carried_sibling_control"
        and bool(row.get("candidate_feature_hit"))
    )
    external_non_abstention_count = sum(
        1
        for row in rows
        if row.get("rerun_surface_role")
        == "carried_imported_external_hard_negative"
        and row.get("prototype_decision")
        != "external_hard_negative_abstain_missing_epk_axes_review_only"
    )
    positive_like_row_count = sum(
        1
        for row in rows
        if row.get("prototype_decision")
        in {
            "candidate_positive_signal_review_only_not_calibrated",
            "source_valid_5hvk_positive_signal_review_only_not_calibrated",
        }
    )
    control_rerun_status = (
        "passes_review_only_controls_but_scorer_blocked"
        if source_ready
        and queue_ready
        and sibling_control_rows
        and imported_external_rows
        and sibling_false_hit_count == 0
        and external_non_abstention_count == 0
        else "blocked_review_only_control_rerun"
    )

    return {
        "metadata": {
            "method": "epk_ligand_specific_5hvk_prototype_control_rerun",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_ligand_specific_5hvk_source_validity_review_method": (
                source_meta.get("method")
            ),
            "source_epk_ligand_specific_5hvk_control_rerun_queue_method": (
                queue_meta.get("method")
            ),
            "source_epk_review_only_scoring_prototype_method": (
                prototype_meta.get("method")
            ),
            "source_epk_review_only_external_hard_negative_score_probe_method": (
                external_probe_meta.get("method")
            ),
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "control_rerun_status": control_rerun_status,
            "source_valid_5hvk_candidate_added": source_ready,
            "source_valid_5hvk_candidate_axis_complete": source_all_axes,
            "source_valid_5hvk_distance_angstrom": source_distance,
            "current_positive_prototype_row_count": len(current_positive_rows),
            "source_valid_5hvk_candidate_row_count": 1 if source_ready else 0,
            "positive_like_review_row_count": positive_like_row_count,
            "sibling_control_row_count": len(sibling_control_rows),
            "sibling_control_false_hit_count": sibling_false_hit_count,
            "imported_external_hard_negative_row_count": len(imported_external_rows),
            "imported_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "review_only_score_probe_non_abstention_count": external_probe_meta.get(
                "review_only_score_probe_non_abstention_count"
            ),
            "not_a_real_scored_reaudit": True,
            "row_count": len(rows),
            "prototype_decision_counts": dict(sorted(decision_counts.items())),
            "prototype_gate_status": "fail_closed_review_only",
            "prototype_failed_closed": True,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "negative_control_distance_distribution_ready": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "use the 5HVK source-valid positive lead to design a calibrated protein-substrate acceptor axis",
                "keep imported external hard negatives in diagnostic mode until a real ePK scorer exists",
                "do not edit fingerprint or label registries until threshold and factory gates pass",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type")),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("pdb_id") or ""),
                str(row.get("accession") or ""),
            ),
        ),
        "warnings": [
            (
                "This 5HVK rerun is a review-only diagnostic. It does not "
                "compute a calibrated ePK score or a real external "
                "hard-negative scored re-audit."
            )
        ],
    }


def build_epk_5hvk_protein_substrate_axis_generalization_audit(
    *,
    epk_protein_substrate_acceptor_candidate_audit: dict[str, Any],
    epk_ligand_specific_5hvk_prototype_control_rerun: dict[str, Any],
) -> dict[str, Any]:
    """Audit whether 5HVK strengthens the protein-substrate acceptor axis."""

    protein_meta = epk_protein_substrate_acceptor_candidate_audit.get(
        "metadata", {}
    )
    if not isinstance(protein_meta, dict):
        protein_meta = {}
    rerun_meta = epk_ligand_specific_5hvk_prototype_control_rerun.get(
        "metadata", {}
    )
    if not isinstance(rerun_meta, dict):
        rerun_meta = {}

    target_fingerprint_id = str(
        protein_meta.get("target_fingerprint_id")
        or rerun_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    current_hit_count = int(protein_meta.get("current_positive_feature_hit_count") or 0)
    ligand_analog_miss_count = int(
        protein_meta.get("ligand_analog_only_positive_miss_count") or 0
    )
    source_valid_5hvk_count = (
        1 if bool(rerun_meta.get("source_valid_5hvk_candidate_added")) else 0
    )
    combined_positive_like_count = current_hit_count + source_valid_5hvk_count
    sibling_false_hit_count = int(
        rerun_meta.get("sibling_control_false_hit_count")
        or protein_meta.get("negative_control_false_hit_count")
        or 0
    )
    external_non_abstention_count = int(
        rerun_meta.get("imported_external_hard_negative_non_abstention_count")
        or 0
    )
    generalization_status = (
        "passes_review_only_generalization_but_not_scoring_admissible"
        if combined_positive_like_count >= 3
        and sibling_false_hit_count == 0
        and external_non_abstention_count == 0
        else "blocked_review_only_generalization"
    )
    ligand_analog_required_for_minimum_review_set = combined_positive_like_count < 3

    rows = [
        {
            "row_type": "current_m_csa_protein_substrate_positive_summary",
            "review_only": True,
            "target_fingerprint_id": target_fingerprint_id,
            "current_positive_feature_hit_count": current_hit_count,
            "current_positive_feature_miss_count": protein_meta.get(
                "current_positive_feature_miss_count"
            ),
            "ligand_analog_only_positive_miss_count": ligand_analog_miss_count,
            "ligand_analog_only_positive_miss_entry_ids": protein_meta.get(
                "ligand_analog_only_positive_miss_entry_ids",
                [],
            ),
            "countable_label_candidate": False,
            "epk_score_computed": False,
        },
        {
            "row_type": "source_valid_5hvk_protein_substrate_positive_lead",
            "review_only": True,
            "target_fingerprint_id": target_fingerprint_id,
            "source_valid_5hvk_candidate_added": bool(
                rerun_meta.get("source_valid_5hvk_candidate_added")
            ),
            "source_valid_5hvk_candidate_axis_complete": bool(
                rerun_meta.get("source_valid_5hvk_candidate_axis_complete")
            ),
            "source_valid_5hvk_distance_angstrom": rerun_meta.get(
                "source_valid_5hvk_distance_angstrom"
            ),
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "ready_for_label_import": False,
        },
        {
            "row_type": "combined_review_control_summary",
            "review_only": True,
            "target_fingerprint_id": target_fingerprint_id,
            "combined_protein_substrate_positive_like_count": (
                combined_positive_like_count
            ),
            "sibling_control_false_hit_count": sibling_false_hit_count,
            "imported_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "feature_admissible_for_production_scoring": False,
            "external_hard_negative_reaudit_scored": False,
            "threshold_calibrated": False,
            "epk_score_computed": False,
        },
    ]

    return {
        "metadata": {
            "method": "epk_5hvk_protein_substrate_axis_generalization_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_acceptor_candidate_audit_method": (
                protein_meta.get("method")
            ),
            "source_epk_ligand_specific_5hvk_prototype_control_rerun_method": (
                rerun_meta.get("method")
            ),
            "generalization_status": generalization_status,
            "current_m_csa_protein_substrate_positive_hit_count": current_hit_count,
            "source_valid_5hvk_protein_substrate_positive_count": (
                source_valid_5hvk_count
            ),
            "combined_protein_substrate_positive_like_count": (
                combined_positive_like_count
            ),
            "ligand_analog_only_positive_miss_count": ligand_analog_miss_count,
            "ligand_analog_required_for_minimum_review_set": (
                ligand_analog_required_for_minimum_review_set
            ),
            "sibling_control_false_hit_count": sibling_false_hit_count,
            "imported_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "feature_admissible_for_production_scoring": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "protein_substrate_axis_not_calibrated_as_real_scorer",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "calibrate the protein-substrate acceptor axis only after a real scorer design is frozen",
                "keep m_csa:640 ligand-analog evidence review-only unless a future policy is pre-registered",
                "rerun imported external hard negatives as real scored controls only after threshold selection",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "This audit shows review-only protein-substrate coverage with "
                "5HVK; it is not production scoring evidence or a clean held-out "
                "performance claim."
            )
        ],
    }


def build_epk_protein_substrate_scorer_design_freeze(
    *,
    epk_5hvk_protein_substrate_axis_generalization_audit: dict[str, Any],
) -> dict[str, Any]:
    """Freeze a review-only ePK protein-substrate diagnostic scorer design."""

    axis_meta = epk_5hvk_protein_substrate_axis_generalization_audit.get(
        "metadata", {}
    )
    if not isinstance(axis_meta, dict):
        axis_meta = {}
    target_fingerprint_id = str(
        axis_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    combined_positive_count = int(
        axis_meta.get("combined_protein_substrate_positive_like_count") or 0
    )
    sibling_false_hit_count = int(axis_meta.get("sibling_control_false_hit_count") or 0)
    external_non_abstention_count = int(
        axis_meta.get("imported_external_hard_negative_non_abstention_count") or 0
    )
    diagnostic_ready = (
        combined_positive_count >= 3
        and sibling_false_hit_count == 0
        and external_non_abstention_count == 0
    )
    design_status = (
        "frozen_review_only_ready_for_diagnostic_calibration"
        if diagnostic_ready
        else "blocked_review_only_design_inputs_incomplete"
    )
    design_version = "epk_protein_substrate_scorer_design_v0_2026_05_19"
    rows = [
        {
            "axis_id": "local_gamma_capable_adenine_nucleotide",
            "axis_type": "local_geometry",
            "predictive_use_status": "diagnostic_candidate_axis_only",
            "required_for_full_axis": True,
            "review_only": True,
        },
        {
            "axis_id": "local_metal_context",
            "axis_type": "local_ligand_context",
            "predictive_use_status": "diagnostic_candidate_axis_only",
            "required_for_full_axis": True,
            "review_only": True,
        },
        {
            "axis_id": "catalytic_acid_base_context",
            "axis_type": "local_or_source_authority_context",
            "predictive_use_status": "diagnostic_not_orphan_discovery_evidence",
            "required_for_full_axis": True,
            "review_only": True,
        },
        {
            "axis_id": "source_validated_protein_substrate_hydroxyl_acceptor",
            "axis_type": "source_authority_context",
            "predictive_use_status": "calibration_context_not_production_scoring",
            "required_for_full_axis": True,
            "review_only": True,
        },
        {
            "axis_id": "gamma_to_source_acceptor_distance_candidate_cutoff",
            "axis_type": "local_geometry",
            "candidate_cutoff_angstrom": 6.0,
            "predictive_use_status": "diagnostic_cutoff_not_selected_threshold",
            "required_for_full_axis": True,
            "review_only": True,
        },
        {
            "axis_id": "sibling_family_counteraxis",
            "axis_type": "counterevidence",
            "predictive_use_status": "diagnostic_fail_closed_counteraxis",
            "required_for_full_axis": False,
            "review_only": True,
        },
        {
            "axis_id": "imported_external_hard_negative_abstention",
            "axis_type": "counterevidence",
            "predictive_use_status": "diagnostic_not_real_scored_reaudit",
            "required_for_full_axis": False,
            "review_only": True,
        },
    ]
    return {
        "metadata": {
            "method": "epk_protein_substrate_scorer_design_freeze",
            "review_only": True,
            "design_version": design_version,
            "design_status": design_status,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_5hvk_protein_substrate_axis_generalization_audit_method": (
                axis_meta.get("method")
            ),
            "combined_protein_substrate_positive_like_count": (
                combined_positive_count
            ),
            "sibling_control_false_hit_count": sibling_false_hit_count,
            "imported_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "ready_for_review_only_calibration_diagnostic": diagnostic_ready,
            "production_scoring_admissible": False,
            "source_authority_axes_present": True,
            "source_authority_axes_valid_for_orphan_discovery_claims": False,
            "mechanism_text_predictive_use_allowed": False,
            "ec_rhea_identifier_predictive_use_allowed": False,
            "uniprot_prose_predictive_use_allowed": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "diagnostic_design_not_implemented_as_real_scorer",
                "source_authority_axes_not_valid_for_orphan_discovery_claims",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "success_criteria_for_next_diagnostic": [
                "retain at least three review-only protein-substrate positive-like rows",
                "keep sibling-control false hits at zero",
                "keep imported external hard-negative non-abstentions at zero",
                "preserve epk_score_computed=false until a production scorer is deliberately implemented",
            ],
            "next_actions": [
                "implement a review-only calibration diagnostic from this frozen design",
                "replace source-authority acceptor context with production-admissible evidence before orphan claims",
                "keep registry edits and label import closed",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "This design freeze is a review-only diagnostic contract. It "
                "freezes axes for the next experiment but does not compute a "
                "production ePK score."
            )
        ],
    }


def build_epk_protein_substrate_calibration_diagnostic(
    *,
    epk_protein_substrate_scorer_design_freeze: dict[str, Any],
    epk_ligand_specific_5hvk_prototype_control_rerun: dict[str, Any],
) -> dict[str, Any]:
    """Run a review-only diagnostic calibration for the frozen ePK design."""

    design_meta = epk_protein_substrate_scorer_design_freeze.get("metadata", {})
    if not isinstance(design_meta, dict):
        design_meta = {}
    rerun_meta = epk_ligand_specific_5hvk_prototype_control_rerun.get(
        "metadata", {}
    )
    if not isinstance(rerun_meta, dict):
        rerun_meta = {}

    target_fingerprint_id = str(
        design_meta.get("target_fingerprint_id")
        or rerun_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    design_ready = bool(design_meta.get("ready_for_review_only_calibration_diagnostic"))
    source_authority_orphan_blocked = not bool(
        design_meta.get("source_authority_axes_valid_for_orphan_discovery_claims")
    )
    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    ligand_analog_excluded_count = 0

    for source_row in epk_ligand_specific_5hvk_prototype_control_rerun.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        row_type = source_row.get("row_type")
        entry_id = source_row.get("entry_id")
        if row_type == "carried_current_epk_positive_prototype":
            if entry_id == "m_csa:640":
                ligand_analog_excluded_count += 1
                decision = "excluded_ligand_analog_positive_review_only"
                score = 0.0
            else:
                decision = "diagnostic_positive_full_axis_review_only"
                score = 1.0
        elif row_type == "ligand_specific_5hvk_source_valid_positive_candidate":
            decision = "diagnostic_positive_full_axis_review_only"
            score = 1.0
        elif row_type in {
            "sibling_homolog_negative_control",
            "sibling_family_specific_negative_control",
        }:
            decision = "diagnostic_sibling_control_blocked_review_only"
            score = 0.0
        elif row_type == "imported_external_hard_negative":
            decision = "diagnostic_external_hard_negative_abstain_review_only"
            score = 0.0
        else:
            continue
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": row_type,
                "entry_id": entry_id,
                "pdb_id": source_row.get("pdb_id"),
                "accession": source_row.get("accession"),
                "family_id": source_row.get("family_id"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "diagnostic_score": score,
                "diagnostic_decision": decision,
                "epk_score_computed": False,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "source_authority_axes_used": row_type
                == "ligand_specific_5hvk_source_valid_positive_candidate",
                "valid_for_orphan_discovery_claims": False,
            }
        )

    positive_rows = [
        row
        for row in rows
        if row.get("diagnostic_decision")
        == "diagnostic_positive_full_axis_review_only"
    ]
    sibling_nonzero_count = sum(
        1
        for row in rows
        if row.get("diagnostic_decision")
        == "diagnostic_sibling_control_blocked_review_only"
        and float(row.get("diagnostic_score") or 0.0) > 0.0
    )
    external_nonzero_count = sum(
        1
        for row in rows
        if row.get("diagnostic_decision")
        == "diagnostic_external_hard_negative_abstain_review_only"
        and float(row.get("diagnostic_score") or 0.0) > 0.0
    )
    diagnostic_status = (
        "passes_review_only_calibration_controls_not_real_scorer"
        if design_ready
        and len(positive_rows) >= 3
        and sibling_nonzero_count == 0
        and external_nonzero_count == 0
        and source_authority_orphan_blocked
        else "blocked_review_only_calibration_diagnostic"
    )
    return {
        "metadata": {
            "method": "epk_protein_substrate_calibration_diagnostic",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_scorer_design_freeze_method": (
                design_meta.get("method")
            ),
            "source_epk_ligand_specific_5hvk_prototype_control_rerun_method": (
                rerun_meta.get("method")
            ),
            "design_version": design_meta.get("design_version"),
            "diagnostic_status": diagnostic_status,
            "diagnostic_positive_full_axis_count": len(positive_rows),
            "ligand_analog_excluded_positive_count": ligand_analog_excluded_count,
            "sibling_control_nonzero_score_count": sibling_nonzero_count,
            "imported_external_hard_negative_nonzero_score_count": (
                external_nonzero_count
            ),
            "review_only_diagnostic_score_computed": True,
            "epk_score_computed": False,
            "production_scoring_admissible": False,
            "source_authority_axes_used": True,
            "source_authority_axes_valid_for_orphan_discovery_claims": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "diagnostic_decision_counts": dict(sorted(decision_counts.items())),
            "remaining_blockers": [
                "diagnostic_scores_are_not_production_epk_scores",
                "source_authority_axes_not_valid_for_orphan_discovery_claims",
                "threshold_not_calibrated_against_broader_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "replace source-authority acceptor evidence with production-admissible local evidence before orphan claims",
                "broaden negative controls before selecting any threshold",
                "keep positive fingerprint and label registries unchanged",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("diagnostic_decision")),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("pdb_id") or ""),
                str(row.get("accession") or ""),
            ),
        ),
        "warnings": [
            (
                "Diagnostic scores are review-only calibration signals and are "
                "not production ePK scores or external hard-negative scored "
                "re-audit evidence."
            )
        ],
    }


def build_epk_source_authority_axis_replacement_gap_audit(
    *,
    epk_protein_substrate_scorer_design_freeze: dict[str, Any],
    epk_protein_substrate_calibration_diagnostic: dict[str, Any],
) -> dict[str, Any]:
    """Audit source-authority axes that block production ePK scoring."""

    design_meta = epk_protein_substrate_scorer_design_freeze.get("metadata", {})
    if not isinstance(design_meta, dict):
        design_meta = {}
    diagnostic_meta = epk_protein_substrate_calibration_diagnostic.get(
        "metadata", {}
    )
    if not isinstance(diagnostic_meta, dict):
        diagnostic_meta = {}
    target_fingerprint_id = str(
        design_meta.get("target_fingerprint_id")
        or diagnostic_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    design_rows = [
        row
        for row in epk_protein_substrate_scorer_design_freeze.get("rows", [])
        or []
        if isinstance(row, dict)
    ]
    source_authority_axis_ids = [
        str(row.get("axis_id"))
        for row in design_rows
        if "source_authority" in str(row.get("axis_type") or "")
        or "source_authority" in str(row.get("predictive_use_status") or "")
    ]
    diagnostic_passed = (
        diagnostic_meta.get("diagnostic_status")
        == "passes_review_only_calibration_controls_not_real_scorer"
    )
    replacement_gap_count = len(source_authority_axis_ids)
    replacement_status = (
        "blocked_review_only_source_authority_axes_require_local_replacements"
        if replacement_gap_count
        else "no_source_authority_replacement_gap_detected"
    )
    rows = [
        {
            "gap_id": "source_validated_protein_substrate_acceptor_identity",
            "source_axis_id": "source_validated_protein_substrate_hydroxyl_acceptor",
            "review_only": True,
            "blocks_production_scoring": True,
            "current_support": (
                "source-mapped phosphoacceptor identity and co-complex context"
            ),
            "required_replacement": (
                "local structural evidence that distinguishes protein-substrate "
                "acceptor geometry without UniProt prose or curated source labels"
            ),
            "next_experiment": (
                "derive a local chain-topology/co-complex acceptor rule and "
                "retest 5HVK, m_csa:35, m_csa:246, sibling controls, and "
                "imported external hard negatives"
            ),
        },
        {
            "gap_id": "source_authority_catalytic_context",
            "source_axis_id": "catalytic_acid_base_context",
            "review_only": True,
            "blocks_production_scoring": True,
            "current_support": "mixed local/source-authority catalytic context",
            "required_replacement": (
                "local residue-role evidence or a fail-closed abstention rule "
                "when catalytic role cannot be inferred without source labels"
            ),
            "next_experiment": (
                "separate local active-site residue evidence from source-authored "
                "role labels in the diagnostic scorer inputs"
            ),
        },
    ]
    if not replacement_gap_count:
        rows = []
    else:
        rows = [
            row
            for row in rows
            if row.get("source_axis_id") in set(source_authority_axis_ids)
        ]
    return {
        "metadata": {
            "method": "epk_source_authority_axis_replacement_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_scorer_design_freeze_method": (
                design_meta.get("method")
            ),
            "source_epk_protein_substrate_calibration_diagnostic_method": (
                diagnostic_meta.get("method")
            ),
            "diagnostic_passed_review_only_controls": diagnostic_passed,
            "source_authority_axis_ids": source_authority_axis_ids,
            "source_authority_axis_count": len(source_authority_axis_ids),
            "replacement_gap_count": replacement_gap_count,
            "replacement_status": replacement_status,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "source_authority_acceptor_identity_requires_local_replacement",
                "source_authority_catalytic_context_requires_local_replacement",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "build a local chain-topology acceptor replacement rule",
                "separate local residue evidence from source-authored catalytic role labels",
                "rerun sibling and imported external controls only after the replacement rule changes the decision surface",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Passing the review-only calibration diagnostic is not enough "
                "for production scoring while source-authority axes remain."
            )
        ],
    }


def build_epk_local_chain_topology_acceptor_replacement_rule(
    *,
    epk_chain_ligand_acceptor_disambiguation_audit: dict[str, Any],
    epk_ligand_specific_5hvk_source_validity_review: dict[str, Any],
    epk_source_authority_axis_replacement_gap_audit: dict[str, Any],
) -> dict[str, Any]:
    """Prototype a local chain-topology replacement for ePK acceptor identity."""

    chain_meta = epk_chain_ligand_acceptor_disambiguation_audit.get(
        "metadata", {}
    )
    if not isinstance(chain_meta, dict):
        chain_meta = {}
    source_meta = epk_ligand_specific_5hvk_source_validity_review.get(
        "metadata", {}
    )
    if not isinstance(source_meta, dict):
        source_meta = {}
    gap_meta = epk_source_authority_axis_replacement_gap_audit.get("metadata", {})
    if not isinstance(gap_meta, dict):
        gap_meta = {}

    target_fingerprint_id = str(
        chain_meta.get("target_fingerprint_id")
        or source_meta.get("target_fingerprint_id")
        or gap_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    rows: list[dict[str, Any]] = []
    for row in epk_chain_ligand_acceptor_disambiguation_audit.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        row_type = row.get("row_type")
        entry_id = row.get("entry_id")
        ligand_analog = bool(row.get("ligand_analog_acceptor"))
        non_catalytic_chain = bool(row.get("non_catalytic_chain_acceptor"))
        if row_type == "current_epk_positive_prototype" and ligand_analog:
            decision = "excluded_ligand_analog_not_local_protein_substrate_rule"
            rule_hit = False
        elif row_type == "current_epk_positive_prototype" and non_catalytic_chain:
            decision = "local_chain_topology_positive_hit_review_only"
            rule_hit = True
        elif row_type in {
            "sibling_homolog_negative_control",
            "sibling_family_specific_negative_control",
            "broader_sibling_negative_control",
        }:
            decision = "local_chain_topology_control_blocked_review_only"
            rule_hit = False
        elif row_type == "imported_external_hard_negative":
            decision = "local_chain_topology_external_abstain_review_only"
            rule_hit = False
        else:
            continue
        rows.append(
            {
                "row_type": row_type,
                "entry_id": entry_id,
                "pdb_id": row.get("pdb_id"),
                "family_id": row.get("family_id"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "candidate_rule_id": "epk_local_chain_topology_acceptor_rule_v0_review_only",
                "candidate_rule_hit": rule_hit,
                "candidate_rule_decision": decision,
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": row.get(
                    "nearest_gamma_to_candidate_acceptor_distance_angstrom"
                ),
                "non_catalytic_chain_acceptor": non_catalytic_chain,
                "ligand_analog_acceptor": ligand_analog,
                "epk_score_computed": False,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
            }
        )

    source_ready = bool(
        source_meta.get("source_validated_kinase_substrate_pair")
    ) and int(source_meta.get("measurement_ready_candidate_count") or 0) > 0
    if source_ready:
        rows.append(
            {
                "row_type": "ligand_specific_5hvk_source_valid_positive_candidate",
                "entry_id": None,
                "pdb_id": source_meta.get("pdb_id"),
                "kinase_accession": source_meta.get("kinase_accession"),
                "acceptor_accession": source_meta.get("acceptor_accession"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "candidate_rule_id": "epk_local_chain_topology_acceptor_rule_v0_review_only",
                "candidate_rule_hit": True,
                "candidate_rule_decision": (
                    "local_chain_topology_source_valid_5hvk_hit_review_only"
                ),
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    source_meta.get("nearest_source_phosphoacceptor_distance_angstrom")
                ),
                "non_catalytic_chain_acceptor": True,
                "ligand_analog_acceptor": False,
                "source_authority_still_required_for_chain_roles": True,
                "epk_score_computed": False,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
            }
        )

    positive_hit_count = sum(
        1
        for row in rows
        if str(row.get("candidate_rule_decision")).endswith("_hit_review_only")
    )
    ligand_analog_excluded_count = sum(
        1
        for row in rows
        if row.get("candidate_rule_decision")
        == "excluded_ligand_analog_not_local_protein_substrate_rule"
    )
    control_false_hit_count = sum(
        1
        for row in rows
        if "control" in str(row.get("candidate_rule_decision"))
        and bool(row.get("candidate_rule_hit"))
    )
    external_non_abstention_count = sum(
        1
        for row in rows
        if row.get("candidate_rule_decision")
        == "local_chain_topology_external_abstain_review_only"
        and bool(row.get("candidate_rule_hit"))
    )
    rule_status = (
        "passes_current_review_controls_source_roles_not_replaced"
        if positive_hit_count >= 3
        and control_false_hit_count == 0
        and external_non_abstention_count == 0
        else "blocked_review_only_local_chain_topology_rule"
    )
    return {
        "metadata": {
            "method": "epk_local_chain_topology_acceptor_replacement_rule",
            "review_only": True,
            "candidate_rule_id": "epk_local_chain_topology_acceptor_rule_v0_review_only",
            "candidate_rule_status": rule_status,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_chain_ligand_acceptor_disambiguation_audit_method": (
                chain_meta.get("method")
            ),
            "source_epk_ligand_specific_5hvk_source_validity_review_method": (
                source_meta.get("method")
            ),
            "source_epk_source_authority_axis_replacement_gap_audit_method": (
                gap_meta.get("method")
            ),
            "positive_rule_hit_count": positive_hit_count,
            "ligand_analog_excluded_positive_count": ligand_analog_excluded_count,
            "control_false_hit_count": control_false_hit_count,
            "imported_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "source_authority_reduced_not_eliminated": True,
            "source_authority_axes_valid_for_orphan_discovery_claims": False,
            "ready_for_production_scoring": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "5hvk_chain_roles_still_depend_on_source_authority",
                "local_chain_topology_rule_not_calibrated_beyond_current_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "replace 5HVK source-assigned chain roles with local polymer/entity evidence",
                "broaden controls for local chain-topology false-hit risk",
                "rerun diagnostic calibration only after the rule changes",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("candidate_rule_decision")),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The local chain-topology rule is review-only and still relies "
                "on source authority for the 5HVK kinase/substrate chain roles."
            )
        ],
    }


def build_epk_5hvk_local_polymer_entity_role_audit(
    *,
    epk_ligand_specific_5hvk_source_validity_review: dict[str, Any],
    epk_local_chain_topology_acceptor_replacement_rule: dict[str, Any],
) -> dict[str, Any]:
    """Audit local 5HVK polymer/entity evidence for kinase/substrate roles."""

    source_meta = epk_ligand_specific_5hvk_source_validity_review.get(
        "metadata", {}
    )
    if not isinstance(source_meta, dict):
        source_meta = {}
    rule_meta = epk_local_chain_topology_acceptor_replacement_rule.get(
        "metadata", {}
    )
    if not isinstance(rule_meta, dict):
        rule_meta = {}
    target_fingerprint_id = str(
        source_meta.get("target_fingerprint_id")
        or rule_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    entity_descriptions = source_meta.get("entity_descriptions", [])
    if not isinstance(entity_descriptions, list):
        entity_descriptions = []
    kinase_chain_ids = source_meta.get("kinase_chain_ids", [])
    if not isinstance(kinase_chain_ids, list):
        kinase_chain_ids = []
    acceptor_chain_ids = source_meta.get("acceptor_chain_ids", [])
    if not isinstance(acceptor_chain_ids, list):
        acceptor_chain_ids = []
    has_ligand = any("ADENYLATE" in str(value).upper() for value in entity_descriptions)
    has_metal = any("MAGNESIUM" in str(value).upper() for value in entity_descriptions)
    has_two_polymer_roles = bool(kinase_chain_ids and acceptor_chain_ids)
    chain_sets_disjoint = not (set(kinase_chain_ids) & set(acceptor_chain_ids))
    local_entity_supports_cocomplex = (
        has_two_polymer_roles and chain_sets_disjoint and has_ligand and has_metal
    )
    source_authority_eliminated = False
    audit_status = (
        "partial_local_entity_support_source_roles_still_required"
        if local_entity_supports_cocomplex
        else "blocked_local_entity_support_incomplete"
    )
    rows = [
        {
            "evidence_id": "5hvk_polymer_entity_context",
            "review_only": True,
            "pdb_id": source_meta.get("pdb_id"),
            "entity_descriptions": entity_descriptions,
            "kinase_chain_ids": kinase_chain_ids,
            "acceptor_chain_ids": acceptor_chain_ids,
            "chain_sets_disjoint": chain_sets_disjoint,
            "local_entity_supports_cocomplex": local_entity_supports_cocomplex,
            "source_authority_eliminated": source_authority_eliminated,
        },
        {
            "evidence_id": "5hvk_ligand_metal_context",
            "review_only": True,
            "pdb_id": source_meta.get("pdb_id"),
            "has_adenylate_ligand_entity": has_ligand,
            "has_magnesium_entity": has_metal,
            "nearest_source_phosphoacceptor_distance_angstrom": source_meta.get(
                "nearest_source_phosphoacceptor_distance_angstrom"
            ),
            "source_authority_eliminated": source_authority_eliminated,
        },
    ]
    return {
        "metadata": {
            "method": "epk_5hvk_local_polymer_entity_role_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_ligand_specific_5hvk_source_validity_review_method": (
                source_meta.get("method")
            ),
            "source_epk_local_chain_topology_acceptor_replacement_rule_method": (
                rule_meta.get("method")
            ),
            "audit_status": audit_status,
            "pdb_id": source_meta.get("pdb_id"),
            "local_entity_supports_cocomplex": local_entity_supports_cocomplex,
            "chain_sets_disjoint": chain_sets_disjoint,
            "kinase_chain_count": len(kinase_chain_ids),
            "acceptor_chain_count": len(acceptor_chain_ids),
            "has_adenylate_ligand_entity": has_ligand,
            "has_magnesium_entity": has_metal,
            "source_authority_eliminated": source_authority_eliminated,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "local_entity_descriptions_do_not_replace_source_role_assignment",
                "5hvk_acceptor_role_still_source_authority_dependent",
                "broader_chain_topology_controls_not_run",
                "external_hard_negative_reaudit_not_real_scorer",
            ],
            "next_actions": [
                "test whether local polymer topology alone can infer kinase/substrate roles without source labels",
                "add broader chain-topology controls before using this rule in calibration",
                "keep all registry and import gates closed",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "5HVK local polymer/entity evidence supports a co-complex, but "
                "does not eliminate source-authority dependence for assigning "
                "kinase and substrate roles."
            )
        ],
    }


def build_epk_source_free_chain_topology_role_audit(
    *,
    epk_5hvk_local_polymer_entity_role_audit: dict[str, Any],
    epk_ligand_specific_substrate_cocomplex_query_probe: dict[str, Any],
    epk_local_chain_topology_acceptor_replacement_rule: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Stress-test source-free chain-topology role assignment for ePK."""

    local_meta = epk_5hvk_local_polymer_entity_role_audit.get("metadata", {})
    if not isinstance(local_meta, dict):
        local_meta = {}
    probe_meta = epk_ligand_specific_substrate_cocomplex_query_probe.get(
        "metadata", {}
    )
    if not isinstance(probe_meta, dict):
        probe_meta = {}
    rule_meta = (
        epk_local_chain_topology_acceptor_replacement_rule.get("metadata", {})
        if isinstance(epk_local_chain_topology_acceptor_replacement_rule, dict)
        else {}
    )
    if not isinstance(rule_meta, dict):
        rule_meta = {}

    target_fingerprint_id = str(
        local_meta.get("target_fingerprint_id")
        or probe_meta.get("target_fingerprint_id")
        or rule_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    def _within_threshold_hits(row: dict[str, Any]) -> list[dict[str, Any]]:
        hits: list[dict[str, Any]] = []
        for hit in row.get("acceptor_hits", []) or []:
            if not isinstance(hit, dict):
                continue
            if bool(hit.get("within_candidate_threshold")):
                hits.append(hit)
        return hits

    rows: list[dict[str, Any]] = []
    local_entity_supports_cocomplex = bool(
        local_meta.get("local_entity_supports_cocomplex")
    )
    local_chain_sets_disjoint = bool(local_meta.get("chain_sets_disjoint"))
    if local_meta.get("method"):
        rows.append(
            {
                "row_type": "local_5hvk_source_free_role_assignment_probe",
                "pdb_id": local_meta.get("pdb_id"),
                "review_only": True,
                "target_fingerprint_id": target_fingerprint_id,
                "local_entity_supports_cocomplex": local_entity_supports_cocomplex,
                "local_chain_sets_disjoint": local_chain_sets_disjoint,
                "has_adenylate_ligand_entity": bool(
                    local_meta.get("has_adenylate_ligand_entity")
                ),
                "has_magnesium_entity": bool(local_meta.get("has_magnesium_entity")),
                "source_fields_masked_for_candidate_rule": True,
                "source_free_role_assignment_decision": (
                    "abstain_role_direction_not_inferable_without_source"
                ),
                "source_authority_eliminated": False,
                "candidate_rule_hit": False,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
            }
        )

    masked_local_candidate_hit_count = 0
    source_valid_cross_accession_positive_count = 0
    known_same_accession_control_risk_count = 0
    same_accession_control_risk_pdb_ids: list[str] = []
    cross_accession_positive_like_pdb_ids: list[str] = []
    for source_row in epk_ligand_specific_substrate_cocomplex_query_probe.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        hits = _within_threshold_hits(source_row)
        if not hits:
            continue
        pdb_id = str(source_row.get("pdb_id") or "")
        probe_status = str(source_row.get("probe_status") or "")
        masked_local_candidate_hit_count += 1
        source_context_class = "unknown_review_context"
        if probe_status == "source_ready_cross_accession_acceptor_hit_review_only":
            source_context_class = "cross_accession_source_valid_positive_like"
            source_valid_cross_accession_positive_count += 1
            if pdb_id:
                cross_accession_positive_like_pdb_ids.append(pdb_id)
        elif probe_status == "source_ready_same_accession_acceptor_hit_review_only":
            source_context_class = "same_accession_phosphosite_control_risk"
            known_same_accession_control_risk_count += 1
            if pdb_id:
                same_accession_control_risk_pdb_ids.append(pdb_id)

        rows.append(
            {
                "row_type": "broader_chain_topology_hit_control",
                "pdb_id": pdb_id or None,
                "review_only": True,
                "target_fingerprint_id": target_fingerprint_id,
                "source_fields_masked_for_candidate_rule": True,
                "masked_predictive_inputs": [
                    "local_gamma_to_hydroxyl_within_threshold",
                    "polymer_chain_count",
                    "adenylate_ligand_context",
                    "metal_ligand_context",
                ],
                "masked_local_candidate_hit": True,
                "source_context_used_for_failure_label_only": True,
                "known_review_context_class": source_context_class,
                "known_probe_status": probe_status,
                "within_threshold_acceptor_hit_count": len(hits),
                "nearest_within_threshold_distance_angstrom": min(
                    float(hit.get("nearest_gamma_distance_angstrom") or 0.0)
                    for hit in hits
                ),
                "would_be_false_hit_under_source_free_acceptor_rule": (
                    source_context_class == "same_accession_phosphosite_control_risk"
                ),
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
            }
        )

    source_free_role_assignment_safe = (
        local_entity_supports_cocomplex
        and local_chain_sets_disjoint
        and masked_local_candidate_hit_count > 0
        and known_same_accession_control_risk_count == 0
        and source_valid_cross_accession_positive_count >= 1
        and bool(local_meta.get("source_authority_eliminated"))
    )
    audit_status = (
        "passes_source_free_chain_topology_controls_review_only"
        if source_free_role_assignment_safe
        else "blocked_review_only_source_free_topology_role_rule_false_hit_risk"
    )
    return {
        "metadata": {
            "method": "epk_source_free_chain_topology_role_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_5hvk_local_polymer_entity_role_audit_method": (
                local_meta.get("method")
            ),
            "source_epk_ligand_specific_substrate_cocomplex_query_probe_method": (
                probe_meta.get("method")
            ),
            "source_epk_local_chain_topology_acceptor_replacement_rule_method": (
                rule_meta.get("method")
            ),
            "audit_status": audit_status,
            "local_entity_supports_cocomplex": local_entity_supports_cocomplex,
            "local_chain_sets_disjoint": local_chain_sets_disjoint,
            "source_fields_masked_for_candidate_rule": True,
            "masked_local_candidate_hit_count": masked_local_candidate_hit_count,
            "source_valid_cross_accession_positive_count": (
                source_valid_cross_accession_positive_count
            ),
            "source_valid_cross_accession_positive_pdb_ids": _sorted_strings(
                cross_accession_positive_like_pdb_ids
            ),
            "known_same_accession_control_risk_count": (
                known_same_accession_control_risk_count
            ),
            "known_same_accession_control_risk_pdb_ids": _sorted_strings(
                same_accession_control_risk_pdb_ids
            ),
            "source_free_role_assignment_safe": source_free_role_assignment_safe,
            "source_authority_eliminated": False,
            "broader_chain_topology_controls_run": bool(probe_meta.get("method")),
            "broader_chain_topology_reviewed_pdb_count": probe_meta.get(
                "reviewed_pdb_count"
            ),
            "broader_chain_topology_query_pdb_count": probe_meta.get(
                "query_pdb_count"
            ),
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "source_free_chain_role_direction_not_inferable_from_current_local_evidence",
                "same_accession_phosphosite_hits_would_false_hit_source_free_rule",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "add a source-free catalytic-chain assignment signal before accepting local topology hits",
                "broaden chain-topology controls with more kinase substrate co-complexes before calibration",
                "keep source-authority axes as review context until the local rule no longer false-hits same-accession controls",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                str(row.get("known_review_context_class") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Source-free chain topology is not yet a production ePK feature: "
                "masked local hit logic cannot distinguish 5HVK-like substrate "
                "co-complexes from same-accession phosphosite control risks."
            )
        ],
    }


def build_epk_heteromeric_chain_topology_signal_audit(
    *,
    epk_source_free_chain_topology_role_audit: dict[str, Any],
    epk_ligand_specific_substrate_cocomplex_query_probe: dict[str, Any],
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Test whether local chain entities disambiguate ePK substrate roles."""

    source_free_meta = epk_source_free_chain_topology_role_audit.get(
        "metadata", {}
    )
    if not isinstance(source_free_meta, dict):
        source_free_meta = {}
    probe_meta = epk_ligand_specific_substrate_cocomplex_query_probe.get(
        "metadata", {}
    )
    if not isinstance(probe_meta, dict):
        probe_meta = {}
    target_fingerprint_id = str(
        source_free_meta.get("target_fingerprint_id")
        or probe_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    cif_cache: dict[str, tuple[str, str | None, str]] = {}
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    acceptor_atom_names = {"SER": "OG", "THR": "OG1", "TYR": "OH"}

    def _within_threshold_hits(row: dict[str, Any]) -> list[dict[str, Any]]:
        return [
            hit
            for hit in row.get("acceptor_hits", []) or []
            if isinstance(hit, dict) and bool(hit.get("within_candidate_threshold"))
        ]

    def _entity_by_chain(cif_text: str) -> dict[str, str]:
        chain_entities: dict[str, str] = {}
        for entity_row in _epk_mmcif_rows(cif_text, "_struct_asym."):
            chain_id = entity_row.get("id")
            entity_id = entity_row.get("entity_id")
            if chain_id not in {None, "", ".", "?"} and entity_id not in {
                None,
                "",
                ".",
                "?",
            }:
                chain_entities[str(chain_id)] = str(entity_id)
        return chain_entities

    def _atom_entity(
        atom: dict[str, Any],
        chain_entities: dict[str, str],
        *,
        auth_first: bool = False,
    ) -> str | None:
        chain_ids = (
            (atom.get("auth_asym_id"), atom.get("label_asym_id"))
            if auth_first
            else (atom.get("label_asym_id"), atom.get("auth_asym_id"))
        )
        for chain_id in chain_ids:
            if chain_id in {None, "", ".", "?"}:
                continue
            entity_id = chain_entities.get(str(chain_id))
            if entity_id:
                return entity_id
        return None

    def _polymer_entity_by_auth_chain(
        atoms: list[dict[str, Any]], chain_entities: dict[str, str]
    ) -> dict[str, str]:
        polymer_entities: dict[str, str] = {}
        for atom in atoms:
            if atom.get("group_PDB") != "ATOM":
                continue
            auth_chain_id = atom.get("auth_asym_id")
            if auth_chain_id in {None, "", ".", "?"}:
                continue
            entity_id = _atom_entity(atom, chain_entities)
            if entity_id:
                polymer_entities.setdefault(str(auth_chain_id), entity_id)
        return polymer_entities

    def _load_cif(pdb_id: str) -> tuple[str, str | None, str]:
        if pdb_id in cif_cache:
            return cif_cache[pdb_id]
        fetch_status = "not_attempted"
        fetch_error = None
        cif_text = cif_texts.get(pdb_id)
        try:
            if cif_text is None and pdb_id:
                cif_text = cif_fetcher(pdb_id)
            fetch_status = "fetched" if cif_text else "missing_pdb_id"
        except Exception as exc:  # pragma: no cover - network failure is data.
            cif_text = ""
            fetch_status = "fetch_failed"
            fetch_error = str(exc)
        result = (cif_text or "", fetch_error, fetch_status)
        cif_cache[pdb_id] = result
        return result

    def _heteromeric_candidate_hits_for_cif(
        cif_text: str,
        *,
        candidate_threshold_angstrom: float = 6.0,
    ) -> list[dict[str, Any]]:
        atoms = parse_atom_site_loop(cif_text) if cif_text else []
        chain_entities = _entity_by_chain(cif_text) if cif_text else {}
        polymer_entities = _polymer_entity_by_auth_chain(atoms, chain_entities)
        gamma_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "HETATM"
            and _epk_atom_code(atom) in gamma_capable_codes
            and _epk_atom_name(atom) == "PG"
        ]
        candidate_hits: dict[tuple[str, str, str, str], dict[str, Any]] = {}
        for acceptor_atom in atoms:
            if acceptor_atom.get("group_PDB") != "ATOM":
                continue
            residue_code = _epk_atom_code(acceptor_atom)
            if acceptor_atom_names.get(residue_code) != _epk_atom_name(
                acceptor_atom
            ):
                continue
            acceptor_entity_id = _atom_entity(acceptor_atom, chain_entities)
            acceptor_chain_name = str(
                acceptor_atom.get("auth_asym_id")
                or acceptor_atom.get("label_asym_id")
                or ""
            )
            acceptor_seq_id = str(
                acceptor_atom.get("auth_seq_id")
                or acceptor_atom.get("label_seq_id")
                or ""
            )
            for gamma_atom in gamma_atoms:
                gamma_chain_name = str(
                    gamma_atom.get("auth_asym_id")
                    or gamma_atom.get("label_asym_id")
                    or ""
                )
                gamma_entity_id = polymer_entities.get(gamma_chain_name)
                if gamma_entity_id is None:
                    gamma_entity_id = _atom_entity(
                        gamma_atom, chain_entities, auth_first=True
                    )
                if (
                    acceptor_entity_id is None
                    or gamma_entity_id is None
                    or acceptor_entity_id == gamma_entity_id
                ):
                    continue
                distance = _epk_atom_distance(acceptor_atom, gamma_atom)
                if distance > candidate_threshold_angstrom:
                    continue
                key = (
                    acceptor_chain_name,
                    acceptor_seq_id,
                    residue_code,
                    gamma_chain_name,
                )
                existing = candidate_hits.get(key)
                if existing is None or distance < float(
                    existing["nearest_gamma_distance_angstrom"]
                ):
                    candidate_hits[key] = {
                        "candidate_chain_name": acceptor_chain_name,
                        "candidate_auth_seq_id": acceptor_seq_id,
                        "candidate_residue_code": residue_code,
                        "acceptor_entity_id": acceptor_entity_id,
                        "gamma_associated_polymer_chain_name": gamma_chain_name,
                        "gamma_associated_polymer_entity_id": gamma_entity_id,
                        "gamma_ligand_code": _epk_atom_code(gamma_atom),
                        "gamma_atom_name": _epk_atom_name(gamma_atom),
                        "nearest_gamma_distance_angstrom": round(distance, 3),
                    }
        return sorted(
            candidate_hits.values(),
            key=lambda hit: (
                float(hit["nearest_gamma_distance_angstrom"]),
                str(hit["candidate_chain_name"]),
                str(hit["candidate_auth_seq_id"]),
            ),
        )

    def _context_class(probe_status: str) -> str:
        if probe_status == "source_ready_cross_accession_acceptor_hit_review_only":
            return "cross_accession_source_valid_positive_like"
        if probe_status == "source_ready_same_accession_acceptor_hit_review_only":
            return "same_accession_phosphosite_control_risk"
        return "unknown_review_context"

    rows: list[dict[str, Any]] = []
    evaluated_hit_control_count = 0
    fetch_failure_count = 0
    unmapped_hit_count = 0
    heteromeric_signal_positive_like_count = 0
    same_accession_control_count = 0
    same_accession_control_signal_false_hit_count = 0
    same_accession_control_abstention_count = 0
    heteromeric_signal_pdb_ids: list[str] = []
    same_accession_control_pdb_ids: list[str] = []
    same_accession_signal_false_hit_pdb_ids: list[str] = []
    same_accession_abstention_pdb_ids: list[str] = []

    for source_row in (
        epk_ligand_specific_substrate_cocomplex_query_probe.get("rows", []) or []
    ):
        if not isinstance(source_row, dict):
            continue
        hits = _within_threshold_hits(source_row)
        if not hits:
            continue

        evaluated_hit_control_count += 1
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        probe_status = str(source_row.get("probe_status") or "")
        review_context_class = _context_class(probe_status)
        if review_context_class == "same_accession_phosphosite_control_risk":
            same_accession_control_count += 1
            if pdb_id:
                same_accession_control_pdb_ids.append(pdb_id)

        cif_text, fetch_error, fetch_status = _load_cif(pdb_id)
        if fetch_status == "fetch_failed":
            fetch_failure_count += 1

        atoms = parse_atom_site_loop(cif_text) if cif_text else []
        chain_entities = _entity_by_chain(cif_text) if cif_text else {}
        polymer_entity_by_auth_chain = _polymer_entity_by_auth_chain(
            atoms, chain_entities
        )
        gamma_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "HETATM"
            and _epk_atom_code(atom) in gamma_capable_codes
            and _epk_atom_name(atom) == "PG"
        ]

        hit_evaluations: list[dict[str, Any]] = []
        row_has_heteromeric_signal = False
        row_has_mapped_hit = False
        for hit in hits:
            residue_code = str(hit.get("candidate_residue_code") or "").upper()
            acceptor_atom_name = acceptor_atom_names.get(residue_code)
            candidate_chain_name = str(hit.get("candidate_chain_name") or "")
            candidate_seq_id = str(hit.get("candidate_auth_seq_id") or "")
            evaluation: dict[str, Any] = {
                "candidate_chain_name": candidate_chain_name or None,
                "candidate_auth_seq_id": candidate_seq_id or None,
                "candidate_residue_code": residue_code or None,
                "expected_acceptor_atom_name": acceptor_atom_name,
                "source_recorded_nearest_gamma_distance_angstrom": hit.get(
                    "nearest_gamma_distance_angstrom"
                ),
                "source_recorded_same_as_source_accession": bool(
                    hit.get("same_as_source_accession")
                ),
                "source_recorded_within_candidate_threshold": bool(
                    hit.get("within_candidate_threshold")
                ),
                "heteromeric_chain_entity_signal_hit": False,
                "mapped_acceptor_atom": False,
            }
            if not acceptor_atom_name:
                hit_evaluations.append(evaluation)
                continue

            acceptor_atoms = [
                atom
                for atom in atoms
                if atom.get("group_PDB") == "ATOM"
                and candidate_chain_name in _label_atom_chain_ids(atom)
                and candidate_seq_id in _label_atom_residue_ids(atom)
                and _epk_atom_code(atom) == residue_code
                and _epk_atom_name(atom) == acceptor_atom_name
            ]
            nearest_gamma = None
            nearest_distance = None
            nearest_acceptor_atom = None
            for acceptor_atom in acceptor_atoms:
                for gamma_atom in gamma_atoms:
                    distance = _epk_atom_distance(acceptor_atom, gamma_atom)
                    if nearest_distance is None or distance < nearest_distance:
                        nearest_distance = distance
                        nearest_gamma = gamma_atom
                        nearest_acceptor_atom = acceptor_atom
            if (
                nearest_gamma is not None
                and nearest_acceptor_atom is not None
                and nearest_distance is not None
            ):
                row_has_mapped_hit = True
                acceptor_entity_id = _atom_entity(nearest_acceptor_atom, chain_entities)
                gamma_associated_chain_name = str(
                    nearest_gamma.get("auth_asym_id")
                    or nearest_gamma.get("label_asym_id")
                    or ""
                )
                gamma_entity_id = polymer_entity_by_auth_chain.get(
                    gamma_associated_chain_name
                )
                gamma_entity_mapping_basis = "atom_site_author_chain_polymer_entity"
                if gamma_entity_id is None:
                    gamma_entity_id = _atom_entity(
                        nearest_gamma, chain_entities, auth_first=True
                    )
                    gamma_entity_mapping_basis = "struct_asym_author_chain_fallback"
                heteromeric_hit = (
                    acceptor_entity_id is not None
                    and gamma_entity_id is not None
                    and acceptor_entity_id != gamma_entity_id
                )
                row_has_heteromeric_signal = (
                    row_has_heteromeric_signal or heteromeric_hit
                )
                evaluation.update(
                    {
                        "mapped_acceptor_atom": True,
                        "acceptor_entity_id": acceptor_entity_id,
                        "gamma_associated_polymer_entity_id": gamma_entity_id,
                        "gamma_associated_polymer_chain_name": (
                            gamma_associated_chain_name
                        ),
                        "gamma_associated_polymer_entity_mapping_basis": (
                            gamma_entity_mapping_basis
                        ),
                        "gamma_ligand_code": _epk_atom_code(nearest_gamma),
                        "gamma_atom_name": _epk_atom_name(nearest_gamma),
                        "nearest_gamma_distance_angstrom": round(
                            nearest_distance, 3
                        ),
                        "heteromeric_chain_entity_signal_hit": heteromeric_hit,
                    }
                )
            hit_evaluations.append(evaluation)

        if not row_has_mapped_hit:
            unmapped_hit_count += 1
        if row_has_heteromeric_signal:
            if review_context_class == "cross_accession_source_valid_positive_like":
                heteromeric_signal_positive_like_count += 1
                if pdb_id:
                    heteromeric_signal_pdb_ids.append(pdb_id)
            elif review_context_class == "same_accession_phosphosite_control_risk":
                same_accession_control_signal_false_hit_count += 1
                if pdb_id:
                    same_accession_signal_false_hit_pdb_ids.append(pdb_id)
        elif review_context_class == "same_accession_phosphosite_control_risk":
            same_accession_control_abstention_count += 1
            if pdb_id:
                same_accession_abstention_pdb_ids.append(pdb_id)

        rows.append(
            {
                "row_type": "heteromeric_chain_topology_hit_control",
                "pdb_id": pdb_id or None,
                "review_only": True,
                "target_fingerprint_id": target_fingerprint_id,
                "source_fields_masked_for_candidate_rule": True,
                "source_context_used_for_failure_label_only": True,
                "known_probe_status": probe_status,
                "known_review_context_class": review_context_class,
                "fetch_status": fetch_status,
                "fetch_error": fetch_error,
                "within_threshold_acceptor_hit_count": len(hits),
                "mapped_hit_count": sum(
                    1
                    for evaluation in hit_evaluations
                    if evaluation.get("mapped_acceptor_atom")
                ),
                "heteromeric_chain_entity_signal_hit": row_has_heteromeric_signal,
                "would_be_false_hit_under_heteromeric_entity_rule": (
                    row_has_heteromeric_signal
                    and review_context_class == "same_accession_phosphosite_control_risk"
                ),
                "hit_evaluations": hit_evaluations,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
            }
        )

    full_probe_candidate_fetch_failure_count = 0
    full_probe_candidate_rows: list[dict[str, Any]] = []
    full_probe_candidate_pdb_ids: list[str] = []
    for source_row in (
        epk_ligand_specific_substrate_cocomplex_query_probe.get("rows", []) or []
    ):
        if not isinstance(source_row, dict):
            continue
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        if not pdb_id:
            continue
        cif_text, fetch_error, fetch_status = _load_cif(pdb_id)
        if fetch_status == "fetch_failed":
            full_probe_candidate_fetch_failure_count += 1
            continue
        candidate_hits = _heteromeric_candidate_hits_for_cif(cif_text)
        if not candidate_hits:
            continue
        full_probe_candidate_pdb_ids.append(pdb_id)
        full_probe_candidate_rows.append(
            {
                "row_type": "full_probe_heteromeric_candidate_scout",
                "pdb_id": pdb_id,
                "review_only": True,
                "target_fingerprint_id": target_fingerprint_id,
                "source_fields_masked_for_candidate_rule": True,
                "known_probe_status": str(source_row.get("probe_status") or ""),
                "source_context_used_for_failure_label_only": True,
                "heteromeric_candidate_hit_count": len(candidate_hits),
                "heteromeric_candidate_hits": candidate_hits[:10],
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
            }
        )
    rows.extend(full_probe_candidate_rows)

    current_hit_controls_passed = (
        evaluated_hit_control_count > 0
        and fetch_failure_count == 0
        and unmapped_hit_count == 0
        and heteromeric_signal_positive_like_count >= 1
        and same_accession_control_count > 0
        and same_accession_control_signal_false_hit_count == 0
    )
    minimum_positive_coverage_met = heteromeric_signal_positive_like_count >= 2
    audit_status = (
        "passes_current_hit_controls_but_insufficient_positive_coverage_review_only"
        if current_hit_controls_passed
        else "blocked_review_only_heteromeric_chain_topology_signal_false_hit_or_gap"
    )
    source_free_5hvk_role_direction_supported = (
        "5HVK" in _sorted_strings(heteromeric_signal_pdb_ids)
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_chain_topology_signal_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_source_free_chain_topology_role_audit_method": (
                source_free_meta.get("method")
            ),
            "source_epk_ligand_specific_substrate_cocomplex_query_probe_method": (
                probe_meta.get("method")
            ),
            "audit_status": audit_status,
            "source_fields_masked_for_candidate_rule": True,
            "heteromeric_entity_signal_definition": (
                "acceptor hydroxyl atom and the nearest adenylate gamma atom's "
                "associated author-chain polymer map to different local "
                "_struct_asym.entity_id values"
            ),
            "masked_local_candidate_hit_count": source_free_meta.get(
                "masked_local_candidate_hit_count"
            ),
            "evaluated_hit_control_count": evaluated_hit_control_count,
            "fetch_failure_count": fetch_failure_count,
            "unmapped_hit_count": unmapped_hit_count,
            "heteromeric_signal_positive_like_count": (
                heteromeric_signal_positive_like_count
            ),
            "heteromeric_signal_positive_like_pdb_ids": _sorted_strings(
                heteromeric_signal_pdb_ids
            ),
            "same_accession_control_count": same_accession_control_count,
            "same_accession_control_pdb_ids": _sorted_strings(
                same_accession_control_pdb_ids
            ),
            "same_accession_control_signal_false_hit_count": (
                same_accession_control_signal_false_hit_count
            ),
            "same_accession_control_signal_false_hit_pdb_ids": _sorted_strings(
                same_accession_signal_false_hit_pdb_ids
            ),
            "same_accession_control_abstention_count": (
                same_accession_control_abstention_count
            ),
            "same_accession_control_abstention_pdb_ids": _sorted_strings(
                same_accession_abstention_pdb_ids
            ),
            "current_hit_controls_passed": current_hit_controls_passed,
            "minimum_positive_coverage_met": minimum_positive_coverage_met,
            "full_probe_candidate_scout_run": True,
            "full_probe_candidate_scout_query_pdb_count": probe_meta.get(
                "query_pdb_count"
            ),
            "full_probe_candidate_scout_fetch_failure_count": (
                full_probe_candidate_fetch_failure_count
            ),
            "full_probe_heteromeric_candidate_structure_count": len(
                _sorted_strings(full_probe_candidate_pdb_ids)
            ),
            "full_probe_heteromeric_candidate_pdb_ids": _sorted_strings(
                full_probe_candidate_pdb_ids
            ),
            "source_free_5hvk_role_direction_supported": (
                source_free_5hvk_role_direction_supported
            ),
            "source_authority_eliminated": False,
            "broader_chain_topology_controls_run": bool(probe_meta.get("method")),
            "broader_chain_topology_reviewed_pdb_count": probe_meta.get(
                "reviewed_pdb_count"
            ),
            "broader_chain_topology_query_pdb_count": probe_meta.get(
                "query_pdb_count"
            ),
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_run_epk_scorer": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "remaining_blockers": [
                "only_one_source_free_heteromeric_positive_like_control",
                "full_probe_heteromeric_candidate_scout_found_only_5hvk",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "broaden heteromeric entity-topology positives beyond the current 60-structure probe before calibration",
                "score imported external hard negatives only after a real review-only scorer exists",
                "keep source context as failure labels until source-free controls are broader",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("known_review_context_class") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The heteromeric entity-topology signal separates the current "
                "5HVK-like hit from same-accession controls, but one positive-like "
                "structure is not enough for production scoring or label import."
            )
        ],
    }


def build_epk_heteromeric_positive_coverage_candidate_scout(
    *,
    epk_heteromeric_chain_topology_signal_audit: dict[str, Any],
    candidate_pdb_ids: list[str],
    source_query: str,
    candidate_threshold_angstrom: float = 6.0,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Scan a bounded follow-on PDB set for source-free heteromeric ePK leads."""

    if candidate_threshold_angstrom <= 0:
        raise ValueError("candidate_threshold_angstrom must be positive")

    heteromeric_meta = epk_heteromeric_chain_topology_signal_audit.get(
        "metadata", {}
    )
    if not isinstance(heteromeric_meta, dict):
        heteromeric_meta = {}
    target_fingerprint_id = str(
        heteromeric_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    candidate_ids = _sorted_strings(candidate_pdb_ids)
    prior_probe_ids = set(
        _sorted_strings(
            heteromeric_meta.get("full_probe_heteromeric_candidate_pdb_ids", [])
        )
    )
    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    acceptor_atom_names = {"SER": "OG", "THR": "OG1", "TYR": "OH"}

    def _entity_by_chain(cif_text: str) -> dict[str, str]:
        return {
            str(row.get("id") or ""): str(row.get("entity_id") or "")
            for row in _epk_mmcif_rows(cif_text, "_struct_asym.")
            if row.get("id") not in {None, "", ".", "?"}
            and row.get("entity_id") not in {None, "", ".", "?"}
        }

    def _atom_entity(
        atom: dict[str, Any],
        chain_entities: dict[str, str],
        *,
        auth_first: bool = False,
    ) -> str | None:
        keys = (
            ["auth_asym_id", "label_asym_id"]
            if auth_first
            else ["label_asym_id", "auth_asym_id"]
        )
        for key in keys:
            chain_id = str(atom.get(key) or "")
            if chain_id in chain_entities:
                return chain_entities[chain_id]
        entity_id = str(atom.get("label_entity_id") or "")
        return entity_id or None

    def _polymer_entity_by_auth_chain(atoms: list[dict[str, Any]]) -> dict[str, str]:
        mapping: dict[str, str] = {}
        for atom in atoms:
            if atom.get("group_PDB") != "ATOM":
                continue
            entity_id = str(atom.get("label_entity_id") or "")
            if not entity_id:
                continue
            for chain_key in ("auth_asym_id", "label_asym_id"):
                chain_id = str(atom.get(chain_key) or "")
                if chain_id and chain_id not in mapping:
                    mapping[chain_id] = entity_id
        return mapping

    def _candidate_hits_for_cif(cif_text: str) -> list[dict[str, Any]]:
        atoms = parse_atom_site_loop(cif_text)
        chain_entities = _entity_by_chain(cif_text)
        polymer_entities = _polymer_entity_by_auth_chain(atoms)
        gamma_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "HETATM"
            and _epk_atom_code(atom) in gamma_capable_codes
            and _epk_atom_name(atom) == "PG"
        ]
        hits: list[dict[str, Any]] = []
        seen_acceptors: set[tuple[str, str, str, str, str]] = set()
        for atom in atoms:
            if atom.get("group_PDB") != "ATOM":
                continue
            residue_code = _epk_atom_code(atom)
            acceptor_atom_name = acceptor_atom_names.get(residue_code)
            if not acceptor_atom_name or _epk_atom_name(atom) != acceptor_atom_name:
                continue
            nearest_gamma = None
            nearest_distance = None
            for gamma_atom in gamma_atoms:
                try:
                    distance = _epk_atom_distance(atom, gamma_atom)
                except (TypeError, ValueError, KeyError):
                    continue
                if nearest_distance is None or distance < nearest_distance:
                    nearest_distance = distance
                    nearest_gamma = gamma_atom
            if (
                nearest_gamma is None
                or nearest_distance is None
                or nearest_distance > candidate_threshold_angstrom
            ):
                continue
            acceptor_entity_id = _atom_entity(atom, chain_entities)
            gamma_chain_name = str(
                nearest_gamma.get("auth_asym_id")
                or nearest_gamma.get("label_asym_id")
                or ""
            )
            gamma_entity_id = polymer_entities.get(gamma_chain_name) or _atom_entity(
                nearest_gamma, chain_entities, auth_first=True
            )
            if (
                acceptor_entity_id is None
                or gamma_entity_id is None
                or acceptor_entity_id == gamma_entity_id
            ):
                continue
            acceptor_key = (
                str(atom.get("auth_asym_id") or atom.get("label_asym_id") or ""),
                str(atom.get("auth_seq_id") or atom.get("label_seq_id") or ""),
                residue_code,
                acceptor_atom_name,
                str(gamma_entity_id),
            )
            if acceptor_key in seen_acceptors:
                continue
            seen_acceptors.add(acceptor_key)
            hits.append(
                {
                    "candidate_chain_name": acceptor_key[0],
                    "candidate_auth_seq_id": acceptor_key[1],
                    "candidate_residue_code": residue_code,
                    "candidate_atom_name": acceptor_atom_name,
                    "acceptor_entity_id": acceptor_entity_id,
                    "gamma_associated_polymer_chain_name": gamma_chain_name,
                    "gamma_associated_polymer_entity_id": gamma_entity_id,
                    "gamma_ligand_code": _epk_atom_code(nearest_gamma),
                    "gamma_atom_name": _epk_atom_name(nearest_gamma),
                    "nearest_gamma_distance_angstrom": round(nearest_distance, 3),
                }
            )
        return sorted(
            hits,
            key=lambda hit: (
                float(hit["nearest_gamma_distance_angstrom"]),
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
                str(hit.get("candidate_residue_code") or ""),
            ),
        )

    rows: list[dict[str, Any]] = []
    fetch_failure_count = 0
    candidate_hit_pdb_ids: list[str] = []
    for pdb_id in candidate_ids:
        row_base = {
            "pdb_id": pdb_id,
            "target_family_id": "epk",
            "target_fingerprint_id_if_future_gated": target_fingerprint_id,
            "review_only": True,
            "ready_for_label_import": False,
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
        }
        try:
            cif_text = cif_texts.get(pdb_id)
            fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id)
            hits = _candidate_hits_for_cif(cif_text)
        except Exception as exc:  # pragma: no cover - network failure is data.
            fetch_failure_count += 1
            rows.append(
                {
                    **row_base,
                    "fetch_status": "fetch_failed",
                    "fetch_error": str(exc),
                    "candidate_threshold_angstrom": candidate_threshold_angstrom,
                    "heteromeric_candidate_hit_count": 0,
                    "heteromeric_candidate_hits": [],
                    "candidate_status": "structure_fetch_failed_review_only",
                    "source_validation_status": "not_started",
                    "measurement_ready": False,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue
        if hits:
            candidate_hit_pdb_ids.append(pdb_id)
            candidate_status = (
                "heteromeric_candidate_source_validation_pending_review_only"
            )
            source_validation_status = "pending_source_validation"
            blockers = [
                "source_validation_pending_for_heteromeric_candidate",
                "protein_substrate_acceptor_source_mapping_not_reviewed",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        else:
            candidate_status = "no_heteromeric_candidate_hit_review_only"
            source_validation_status = "not_applicable_no_candidate_hit"
            blockers = [
                "no_source_free_heteromeric_candidate_hit",
                "positive_coverage_not_expanded",
            ]
        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "heteromeric_candidate_hit_count": len(hits),
                "heteromeric_candidate_hits": hits[:10],
                "candidate_status": candidate_status,
                "source_validation_status": source_validation_status,
                "measurement_ready": False,
                "remaining_blockers": blockers,
            }
        )

    source_validation_queue_ready = bool(candidate_hit_pdb_ids)
    candidate_status_counts = Counter(
        str(row.get("candidate_status") or "") for row in rows
    )
    positive_coverage_status = (
        "source_validation_pending_for_broadened_heteromeric_candidates_review_only"
        if source_validation_queue_ready
        else "blocked_no_new_heteromeric_candidates_review_only"
    )
    current_positive_like_count = int(
        heteromeric_meta.get("heteromeric_signal_positive_like_count") or 0
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_positive_coverage_candidate_scout",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_chain_topology_signal_audit_method": (
                heteromeric_meta.get("method")
            ),
            "source_query": source_query,
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "input_candidate_count": len(candidate_ids),
            "reviewed_candidate_count": len(rows),
            "fetch_failure_count": fetch_failure_count,
            "candidate_status_counts": dict(sorted(candidate_status_counts.items())),
            "heteromeric_candidate_structure_count": len(candidate_hit_pdb_ids),
            "heteromeric_candidate_pdb_ids": _sorted_strings(candidate_hit_pdb_ids),
            "new_heteromeric_candidate_pdb_ids": [
                pdb_id
                for pdb_id in _sorted_strings(candidate_hit_pdb_ids)
                if pdb_id not in prior_probe_ids
            ],
            "source_validation_queue_ready": source_validation_queue_ready,
            "current_source_valid_positive_like_count": current_positive_like_count,
            "minimum_positive_coverage_met": False,
            "positive_coverage_status": positive_coverage_status,
            "ready_to_measure_gamma_acceptor_distance": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "bounded_heteromeric_candidate_scout_executed",
            "blocker_not_removed": [
                "source_validation_pending_for_new_heteromeric_candidates",
                "only_one_source_valid_heteromeric_positive_like_control",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This scout scans a bounded follow-on active-state kinase PDB "
                "set for source-free heteromeric entity topology. Hits are only "
                "source-validation leads; they are not positive labels, ePK "
                "scores, external hard-negative re-audits, or production "
                "fingerprint evidence."
            ),
            "next_actions": [
                "source-validate the new heteromeric candidate PDBs before treating any as positive-like controls",
                "keep the one validated 5HVK case as the only source-valid heteromeric positive until validation passes",
                "do not calibrate thresholds or score external hard negatives from unsourced topology hits",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "New heteromeric topology hits remain source-validation leads "
                "and cannot expand the positive fingerprint universe."
            )
        ],
    }


def build_epk_heteromeric_candidate_source_validation_review(
    *,
    epk_heteromeric_positive_coverage_candidate_scout: dict[str, Any],
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Source-review heteromeric topology leads before treating them as positives."""

    scout_meta = epk_heteromeric_positive_coverage_candidate_scout.get(
        "metadata", {}
    )
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    target_fingerprint_id = str(
        scout_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }

    def _structure_source_context(cif_text: str) -> dict[str, Any]:
        struct_rows = _epk_mmcif_rows(cif_text, "_struct.")
        keyword_rows = _epk_mmcif_rows(cif_text, "_struct_keywords.")
        entity_rows = _epk_mmcif_rows(cif_text, "_entity.")
        title = _first_present_value(struct_rows, "title")
        keywords = _sorted_strings(
            value
            for row in keyword_rows
            for value in (row.get("pdbx_keywords"), row.get("text"))
            if value not in {None, "", ".", "?"}
        )
        entity_descriptions = _sorted_strings(
            row.get("pdbx_description")
            for row in entity_rows
            if row.get("pdbx_description") not in {None, "", ".", "?"}
        )
        raw_source_contexts: list[str] = []
        raw_text = cif_text.lower()
        if (
            ("gsk3 peptide" in raw_text or "gsk-3 peptide" in raw_text)
            and (
                "pkb" in raw_text
                or "akt" in raw_text
                or "protein kinase b" in raw_text
            )
        ):
            raw_source_contexts.append("raw_cif_mentions_pkb_gsk3_peptide")
            raw_source_contexts.append("pkb gsk3 peptide")
        chain_accessions: dict[str, list[str]] = defaultdict(list)
        for row in _epk_struct_ref_seq_rows(cif_text):
            accession = str(row.get("pdbx_db_accession") or "")
            chain_ids = _sorted_strings(str(row.get("pdbx_strand_id") or "").split(","))
            if not accession:
                continue
            for chain_id in chain_ids:
                if accession not in chain_accessions[chain_id]:
                    chain_accessions[chain_id].append(accession)
        source_text = " ".join(
            [title or "", *keywords, *entity_descriptions, *raw_source_contexts]
        ).lower()
        return {
            "structure_title": title,
            "keywords": keywords,
            "entity_descriptions": entity_descriptions,
            "chain_accessions": {
                chain: sorted(accessions)
                for chain, accessions in sorted(chain_accessions.items())
            },
            "source_text": source_text,
        }

    def _validation_decision(source_text: str) -> tuple[str, str | None, list[str], list[str]]:
        if "upf1" in source_text and "smg1" in source_text:
            return (
                "accepted_source_valid_heteromeric_kinase_substrate_review_only",
                "smg1_upf1",
                ["structure_title_links_smg1_kinase_complex_to_upf1_substrate"],
                [
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            )
        if "p53" in source_text and "atm" in source_text:
            return (
                "accepted_source_valid_heteromeric_kinase_substrate_review_only",
                "atm_p53",
                ["source_context_links_atm_kinase_to_p53_candidate_substrate"],
                [
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            )
        if ("gsk3 peptide" in source_text or "gsk-3 peptide" in source_text) and (
            "pkb" in source_text
            or "akt" in source_text
            or "protein kinase b" in source_text
        ):
            return (
                "accepted_source_valid_heteromeric_kinase_substrate_review_only",
                "pkb_gsk3",
                ["source_context_links_pkb_kinase_complex_to_gsk3_peptide_substrate"],
                [
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            )
        if "braf" in source_text and "mek1" in source_text:
            return (
                "blocked_ambiguous_kinase_kinase_role_direction_review_only",
                None,
                ["structure_title_supports_braf_mek1_complex_but_role_direction_is_ambiguous"],
                [
                    "kinase_kinase_role_direction_needs_manual_source_review",
                    "protein_substrate_acceptor_source_mapping_not_reviewed",
                    "external_hard_negative_reaudit_not_real_scorer",
                ],
            )
        if (
            (
                "mek1" in source_text
                or "mitogen-activated protein kinase kinase 1" in source_text
                or "q02750" in source_text
            )
            and (
                "erk1" in source_text
                or "mitogen-activated protein kinase 3" in source_text
                or "p27361" in source_text
            )
        ):
            return (
                "blocked_mek_erk_role_direction_or_phosphosite_state_unresolved_review_only",
                "mek1_erk1",
                [
                    "source_context_supports_mek1_erk1_complex_but_role_direction_or_phosphosite_state_needs_manual_review"
                ],
                [
                    "kinase_substrate_role_direction_needs_phosphosite_source_review",
                    "acceptor_phosphorylation_state_not_adjudicated",
                    "external_hard_negative_reaudit_not_real_scorer",
                ],
            )
        if "kaic" in source_text:
            return (
                "rejected_non_epk_substrate_cocomplex_or_designed_clock_protein_review_only",
                None,
                ["structure_title_indicates_designed_clock_protein_not_epk_substrate_cocomplex"],
                [
                    "not_a_source_valid_epk_kinase_substrate_pair",
                    "positive_coverage_not_expanded_by_this_row",
                ],
            )
        return (
            "blocked_source_context_insufficient_review_only",
            None,
            ["no_explicit_kinase_substrate_source_context_detected"],
            [
                "source_validation_pending_for_heteromeric_candidate",
                "protein_substrate_acceptor_source_mapping_not_reviewed",
            ],
        )

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    accepted_pdb_ids: list[str] = []
    accepted_pair_ids: list[str] = []
    fetch_failure_count = 0
    candidate_rows = [
        row
        for row in epk_heteromeric_positive_coverage_candidate_scout.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and row.get("candidate_status")
        == "heteromeric_candidate_source_validation_pending_review_only"
    ]
    for candidate_row in candidate_rows:
        pdb_id = str(candidate_row.get("pdb_id") or "").upper()
        row_base = {
            "pdb_id": pdb_id,
            "target_family_id": "epk",
            "target_fingerprint_id_if_future_gated": target_fingerprint_id,
            "review_only": True,
            "ready_for_label_import": False,
            "countable_label_candidate": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "measurement_ready": False,
        }
        try:
            cif_text = cif_texts.get(pdb_id)
            fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id)
            context = _structure_source_context(cif_text)
        except Exception as exc:  # pragma: no cover - network failure is data.
            fetch_failure_count += 1
            status = "structure_fetch_failed_review_only"
            status_counts[status] += 1
            rows.append(
                {
                    **row_base,
                    "fetch_status": "fetch_failed",
                    "fetch_error": str(exc),
                    "source_validation_status": status,
                    "source_pair_id": None,
                    "source_validation_evidence": [],
                    "structure_title": None,
                    "entity_descriptions": [],
                    "chain_accessions": {},
                    "heteromeric_candidate_hit_count": int(
                        candidate_row.get("heteromeric_candidate_hit_count") or 0
                    ),
                    "nearest_heteromeric_candidate_distance_angstrom": None,
                    "source_validated_positive_like": False,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue
        status, source_pair_id, evidence, blockers = _validation_decision(
            str(context.get("source_text") or "")
        )
        status_counts[status] += 1
        source_validated = (
            status
            == "accepted_source_valid_heteromeric_kinase_substrate_review_only"
        )
        if source_validated:
            accepted_pdb_ids.append(pdb_id)
            if source_pair_id:
                accepted_pair_ids.append(source_pair_id)
        hits = [
            hit
            for hit in candidate_row.get("heteromeric_candidate_hits", []) or []
            if isinstance(hit, dict)
        ]
        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "source_validation_status": status,
                "source_pair_id": source_pair_id,
                "source_validation_evidence": evidence,
                "structure_title": context.get("structure_title"),
                "keywords": context.get("keywords", []),
                "entity_descriptions": context.get("entity_descriptions", []),
                "chain_accessions": context.get("chain_accessions", {}),
                "heteromeric_candidate_hit_count": int(
                    candidate_row.get("heteromeric_candidate_hit_count") or 0
                ),
                "nearest_heteromeric_candidate_distance_angstrom": (
                    min(
                        float(hit.get("nearest_gamma_distance_angstrom"))
                        for hit in hits
                        if hit.get("nearest_gamma_distance_angstrom") is not None
                    )
                    if any(
                        hit.get("nearest_gamma_distance_angstrom") is not None
                        for hit in hits
                    )
                    else None
                ),
                "candidate_hits": hits[:10],
                "source_validated_positive_like": source_validated,
                "remaining_blockers": sorted(set(blockers)),
            }
        )

    accepted_pair_ids_sorted = _sorted_strings(accepted_pair_ids)
    return {
        "metadata": {
            "method": "epk_heteromeric_candidate_source_validation_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_positive_coverage_candidate_scout_method": (
                scout_meta.get("method")
            ),
            "reviewed_candidate_count": len(rows),
            "fetch_failure_count": fetch_failure_count,
            "source_validation_status_counts": dict(sorted(status_counts.items())),
            "source_validated_new_candidate_count": len(accepted_pdb_ids),
            "source_validated_new_candidate_pdb_ids": _sorted_strings(accepted_pdb_ids),
            "source_validated_unique_pair_count": len(accepted_pair_ids_sorted),
            "source_validated_unique_pair_ids": accepted_pair_ids_sorted,
            "ambiguous_candidate_count": int(
                status_counts[
                    "blocked_ambiguous_kinase_kinase_role_direction_review_only"
                ]
            ),
            "rejected_candidate_count": int(
                status_counts[
                    "rejected_non_epk_substrate_cocomplex_or_designed_clock_protein_review_only"
                ]
            ),
            "minimum_positive_coverage_met_review_only": (
                len(accepted_pair_ids_sorted) >= 2
            ),
            "ready_to_measure_gamma_acceptor_distance": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "heteromeric_candidate_source_validation_review_executed",
            "blocker_not_removed": [
                "source_free_role_direction_not_generalized_to_scoring",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact source-reviews heteromeric topology leads. "
                "Accepted rows are positive-like review controls only; they are "
                "not countable labels, ePK scores, or held-out performance "
                "evidence."
            ),
            "next_actions": [
                "rerun the heteromeric topology audit with source-validated candidates separated from ambiguous and rejected rows",
                "treat BRAF/MEK kinase-kinase hits as ambiguous until role direction is source-reviewed",
                "keep threshold selection and external hard-negative scoring closed",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("source_validation_status") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Source-validated heteromeric candidates remain review-only "
                "controls until scorer, threshold, external re-audit, and "
                "registry gates exist."
            )
        ],
    }


def build_epk_ligand_specific_active_query_extension_audit(
    *,
    epk_ligand_specific_active_query_candidate_scouts: list[dict[str, Any]],
    epk_ligand_specific_active_query_source_validation_reviews: list[dict[str, Any]],
    known_source_valid_positive_pdb_ids: list[str] | None = None,
    prior_counterexample_pdb_ids: list[str] | None = None,
) -> dict[str, Any]:
    """Aggregate extended active-query scouts into one review-only decision."""

    known_positive_ids = set(
        _sorted_strings(
            known_source_valid_positive_pdb_ids
            or [
                "1IR3",
                "1O6K",
                "1O6L",
                "2PHK",
                "5HVK",
                "6Z3R",
                "8OXM",
                "8OXO",
            ]
        )
    )
    prior_counterexample_ids = set(
        _sorted_strings(
            prior_counterexample_pdb_ids
            or [
                "2JJ2",
                "4HPU",
                "7B56",
                "7M0T",
                "7M0W",
                "7T55",
                "7T56",
                "7T57",
                "7ZDT",
                "7ZDU",
                "7ZE5",
                "8ZN6",
                "9L3M",
                "9L3U",
            ]
        )
    )

    validation_rows_by_pdb: dict[str, dict[str, Any]] = {}
    validation_status_counts: Counter[str] = Counter()
    for review in epk_ligand_specific_active_query_source_validation_reviews:
        for row in review.get("rows", []) or []:
            if not isinstance(row, dict):
                continue
            pdb_id = str(row.get("pdb_id") or "").upper()
            if not pdb_id:
                continue
            validation_rows_by_pdb[pdb_id] = row
            validation_status_counts[str(row.get("source_validation_status") or "")] += 1

    rows: list[dict[str, Any]] = []
    scout_status_counts: Counter[str] = Counter()
    reviewed_pdb_ids: list[str] = []
    topology_hit_pdb_ids: list[str] = []
    same_author_chain_pdb_ids: list[str] = []
    source_query_values: list[str] = []
    target_fingerprint_id = "epk_atp_gamma_phosphoryl_transfer"

    def _text_blob(validation_row: dict[str, Any]) -> str:
        pieces: list[str] = []
        for key in ("structure_title",):
            value = validation_row.get(key)
            if value not in {None, "", ".", "?"}:
                pieces.append(str(value))
        for key in ("keywords", "entity_descriptions", "source_validation_evidence"):
            values = validation_row.get(key, [])
            if isinstance(values, list):
                pieces.extend(str(value) for value in values)
        accessions = validation_row.get("chain_accessions", {})
        if isinstance(accessions, dict):
            for value in accessions.values():
                if isinstance(value, list):
                    pieces.extend(str(item) for item in value)
        return " ".join(pieces).lower()

    for scout in epk_ligand_specific_active_query_candidate_scouts:
        scout_meta = scout.get("metadata", {})
        if isinstance(scout_meta, dict):
            source_query = str(scout_meta.get("source_query") or "")
            if source_query:
                source_query_values.append(source_query)
            target_fingerprint_id = str(
                scout_meta.get("target_fingerprint_id") or target_fingerprint_id
            )
        else:
            source_query = ""
        for scout_row in scout.get("rows", []) or []:
            if not isinstance(scout_row, dict):
                continue
            pdb_id = str(scout_row.get("pdb_id") or "").upper()
            if not pdb_id:
                continue
            reviewed_pdb_ids.append(pdb_id)
            candidate_status = str(scout_row.get("candidate_status") or "")
            scout_status_counts[candidate_status] += 1
            hits = [
                hit
                for hit in scout_row.get("heteromeric_candidate_hits", []) or []
                if isinstance(hit, dict)
            ]
            topology_hit = bool(hits)
            if topology_hit:
                topology_hit_pdb_ids.append(pdb_id)
            has_same_author_chain_hit = any(
                str(hit.get("candidate_chain_name") or "")
                and str(hit.get("candidate_chain_name") or "")
                == str(hit.get("gamma_associated_polymer_chain_name") or "")
                for hit in hits
            )
            if has_same_author_chain_hit:
                same_author_chain_pdb_ids.append(pdb_id)
            validation_row = validation_rows_by_pdb.get(pdb_id, {})
            source_text = _text_blob(validation_row)
            known_context = "unreviewed_or_no_topology_hit"
            if topology_hit and pdb_id in known_positive_ids:
                known_context = "known_source_valid_positive_repeat"
            elif topology_hit and pdb_id in prior_counterexample_ids:
                known_context = "prior_counterexample_repeat"
            elif topology_hit:
                known_context = "new_topology_hit_needs_source_adjudication"

            rows.append(
                {
                    "row_type": "ligand_specific_active_query_extension_structure",
                    "pdb_id": pdb_id,
                    "source_query": source_query,
                    "review_only": True,
                    "target_family_id": "epk",
                    "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                    "candidate_status": candidate_status,
                    "heteromeric_candidate_hit_count": len(hits),
                    "heteromeric_candidate_hits": hits[:10],
                    "topology_hit": topology_hit,
                    "known_context": known_context,
                    "source_validation_status": validation_row.get(
                        "source_validation_status"
                    ),
                    "source_pair_id": validation_row.get("source_pair_id"),
                    "source_validated_positive_like": bool(
                        validation_row.get("source_validated_positive_like")
                    ),
                    "structure_title": validation_row.get("structure_title"),
                    "same_author_chain_topology_artifact_risk": (
                        has_same_author_chain_hit
                    ),
                    "mek_erk_role_direction_blocker": (
                        "mek1" in source_text and "erk1" in source_text
                    )
                    or ("q02750" in source_text and "p27361" in source_text),
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                }
            )

    topology_hit_ids = _sorted_strings(topology_hit_pdb_ids)
    known_positive_repeat_ids = [
        pdb_id for pdb_id in topology_hit_ids if pdb_id in known_positive_ids
    ]
    prior_counterexample_repeat_ids = [
        pdb_id for pdb_id in topology_hit_ids if pdb_id in prior_counterexample_ids
    ]
    new_topology_hit_ids = [
        pdb_id
        for pdb_id in topology_hit_ids
        if pdb_id not in known_positive_ids and pdb_id not in prior_counterexample_ids
    ]
    source_validated_ids = _sorted_strings(
        row["pdb_id"]
        for row in rows
        if bool(row.get("source_validated_positive_like"))
    )
    source_validated_new_ids = [
        pdb_id for pdb_id in source_validated_ids if pdb_id not in known_positive_ids
    ]
    mek_erk_blocker_ids = _sorted_strings(
        row["pdb_id"] for row in rows if row.get("mek_erk_role_direction_blocker")
    )
    same_author_chain_ids = _sorted_strings(same_author_chain_pdb_ids)
    blocked_new_topology_ids = [
        pdb_id for pdb_id in new_topology_hit_ids if pdb_id not in source_validated_new_ids
    ]
    status = "closed_no_new_clean_broad_protein_substrate_positive_review_only"
    if source_validated_new_ids:
        status = "source_valid_new_positive_found_review_only"
    elif mek_erk_blocker_ids:
        status = "blocked_review_only_mek_erk_role_direction_and_acceptor_state_unresolved"

    blocker_not_removed = [
        "no_new_clean_broad_protein_substrate_positive",
        "threshold_not_calibrated_against_negative_controls",
        "external_hard_negative_reaudit_not_real_scorer",
        "registry_and_label_factory_extension_not_implemented",
    ]
    if mek_erk_blocker_ids:
        blocker_not_removed.append("mek_erk_role_direction_and_acceptor_state_unresolved")
    if same_author_chain_ids:
        blocker_not_removed.append("same_author_chain_entity_mapping_artifact_risk")

    return {
        "metadata": {
            "method": "epk_ligand_specific_active_query_extension_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "candidate_scout_artifact_count": len(
                epk_ligand_specific_active_query_candidate_scouts
            ),
            "source_validation_review_artifact_count": len(
                epk_ligand_specific_active_query_source_validation_reviews
            ),
            "source_queries": _sorted_strings(source_query_values),
            "reviewed_structure_count": len(reviewed_pdb_ids),
            "unique_reviewed_structure_count": len(_sorted_strings(reviewed_pdb_ids)),
            "candidate_status_counts": dict(sorted(scout_status_counts.items())),
            "source_validation_status_counts": dict(
                sorted(validation_status_counts.items())
            ),
            "heteromeric_topology_hit_count": len(topology_hit_ids),
            "heteromeric_topology_hit_pdb_ids": topology_hit_ids,
            "known_positive_repeat_hit_count": len(known_positive_repeat_ids),
            "known_positive_repeat_hit_pdb_ids": known_positive_repeat_ids,
            "prior_counterexample_repeat_hit_count": len(
                prior_counterexample_repeat_ids
            ),
            "prior_counterexample_repeat_hit_pdb_ids": (
                prior_counterexample_repeat_ids
            ),
            "new_topology_hit_count": len(new_topology_hit_ids),
            "new_topology_hit_pdb_ids": new_topology_hit_ids,
            "blocked_new_topology_hit_count": len(blocked_new_topology_ids),
            "blocked_new_topology_hit_pdb_ids": blocked_new_topology_ids,
            "source_validated_candidate_count": len(source_validated_ids),
            "source_validated_candidate_pdb_ids": source_validated_ids,
            "source_validated_new_candidate_count": len(source_validated_new_ids),
            "source_validated_new_candidate_pdb_ids": source_validated_new_ids,
            "mek_erk_role_direction_blocker_count": len(mek_erk_blocker_ids),
            "mek_erk_role_direction_blocker_pdb_ids": mek_erk_blocker_ids,
            "same_author_chain_topology_artifact_risk_count": len(
                same_author_chain_ids
            ),
            "same_author_chain_topology_artifact_risk_pdb_ids": (
                same_author_chain_ids
            ),
            "active_query_extension_status": status,
            "ready_to_measure_gamma_acceptor_distance": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "active_query_extended_beyond_first_100",
            "blocker_not_removed": blocker_not_removed,
            "review_only_rule": (
                "This audit aggregates bounded ligand-specific active-query "
                "scouts. It records repeated positives, repeated counterexamples, "
                "and new blocked topology hits; it is not an ePK score, external "
                "hard-negative re-audit, registry edit, or label import."
            ),
            "next_actions": [
                "source-review MEK1/ERK1 role direction and phosphoacceptor state before treating those rows as broad protein-substrate positives",
                "treat same-author-chain/entity-mismatch hits as counter-axis risk before any scorer calibration",
                "continue broader source search only if it can add source-authoritative protein-substrate positives beyond known repeats",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("known_context") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Extended active-query hits remain review-only and fail closed "
                "until source authority, role direction, thresholds, and external "
                "hard-negative scored re-audit gates exist."
            )
        ],
    }


def build_epk_mek_erk_phosphosite_source_review(
    *,
    epk_mek_erk_source_validation_review: dict[str, Any],
    uniprot_records_by_accession: dict[str, Any] | None = None,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
    uniprot_fetcher=None,
) -> dict[str, Any]:
    """Review MEK1/ERK1 topology hits against explicit phosphosite evidence."""

    review_meta = epk_mek_erk_source_validation_review.get("metadata", {})
    if not isinstance(review_meta, dict):
        review_meta = {}
    target_fingerprint_id = str(
        review_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    provided_uniprot_records = {
        str(key).upper(): value
        for key, value in (uniprot_records_by_accession or {}).items()
    }
    fetched_uniprot_accessions: list[str] = []
    uniprot_fetch_failures: dict[str, str] = {}
    uniprot_cache: dict[str, dict[str, Any]] = {}

    def _load_uniprot_record(accession: str) -> dict[str, Any]:
        accession_upper = accession.upper()
        if not accession_upper:
            return {}
        if accession_upper in uniprot_cache:
            return uniprot_cache[accession_upper]
        record = _unwrap_uniprot_entry_record(
            provided_uniprot_records.get(accession_upper)
        )
        if not record and uniprot_fetcher is not None:
            try:
                record = _unwrap_uniprot_entry_record(uniprot_fetcher(accession))
                fetched_uniprot_accessions.append(accession_upper)
            except Exception as exc:  # pragma: no cover - network failure is data.
                record = {}
                uniprot_fetch_failures[accession_upper] = str(exc)
        elif not record and uniprot_fetcher is None:
            try:
                from .adapters import fetch_uniprot_entry

                record = _unwrap_uniprot_entry_record(fetch_uniprot_entry(accession))
                fetched_uniprot_accessions.append(accession_upper)
            except Exception as exc:  # pragma: no cover - network failure is data.
                record = {}
                uniprot_fetch_failures[accession_upper] = str(exc)
        uniprot_cache[accession_upper] = record
        return record

    def _chain_accessions_from_cif(cif_text: str) -> dict[str, list[str]]:
        chain_accessions: dict[str, list[str]] = defaultdict(list)
        for row in _epk_struct_ref_seq_rows(cif_text):
            accession = str(row.get("pdbx_db_accession") or "").upper()
            if not accession:
                continue
            for chain_id in _sorted_strings(
                str(row.get("pdbx_strand_id") or "").split(",")
            ):
                if accession not in chain_accessions[chain_id]:
                    chain_accessions[chain_id].append(accession)
        return {
            chain_id: sorted(accessions)
            for chain_id, accessions in sorted(chain_accessions.items())
        }

    def _merge_chain_accessions(
        row_accessions: Any, cif_accessions: dict[str, list[str]]
    ) -> dict[str, list[str]]:
        merged: dict[str, list[str]] = defaultdict(list)
        if isinstance(row_accessions, dict):
            for chain_id, accessions in row_accessions.items():
                for accession in _sorted_strings(accessions):
                    accession_upper = accession.upper()
                    if accession_upper not in merged[str(chain_id)]:
                        merged[str(chain_id)].append(accession_upper)
        for chain_id, accessions in cif_accessions.items():
            for accession in accessions:
                accession_upper = accession.upper()
                if accession_upper not in merged[str(chain_id)]:
                    merged[str(chain_id)].append(accession_upper)
        return {
            chain_id: sorted(accessions)
            for chain_id, accessions in sorted(merged.items())
        }

    def _chain_primary_accession(
        chain_accessions: dict[str, list[str]], chain_id: str
    ) -> str | None:
        accessions = chain_accessions.get(chain_id) or []
        return accessions[0] if len(accessions) == 1 else None

    def _auth_residue_to_uniprot_position(
        *, cif_text: str, accession: str, chain_id: str, auth_resid: str
    ) -> int | None:
        accession_upper = accession.upper()
        for row in _epk_struct_ref_seq_rows(cif_text):
            if str(row.get("pdbx_db_accession") or "").upper() != accession_upper:
                continue
            if chain_id not in _sorted_strings(
                str(row.get("pdbx_strand_id") or "").split(",")
            ):
                continue
            try:
                auth_begin = int(str(row.get("pdbx_auth_seq_align_beg")))
                auth_end = int(str(row.get("pdbx_auth_seq_align_end")))
                db_begin = int(str(row.get("db_align_beg")))
                auth_value = int(str(auth_resid))
            except (TypeError, ValueError):
                continue
            if auth_begin <= auth_value <= auth_end:
                return db_begin + (auth_value - auth_begin)
        return None

    def _modified_residue_rows(cif_text: str) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for row in _epk_mmcif_rows(cif_text, "_pdbx_struct_mod_residue."):
            rows.append(
                {
                    "auth_asym_id": row.get("auth_asym_id"),
                    "auth_seq_id": row.get("auth_seq_id"),
                    "auth_comp_id": row.get("auth_comp_id"),
                    "label_asym_id": row.get("label_asym_id"),
                    "label_seq_id": row.get("label_seq_id"),
                    "label_comp_id": row.get("label_comp_id"),
                    "parent_comp_id": row.get("parent_comp_id"),
                    "details": row.get("details"),
                }
            )
        return rows

    def _is_candidate_modified(
        modified_rows: list[dict[str, Any]], chain_id: str, auth_resid: str
    ) -> bool:
        return any(
            str(row.get("auth_asym_id") or "") == chain_id
            and str(row.get("auth_seq_id") or "") == auth_resid
            for row in modified_rows
        )

    def _companion_modified_sites(
        *,
        modified_rows: list[dict[str, Any]],
        chain_id: str,
        candidate_auth_resid: str,
    ) -> list[dict[str, Any]]:
        return sorted(
            [
                row
                for row in modified_rows
                if str(row.get("auth_asym_id") or "") == chain_id
                and str(row.get("auth_seq_id") or "") != candidate_auth_resid
            ],
            key=lambda row: (
                int(str(row.get("auth_seq_id") or "0"))
                if str(row.get("auth_seq_id") or "").isdigit()
                else 0,
                str(row.get("auth_comp_id") or ""),
            ),
        )

    def _phosphosite_match(
        *, record: dict[str, Any], position: int | None, residue_code: str
    ) -> dict[str, Any] | None:
        if position is None:
            return None
        residue_code_upper = residue_code.upper()
        for feature in _epk_uniprot_phosphoacceptor_features(record):
            try:
                feature_position = int(str(feature.get("position")))
            except (TypeError, ValueError):
                continue
            if feature_position != position:
                continue
            description = str(feature.get("description") or "")
            lowered = description.lower()
            residue_matches = (
                ("phosphotyrosine" in lowered and residue_code_upper in {"TYR", "PTR"})
                or (
                    "phosphothreonine" in lowered
                    and residue_code_upper in {"THR", "TPO"}
                )
                or (
                    "phosphoserine" in lowered
                    and residue_code_upper in {"SER", "SEP"}
                )
            )
            if residue_matches:
                return feature
        return None

    def _kinase_reaction_supports_protein_phosphorylation(
        record: dict[str, Any]
    ) -> bool:
        for comment in record.get("catalytic_activity_comments", []) or []:
            if not isinstance(comment, dict):
                continue
            reaction = str(comment.get("reaction") or "").lower()
            if "[protein]" in reaction and "atp" in reaction and "phospho" in reaction:
                return True
        return False

    def _best_candidate_hit(row: dict[str, Any]) -> dict[str, Any]:
        hits = [
            hit for hit in row.get("candidate_hits", []) or [] if isinstance(hit, dict)
        ]
        if not hits:
            hits = [
                hit
                for hit in row.get("heteromeric_candidate_hits", []) or []
                if isinstance(hit, dict)
            ]
        if not hits:
            return {}
        return sorted(
            hits,
            key=lambda hit: (
                float(hit.get("nearest_gamma_distance_angstrom") or 9999.0),
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
            ),
        )[0]

    candidate_rows_by_pdb: dict[str, dict[str, Any]] = {}
    for row in epk_mek_erk_source_validation_review.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        status = str(row.get("source_validation_status") or "")
        pdb_id = str(row.get("pdb_id") or "").upper()
        if not pdb_id:
            continue
        if (
            row.get("source_pair_id") == "mek1_erk1"
            or status
            == "blocked_mek_erk_role_direction_or_phosphosite_state_unresolved_review_only"
        ):
            candidate_rows_by_pdb.setdefault(pdb_id, row)

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    measurement_ready_pdb_ids: list[str] = []
    terminal_not_ready_pdb_ids: list[str] = []
    distances: list[float] = []
    cif_fetch_failures: dict[str, str] = {}
    fetched_pdb_ids: list[str] = []

    for pdb_id, source_row in sorted(candidate_rows_by_pdb.items()):
        hit = _best_candidate_hit(source_row)
        row_base = {
            "row_type": "mek_erk_phosphosite_source_review_candidate",
            "pdb_id": pdb_id,
            "target_family_id": "epk",
            "target_fingerprint_id_if_future_gated": target_fingerprint_id,
            "review_only": True,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "structure_title": source_row.get("structure_title"),
            "source_validation_status_input": source_row.get(
                "source_validation_status"
            ),
            "candidate_hit": hit,
        }
        try:
            cif_text = cif_texts.get(pdb_id)
            fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id)
                fetched_pdb_ids.append(pdb_id)
        except Exception as exc:  # pragma: no cover - network failure is data.
            status = "structure_fetch_failed_review_only"
            cif_fetch_failures[pdb_id] = str(exc)
            status_counts[status] += 1
            terminal_not_ready_pdb_ids.append(pdb_id)
            rows.append(
                {
                    **row_base,
                    "fetch_status": "fetch_failed",
                    "fetch_error": str(exc),
                    "phosphosite_source_review_status": status,
                    "source_authoritative_measurement_ready": False,
                    "gamma_acceptor_distance_measured": False,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue

        struct_rows = _epk_mmcif_rows(cif_text, "_struct.")
        title = _first_present_value(struct_rows, "title") or source_row.get(
            "structure_title"
        )
        modified_rows = _modified_residue_rows(cif_text)
        chain_accessions = _merge_chain_accessions(
            source_row.get("chain_accessions"),
            _chain_accessions_from_cif(cif_text),
        )
        candidate_chain = str(hit.get("candidate_chain_name") or "")
        gamma_chain = str(hit.get("gamma_associated_polymer_chain_name") or "")
        candidate_auth_resid = str(hit.get("candidate_auth_seq_id") or "")
        candidate_code = str(hit.get("candidate_residue_code") or "").upper()
        acceptor_accession = _chain_primary_accession(
            chain_accessions, candidate_chain
        )
        kinase_accession = _chain_primary_accession(chain_accessions, gamma_chain)
        acceptor_record = _load_uniprot_record(acceptor_accession or "")
        kinase_record = _load_uniprot_record(kinase_accession or "")
        candidate_position = (
            _auth_residue_to_uniprot_position(
                cif_text=cif_text,
                accession=acceptor_accession,
                chain_id=candidate_chain,
                auth_resid=candidate_auth_resid,
            )
            if acceptor_accession
            else None
        )
        phosphosite_feature = _phosphosite_match(
            record=acceptor_record,
            position=candidate_position,
            residue_code=candidate_code,
        )
        kinase_reaction_supported = _kinase_reaction_supports_protein_phosphorylation(
            kinase_record
        )
        role_direction_supported = (
            kinase_accession == "Q02750"
            and acceptor_accession == "P27361"
            and kinase_reaction_supported
            and phosphosite_feature is not None
            and "map2k" in str(phosphosite_feature.get("description") or "").lower()
        )
        same_chain = bool(candidate_chain and candidate_chain == gamma_chain)
        candidate_modified = _is_candidate_modified(
            modified_rows, candidate_chain, candidate_auth_resid
        )
        companion_modified = _companion_modified_sites(
            modified_rows=modified_rows,
            chain_id=candidate_chain,
            candidate_auth_resid=candidate_auth_resid,
        )
        try:
            nearest_distance = float(hit.get("nearest_gamma_distance_angstrom"))
        except (TypeError, ValueError):
            nearest_distance = None

        if role_direction_supported and not same_chain and not candidate_modified:
            status = (
                "source_authoritative_mek1_erk1_phosphosite_measurement_ready_review_only"
            )
            measurement_ready = True
            blockers = [
                "source_review_evidence_not_source_free_predictive_feature",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ]
            measurement_ready_pdb_ids.append(pdb_id)
            if nearest_distance is not None:
                distances.append(nearest_distance)
        elif same_chain:
            status = "rejected_same_chain_mek_active_site_not_erk_phosphosite_review_only"
            measurement_ready = False
            blockers = [
                "candidate_acceptor_chain_matches_gamma_chain",
                "same_author_chain_entity_mapping_artifact_risk",
                "source_phosphosite_not_on_candidate_chain",
            ]
            terminal_not_ready_pdb_ids.append(pdb_id)
        elif phosphosite_feature is None:
            status = "blocked_source_phosphosite_not_matched_to_candidate_review_only"
            measurement_ready = False
            blockers = [
                "candidate_residue_not_matched_to_source_phosphosite_feature",
                "role_direction_or_acceptor_identity_unresolved",
            ]
            terminal_not_ready_pdb_ids.append(pdb_id)
        else:
            status = "blocked_mek_erk_role_direction_or_acceptor_state_review_only"
            measurement_ready = False
            blockers = [
                "role_direction_or_acceptor_state_unresolved",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
            terminal_not_ready_pdb_ids.append(pdb_id)

        status_counts[status] += 1
        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "structure_title": title,
                "chain_accessions": chain_accessions,
                "candidate_chain_name": candidate_chain,
                "gamma_associated_polymer_chain_name": gamma_chain,
                "candidate_same_chain_as_gamma": same_chain,
                "candidate_auth_seq_id": candidate_auth_resid,
                "candidate_residue_code": candidate_code,
                "candidate_uniprot_accession": acceptor_accession,
                "candidate_uniprot_position": candidate_position,
                "kinase_uniprot_accession": kinase_accession,
                "kinase_protein_phosphorylation_reaction_supported": (
                    kinase_reaction_supported
                ),
                "source_phosphosite_feature": phosphosite_feature,
                "source_phosphosite_matched_candidate": phosphosite_feature is not None,
                "source_role_direction_supported": role_direction_supported,
                "candidate_residue_modified_in_structure": candidate_modified,
                "companion_modified_residue_rows_on_candidate_chain": (
                    companion_modified
                ),
                "structure_modified_residue_rows": modified_rows,
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    round(nearest_distance, 3)
                    if nearest_distance is not None
                    else None
                ),
                "gamma_acceptor_distance_measured": nearest_distance is not None,
                "source_authoritative_measurement_ready": measurement_ready,
                "phosphosite_source_review_status": status,
                "remaining_blockers": blockers,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_orphan_discovery_claims": False,
            }
        )

    measurement_ready_pdb_ids = _sorted_strings(measurement_ready_pdb_ids)
    terminal_not_ready_pdb_ids = _sorted_strings(terminal_not_ready_pdb_ids)
    if measurement_ready_pdb_ids:
        review_status = (
            "adds_source_authoritative_broad_protein_substrate_rows_review_only"
        )
    else:
        review_status = "fails_closed_no_source_authoritative_mek_erk_rows"
    return {
        "metadata": {
            "method": "epk_mek_erk_phosphosite_source_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_source_validation_review_method": (
                review_meta.get("method")
            ),
            "reviewed_candidate_count": len(rows),
            "source_review_status": review_status,
            "phosphosite_source_review_status_counts": dict(
                sorted(status_counts.items())
            ),
            "source_authoritative_measurement_ready_count": len(
                measurement_ready_pdb_ids
            ),
            "source_authoritative_measurement_ready_pdb_ids": (
                measurement_ready_pdb_ids
            ),
            "terminal_not_ready_count": len(terminal_not_ready_pdb_ids),
            "terminal_not_ready_pdb_ids": terminal_not_ready_pdb_ids,
            "same_chain_artifact_rejected_count": int(
                status_counts[
                    "rejected_same_chain_mek_active_site_not_erk_phosphosite_review_only"
                ]
            ),
            "same_chain_artifact_rejected_pdb_ids": [
                row.get("pdb_id")
                for row in rows
                if row.get("phosphosite_source_review_status")
                == "rejected_same_chain_mek_active_site_not_erk_phosphosite_review_only"
            ],
            "gamma_acceptor_distance_measured_count": len(distances),
            "nearest_gamma_acceptor_distance_min_angstrom": (
                round(min(distances), 3) if distances else None
            ),
            "nearest_gamma_acceptor_distance_max_angstrom": (
                round(max(distances), 3) if distances else None
            ),
            "fetched_pdb_ids": _sorted_strings(fetched_pdb_ids),
            "cif_fetch_failure_count": len(cif_fetch_failures),
            "cif_fetch_failures": cif_fetch_failures,
            "fetched_uniprot_accessions": _sorted_strings(fetched_uniprot_accessions),
            "uniprot_fetch_failure_count": len(uniprot_fetch_failures),
            "uniprot_fetch_failures": dict(sorted(uniprot_fetch_failures.items())),
            "source_context_used_as_review_evidence_only": True,
            "source_free_predictive_feature_materialized": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_measure_gamma_acceptor_distance": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "mek_erk_phosphosite_source_review_executed",
            "blocker_not_removed": [
                "source_review_evidence_not_source_free_predictive_feature",
                "source_free_protein_role_and_acceptor_identity_generalization_not_rerun",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact reviews MEK1/ERK1 topology hits against PDB "
                "modified-residue records and UniProt phosphosite evidence. "
                "Rows can become measurement-ready review controls, but this "
                "does not create a source-free ePK scorer, threshold, registry "
                "edit, label import, or held-out performance claim."
            ),
            "next_actions": [
                "rerun protein-substrate role and acceptor-identity controls with the source-reviewed MEK1/ERK1 rows before threshold work",
                "keep same-chain MEK active-site hits as topology counterexamples",
                "convert source-reviewed phosphosite support into a source-free predictive feature only after broad controls and external scored re-audit pass",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("phosphosite_source_review_status") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "MEK1/ERK1 phosphosite source review remains review-only and "
                "does not authorize ePK scoring, thresholding, registry edits, "
                "or label import."
            )
        ],
    }


def build_epk_mek_erk_role_control_rerun(
    *,
    epk_mek_erk_phosphosite_source_review: dict[str, Any],
    epk_source_free_protein_substrate_role_discriminator_audit: dict[str, Any],
    epk_midlength_protein_role_counteraxis_audit: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Rerun review-only role controls after MEK1/ERK1 phosphosite review."""

    source_meta = epk_mek_erk_phosphosite_source_review.get("metadata", {})
    if not isinstance(source_meta, dict):
        source_meta = {}
    protein_role_meta = (
        epk_source_free_protein_substrate_role_discriminator_audit.get(
            "metadata", {}
        )
        if isinstance(
            epk_source_free_protein_substrate_role_discriminator_audit, dict
        )
        else {}
    )
    if not isinstance(protein_role_meta, dict):
        protein_role_meta = {}
    midlength_meta = (
        epk_midlength_protein_role_counteraxis_audit.get("metadata", {})
        if isinstance(epk_midlength_protein_role_counteraxis_audit, dict)
        else {}
    )
    if not isinstance(midlength_meta, dict):
        midlength_meta = {}

    target_fingerprint_id = str(
        source_meta.get("target_fingerprint_id")
        or protein_role_meta.get("target_fingerprint_id")
        or midlength_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    rule_id = "epk_mek_erk_role_control_rerun_v0_review_only"
    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    broad_hit_pdb_ids: list[str] = []
    same_chain_blocked_pdb_ids: list[str] = []
    source_review_miss_pdb_ids: list[str] = []

    for source_row in epk_mek_erk_phosphosite_source_review.get("rows", []) or []:
        if not isinstance(source_row, dict):
            continue
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        source_ready = bool(source_row.get("source_authoritative_measurement_ready"))
        same_chain = bool(source_row.get("candidate_same_chain_as_gamma"))
        candidate_accession = str(source_row.get("candidate_uniprot_accession") or "")
        kinase_accession = str(source_row.get("kinase_uniprot_accession") or "")
        role_hit = (
            source_ready
            and not same_chain
            and bool(candidate_accession)
            and bool(kinase_accession)
            and candidate_accession != kinase_accession
        )
        if role_hit:
            decision = (
                "source_reviewed_mek_erk_broad_protein_role_hit_review_only"
            )
            broad_hit_pdb_ids.append(pdb_id)
        elif same_chain:
            decision = "same_chain_mek_active_site_counterexample_blocked_review_only"
            same_chain_blocked_pdb_ids.append(pdb_id)
        else:
            decision = "source_reviewed_mek_erk_role_miss_review_only"
            source_review_miss_pdb_ids.append(pdb_id)
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "mek_erk_role_control_rerun_candidate",
                "source_row_type": source_row.get("row_type"),
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "rule_id": rule_id,
                "source_phosphosite_review_status": source_row.get(
                    "phosphosite_source_review_status"
                ),
                "source_authoritative_measurement_ready": source_ready,
                "candidate_uniprot_accession": candidate_accession or None,
                "candidate_uniprot_position": source_row.get(
                    "candidate_uniprot_position"
                ),
                "kinase_uniprot_accession": kinase_accession or None,
                "candidate_same_chain_as_gamma": same_chain,
                "source_phosphosite_matched_candidate": bool(
                    source_row.get("source_phosphosite_matched_candidate")
                ),
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    source_row.get(
                        "nearest_gamma_to_candidate_acceptor_distance_angstrom"
                    )
                ),
                "mek_erk_role_control_rule_hit": role_hit,
                "role_control_decision": decision,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "source_review_evidence_not_source_free_predictive_feature",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    broad_hit_pdb_ids = _sorted_strings(broad_hit_pdb_ids)
    same_chain_blocked_pdb_ids = _sorted_strings(same_chain_blocked_pdb_ids)
    source_review_miss_pdb_ids = _sorted_strings(source_review_miss_pdb_ids)
    current_control_false_hit_count = int(
        protein_role_meta.get("protein_role_control_false_hit_count") or 0
    )
    external_non_abstention_count = int(
        protein_role_meta.get("protein_role_external_hard_negative_non_abstention_count")
        or 0
    )
    midlength_residual_false_hit_count = int(
        midlength_meta.get("residual_protein_role_false_hit_count") or 0
    )
    if (
        broad_hit_pdb_ids
        and not source_review_miss_pdb_ids
        and current_control_false_hit_count == 0
        and external_non_abstention_count == 0
        and midlength_residual_false_hit_count == 0
    ):
        status = (
            "passes_review_only_with_source_reviewed_broad_rows_but_scoring_closed"
        )
    else:
        status = "fails_closed_mek_erk_role_control_rerun"

    return {
        "metadata": {
            "method": "epk_mek_erk_role_control_rerun",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "rule_id": rule_id,
            "source_epk_mek_erk_phosphosite_source_review_method": (
                source_meta.get("method")
            ),
            "source_epk_source_free_protein_substrate_role_discriminator_audit_method": (
                protein_role_meta.get("method")
            ),
            "source_epk_midlength_protein_role_counteraxis_audit_method": (
                midlength_meta.get("method")
            ),
            "role_control_rerun_status": status,
            "reviewed_candidate_count": len(rows),
            "source_reviewed_broad_protein_role_hit_count": len(broad_hit_pdb_ids),
            "source_reviewed_broad_protein_role_hit_pdb_ids": broad_hit_pdb_ids,
            "same_chain_counterexample_blocked_count": len(
                same_chain_blocked_pdb_ids
            ),
            "same_chain_counterexample_blocked_pdb_ids": same_chain_blocked_pdb_ids,
            "source_reviewed_role_miss_count": len(source_review_miss_pdb_ids),
            "source_reviewed_role_miss_pdb_ids": source_review_miss_pdb_ids,
            "carried_current_control_false_hit_count": (
                current_control_false_hit_count
            ),
            "carried_imported_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "carried_midlength_residual_false_hit_count": (
                midlength_residual_false_hit_count
            ),
            "role_control_decision_counts": dict(sorted(decision_counts.items())),
            "source_free_predictive_feature_materialized": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "mek_erk_source_reviewed_rows_rerun_against_role_controls",
            "blocker_not_removed": [
                "source_review_evidence_not_source_free_predictive_feature",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact reruns role-control accounting after MEK1/ERK1 "
                "phosphosite source review. It can add review-only broad "
                "protein-substrate rows, but it does not create a source-free "
                "scorer, threshold, registry edit, label import, or performance "
                "claim."
            ),
            "next_actions": [
                "stress source-reviewed MEK1/ERK1 rows against sibling and broad-query topology counterexamples before scorer calibration",
                "materialize a source-free acceptor-identity feature that does not depend on UniProt phosphosite text",
                "keep external hard-negative re-audit closed until a calibrated ePK score exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("role_control_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "MEK1/ERK1 role-control rerun is review-only and cannot "
                "authorize threshold selection, production scoring, registry "
                "edits, or label import."
            )
        ],
    }


def build_epk_mek_erk_broad_role_stress_audit(
    *,
    epk_mek_erk_role_control_rerun: dict[str, Any],
    epk_multi_query_active_site_terminal_audit: dict[str, Any],
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Stress source-reviewed MEK1/ERK1 broad-role logic on terminal queries."""

    rerun_meta = epk_mek_erk_role_control_rerun.get("metadata", {})
    if not isinstance(rerun_meta, dict):
        rerun_meta = {}
    terminal_meta = epk_multi_query_active_site_terminal_audit.get("metadata", {})
    if not isinstance(terminal_meta, dict):
        terminal_meta = {}
    target_fingerprint_id = str(
        rerun_meta.get("target_fingerprint_id")
        or terminal_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(candidate_threshold_angstrom)
    except (TypeError, ValueError):
        threshold = 6.0
    source_reviewed_positive_ids = set(
        _sorted_strings(
            rerun_meta.get("source_reviewed_broad_protein_role_hit_pdb_ids", [])
        )
    )
    known_positive_ids = set(
        _sorted_strings(
            terminal_meta.get("known_positive_repeat_hit_pdb_ids", [])
        )
    )

    def _nearest_hit(row: dict[str, Any]) -> dict[str, Any]:
        hits = [
            hit
            for hit in row.get("heteromeric_candidate_hits", []) or []
            if isinstance(hit, dict)
        ]
        if not hits:
            return {}
        return sorted(
            hits,
            key=lambda hit: (
                float(hit.get("nearest_gamma_distance_angstrom") or 9999.0),
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
            ),
        )[0]

    rows_by_pdb: dict[str, dict[str, Any]] = {}
    for row in epk_multi_query_active_site_terminal_audit.get("rows", []) or []:
        if not isinstance(row, dict) or not bool(row.get("topology_hit")):
            continue
        pdb_id = str(row.get("pdb_id") or "").upper()
        if not pdb_id:
            continue
        rows_by_pdb.setdefault(pdb_id, row)

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    positive_retained_pdb_ids: list[str] = []
    known_positive_retained_pdb_ids: list[str] = []
    nonpositive_false_hit_pdb_ids: list[str] = []
    same_chain_blocked_pdb_ids: list[str] = []
    source_reviewed_positive_missing_ids: list[str] = []

    for pdb_id, terminal_row in sorted(rows_by_pdb.items()):
        hit = _nearest_hit(terminal_row)
        candidate_chain = str(hit.get("candidate_chain_name") or "")
        gamma_chain = str(hit.get("gamma_associated_polymer_chain_name") or "")
        try:
            distance = float(hit.get("nearest_gamma_distance_angstrom"))
        except (TypeError, ValueError):
            distance = None
        same_chain = bool(candidate_chain and candidate_chain == gamma_chain)
        naive_role_hit = (
            distance is not None
            and distance <= threshold
            and not same_chain
            and bool(candidate_chain)
            and bool(gamma_chain)
        )
        source_reviewed_positive = pdb_id in source_reviewed_positive_ids
        known_positive = pdb_id in known_positive_ids or bool(
            terminal_row.get("source_validated_positive_like")
        )
        nonpositive_control = not source_reviewed_positive and not known_positive
        if source_reviewed_positive and naive_role_hit:
            decision = "source_reviewed_mek_erk_positive_retained_review_only"
            positive_retained_pdb_ids.append(pdb_id)
        elif source_reviewed_positive:
            decision = "source_reviewed_mek_erk_positive_missed_review_only"
            source_reviewed_positive_missing_ids.append(pdb_id)
        elif known_positive and naive_role_hit:
            decision = "known_positive_repeat_retained_review_only"
            known_positive_retained_pdb_ids.append(pdb_id)
        elif nonpositive_control and same_chain:
            decision = "nonpositive_same_chain_topology_blocked_review_only"
            same_chain_blocked_pdb_ids.append(pdb_id)
        elif nonpositive_control and naive_role_hit:
            decision = "nonpositive_naive_broad_role_false_hit_review_only"
            nonpositive_false_hit_pdb_ids.append(pdb_id)
        else:
            decision = "nonpositive_abstained_by_naive_broad_role_review_only"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "mek_erk_broad_role_stress_terminal_topology_hit",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "candidate_threshold_angstrom": threshold,
                "candidate_chain_name": candidate_chain,
                "gamma_associated_polymer_chain_name": gamma_chain,
                "candidate_same_chain_as_gamma": same_chain,
                "nearest_gamma_distance_angstrom": (
                    round(distance, 3) if distance is not None else None
                ),
                "source_validation_status": terminal_row.get(
                    "source_validation_status"
                ),
                "known_context": terminal_row.get("known_context"),
                "source_pair_id": terminal_row.get("source_pair_id"),
                "source_reviewed_mek_erk_positive": source_reviewed_positive,
                "known_positive_repeat_or_source_valid": known_positive,
                "naive_broad_protein_role_rule_hit": naive_role_hit,
                "broad_role_stress_decision": decision,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
            }
        )

    positive_retained_pdb_ids = _sorted_strings(positive_retained_pdb_ids)
    known_positive_retained_pdb_ids = _sorted_strings(
        known_positive_retained_pdb_ids
    )
    nonpositive_false_hit_pdb_ids = _sorted_strings(nonpositive_false_hit_pdb_ids)
    same_chain_blocked_pdb_ids = _sorted_strings(same_chain_blocked_pdb_ids)
    source_reviewed_positive_missing_ids = _sorted_strings(
        source_reviewed_positive_missing_ids
    )
    if nonpositive_false_hit_pdb_ids or source_reviewed_positive_missing_ids:
        status = "fails_closed_naive_broad_role_rule_false_hits_terminal_surface"
    else:
        status = "passes_current_terminal_surface_but_review_only_not_calibrated"

    return {
        "metadata": {
            "method": "epk_mek_erk_broad_role_stress_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_role_control_rerun_method": rerun_meta.get(
                "method"
            ),
            "source_epk_multi_query_active_site_terminal_audit_method": (
                terminal_meta.get("method")
            ),
            "candidate_threshold_angstrom": threshold,
            "broad_role_stress_status": status,
            "reviewed_topology_hit_count": len(rows),
            "source_reviewed_mek_erk_positive_retained_count": len(
                positive_retained_pdb_ids
            ),
            "source_reviewed_mek_erk_positive_retained_pdb_ids": (
                positive_retained_pdb_ids
            ),
            "source_reviewed_mek_erk_positive_missed_count": len(
                source_reviewed_positive_missing_ids
            ),
            "source_reviewed_mek_erk_positive_missed_pdb_ids": (
                source_reviewed_positive_missing_ids
            ),
            "known_positive_repeat_retained_count": len(
                known_positive_retained_pdb_ids
            ),
            "known_positive_repeat_retained_pdb_ids": known_positive_retained_pdb_ids,
            "nonpositive_naive_broad_role_false_hit_count": len(
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_naive_broad_role_false_hit_pdb_ids": (
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_same_chain_blocked_count": len(same_chain_blocked_pdb_ids),
            "nonpositive_same_chain_blocked_pdb_ids": same_chain_blocked_pdb_ids,
            "broad_role_stress_decision_counts": dict(
                sorted(decision_counts.items())
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "source_reviewed_mek_erk_rows_stressed_against_terminal_query_surface",
            "blocker_not_removed": [
                "naive_broad_role_rule_false_hits_terminal_surface",
                "source_review_evidence_not_source_free_predictive_feature",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This stress audit asks whether a naive source-free broad-role "
                "rule can retain source-reviewed MEK1/ERK1 positives while "
                "blocking terminal active-query counterexamples. It is a "
                "fail-closed diagnostic, not an ePK score or threshold gate."
            ),
            "next_actions": [
                "add a concrete counter-axis for the false-hit terminal topology rows before scorer calibration",
                "keep same-chain topology blocked as counterevidence",
                "do not run a real external hard-negative re-audit until false hits are repaired",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("broad_role_stress_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Broad-role stress is review-only and does not authorize "
                "threshold selection, production scoring, registry edits, or "
                "label import."
            )
        ],
    }


def build_epk_mek_erk_context_counteraxis_stress_audit(
    *,
    epk_mek_erk_broad_role_stress_audit: dict[str, Any],
) -> dict[str, Any]:
    """Apply a review-context counteraxis to MEK1/ERK1 broad-role stress hits."""

    broad_meta = epk_mek_erk_broad_role_stress_audit.get("metadata", {})
    if not isinstance(broad_meta, dict):
        broad_meta = {}
    target_fingerprint_id = str(
        broad_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    threshold = broad_meta.get("candidate_threshold_angstrom")
    rule_id = "epk_mek_erk_review_context_counteraxis_v0"

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    positive_retained_pdb_ids: list[str] = []
    known_positive_retained_pdb_ids: list[str] = []
    prior_counterexample_blocked_pdb_ids: list[str] = []
    same_chain_blocked_pdb_ids: list[str] = []
    residual_false_hit_pdb_ids: list[str] = []

    for broad_row in epk_mek_erk_broad_role_stress_audit.get("rows", []) or []:
        if not isinstance(broad_row, dict):
            continue
        pdb_id = str(broad_row.get("pdb_id") or "").upper()
        if not pdb_id:
            continue
        broad_decision = str(broad_row.get("broad_role_stress_decision") or "")
        known_context = str(broad_row.get("known_context") or "")
        source_reviewed_positive = bool(
            broad_row.get("source_reviewed_mek_erk_positive")
        )
        known_positive = bool(
            broad_row.get("known_positive_repeat_or_source_valid")
        )
        same_chain = bool(broad_row.get("candidate_same_chain_as_gamma"))
        naive_hit = bool(broad_row.get("naive_broad_protein_role_rule_hit"))
        if source_reviewed_positive and naive_hit:
            decision = "source_reviewed_mek_erk_positive_retained_review_only"
            positive_retained_pdb_ids.append(pdb_id)
        elif known_positive and naive_hit:
            decision = "known_positive_repeat_retained_review_only"
            known_positive_retained_pdb_ids.append(pdb_id)
        elif same_chain:
            decision = "same_chain_topology_blocked_review_only"
            same_chain_blocked_pdb_ids.append(pdb_id)
        elif (
            broad_decision
            == "nonpositive_naive_broad_role_false_hit_review_only"
            and known_context == "prior_counterexample_repeat"
        ):
            decision = "prior_counterexample_context_blocked_review_only"
            prior_counterexample_blocked_pdb_ids.append(pdb_id)
        elif (
            broad_decision
            == "nonpositive_naive_broad_role_false_hit_review_only"
        ):
            decision = "residual_new_topology_false_hit_review_only"
            residual_false_hit_pdb_ids.append(pdb_id)
        else:
            decision = "nonpositive_abstained_review_only"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "mek_erk_context_counteraxis_terminal_topology_hit",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "rule_id": rule_id,
                "candidate_threshold_angstrom": threshold,
                "source_broad_role_stress_decision": broad_decision,
                "known_context": broad_row.get("known_context"),
                "source_validation_status": broad_row.get(
                    "source_validation_status"
                ),
                "candidate_same_chain_as_gamma": same_chain,
                "source_reviewed_mek_erk_positive": source_reviewed_positive,
                "known_positive_repeat_or_source_valid": known_positive,
                "naive_broad_protein_role_rule_hit": naive_hit,
                "context_counteraxis_decision": decision,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
            }
        )

    positive_retained_pdb_ids = _sorted_strings(positive_retained_pdb_ids)
    known_positive_retained_pdb_ids = _sorted_strings(
        known_positive_retained_pdb_ids
    )
    prior_counterexample_blocked_pdb_ids = _sorted_strings(
        prior_counterexample_blocked_pdb_ids
    )
    same_chain_blocked_pdb_ids = _sorted_strings(same_chain_blocked_pdb_ids)
    residual_false_hit_pdb_ids = _sorted_strings(residual_false_hit_pdb_ids)
    if residual_false_hit_pdb_ids:
        status = (
            "fails_closed_context_counteraxis_reduces_but_does_not_clear_false_hits"
        )
    else:
        status = "passes_review_context_counteraxis_but_not_source_free"

    return {
        "metadata": {
            "method": "epk_mek_erk_context_counteraxis_stress_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_broad_role_stress_audit_method": (
                broad_meta.get("method")
            ),
            "rule_id": rule_id,
            "candidate_threshold_angstrom": threshold,
            "context_counteraxis_status": status,
            "reviewed_topology_hit_count": len(rows),
            "source_reviewed_mek_erk_positive_retained_count": len(
                positive_retained_pdb_ids
            ),
            "source_reviewed_mek_erk_positive_retained_pdb_ids": (
                positive_retained_pdb_ids
            ),
            "known_positive_repeat_retained_count": len(
                known_positive_retained_pdb_ids
            ),
            "known_positive_repeat_retained_pdb_ids": known_positive_retained_pdb_ids,
            "prior_counterexample_context_blocked_count": len(
                prior_counterexample_blocked_pdb_ids
            ),
            "prior_counterexample_context_blocked_pdb_ids": (
                prior_counterexample_blocked_pdb_ids
            ),
            "same_chain_topology_blocked_count": len(same_chain_blocked_pdb_ids),
            "same_chain_topology_blocked_pdb_ids": same_chain_blocked_pdb_ids,
            "residual_new_topology_false_hit_count": len(
                residual_false_hit_pdb_ids
            ),
            "residual_new_topology_false_hit_pdb_ids": residual_false_hit_pdb_ids,
            "context_counteraxis_decision_counts": dict(
                sorted(decision_counts.items())
            ),
            "decision_surface_changed": True,
            "source_free_predictive_feature_materialized": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "prior_counterexample_context_blocks_six_mek_erk_broad_role_false_hits",
            "blocker_not_removed": [
                "review_context_counteraxis_not_source_free",
                "residual_new_topology_false_hits_need_source_adjudication",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact changes the review-only decision surface by "
                "blocking prior-counterexample repeats after MEK1/ERK1 broad "
                "role stress. It uses review context, so it is not a "
                "source-free ePK scorer or production-admissible counteraxis."
            ),
            "next_actions": [
                "source-adjudicate residual new topology hits 7CAG and 8BMS before scorer calibration",
                "replace review-context blocking with a source-free feature before any production threshold",
                "keep external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("context_counteraxis_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "MEK1/ERK1 context counteraxis stress is review-only and "
                "depends on review context; it cannot support production "
                "scoring, registry edits, or label import."
            )
        ],
    }


def build_epk_mek_erk_residual_false_hit_source_adjudication(
    *,
    epk_mek_erk_context_counteraxis_stress_audit: dict[str, Any],
    epk_ligand_specific_active_query_source_validation_reviews: list[dict[str, Any]],
) -> dict[str, Any]:
    """Source-adjudicate residual MEK/ERK broad-role topology false hits."""

    context_meta = epk_mek_erk_context_counteraxis_stress_audit.get(
        "metadata", {}
    )
    if not isinstance(context_meta, dict):
        context_meta = {}
    target_fingerprint_id = str(
        context_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    residual_pdb_ids = _sorted_strings(
        context_meta.get("residual_new_topology_false_hit_pdb_ids", [])
    )
    residual_context_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_mek_erk_context_counteraxis_stress_audit.get("rows", [])
        or []
        if isinstance(row, dict)
        and row.get("context_counteraxis_decision")
        == "residual_new_topology_false_hit_review_only"
    }
    validation_rows_by_pdb: dict[str, dict[str, Any]] = {}
    for review in epk_ligand_specific_active_query_source_validation_reviews:
        if not isinstance(review, dict):
            continue
        for row in review.get("rows", []) or []:
            if not isinstance(row, dict):
                continue
            pdb_id = str(row.get("pdb_id") or "").upper()
            if pdb_id:
                validation_rows_by_pdb[pdb_id] = row

    def _source_text(row: dict[str, Any]) -> str:
        pieces: list[str] = []
        for key in (
            "structure_title",
            "keywords",
            "entity_descriptions",
            "source_validation_evidence",
        ):
            value = row.get(key)
            if isinstance(value, list):
                pieces.extend(str(item) for item in value)
            elif value not in {None, "", ".", "?"}:
                pieces.append(str(value))
        accessions = row.get("chain_accessions", {})
        if isinstance(accessions, dict):
            for chain_id, values in accessions.items():
                pieces.append(str(chain_id))
                if isinstance(values, list):
                    pieces.extend(str(item) for item in values)
                elif values not in {None, "", ".", "?"}:
                    pieces.append(str(values))
        return " ".join(pieces).lower()

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    terminal_blocked_pdb_ids: list[str] = []
    unresolved_pdb_ids: list[str] = []
    transporter_false_hit_pdb_ids: list[str] = []
    missing_source_review_pdb_ids: list[str] = []
    source_review_artifact_count = len(
        [
            review
            for review in epk_ligand_specific_active_query_source_validation_reviews
            if isinstance(review, dict)
        ]
    )

    for pdb_id in residual_pdb_ids:
        validation_row = validation_rows_by_pdb.get(pdb_id, {})
        context_row = residual_context_by_pdb.get(pdb_id, {})
        text = _source_text(validation_row)
        transporter_context = any(
            token in text
            for token in (
                "transporter",
                "transport protein",
                "permease",
                "sugabc",
                "sugb",
                "sugc",
                "lpqy",
                "ecft",
                "energy-coupling factor",
                "membrane protein",
            )
        )
        kinase_source_context = any(
            token in text
            for token in (
                "protein kinase",
                "kinase-substrate",
                "phosphoprotein",
                "phosphotransferase",
                "[protein]",
            )
        )
        explicit_negative_review = (
            "no_explicit_kinase_substrate_source_context_detected" in text
        )
        if validation_row and transporter_context and not kinase_source_context:
            status = "terminal_non_epk_transporter_false_hit_review_only"
            terminal_blocked_pdb_ids.append(pdb_id)
            transporter_false_hit_pdb_ids.append(pdb_id)
            remaining_blockers = [
                "source_context_counterevidence_not_source_free_predictive_feature",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ]
        elif validation_row and explicit_negative_review and not kinase_source_context:
            status = "terminal_no_kinase_substrate_source_context_review_only"
            terminal_blocked_pdb_ids.append(pdb_id)
            remaining_blockers = [
                "source_context_counterevidence_not_source_free_predictive_feature",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ]
        else:
            status = "unresolved_residual_false_hit_source_context_review_only"
            unresolved_pdb_ids.append(pdb_id)
            if not validation_row:
                missing_source_review_pdb_ids.append(pdb_id)
            remaining_blockers = [
                "residual_false_hit_source_context_unresolved",
                "source_free_counteraxis_not_materialized",
                "threshold_not_calibrated_against_negative_controls",
            ]
        status_counts[status] += 1
        rows.append(
            {
                "row_type": "mek_erk_residual_false_hit_source_adjudication",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "source_context_used_for_counterevidence": True,
                "source_free_predictive_feature_materialized": False,
                "context_counteraxis_decision": context_row.get(
                    "context_counteraxis_decision"
                ),
                "source_validation_status": validation_row.get(
                    "source_validation_status"
                ),
                "source_validation_evidence": validation_row.get(
                    "source_validation_evidence", []
                ),
                "structure_title": validation_row.get("structure_title"),
                "keywords": validation_row.get("keywords", []),
                "entity_descriptions": validation_row.get("entity_descriptions", []),
                "chain_accessions": validation_row.get("chain_accessions", {}),
                "candidate_hits": validation_row.get("candidate_hits", []),
                "transporter_source_context_detected": transporter_context,
                "kinase_source_context_detected": kinase_source_context,
                "explicit_negative_source_review_detected": (
                    explicit_negative_review
                ),
                "source_adjudication_status": status,
                "terminally_blocked_as_broad_role_false_hit": (
                    status
                    in {
                        "terminal_non_epk_transporter_false_hit_review_only",
                        "terminal_no_kinase_substrate_source_context_review_only",
                    }
                ),
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_orphan_discovery_claims": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": remaining_blockers,
            }
        )

    terminal_blocked_pdb_ids = _sorted_strings(terminal_blocked_pdb_ids)
    unresolved_pdb_ids = _sorted_strings(unresolved_pdb_ids)
    transporter_false_hit_pdb_ids = _sorted_strings(transporter_false_hit_pdb_ids)
    missing_source_review_pdb_ids = _sorted_strings(missing_source_review_pdb_ids)
    status = (
        "passes_review_only_residual_false_hits_terminally_blocked_not_source_free"
        if residual_pdb_ids
        and len(terminal_blocked_pdb_ids) == len(residual_pdb_ids)
        and not unresolved_pdb_ids
        else "fails_closed_residual_false_hit_source_adjudication_incomplete"
    )
    return {
        "metadata": {
            "method": "epk_mek_erk_residual_false_hit_source_adjudication",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_context_counteraxis_stress_audit_method": (
                context_meta.get("method")
            ),
            "source_validation_review_artifact_count": source_review_artifact_count,
            "residual_false_hit_input_count": len(residual_pdb_ids),
            "residual_false_hit_input_pdb_ids": residual_pdb_ids,
            "reviewed_residual_false_hit_count": len(rows),
            "terminally_blocked_residual_false_hit_count": len(
                terminal_blocked_pdb_ids
            ),
            "terminally_blocked_residual_false_hit_pdb_ids": (
                terminal_blocked_pdb_ids
            ),
            "transporter_false_hit_count": len(transporter_false_hit_pdb_ids),
            "transporter_false_hit_pdb_ids": transporter_false_hit_pdb_ids,
            "unresolved_residual_false_hit_count": len(unresolved_pdb_ids),
            "unresolved_residual_false_hit_pdb_ids": unresolved_pdb_ids,
            "missing_source_review_count": len(missing_source_review_pdb_ids),
            "missing_source_review_pdb_ids": missing_source_review_pdb_ids,
            "source_adjudication_status": status,
            "source_adjudication_status_counts": dict(sorted(status_counts.items())),
            "source_context_counterevidence_used": True,
            "source_free_predictive_feature_materialized": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "residual_new_topology_false_hits_source_adjudicated",
            "blocker_not_removed": [
                "source_context_counterevidence_not_source_free_predictive_feature",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This source-adjudication artifact turns the residual MEK/ERK "
                "broad-role topology false hits into terminal review-only "
                "counterexamples. It uses source context, so it is not a "
                "source-free ePK counteraxis or production score."
            ),
            "next_actions": [
                "replace source-context residual-hit blocking with a source-free acceptor or substrate identity feature",
                "do not calibrate MEK/ERK broad-role thresholds from this source-adjudicated surface",
                "keep external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": sorted(rows, key=lambda row: str(row.get("pdb_id") or "")),
        "warnings": [
            (
                "Residual false-hit source adjudication is review-only and "
                "does not authorize threshold selection, scoring, registry "
                "edits, or label import."
            )
        ],
    }


def build_epk_mek_erk_source_free_topology_ambiguity_counteraxis(
    *,
    epk_mek_erk_phosphosite_source_review: dict[str, Any],
    epk_mek_erk_context_counteraxis_stress_audit: dict[str, Any],
    candidate_context_artifacts: list[dict[str, Any]],
) -> dict[str, Any]:
    """Test a source-free local topology ambiguity counteraxis for MEK/ERK."""

    source_meta = epk_mek_erk_phosphosite_source_review.get("metadata", {})
    if not isinstance(source_meta, dict):
        source_meta = {}
    context_meta = epk_mek_erk_context_counteraxis_stress_audit.get(
        "metadata", {}
    )
    if not isinstance(context_meta, dict):
        context_meta = {}
    target_fingerprint_id = str(
        source_meta.get("target_fingerprint_id")
        or context_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    positive_pdb_ids = _sorted_strings(
        source_meta.get("source_authoritative_measurement_ready_pdb_ids", [])
    )
    residual_pdb_ids = _sorted_strings(
        context_meta.get("residual_new_topology_false_hit_pdb_ids", [])
    )
    source_meta_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_mek_erk_phosphosite_source_review.get("rows", []) or []
        if isinstance(row, dict)
    }

    def _hits_from_row(row: dict[str, Any]) -> list[dict[str, Any]]:
        hits: list[dict[str, Any]] = []
        single_hit = row.get("candidate_hit")
        if isinstance(single_hit, dict):
            hits.append(single_hit)
        for key in ("candidate_hits", "heteromeric_candidate_hits"):
            values = row.get(key, [])
            if isinstance(values, list):
                hits.extend(hit for hit in values if isinstance(hit, dict))
        unique: dict[tuple[str, str, str, str], dict[str, Any]] = {}
        for hit in hits:
            key = (
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
                str(hit.get("candidate_residue_code") or ""),
                str(hit.get("gamma_associated_polymer_chain_name") or ""),
            )
            existing = unique.get(key)
            try:
                distance = float(hit.get("nearest_gamma_distance_angstrom"))
            except (TypeError, ValueError):
                distance = 9999.0
            if existing is None:
                unique[key] = hit
                continue
            try:
                existing_distance = float(
                    existing.get("nearest_gamma_distance_angstrom")
                )
            except (TypeError, ValueError):
                existing_distance = 9999.0
            if distance < existing_distance:
                unique[key] = hit
        return sorted(
            unique.values(),
            key=lambda hit: (
                float(hit.get("nearest_gamma_distance_angstrom") or 9999.0),
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
                str(hit.get("gamma_associated_polymer_chain_name") or ""),
            ),
        )

    hits_by_pdb: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in epk_mek_erk_phosphosite_source_review.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        pdb_id = str(row.get("pdb_id") or "").upper()
        if pdb_id:
            hits_by_pdb[pdb_id].extend(_hits_from_row(row))
    for artifact in candidate_context_artifacts:
        if not isinstance(artifact, dict):
            continue
        for row in artifact.get("rows", []) or []:
            if not isinstance(row, dict):
                continue
            pdb_id = str(row.get("pdb_id") or "").upper()
            if pdb_id:
                hits_by_pdb[pdb_id].extend(_hits_from_row(row))
    hits_by_pdb = {
        pdb_id: _hits_from_row({"candidate_hits": hits})
        for pdb_id, hits in sorted(hits_by_pdb.items())
    }

    def _has_same_chain_hit(hits: list[dict[str, Any]]) -> bool:
        return any(
            str(hit.get("candidate_chain_name") or "")
            and str(hit.get("candidate_chain_name") or "")
            == str(hit.get("gamma_associated_polymer_chain_name") or "")
            for hit in hits
        )

    def _has_reciprocal_cross_chain_hits(hits: list[dict[str, Any]]) -> bool:
        for left_index, left in enumerate(hits):
            left_candidate = str(left.get("candidate_chain_name") or "")
            left_gamma = str(left.get("gamma_associated_polymer_chain_name") or "")
            if not left_candidate or not left_gamma or left_candidate == left_gamma:
                continue
            for right in hits[left_index + 1 :]:
                right_candidate = str(right.get("candidate_chain_name") or "")
                right_gamma = str(right.get("gamma_associated_polymer_chain_name") or "")
                if left_candidate == right_gamma and left_gamma == right_candidate:
                    return True
        return False

    rows: list[dict[str, Any]] = []
    retained_positive_pdb_ids: list[str] = []
    lost_positive_pdb_ids: list[str] = []
    blocked_residual_pdb_ids: list[str] = []
    residual_false_hit_pdb_ids: list[str] = []
    missing_hit_pdb_ids: list[str] = []
    decision_counts: Counter[str] = Counter()
    for pdb_id in _sorted_strings(set(positive_pdb_ids) | set(residual_pdb_ids)):
        hits = hits_by_pdb.get(pdb_id, [])
        has_same_chain_hit = _has_same_chain_hit(hits)
        has_reciprocal_hits = _has_reciprocal_cross_chain_hits(hits)
        topology_ambiguous = has_same_chain_hit or has_reciprocal_hits
        positive = pdb_id in positive_pdb_ids
        residual = pdb_id in residual_pdb_ids
        if not hits:
            decision = "missing_local_topology_hits_review_only"
            missing_hit_pdb_ids.append(pdb_id)
        elif positive and not topology_ambiguous:
            decision = "source_reviewed_positive_retained_review_only"
            retained_positive_pdb_ids.append(pdb_id)
        elif positive:
            decision = "source_reviewed_positive_lost_to_ambiguity_rule_review_only"
            lost_positive_pdb_ids.append(pdb_id)
        elif residual and topology_ambiguous:
            decision = "residual_false_hit_blocked_by_topology_ambiguity_review_only"
            blocked_residual_pdb_ids.append(pdb_id)
        elif residual:
            decision = "residual_false_hit_not_blocked_by_topology_ambiguity_review_only"
            residual_false_hit_pdb_ids.append(pdb_id)
        else:
            decision = "unclassified_topology_row_review_only"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "mek_erk_source_free_topology_ambiguity_counteraxis_row",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "source_fields_masked_for_candidate_rule": True,
                "source_context_used_for_failure_label_only": True,
                "known_source_reviewed_positive": positive,
                "known_residual_false_hit": residual,
                "candidate_hit_count": len(hits),
                "candidate_hits": hits,
                "same_chain_companion_hit_detected": has_same_chain_hit,
                "reciprocal_cross_chain_hit_detected": has_reciprocal_hits,
                "topology_ambiguity_counteraxis_hit": topology_ambiguous,
                "counteraxis_decision": decision,
                "source_review_status": source_meta_by_pdb.get(pdb_id, {}).get(
                    "phosphosite_source_review_status"
                ),
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_orphan_discovery_claims": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
            }
        )

    retained_positive_pdb_ids = _sorted_strings(retained_positive_pdb_ids)
    lost_positive_pdb_ids = _sorted_strings(lost_positive_pdb_ids)
    blocked_residual_pdb_ids = _sorted_strings(blocked_residual_pdb_ids)
    residual_false_hit_pdb_ids = _sorted_strings(residual_false_hit_pdb_ids)
    missing_hit_pdb_ids = _sorted_strings(missing_hit_pdb_ids)
    status = (
        "passes_bounded_residual_controls_source_free_topology_ambiguity_review_only"
        if positive_pdb_ids
        and residual_pdb_ids
        and len(retained_positive_pdb_ids) == len(positive_pdb_ids)
        and len(blocked_residual_pdb_ids) == len(residual_pdb_ids)
        and not lost_positive_pdb_ids
        and not residual_false_hit_pdb_ids
        and not missing_hit_pdb_ids
        else "fails_closed_source_free_topology_ambiguity_counteraxis"
    )
    return {
        "metadata": {
            "method": "epk_mek_erk_source_free_topology_ambiguity_counteraxis",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_phosphosite_source_review_method": (
                source_meta.get("method")
            ),
            "source_epk_mek_erk_context_counteraxis_stress_audit_method": (
                context_meta.get("method")
            ),
            "candidate_context_artifact_count": len(
                [artifact for artifact in candidate_context_artifacts if artifact]
            ),
            "rule_id": "epk_mek_erk_source_free_topology_ambiguity_counteraxis_v0",
            "source_free_counteraxis_status": status,
            "source_fields_masked_for_candidate_rule": True,
            "source_context_used_for_failure_label_only": True,
            "source_free_predictive_feature_materialized": True,
            "source_reviewed_positive_input_count": len(positive_pdb_ids),
            "source_reviewed_positive_input_pdb_ids": positive_pdb_ids,
            "source_reviewed_positive_retained_count": len(
                retained_positive_pdb_ids
            ),
            "source_reviewed_positive_retained_pdb_ids": retained_positive_pdb_ids,
            "source_reviewed_positive_lost_count": len(lost_positive_pdb_ids),
            "source_reviewed_positive_lost_pdb_ids": lost_positive_pdb_ids,
            "residual_false_hit_input_count": len(residual_pdb_ids),
            "residual_false_hit_input_pdb_ids": residual_pdb_ids,
            "residual_false_hit_blocked_count": len(blocked_residual_pdb_ids),
            "residual_false_hit_blocked_pdb_ids": blocked_residual_pdb_ids,
            "residual_false_hit_unblocked_count": len(residual_false_hit_pdb_ids),
            "residual_false_hit_unblocked_pdb_ids": residual_false_hit_pdb_ids,
            "missing_local_topology_hit_count": len(missing_hit_pdb_ids),
            "missing_local_topology_hit_pdb_ids": missing_hit_pdb_ids,
            "decision_counts": dict(sorted(decision_counts.items())),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "bounded_residual_false_hits_blocked_by_source_free_topology_ambiguity",
            "blocker_not_removed": [
                "topology_ambiguity_counteraxis_only_bounded_to_mek_erk_residuals",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact uses only local topology hit-pattern ambiguity "
                "for the candidate rule: same-chain companion hits or reciprocal "
                "cross-chain ATP-to-hydroxyl hits. Source context is used only "
                "to label positives and residual false hits for review."
            ),
            "next_actions": [
                "stress the topology-ambiguity counteraxis against broader heteromeric positives and controls",
                "do not calibrate thresholds until the rule clears broader source-free controls",
                "keep external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("counteraxis_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The topology-ambiguity counteraxis is a bounded review-only "
                "source-free feature probe, not production scoring evidence."
            )
        ],
    }


def build_epk_mek_erk_source_free_topology_broader_stress_audit(
    *,
    epk_mek_erk_broad_role_stress_audit: dict[str, Any],
    candidate_context_artifacts: list[dict[str, Any]],
) -> dict[str, Any]:
    """Stress the topology-ambiguity rule against broader MEK/ERK hits."""

    broad_meta = epk_mek_erk_broad_role_stress_audit.get("metadata", {})
    if not isinstance(broad_meta, dict):
        broad_meta = {}
    target_fingerprint_id = str(
        broad_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    threshold = broad_meta.get("candidate_threshold_angstrom")

    def _safe_float(value: Any) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return 9999.0

    def _hits_from_row(row: dict[str, Any]) -> list[dict[str, Any]]:
        hits: list[dict[str, Any]] = []
        single_hit = row.get("candidate_hit")
        if isinstance(single_hit, dict):
            hits.append(single_hit)
        for key in ("candidate_hits", "heteromeric_candidate_hits"):
            values = row.get(key, [])
            if isinstance(values, list):
                hits.extend(hit for hit in values if isinstance(hit, dict))
        candidate_chain = str(row.get("candidate_chain_name") or "")
        gamma_chain = str(row.get("gamma_associated_polymer_chain_name") or "")
        if candidate_chain and gamma_chain:
            hits.append(
                {
                    "candidate_chain_name": candidate_chain,
                    "candidate_auth_seq_id": row.get("candidate_auth_seq_id"),
                    "candidate_residue_code": row.get("candidate_residue_code"),
                    "gamma_associated_polymer_chain_name": gamma_chain,
                    "nearest_gamma_distance_angstrom": row.get(
                        "nearest_gamma_distance_angstrom"
                    ),
                }
            )
        unique: dict[tuple[str, str, str, str], dict[str, Any]] = {}
        for hit in hits:
            key = (
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
                str(hit.get("candidate_residue_code") or ""),
                str(hit.get("gamma_associated_polymer_chain_name") or ""),
            )
            existing = unique.get(key)
            if existing is None or _safe_float(
                hit.get("nearest_gamma_distance_angstrom")
            ) < _safe_float(existing.get("nearest_gamma_distance_angstrom")):
                unique[key] = hit
        return sorted(
            unique.values(),
            key=lambda hit: (
                _safe_float(hit.get("nearest_gamma_distance_angstrom")),
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
                str(hit.get("gamma_associated_polymer_chain_name") or ""),
            ),
        )

    hits_by_pdb: dict[str, list[dict[str, Any]]] = defaultdict(list)
    broad_rows_by_pdb: dict[str, dict[str, Any]] = {}
    for row in epk_mek_erk_broad_role_stress_audit.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        pdb_id = str(row.get("pdb_id") or "").upper()
        if not pdb_id:
            continue
        broad_rows_by_pdb[pdb_id] = row
        hits_by_pdb[pdb_id].extend(_hits_from_row(row))
    for artifact in candidate_context_artifacts:
        if not isinstance(artifact, dict):
            continue
        for row in artifact.get("rows", []) or []:
            if not isinstance(row, dict):
                continue
            pdb_id = str(row.get("pdb_id") or "").upper()
            if pdb_id:
                hits_by_pdb[pdb_id].extend(_hits_from_row(row))
    hits_by_pdb = {
        pdb_id: _hits_from_row({"candidate_hits": hits})
        for pdb_id, hits in sorted(hits_by_pdb.items())
    }

    def _has_same_chain_hit(hits: list[dict[str, Any]]) -> bool:
        return any(
            str(hit.get("candidate_chain_name") or "")
            and str(hit.get("candidate_chain_name") or "")
            == str(hit.get("gamma_associated_polymer_chain_name") or "")
            for hit in hits
        )

    def _has_reciprocal_cross_chain_hits(hits: list[dict[str, Any]]) -> bool:
        for left_index, left in enumerate(hits):
            left_candidate = str(left.get("candidate_chain_name") or "")
            left_gamma = str(left.get("gamma_associated_polymer_chain_name") or "")
            if not left_candidate or not left_gamma or left_candidate == left_gamma:
                continue
            for right in hits[left_index + 1 :]:
                right_candidate = str(right.get("candidate_chain_name") or "")
                right_gamma = str(right.get("gamma_associated_polymer_chain_name") or "")
                if left_candidate == right_gamma and left_gamma == right_candidate:
                    return True
        return False

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    retained_positive_pdb_ids: list[str] = []
    lost_positive_pdb_ids: list[str] = []
    blocked_false_hit_pdb_ids: list[str] = []
    residual_false_hit_pdb_ids: list[str] = []
    missing_hit_pdb_ids: list[str] = []

    for pdb_id, broad_row in sorted(broad_rows_by_pdb.items()):
        if not bool(broad_row.get("naive_broad_protein_role_rule_hit")):
            continue
        hits = hits_by_pdb.get(pdb_id, [])
        has_same_chain_hit = _has_same_chain_hit(hits)
        has_reciprocal_hits = _has_reciprocal_cross_chain_hits(hits)
        topology_ambiguous = has_same_chain_hit or has_reciprocal_hits
        positive = bool(broad_row.get("source_reviewed_mek_erk_positive")) or bool(
            broad_row.get("known_positive_repeat_or_source_valid")
        )
        false_hit = (
            broad_row.get("broad_role_stress_decision")
            == "nonpositive_naive_broad_role_false_hit_review_only"
        )
        if not hits:
            decision = "missing_local_topology_hits_review_only"
            missing_hit_pdb_ids.append(pdb_id)
        elif positive and not topology_ambiguous:
            decision = "positive_control_retained_review_only"
            retained_positive_pdb_ids.append(pdb_id)
        elif positive:
            decision = "positive_control_lost_to_topology_ambiguity_review_only"
            lost_positive_pdb_ids.append(pdb_id)
        elif false_hit and topology_ambiguous:
            decision = "false_hit_blocked_by_topology_ambiguity_review_only"
            blocked_false_hit_pdb_ids.append(pdb_id)
        elif false_hit:
            decision = "false_hit_not_blocked_by_topology_ambiguity_review_only"
            residual_false_hit_pdb_ids.append(pdb_id)
        else:
            decision = "nonpositive_abstained_review_only"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "mek_erk_source_free_topology_broader_stress_row",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "candidate_threshold_angstrom": threshold,
                "source_fields_masked_for_candidate_rule": True,
                "source_context_used_for_failure_label_only": True,
                "known_positive_control": positive,
                "known_false_hit_control": false_hit,
                "source_broad_role_stress_decision": broad_row.get(
                    "broad_role_stress_decision"
                ),
                "known_context": broad_row.get("known_context"),
                "candidate_hit_count": len(hits),
                "candidate_hits": hits,
                "same_chain_companion_hit_detected": has_same_chain_hit,
                "reciprocal_cross_chain_hit_detected": has_reciprocal_hits,
                "topology_ambiguity_counteraxis_hit": topology_ambiguous,
                "counteraxis_decision": decision,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_orphan_discovery_claims": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
            }
        )

    retained_positive_pdb_ids = _sorted_strings(retained_positive_pdb_ids)
    lost_positive_pdb_ids = _sorted_strings(lost_positive_pdb_ids)
    blocked_false_hit_pdb_ids = _sorted_strings(blocked_false_hit_pdb_ids)
    residual_false_hit_pdb_ids = _sorted_strings(residual_false_hit_pdb_ids)
    missing_hit_pdb_ids = _sorted_strings(missing_hit_pdb_ids)
    if residual_false_hit_pdb_ids or lost_positive_pdb_ids or missing_hit_pdb_ids:
        status = "fails_closed_broader_topology_ambiguity_residual_false_hits"
    else:
        status = "passes_broader_topology_ambiguity_controls_review_only"

    return {
        "metadata": {
            "method": "epk_mek_erk_source_free_topology_broader_stress_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_broad_role_stress_audit_method": (
                broad_meta.get("method")
            ),
            "candidate_context_artifact_count": len(
                [artifact for artifact in candidate_context_artifacts if artifact]
            ),
            "rule_id": "epk_mek_erk_source_free_topology_ambiguity_counteraxis_v0",
            "broader_stress_status": status,
            "reviewed_broad_topology_hit_count": len(rows),
            "positive_control_input_count": len(
                retained_positive_pdb_ids + lost_positive_pdb_ids
            ),
            "positive_control_retained_count": len(retained_positive_pdb_ids),
            "positive_control_retained_pdb_ids": retained_positive_pdb_ids,
            "positive_control_lost_count": len(lost_positive_pdb_ids),
            "positive_control_lost_pdb_ids": lost_positive_pdb_ids,
            "false_hit_control_input_count": len(
                blocked_false_hit_pdb_ids + residual_false_hit_pdb_ids
            ),
            "false_hit_blocked_count": len(blocked_false_hit_pdb_ids),
            "false_hit_blocked_pdb_ids": blocked_false_hit_pdb_ids,
            "residual_false_hit_count": len(residual_false_hit_pdb_ids),
            "residual_false_hit_pdb_ids": residual_false_hit_pdb_ids,
            "missing_local_topology_hit_count": len(missing_hit_pdb_ids),
            "missing_local_topology_hit_pdb_ids": missing_hit_pdb_ids,
            "decision_counts": dict(sorted(decision_counts.items())),
            "source_free_predictive_feature_materialized": True,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": (
                "bounded_mek_erk_residual_topology_false_hits_are_not_the_only_stress_surface"
            ),
            "blocker_not_removed": [
                "broader_topology_ambiguity_rule_leaves_false_hits",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact applies the same source-free local topology "
                "ambiguity rule to the broader MEK/ERK broad-role hit surface. "
                "Source context is used only to label controls."
            ),
            "next_actions": [
                "find an additional source-free acceptor or substrate identity axis for residual false hits",
                "do not promote the topology-ambiguity rule as a production counteraxis",
                "keep real external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("counteraxis_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Broader topology ambiguity stress is review-only and failed "
                "closed; it cannot support threshold selection, scoring, "
                "registry edits, or label import."
            )
        ],
    }


def build_epk_mek_erk_substrate_mode_counteraxis_audit(
    *,
    epk_mek_erk_source_free_topology_broader_stress_audit: dict[str, Any],
    candidate_threshold_angstrom: float = 6.0,
    max_n_terminal_acceptor_auth_seq_id: int = 25,
) -> dict[str, Any]:
    """Probe a source-free substrate-mode rule on MEK/ERK broad-role stress."""

    stress_meta = epk_mek_erk_source_free_topology_broader_stress_audit.get(
        "metadata", {}
    )
    if not isinstance(stress_meta, dict):
        stress_meta = {}
    target_fingerprint_id = str(
        stress_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(
            stress_meta.get("candidate_threshold_angstrom")
            or candidate_threshold_angstrom
        )
    except (TypeError, ValueError):
        threshold = 6.0
    try:
        n_terminal_max = int(max_n_terminal_acceptor_auth_seq_id)
    except (TypeError, ValueError):
        n_terminal_max = 25
    n_terminal_max = max(1, n_terminal_max)

    hydroxyl_residue_codes = {"SER", "THR", "TYR"}

    def _safe_float(value: Any) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return 9999.0

    def _optional_int(value: Any) -> int | None:
        try:
            if value in {None, "", ".", "?"}:
                return None
            return int(float(str(value)))
        except (TypeError, ValueError):
            return None

    def _primary_hydroxyl_hit(row: dict[str, Any]) -> dict[str, Any]:
        hits = [
            hit
            for hit in row.get("candidate_hits", []) or []
            if isinstance(hit, dict)
            and str(hit.get("candidate_residue_code") or "").upper()
            in hydroxyl_residue_codes
            and _safe_float(hit.get("nearest_gamma_distance_angstrom")) <= threshold
        ]
        return (
            sorted(
                hits,
                key=lambda hit: (
                    _safe_float(hit.get("nearest_gamma_distance_angstrom")),
                    str(hit.get("candidate_chain_name") or ""),
                    str(hit.get("candidate_auth_seq_id") or ""),
                    str(hit.get("candidate_residue_code") or ""),
                ),
            )[0]
            if hits
            else {}
        )

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    positive_retained_pdb_ids: list[str] = []
    positive_lost_pdb_ids: list[str] = []
    topology_blocked_false_hit_pdb_ids: list[str] = []
    substrate_blocked_false_hit_pdb_ids: list[str] = []
    residual_false_hit_pdb_ids: list[str] = []
    missing_primary_hit_pdb_ids: list[str] = []

    for stress_row in (
        epk_mek_erk_source_free_topology_broader_stress_audit.get("rows", [])
        or []
    ):
        if not isinstance(stress_row, dict):
            continue
        pdb_id = str(stress_row.get("pdb_id") or "").upper()
        if not pdb_id:
            continue
        hit = _primary_hydroxyl_hit(stress_row)
        residue_code = str(hit.get("candidate_residue_code") or "").upper()
        auth_seq_id = _optional_int(hit.get("candidate_auth_seq_id"))
        tyrosine_mode_hit = residue_code == "TYR"
        n_terminal_mode_hit = (
            residue_code in {"SER", "THR", "TYR"}
            and auth_seq_id is not None
            and auth_seq_id <= n_terminal_max
        )
        substrate_mode_rule_hit = bool(tyrosine_mode_hit or n_terminal_mode_hit)
        topology_blocked = bool(
            stress_row.get("topology_ambiguity_counteraxis_hit")
        )
        positive = bool(stress_row.get("known_positive_control"))
        false_hit = bool(stress_row.get("known_false_hit_control"))
        if not hit:
            decision = "missing_primary_hydroxyl_hit_review_only"
            missing_primary_hit_pdb_ids.append(pdb_id)
        elif positive and substrate_mode_rule_hit:
            decision = "positive_control_retained_by_substrate_mode_review_only"
            positive_retained_pdb_ids.append(pdb_id)
        elif positive:
            decision = "positive_control_lost_by_substrate_mode_review_only"
            positive_lost_pdb_ids.append(pdb_id)
        elif false_hit and topology_blocked:
            decision = "false_hit_blocked_by_existing_topology_counteraxis_review_only"
            topology_blocked_false_hit_pdb_ids.append(pdb_id)
        elif false_hit and not substrate_mode_rule_hit:
            decision = "false_hit_blocked_by_substrate_mode_counteraxis_review_only"
            substrate_blocked_false_hit_pdb_ids.append(pdb_id)
        elif false_hit:
            decision = "false_hit_not_blocked_by_substrate_mode_review_only"
            residual_false_hit_pdb_ids.append(pdb_id)
        else:
            decision = "nonpositive_abstained_review_only"
        decision_counts[decision] += 1
        counterevidence_reasons: list[str] = []
        if not hit:
            counterevidence_reasons.append("primary_hydroxyl_hit_missing")
        if residue_code and residue_code != "TYR" and not n_terminal_mode_hit:
            counterevidence_reasons.append(
                "acceptor_residue_not_tyrosine_or_n_terminal_ser_thr_tyr"
            )
        if auth_seq_id is None:
            counterevidence_reasons.append("acceptor_auth_seq_id_missing")
        elif auth_seq_id > n_terminal_max and residue_code != "TYR":
            counterevidence_reasons.append(
                "acceptor_auth_seq_id_outside_n_terminal_substrate_mode"
            )
        if topology_blocked:
            counterevidence_reasons.append("topology_ambiguity_counteraxis_hit")
        rows.append(
            {
                "row_type": "mek_erk_substrate_mode_counteraxis_stress_row",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "source_context_used_for_failure_label_only": True,
                "candidate_threshold_angstrom": threshold,
                "max_n_terminal_acceptor_auth_seq_id": n_terminal_max,
                "known_positive_control": positive,
                "known_false_hit_control": false_hit,
                "source_topology_broader_stress_decision": (
                    stress_row.get("counteraxis_decision")
                ),
                "known_context": stress_row.get("known_context"),
                "primary_candidate_acceptor_residue_code": residue_code or None,
                "primary_candidate_acceptor_auth_seq_id": (
                    hit.get("candidate_auth_seq_id")
                ),
                "primary_candidate_acceptor_chain_name": (
                    hit.get("candidate_chain_name")
                ),
                "primary_gamma_associated_polymer_chain_name": (
                    hit.get("gamma_associated_polymer_chain_name")
                ),
                "nearest_gamma_distance_angstrom": (
                    hit.get("nearest_gamma_distance_angstrom")
                ),
                "tyrosine_acceptor_mode_hit": tyrosine_mode_hit,
                "n_terminal_ser_thr_tyr_acceptor_mode_hit": n_terminal_mode_hit,
                "substrate_mode_counteraxis_rule_hit": substrate_mode_rule_hit,
                "topology_ambiguity_counteraxis_hit": topology_blocked,
                "substrate_mode_counteraxis_decision": decision,
                "substrate_mode_counterevidence_reasons": _sorted_strings(
                    counterevidence_reasons
                ),
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_orphan_discovery_claims": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "substrate_mode_rule_current_stress_only_not_calibrated",
                    "residue_class_and_auth_position_are_weak_substrate_identity",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    positive_retained_pdb_ids = _sorted_strings(positive_retained_pdb_ids)
    positive_lost_pdb_ids = _sorted_strings(positive_lost_pdb_ids)
    topology_blocked_false_hit_pdb_ids = _sorted_strings(
        topology_blocked_false_hit_pdb_ids
    )
    substrate_blocked_false_hit_pdb_ids = _sorted_strings(
        substrate_blocked_false_hit_pdb_ids
    )
    residual_false_hit_pdb_ids = _sorted_strings(residual_false_hit_pdb_ids)
    missing_primary_hit_pdb_ids = _sorted_strings(missing_primary_hit_pdb_ids)
    if positive_lost_pdb_ids or residual_false_hit_pdb_ids or missing_primary_hit_pdb_ids:
        status = "fails_closed_substrate_mode_counteraxis_gap_or_false_hit"
    else:
        status = "passes_current_broad_stress_substrate_mode_controls_review_only"

    return {
        "metadata": {
            "method": "epk_mek_erk_substrate_mode_counteraxis_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_source_free_topology_broader_stress_audit_method": (
                stress_meta.get("method")
            ),
            "rule_id": "epk_mek_erk_tyr_or_n_terminal_substrate_mode_counteraxis_v0",
            "candidate_threshold_angstrom": threshold,
            "max_n_terminal_acceptor_auth_seq_id": n_terminal_max,
            "substrate_mode_counteraxis_status": status,
            "reviewed_broad_topology_hit_count": len(rows),
            "positive_control_retained_count": len(positive_retained_pdb_ids),
            "positive_control_retained_pdb_ids": positive_retained_pdb_ids,
            "positive_control_lost_count": len(positive_lost_pdb_ids),
            "positive_control_lost_pdb_ids": positive_lost_pdb_ids,
            "false_hit_blocked_by_topology_count": len(
                topology_blocked_false_hit_pdb_ids
            ),
            "false_hit_blocked_by_topology_pdb_ids": (
                topology_blocked_false_hit_pdb_ids
            ),
            "false_hit_blocked_by_substrate_mode_count": len(
                substrate_blocked_false_hit_pdb_ids
            ),
            "false_hit_blocked_by_substrate_mode_pdb_ids": (
                substrate_blocked_false_hit_pdb_ids
            ),
            "residual_false_hit_count": len(residual_false_hit_pdb_ids),
            "residual_false_hit_pdb_ids": residual_false_hit_pdb_ids,
            "missing_primary_hydroxyl_hit_count": len(missing_primary_hit_pdb_ids),
            "missing_primary_hydroxyl_hit_pdb_ids": missing_primary_hit_pdb_ids,
            "decision_counts": dict(sorted(decision_counts.items())),
            "source_free_predictive_feature_materialized": True,
            "substrate_mode_axis_weak_current_stress_only": True,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": (
                "broader_mek_erk_false_hits_blocked_by_topology_or_substrate_mode_counteraxis"
            ),
            "blocker_not_removed": [
                "substrate_mode_rule_current_stress_only_not_calibrated",
                "residue_class_and_auth_position_are_weak_substrate_identity",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact tests a source-free substrate-mode heuristic on "
                "the broader MEK/ERK broad-role stress surface: retain local "
                "tyrosine acceptors or N-terminal Ser/Thr/Tyr acceptors while "
                "carrying the existing topology-ambiguity counteraxis. Source "
                "context labels controls only; this is not a calibrated ePK "
                "score or production-admissible substrate identity rule."
            ),
            "next_actions": [
                "stress this substrate-mode heuristic on a fresh outside-query tranche before scorer calibration",
                "replace residue-class/auth-position heuristics with stronger substrate identity evidence",
                "keep real external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("substrate_mode_counteraxis_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The MEK/ERK substrate-mode counteraxis is review-only and "
                "current-stress scoped; it cannot support threshold selection, "
                "production scoring, registry edits, or label import."
            )
        ],
    }


def build_epk_mek_erk_substrate_mode_fresh_stress_audit(
    *,
    epk_mek_erk_substrate_mode_counteraxis_audit: dict[str, Any],
    epk_mek_erk_targeted_candidate_scout: dict[str, Any],
    epk_mek_erk_targeted_source_validation_review: dict[str, Any] | None = None,
    candidate_threshold_angstrom: float = 6.0,
    max_n_terminal_acceptor_auth_seq_id: int = 25,
) -> dict[str, Any]:
    """Stress the MEK/ERK substrate-mode rule on a fresh targeted tranche."""

    substrate_meta = epk_mek_erk_substrate_mode_counteraxis_audit.get(
        "metadata", {}
    )
    if not isinstance(substrate_meta, dict):
        substrate_meta = {}
    scout_meta = epk_mek_erk_targeted_candidate_scout.get("metadata", {})
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    validation_meta: dict[str, Any] = {}
    if isinstance(epk_mek_erk_targeted_source_validation_review, dict):
        validation_meta = epk_mek_erk_targeted_source_validation_review.get(
            "metadata", {}
        )
        if not isinstance(validation_meta, dict):
            validation_meta = {}

    target_fingerprint_id = str(
        substrate_meta.get("target_fingerprint_id")
        or scout_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(
            substrate_meta.get("candidate_threshold_angstrom")
            or candidate_threshold_angstrom
        )
    except (TypeError, ValueError):
        threshold = 6.0
    try:
        n_terminal_max = int(
            substrate_meta.get("max_n_terminal_acceptor_auth_seq_id")
            or max_n_terminal_acceptor_auth_seq_id
        )
    except (TypeError, ValueError):
        n_terminal_max = 25
    n_terminal_max = max(1, n_terminal_max)

    current_surface_pdb_ids = {
        str(row.get("pdb_id") or "").upper()
        for row in epk_mek_erk_substrate_mode_counteraxis_audit.get("rows", [])
        or []
        if isinstance(row, dict) and row.get("pdb_id")
    }
    validation_by_pdb: dict[str, dict[str, Any]] = {}
    if isinstance(epk_mek_erk_targeted_source_validation_review, dict):
        for validation_row in (
            epk_mek_erk_targeted_source_validation_review.get("rows", []) or []
        ):
            if not isinstance(validation_row, dict):
                continue
            pdb_id = str(validation_row.get("pdb_id") or "").upper()
            if pdb_id:
                validation_by_pdb[pdb_id] = validation_row

    hydroxyl_residue_codes = {"SER", "THR", "TYR"}

    def _safe_float(value: Any) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return 9999.0

    def _optional_int(value: Any) -> int | None:
        try:
            if value in {None, "", ".", "?"}:
                return None
            return int(float(str(value)))
        except (TypeError, ValueError):
            return None

    def _candidate_hits(row: dict[str, Any]) -> list[dict[str, Any]]:
        hits = row.get("heteromeric_candidate_hits")
        if not isinstance(hits, list):
            hits = row.get("candidate_hits")
        return [hit for hit in hits or [] if isinstance(hit, dict)]

    def _primary_hydroxyl_hit(row: dict[str, Any]) -> dict[str, Any]:
        hits = [
            hit
            for hit in _candidate_hits(row)
            if str(hit.get("candidate_residue_code") or "").upper()
            in hydroxyl_residue_codes
            and _safe_float(hit.get("nearest_gamma_distance_angstrom")) <= threshold
        ]
        return (
            sorted(
                hits,
                key=lambda hit: (
                    _safe_float(hit.get("nearest_gamma_distance_angstrom")),
                    str(hit.get("candidate_chain_name") or ""),
                    str(hit.get("candidate_auth_seq_id") or ""),
                    str(hit.get("candidate_residue_code") or ""),
                ),
            )[0]
            if hits
            else {}
        )

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    fresh_pdb_ids: list[str] = []
    fresh_rule_hit_pdb_ids: list[str] = []
    fresh_rejected_pdb_ids: list[str] = []
    fresh_topology_ambiguous_pdb_ids: list[str] = []
    fresh_missing_hit_pdb_ids: list[str] = []
    repeat_pdb_ids: list[str] = []
    repeat_rule_hit_pdb_ids: list[str] = []

    for scout_row in epk_mek_erk_targeted_candidate_scout.get("rows", []) or []:
        if not isinstance(scout_row, dict):
            continue
        pdb_id = str(scout_row.get("pdb_id") or "").upper()
        if not pdb_id or not _candidate_hits(scout_row):
            continue
        validation_row = validation_by_pdb.get(pdb_id, {})
        source_validation_status = str(
            validation_row.get("source_validation_status")
            or scout_row.get("source_validation_status")
            or ""
        )
        hit = _primary_hydroxyl_hit(scout_row)
        residue_code = str(hit.get("candidate_residue_code") or "").upper()
        auth_seq_id = _optional_int(hit.get("candidate_auth_seq_id"))
        candidate_chain = str(hit.get("candidate_chain_name") or "")
        gamma_chain = str(hit.get("gamma_associated_polymer_chain_name") or "")
        tyrosine_mode_hit = residue_code == "TYR"
        n_terminal_mode_hit = (
            residue_code in hydroxyl_residue_codes
            and auth_seq_id is not None
            and auth_seq_id <= n_terminal_max
        )
        substrate_mode_rule_hit = bool(tyrosine_mode_hit or n_terminal_mode_hit)
        topology_ambiguous = bool(candidate_chain and candidate_chain == gamma_chain)
        repeat_from_current_surface = pdb_id in current_surface_pdb_ids
        if repeat_from_current_surface:
            repeat_pdb_ids.append(pdb_id)
            if substrate_mode_rule_hit:
                repeat_rule_hit_pdb_ids.append(pdb_id)
            decision = (
                "repeat_current_surface_retained_by_substrate_mode_review_only"
                if substrate_mode_rule_hit
                else "repeat_current_surface_not_retained_review_only"
            )
        else:
            fresh_pdb_ids.append(pdb_id)
            if not hit:
                fresh_missing_hit_pdb_ids.append(pdb_id)
                decision = "fresh_nonrepeat_missing_primary_hydroxyl_hit_review_only"
            elif substrate_mode_rule_hit:
                fresh_rule_hit_pdb_ids.append(pdb_id)
                decision = "fresh_nonrepeat_rule_hit_unresolved_review_only"
            else:
                fresh_rejected_pdb_ids.append(pdb_id)
                if topology_ambiguous:
                    fresh_topology_ambiguous_pdb_ids.append(pdb_id)
                    decision = (
                        "fresh_nonrepeat_blocked_by_topology_and_substrate_mode_review_only"
                    )
                else:
                    decision = "fresh_nonrepeat_blocked_by_substrate_mode_review_only"
        decision_counts[decision] += 1
        counterevidence_reasons: list[str] = []
        if not hit:
            counterevidence_reasons.append("primary_hydroxyl_hit_missing")
        if residue_code and residue_code != "TYR" and not n_terminal_mode_hit:
            counterevidence_reasons.append(
                "acceptor_residue_not_tyrosine_or_n_terminal_ser_thr_tyr"
            )
        if auth_seq_id is None:
            counterevidence_reasons.append("acceptor_auth_seq_id_missing")
        elif auth_seq_id > n_terminal_max and residue_code != "TYR":
            counterevidence_reasons.append(
                "acceptor_auth_seq_id_outside_n_terminal_substrate_mode"
            )
        if topology_ambiguous:
            counterevidence_reasons.append("same_auth_chain_topology_ambiguity")
        rows.append(
            {
                "row_type": "mek_erk_substrate_mode_fresh_stress_row",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "fresh_nonrepeat_candidate": not repeat_from_current_surface,
                "repeat_from_current_stress_surface": repeat_from_current_surface,
                "text_free_inputs_only": True,
                "source_context_used_for_failure_label_only": True,
                "candidate_threshold_angstrom": threshold,
                "max_n_terminal_acceptor_auth_seq_id": n_terminal_max,
                "source_validation_status": source_validation_status or None,
                "source_pair_id": validation_row.get("source_pair_id"),
                "primary_candidate_acceptor_residue_code": residue_code or None,
                "primary_candidate_acceptor_auth_seq_id": (
                    hit.get("candidate_auth_seq_id")
                ),
                "primary_candidate_acceptor_chain_name": (
                    hit.get("candidate_chain_name")
                ),
                "primary_gamma_associated_polymer_chain_name": (
                    hit.get("gamma_associated_polymer_chain_name")
                ),
                "nearest_gamma_distance_angstrom": (
                    hit.get("nearest_gamma_distance_angstrom")
                ),
                "tyrosine_acceptor_mode_hit": tyrosine_mode_hit,
                "n_terminal_ser_thr_tyr_acceptor_mode_hit": n_terminal_mode_hit,
                "substrate_mode_counteraxis_rule_hit": substrate_mode_rule_hit,
                "same_auth_chain_topology_ambiguity": topology_ambiguous,
                "fresh_stress_decision": decision,
                "substrate_mode_counterevidence_reasons": _sorted_strings(
                    counterevidence_reasons
                ),
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_orphan_discovery_claims": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "fresh_controls_all_topology_confounded",
                    "substrate_mode_rule_not_calibrated",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    fresh_pdb_ids = _sorted_strings(fresh_pdb_ids)
    fresh_rule_hit_pdb_ids = _sorted_strings(fresh_rule_hit_pdb_ids)
    fresh_rejected_pdb_ids = _sorted_strings(fresh_rejected_pdb_ids)
    fresh_topology_ambiguous_pdb_ids = _sorted_strings(
        fresh_topology_ambiguous_pdb_ids
    )
    fresh_missing_hit_pdb_ids = _sorted_strings(fresh_missing_hit_pdb_ids)
    repeat_pdb_ids = _sorted_strings(repeat_pdb_ids)
    repeat_rule_hit_pdb_ids = _sorted_strings(repeat_rule_hit_pdb_ids)
    if fresh_rule_hit_pdb_ids or fresh_missing_hit_pdb_ids:
        status = "fails_closed_fresh_substrate_mode_stress_residual_hits"
    elif fresh_pdb_ids and fresh_topology_ambiguous_pdb_ids == fresh_pdb_ids:
        status = "passes_fresh_nonrepeat_controls_with_topology_confounding_review_only"
    elif fresh_pdb_ids:
        status = "passes_fresh_nonrepeat_controls_review_only"
    else:
        status = "blocked_no_fresh_nonrepeat_candidates_review_only"

    return {
        "metadata": {
            "method": "epk_mek_erk_substrate_mode_fresh_stress_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_substrate_mode_counteraxis_audit_method": (
                substrate_meta.get("method")
            ),
            "source_epk_mek_erk_targeted_candidate_scout_method": (
                scout_meta.get("method")
            ),
            "source_epk_mek_erk_targeted_source_validation_review_method": (
                validation_meta.get("method")
            ),
            "rule_id": "epk_mek_erk_tyr_or_n_terminal_substrate_mode_counteraxis_v0",
            "candidate_threshold_angstrom": threshold,
            "max_n_terminal_acceptor_auth_seq_id": n_terminal_max,
            "substrate_mode_fresh_stress_status": status,
            "reviewed_candidate_count": len(rows),
            "fresh_nonrepeat_candidate_count": len(fresh_pdb_ids),
            "fresh_nonrepeat_candidate_pdb_ids": fresh_pdb_ids,
            "fresh_nonrepeat_rule_hit_count": len(fresh_rule_hit_pdb_ids),
            "fresh_nonrepeat_rule_hit_pdb_ids": fresh_rule_hit_pdb_ids,
            "fresh_nonrepeat_rejected_by_substrate_mode_count": len(
                fresh_rejected_pdb_ids
            ),
            "fresh_nonrepeat_rejected_by_substrate_mode_pdb_ids": (
                fresh_rejected_pdb_ids
            ),
            "fresh_nonrepeat_topology_ambiguous_count": len(
                fresh_topology_ambiguous_pdb_ids
            ),
            "fresh_nonrepeat_topology_ambiguous_pdb_ids": (
                fresh_topology_ambiguous_pdb_ids
            ),
            "fresh_nonrepeat_missing_primary_hydroxyl_count": len(
                fresh_missing_hit_pdb_ids
            ),
            "fresh_nonrepeat_missing_primary_hydroxyl_pdb_ids": (
                fresh_missing_hit_pdb_ids
            ),
            "repeat_current_surface_candidate_count": len(repeat_pdb_ids),
            "repeat_current_surface_candidate_pdb_ids": repeat_pdb_ids,
            "repeat_current_surface_rule_hit_count": len(repeat_rule_hit_pdb_ids),
            "repeat_current_surface_rule_hit_pdb_ids": repeat_rule_hit_pdb_ids,
            "source_free_predictive_feature_materialized": True,
            "substrate_mode_axis_weak_current_stress_only": True,
            "fresh_stress_topology_confounded": bool(
                fresh_pdb_ids and fresh_topology_ambiguous_pdb_ids == fresh_pdb_ids
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": (
                "fresh_nonrepeat_mek_erk_tranche_has_no_substrate_mode_rule_hits"
            ),
            "blocker_not_removed": [
                "fresh_nonrepeat_controls_all_topology_confounded",
                "no_new_clean_source_valid_positive_coverage",
                "substrate_mode_rule_not_calibrated",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "decision_counts": dict(sorted(decision_counts.items())),
            "review_only_rule": (
                "This artifact applies the MEK/ERK substrate-mode heuristic to "
                "a targeted outside-query tranche. Source review labels fresh "
                "controls only; the rule remains review-only, topology-confounded, "
                "and not admissible for scoring or registry edits."
            ),
            "next_actions": [
                "find a fresh non-topology-confounded MEK/ERK or kinase-substrate tranche",
                "replace residue-position substrate mode with stronger source-free substrate identity evidence",
                "keep ePK thresholding and external hard-negative scoring closed",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("fresh_stress_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Fresh MEK/ERK substrate-mode stress is review-only and "
                "topology-confounded; it cannot support threshold selection, "
                "production scoring, registry edits, or label import."
            )
        ],
    }


def build_epk_mek_erk_substrate_mode_existing_scout_gap_audit(
    *,
    epk_mek_erk_substrate_mode_counteraxis_audit: dict[str, Any],
    epk_mek_erk_substrate_mode_fresh_stress_audit: dict[str, Any],
    candidate_context_artifacts: list[dict[str, Any]],
    candidate_threshold_angstrom: float = 6.0,
    max_n_terminal_acceptor_auth_seq_id: int = 25,
) -> dict[str, Any]:
    """Audit existing candidate scouts for non-topology-confounded next rows."""

    substrate_meta = epk_mek_erk_substrate_mode_counteraxis_audit.get(
        "metadata", {}
    )
    if not isinstance(substrate_meta, dict):
        substrate_meta = {}
    fresh_meta = epk_mek_erk_substrate_mode_fresh_stress_audit.get("metadata", {})
    if not isinstance(fresh_meta, dict):
        fresh_meta = {}
    target_fingerprint_id = str(
        substrate_meta.get("target_fingerprint_id")
        or fresh_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(
            substrate_meta.get("candidate_threshold_angstrom")
            or fresh_meta.get("candidate_threshold_angstrom")
            or candidate_threshold_angstrom
        )
    except (TypeError, ValueError):
        threshold = 6.0
    try:
        n_terminal_max = int(
            substrate_meta.get("max_n_terminal_acceptor_auth_seq_id")
            or fresh_meta.get("max_n_terminal_acceptor_auth_seq_id")
            or max_n_terminal_acceptor_auth_seq_id
        )
    except (TypeError, ValueError):
        n_terminal_max = 25
    n_terminal_max = max(1, n_terminal_max)

    reviewed_pdb_ids = {
        str(row.get("pdb_id") or "").upper()
        for artifact in (
            epk_mek_erk_substrate_mode_counteraxis_audit,
            epk_mek_erk_substrate_mode_fresh_stress_audit,
        )
        for row in artifact.get("rows", []) or []
        if isinstance(row, dict) and row.get("pdb_id")
    }
    hydroxyl_residue_codes = {"SER", "THR", "TYR"}

    def _safe_float(value: Any) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return 9999.0

    def _optional_int(value: Any) -> int | None:
        try:
            if value in {None, "", ".", "?"}:
                return None
            return int(float(str(value)))
        except (TypeError, ValueError):
            return None

    def _candidate_hits(row: dict[str, Any]) -> list[dict[str, Any]]:
        hits = row.get("heteromeric_candidate_hits")
        if not isinstance(hits, list):
            hits = row.get("candidate_hits")
        return [hit for hit in hits or [] if isinstance(hit, dict)]

    def _primary_hydroxyl_hit(row: dict[str, Any]) -> dict[str, Any]:
        hits = [
            hit
            for hit in _candidate_hits(row)
            if str(hit.get("candidate_residue_code") or "").upper()
            in hydroxyl_residue_codes
            and _safe_float(hit.get("nearest_gamma_distance_angstrom")) <= threshold
        ]
        return (
            sorted(
                hits,
                key=lambda hit: (
                    _safe_float(hit.get("nearest_gamma_distance_angstrom")),
                    str(hit.get("candidate_chain_name") or ""),
                    str(hit.get("candidate_auth_seq_id") or ""),
                    str(hit.get("candidate_residue_code") or ""),
                ),
            )[0]
            if hits
            else {}
        )

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    materialized_unreviewed_pdb_ids: set[str] = set()
    topology_confounded_pdb_ids: set[str] = set()
    non_topology_confounded_pdb_ids: set[str] = set()
    non_topology_rule_hit_pdb_ids: set[str] = set()
    missing_primary_hit_pdb_ids: set[str] = set()

    for artifact_index, artifact in enumerate(candidate_context_artifacts):
        if not isinstance(artifact, dict):
            continue
        artifact_meta = artifact.get("metadata", {})
        if not isinstance(artifact_meta, dict):
            artifact_meta = {}
        for candidate_row in artifact.get("rows", []) or []:
            if not isinstance(candidate_row, dict):
                continue
            pdb_id = str(candidate_row.get("pdb_id") or "").upper()
            if not pdb_id or pdb_id in reviewed_pdb_ids:
                continue
            if not _candidate_hits(candidate_row):
                continue
            materialized_unreviewed_pdb_ids.add(pdb_id)
            hit = _primary_hydroxyl_hit(candidate_row)
            residue_code = str(hit.get("candidate_residue_code") or "").upper()
            auth_seq_id = _optional_int(hit.get("candidate_auth_seq_id"))
            candidate_chain = str(hit.get("candidate_chain_name") or "")
            gamma_chain = str(hit.get("gamma_associated_polymer_chain_name") or "")
            tyrosine_mode_hit = residue_code == "TYR"
            n_terminal_mode_hit = (
                residue_code in hydroxyl_residue_codes
                and auth_seq_id is not None
                and auth_seq_id <= n_terminal_max
            )
            substrate_mode_rule_hit = bool(tyrosine_mode_hit or n_terminal_mode_hit)
            topology_confounded = bool(candidate_chain and candidate_chain == gamma_chain)
            if not hit:
                missing_primary_hit_pdb_ids.add(pdb_id)
                decision = "existing_scout_missing_primary_hydroxyl_hit_review_only"
            elif topology_confounded:
                topology_confounded_pdb_ids.add(pdb_id)
                decision = "existing_scout_topology_confounded_review_only"
            else:
                non_topology_confounded_pdb_ids.add(pdb_id)
                if substrate_mode_rule_hit:
                    non_topology_rule_hit_pdb_ids.add(pdb_id)
                    decision = (
                        "existing_scout_non_topology_confounded_rule_hit_review_only"
                    )
                else:
                    decision = (
                        "existing_scout_non_topology_confounded_rule_rejected_review_only"
                    )
            decision_counts[decision] += 1
            rows.append(
                {
                    "row_type": "mek_erk_substrate_mode_existing_scout_gap_row",
                    "pdb_id": pdb_id,
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "candidate_threshold_angstrom": threshold,
                    "max_n_terminal_acceptor_auth_seq_id": n_terminal_max,
                    "source_artifact_index": artifact_index,
                    "source_artifact_method": artifact_meta.get("method"),
                    "source_query": artifact_meta.get("source_query"),
                    "primary_candidate_acceptor_residue_code": residue_code or None,
                    "primary_candidate_acceptor_auth_seq_id": (
                        hit.get("candidate_auth_seq_id")
                    ),
                    "primary_candidate_acceptor_chain_name": (
                        hit.get("candidate_chain_name")
                    ),
                    "primary_gamma_associated_polymer_chain_name": (
                        hit.get("gamma_associated_polymer_chain_name")
                    ),
                    "nearest_gamma_distance_angstrom": (
                        hit.get("nearest_gamma_distance_angstrom")
                    ),
                    "same_auth_chain_topology_ambiguity": topology_confounded,
                    "tyrosine_acceptor_mode_hit": tyrosine_mode_hit,
                    "n_terminal_ser_thr_tyr_acceptor_mode_hit": n_terminal_mode_hit,
                    "substrate_mode_counteraxis_rule_hit": substrate_mode_rule_hit,
                    "existing_scout_gap_decision": decision,
                    "production_scoring_admissible": False,
                    "ready_for_production_scoring": False,
                    "ready_for_orphan_discovery_claims": False,
                    "ready_for_label_import": False,
                    "countable_label_candidate": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                }
            )

    materialized_unreviewed_ids = _sorted_strings(materialized_unreviewed_pdb_ids)
    topology_confounded_ids = _sorted_strings(topology_confounded_pdb_ids)
    non_topology_confounded_ids = _sorted_strings(non_topology_confounded_pdb_ids)
    non_topology_rule_hit_ids = _sorted_strings(non_topology_rule_hit_pdb_ids)
    missing_primary_hit_ids = _sorted_strings(missing_primary_hit_pdb_ids)
    if non_topology_confounded_ids:
        status = "existing_scouts_have_non_topology_confounded_candidates_review_only"
    elif materialized_unreviewed_ids:
        status = "blocked_existing_scouts_only_topology_confounded_candidates_review_only"
    else:
        status = "blocked_no_existing_scout_candidates_after_exclusions_review_only"

    return {
        "metadata": {
            "method": "epk_mek_erk_substrate_mode_existing_scout_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_substrate_mode_counteraxis_audit_method": (
                substrate_meta.get("method")
            ),
            "source_epk_mek_erk_substrate_mode_fresh_stress_audit_method": (
                fresh_meta.get("method")
            ),
            "candidate_context_artifact_count": len(candidate_context_artifacts),
            "candidate_threshold_angstrom": threshold,
            "max_n_terminal_acceptor_auth_seq_id": n_terminal_max,
            "existing_scout_gap_status": status,
            "reviewed_exclusion_pdb_count": len(reviewed_pdb_ids),
            "materialized_unreviewed_hit_count": len(materialized_unreviewed_ids),
            "materialized_unreviewed_hit_pdb_ids": materialized_unreviewed_ids,
            "topology_confounded_candidate_count": len(topology_confounded_ids),
            "topology_confounded_candidate_pdb_ids": topology_confounded_ids,
            "non_topology_confounded_candidate_count": len(
                non_topology_confounded_ids
            ),
            "non_topology_confounded_candidate_pdb_ids": (
                non_topology_confounded_ids
            ),
            "non_topology_confounded_rule_hit_count": len(
                non_topology_rule_hit_ids
            ),
            "non_topology_confounded_rule_hit_pdb_ids": non_topology_rule_hit_ids,
            "missing_primary_hydroxyl_hit_count": len(missing_primary_hit_ids),
            "missing_primary_hydroxyl_hit_pdb_ids": missing_primary_hit_ids,
            "decision_counts": dict(sorted(decision_counts.items())),
            "source_free_predictive_feature_materialized": True,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "existing_materialized_scouts_audited_for_next_tranche_reuse",
            "blocker_not_removed": [
                "no_existing_non_topology_confounded_substrate_mode_tranche",
                "substrate_mode_rule_not_calibrated",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact audits already materialized ePK candidate scouts "
                "for reusable non-topology-confounded substrate-mode stress rows. "
                "It records a negative queue result only; it does not query new "
                "sources, score ePK, edit registries, or import labels."
            ),
            "next_actions": [
                "source a new bounded tranche because existing scouts do not provide a clean non-topology-confounded substrate-mode stress row",
                "prefer kinase-substrate rows with different auth chains and explicit local acceptor context",
                "keep thresholding and external hard-negative scoring closed",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("existing_scout_gap_decision") or ""),
                str(row.get("pdb_id") or ""),
                str(row.get("source_artifact_index") or ""),
            ),
        ),
        "warnings": [
            (
                "Existing scout gap audit is review-only negative queue evidence; "
                "it cannot support threshold selection, production scoring, "
                "registry edits, or label import."
            )
        ],
    }


def build_epk_substrate_mode_next_tranche_source_review(
    *,
    epk_mek_erk_substrate_mode_counteraxis_audit: dict[str, Any],
    epk_next_tranche_candidate_scout: dict[str, Any],
    epk_next_tranche_source_validation_review: dict[str, Any] | None = None,
    uniprot_records_by_accession: dict[str, Any] | None = None,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
    uniprot_fetcher=None,
    candidate_threshold_angstrom: float = 6.0,
    max_n_terminal_acceptor_auth_seq_id: int = 25,
) -> dict[str, Any]:
    """Source-map a fresh non-topology-confounded substrate-mode tranche."""

    substrate_meta = epk_mek_erk_substrate_mode_counteraxis_audit.get(
        "metadata", {}
    )
    if not isinstance(substrate_meta, dict):
        substrate_meta = {}
    scout_meta = epk_next_tranche_candidate_scout.get("metadata", {})
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    validation_meta: dict[str, Any] = {}
    if isinstance(epk_next_tranche_source_validation_review, dict):
        validation_meta = epk_next_tranche_source_validation_review.get(
            "metadata", {}
        )
        if not isinstance(validation_meta, dict):
            validation_meta = {}

    target_fingerprint_id = str(
        substrate_meta.get("target_fingerprint_id")
        or scout_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(
            substrate_meta.get("candidate_threshold_angstrom")
            or candidate_threshold_angstrom
        )
    except (TypeError, ValueError):
        threshold = 6.0
    try:
        n_terminal_max = int(
            substrate_meta.get("max_n_terminal_acceptor_auth_seq_id")
            or max_n_terminal_acceptor_auth_seq_id
        )
    except (TypeError, ValueError):
        n_terminal_max = 25
    n_terminal_max = max(1, n_terminal_max)

    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    provided_uniprot_records = {
        str(key).upper(): value
        for key, value in (uniprot_records_by_accession or {}).items()
    }
    fetched_uniprot_accessions: list[str] = []
    uniprot_fetch_failures: dict[str, str] = {}
    uniprot_cache: dict[str, dict[str, Any]] = {}
    hydroxyl_residue_codes = {"SER", "THR", "TYR"}

    def _safe_float(value: Any) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return 9999.0

    def _optional_int(value: Any) -> int | None:
        try:
            if value in {None, "", ".", "?"}:
                return None
            return int(float(str(value)))
        except (TypeError, ValueError):
            return None

    def _load_uniprot_record(accession: str) -> dict[str, Any]:
        accession_upper = accession.upper()
        if not accession_upper:
            return {}
        if accession_upper in uniprot_cache:
            return uniprot_cache[accession_upper]
        record = _unwrap_uniprot_entry_record(
            provided_uniprot_records.get(accession_upper)
        )
        fetch = uniprot_fetcher
        if not record and fetch is None:
            try:
                from .adapters import fetch_uniprot_entry

                fetch = fetch_uniprot_entry
            except Exception:  # pragma: no cover - import failure is not expected.
                fetch = None
        if not record and fetch is not None:
            try:
                record = _unwrap_uniprot_entry_record(fetch(accession_upper))
                fetched_uniprot_accessions.append(accession_upper)
            except Exception as exc:  # pragma: no cover - network failure is data.
                record = {}
                uniprot_fetch_failures[accession_upper] = str(exc)
        uniprot_cache[accession_upper] = record
        return record

    def _chain_accessions_from_cif(cif_text: str) -> dict[str, list[str]]:
        chain_accessions: dict[str, list[str]] = defaultdict(list)
        for row in _epk_struct_ref_seq_rows(cif_text):
            accession = str(row.get("pdbx_db_accession") or "").upper()
            if not accession:
                continue
            for chain_id in _sorted_strings(
                str(row.get("pdbx_strand_id") or "").split(",")
            ):
                if accession not in chain_accessions[chain_id]:
                    chain_accessions[chain_id].append(accession)
        return {
            chain_id: sorted(accessions)
            for chain_id, accessions in sorted(chain_accessions.items())
        }

    def _merge_chain_accessions(
        row_accessions: Any, cif_accessions: dict[str, list[str]]
    ) -> dict[str, list[str]]:
        merged: dict[str, list[str]] = defaultdict(list)
        if isinstance(row_accessions, dict):
            for chain_id, accessions in row_accessions.items():
                for accession in _sorted_strings(accessions):
                    accession_upper = accession.upper()
                    if accession_upper not in merged[str(chain_id)]:
                        merged[str(chain_id)].append(accession_upper)
        for chain_id, accessions in cif_accessions.items():
            for accession in accessions:
                accession_upper = accession.upper()
                if accession_upper not in merged[str(chain_id)]:
                    merged[str(chain_id)].append(accession_upper)
        return {
            chain_id: sorted(accessions)
            for chain_id, accessions in sorted(merged.items())
        }

    def _chain_primary_accession(
        chain_accessions: dict[str, list[str]], chain_id: str
    ) -> str | None:
        accessions = chain_accessions.get(chain_id) or []
        return accessions[0] if len(accessions) == 1 else None

    def _auth_residue_to_uniprot_position(
        *, cif_text: str, accession: str, chain_id: str, auth_resid: str
    ) -> int | None:
        accession_upper = accession.upper()
        for row in _epk_struct_ref_seq_rows(cif_text):
            if str(row.get("pdbx_db_accession") or "").upper() != accession_upper:
                continue
            if chain_id not in _sorted_strings(
                str(row.get("pdbx_strand_id") or "").split(",")
            ):
                continue
            try:
                auth_begin = int(str(row.get("pdbx_auth_seq_align_beg")))
                auth_end = int(str(row.get("pdbx_auth_seq_align_end")))
                db_begin = int(str(row.get("db_align_beg")))
                auth_value = int(str(auth_resid))
            except (TypeError, ValueError):
                continue
            if auth_begin <= auth_value <= auth_end:
                return db_begin + (auth_value - auth_begin)
        return None

    def _phosphosite_match(
        *, record: dict[str, Any], position: int | None, residue_code: str
    ) -> dict[str, Any] | None:
        if position is None:
            return None
        residue_code_upper = residue_code.upper()
        for feature in _epk_uniprot_phosphoacceptor_features(record):
            try:
                feature_position = int(str(feature.get("position")))
            except (TypeError, ValueError):
                continue
            if feature_position != position:
                continue
            description = str(feature.get("description") or "")
            lowered = description.lower()
            residue_matches = (
                ("phosphotyrosine" in lowered and residue_code_upper in {"TYR", "PTR"})
                or (
                    "phosphothreonine" in lowered
                    and residue_code_upper in {"THR", "TPO"}
                )
                or (
                    "phosphoserine" in lowered
                    and residue_code_upper in {"SER", "SEP"}
                )
            )
            if residue_matches:
                return feature
        return None

    def _kinase_reaction_supports_protein_phosphorylation(
        record: dict[str, Any]
    ) -> bool:
        for comment in record.get("catalytic_activity_comments", []) or []:
            if not isinstance(comment, dict):
                continue
            reaction = str(comment.get("reaction") or "").lower()
            if "[protein]" in reaction and "atp" in reaction and "phospho" in reaction:
                return True
        return False

    def _best_candidate_hit(row: dict[str, Any]) -> dict[str, Any]:
        hits = [
            hit
            for hit in row.get("heteromeric_candidate_hits", []) or []
            if isinstance(hit, dict)
            and str(hit.get("candidate_residue_code") or "").upper()
            in hydroxyl_residue_codes
            and _safe_float(hit.get("nearest_gamma_distance_angstrom")) <= threshold
        ]
        if not hits:
            hits = [
                hit
                for hit in row.get("candidate_hits", []) or []
                if isinstance(hit, dict)
                and str(hit.get("candidate_residue_code") or "").upper()
                in hydroxyl_residue_codes
                and _safe_float(hit.get("nearest_gamma_distance_angstrom")) <= threshold
            ]
        return (
            sorted(
                hits,
                key=lambda hit: (
                    _safe_float(hit.get("nearest_gamma_distance_angstrom")),
                    str(hit.get("candidate_chain_name") or ""),
                    str(hit.get("candidate_auth_seq_id") or ""),
                    str(hit.get("candidate_residue_code") or ""),
                ),
            )[0]
            if hits
            else {}
        )

    validation_rows_by_pdb: dict[str, dict[str, Any]] = {}
    if isinstance(epk_next_tranche_source_validation_review, dict):
        for row in epk_next_tranche_source_validation_review.get("rows", []) or []:
            if isinstance(row, dict) and row.get("pdb_id"):
                validation_rows_by_pdb[str(row.get("pdb_id")).upper()] = row

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    fetched_pdb_ids: list[str] = []
    cif_fetch_failures: dict[str, str] = {}
    non_topology_pdb_ids: list[str] = []
    source_mapped_ready_pdb_ids: list[str] = []
    unresolved_pdb_ids: list[str] = []
    substrate_rejected_pdb_ids: list[str] = []
    topology_confounded_pdb_ids: list[str] = []
    substrate_rule_hit_pdb_ids: list[str] = []
    distances: list[float] = []

    candidate_rows = [
        row
        for row in epk_next_tranche_candidate_scout.get("rows", []) or []
        if isinstance(row, dict)
        and row.get("candidate_status")
        == "heteromeric_candidate_source_validation_pending_review_only"
    ]
    for candidate_row in candidate_rows:
        pdb_id = str(candidate_row.get("pdb_id") or "").upper()
        validation_row = validation_rows_by_pdb.get(pdb_id, {})
        hit = _best_candidate_hit(candidate_row)
        row_base = {
            "row_type": "epk_substrate_mode_next_tranche_source_review_row",
            "pdb_id": pdb_id,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "review_only": True,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "source_validation_status_input": validation_row.get(
                "source_validation_status"
            ),
            "candidate_hit": hit,
        }
        try:
            cif_text = cif_texts.get(pdb_id)
            fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id)
                fetched_pdb_ids.append(pdb_id)
        except Exception as exc:  # pragma: no cover - network failure is data.
            status = "structure_fetch_failed_review_only"
            status_counts[status] += 1
            cif_fetch_failures[pdb_id] = str(exc)
            rows.append(
                {
                    **row_base,
                    "fetch_status": "fetch_failed",
                    "fetch_error": str(exc),
                    "next_tranche_source_review_status": status,
                    "measurement_ready_for_review_controls": False,
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue

        struct_rows = _epk_mmcif_rows(cif_text, "_struct.")
        title = _first_present_value(struct_rows, "title") or validation_row.get(
            "structure_title"
        )
        chain_accessions = _merge_chain_accessions(
            validation_row.get("chain_accessions"),
            _chain_accessions_from_cif(cif_text),
        )
        candidate_chain = str(hit.get("candidate_chain_name") or "")
        gamma_chain = str(hit.get("gamma_associated_polymer_chain_name") or "")
        candidate_auth_resid = str(hit.get("candidate_auth_seq_id") or "")
        candidate_code = str(hit.get("candidate_residue_code") or "").upper()
        candidate_auth_seq_id_int = _optional_int(candidate_auth_resid)
        tyrosine_mode_hit = candidate_code == "TYR"
        n_terminal_mode_hit = (
            candidate_code in hydroxyl_residue_codes
            and candidate_auth_seq_id_int is not None
            and candidate_auth_seq_id_int <= n_terminal_max
        )
        substrate_mode_rule_hit = bool(tyrosine_mode_hit or n_terminal_mode_hit)
        same_chain = bool(candidate_chain and candidate_chain == gamma_chain)
        acceptor_accession = _chain_primary_accession(
            chain_accessions, candidate_chain
        )
        kinase_accession = _chain_primary_accession(chain_accessions, gamma_chain)
        candidate_position = (
            _auth_residue_to_uniprot_position(
                cif_text=cif_text,
                accession=acceptor_accession,
                chain_id=candidate_chain,
                auth_resid=candidate_auth_resid,
            )
            if acceptor_accession
            else None
        )
        acceptor_record = _load_uniprot_record(acceptor_accession or "")
        kinase_record = _load_uniprot_record(kinase_accession or "")
        phosphosite_feature = _phosphosite_match(
            record=acceptor_record,
            position=candidate_position,
            residue_code=candidate_code,
        )
        kinase_reaction_supported = _kinase_reaction_supports_protein_phosphorylation(
            kinase_record
        )
        phosphosite_description = str(
            phosphosite_feature.get("description") if phosphosite_feature else ""
        )
        pkb_gsk3b_source_context_matched = (
            validation_row.get("source_pair_id") == "pkb_gsk3"
            and acceptor_accession == "P49841"
            and candidate_position == 9
            and phosphosite_feature is not None
            and any(token in phosphosite_description.lower() for token in ("akt", "pkb"))
        )
        akt_gsk3b_source_mapped = (
            kinase_accession == "P31749"
            and acceptor_accession == "P49841"
            and candidate_position == 9
            and phosphosite_feature is not None
            and any(token in phosphosite_description.lower() for token in ("akt", "pkb"))
            and kinase_reaction_supported
        )
        try:
            nearest_distance = float(hit.get("nearest_gamma_distance_angstrom"))
        except (TypeError, ValueError):
            nearest_distance = None

        if not hit:
            status = "missing_primary_hydroxyl_hit_review_only"
            blockers = [
                "primary_hydroxyl_hit_missing",
                "positive_coverage_not_expanded",
            ]
        elif same_chain:
            status = "topology_confounded_not_measurement_ready_review_only"
            topology_confounded_pdb_ids.append(pdb_id)
            blockers = [
                "candidate_acceptor_chain_matches_gamma_chain",
                "fresh_non_topology_confounded_tranche_not_supplied_by_this_row",
            ]
        elif not substrate_mode_rule_hit:
            status = "non_topology_confounded_rejected_by_substrate_mode_review_only"
            non_topology_pdb_ids.append(pdb_id)
            substrate_rejected_pdb_ids.append(pdb_id)
            blockers = [
                "substrate_mode_rule_not_hit",
                "positive_coverage_not_expanded",
            ]
        elif akt_gsk3b_source_mapped:
            status = (
                "source_mapped_non_topology_substrate_mode_measurement_ready_review_only"
            )
            non_topology_pdb_ids.append(pdb_id)
            source_mapped_ready_pdb_ids.append(pdb_id)
            substrate_rule_hit_pdb_ids.append(pdb_id)
            blockers = [
                "source_review_evidence_not_source_free_predictive_feature",
                "substrate_mode_rule_not_calibrated",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ]
            if nearest_distance is not None:
                distances.append(nearest_distance)
        else:
            status = "non_topology_confounded_source_mapping_unresolved_review_only"
            non_topology_pdb_ids.append(pdb_id)
            if substrate_mode_rule_hit:
                substrate_rule_hit_pdb_ids.append(pdb_id)
            unresolved_pdb_ids.append(pdb_id)
            blockers = [
                (
                    "pkb_gsk3b_source_context_detected_but_exact_akt1_or_chain_mapping_unresolved"
                    if pkb_gsk3b_source_context_matched
                    else "source_phosphosite_or_role_direction_not_mapped_to_candidate"
                ),
                "substrate_mode_rule_not_calibrated",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        status_counts[status] += 1
        rows.append(
            {
                **row_base,
                "fetch_status": fetch_status,
                "structure_title": title,
                "chain_accessions": chain_accessions,
                "candidate_chain_name": candidate_chain,
                "gamma_associated_polymer_chain_name": gamma_chain,
                "candidate_same_chain_as_gamma": same_chain,
                "candidate_auth_seq_id": candidate_auth_resid,
                "candidate_residue_code": candidate_code or None,
                "candidate_uniprot_accession": acceptor_accession,
                "candidate_uniprot_position": candidate_position,
                "kinase_uniprot_accession": kinase_accession,
                "kinase_protein_phosphorylation_reaction_supported": (
                    kinase_reaction_supported
                ),
                "source_phosphosite_feature": phosphosite_feature,
                "source_phosphosite_matched_candidate": phosphosite_feature
                is not None,
                "pkb_gsk3b_source_context_matched": pkb_gsk3b_source_context_matched,
                "pkb_gsk3b_exact_mapping_blocked": (
                    pkb_gsk3b_source_context_matched
                    and not akt_gsk3b_source_mapped
                ),
                "akt1_gsk3b_source_mapped": akt_gsk3b_source_mapped,
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    round(nearest_distance, 3)
                    if nearest_distance is not None
                    else None
                ),
                "gamma_acceptor_distance_measured": nearest_distance is not None,
                "tyrosine_acceptor_mode_hit": tyrosine_mode_hit,
                "n_terminal_ser_thr_tyr_acceptor_mode_hit": n_terminal_mode_hit,
                "substrate_mode_counteraxis_rule_hit": substrate_mode_rule_hit,
                "measurement_ready_for_review_controls": (
                    status
                    == "source_mapped_non_topology_substrate_mode_measurement_ready_review_only"
                ),
                "next_tranche_source_review_status": status,
                "remaining_blockers": blockers,
                "production_scoring_admissible": False,
            }
        )

    non_topology_ids = _sorted_strings(non_topology_pdb_ids)
    source_ready_ids = _sorted_strings(source_mapped_ready_pdb_ids)
    unresolved_ids = _sorted_strings(unresolved_pdb_ids)
    substrate_rejected_ids = _sorted_strings(substrate_rejected_pdb_ids)
    topology_confounded_ids = _sorted_strings(topology_confounded_pdb_ids)
    substrate_rule_hit_ids = _sorted_strings(substrate_rule_hit_pdb_ids)
    if source_ready_ids:
        review_status = (
            "adds_source_mapped_non_topology_substrate_mode_row_review_only"
        )
        blocker_removed = "fresh_non_topology_confounded_tranche_materialized_and_source_mapped"
    elif unresolved_ids:
        review_status = "fails_closed_non_topology_tranche_source_mapping_unresolved"
        blocker_removed = "fresh_non_topology_confounded_tranche_materialized"
    elif substrate_rejected_ids:
        review_status = "fails_closed_non_topology_tranche_rejected_by_substrate_mode"
        blocker_removed = "fresh_non_topology_confounded_tranche_materialized"
    elif topology_confounded_ids:
        review_status = "blocked_next_tranche_only_topology_confounded_review_only"
        blocker_removed = "next_tranche_reviewed_but_no_clean_non_topology_row"
    else:
        review_status = "blocked_no_next_tranche_candidate_hits_review_only"
        blocker_removed = "next_tranche_reviewed"

    return {
        "metadata": {
            "method": "epk_substrate_mode_next_tranche_source_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_mek_erk_substrate_mode_counteraxis_audit_method": (
                substrate_meta.get("method")
            ),
            "source_epk_next_tranche_candidate_scout_method": scout_meta.get(
                "method"
            ),
            "source_epk_next_tranche_source_validation_review_method": (
                validation_meta.get("method")
            ),
            "source_query": scout_meta.get("source_query"),
            "candidate_threshold_angstrom": threshold,
            "max_n_terminal_acceptor_auth_seq_id": n_terminal_max,
            "next_tranche_source_review_status": review_status,
            "reviewed_candidate_count": len(rows),
            "non_topology_confounded_candidate_count": len(non_topology_ids),
            "non_topology_confounded_candidate_pdb_ids": non_topology_ids,
            "substrate_mode_rule_hit_non_topology_count": len(
                substrate_rule_hit_ids
            ),
            "substrate_mode_rule_hit_non_topology_pdb_ids": substrate_rule_hit_ids,
            "source_mapped_measurement_ready_count": len(source_ready_ids),
            "source_mapped_measurement_ready_pdb_ids": source_ready_ids,
            "source_mapping_unresolved_count": len(unresolved_ids),
            "source_mapping_unresolved_pdb_ids": unresolved_ids,
            "substrate_mode_rejected_count": len(substrate_rejected_ids),
            "substrate_mode_rejected_pdb_ids": substrate_rejected_ids,
            "topology_confounded_candidate_count": len(topology_confounded_ids),
            "topology_confounded_candidate_pdb_ids": topology_confounded_ids,
            "nearest_gamma_acceptor_distance_min_angstrom": (
                round(min(distances), 3) if distances else None
            ),
            "nearest_gamma_acceptor_distance_max_angstrom": (
                round(max(distances), 3) if distances else None
            ),
            "decision_counts": dict(sorted(status_counts.items())),
            "fetched_pdb_ids": _sorted_strings(fetched_pdb_ids),
            "cif_fetch_failure_count": len(cif_fetch_failures),
            "cif_fetch_failures": cif_fetch_failures,
            "fetched_uniprot_accessions": _sorted_strings(fetched_uniprot_accessions),
            "uniprot_fetch_failure_count": len(uniprot_fetch_failures),
            "uniprot_fetch_failures": dict(sorted(uniprot_fetch_failures.items())),
            "source_context_used_as_review_evidence_only": True,
            "source_free_predictive_feature_materialized": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": blocker_removed,
            "blocker_not_removed": [
                "source_review_evidence_not_source_free_predictive_feature",
                "substrate_mode_rule_not_calibrated",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact source-maps a fresh substrate-mode tranche. "
                "A row can become measurement-ready review evidence only when "
                "local non-topology gamma geometry maps to an explicit source "
                "phosphosite and kinase/substrate accession pair. It does not "
                "score ePK, select a threshold, edit registries, or import labels."
            ),
            "next_actions": [
                "stress the source-mapped substrate-mode row against fresh non-topology controls",
                "replace source-reviewed phosphosite support with a source-free substrate identity feature before scoring",
                "keep real external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("next_tranche_source_review_status") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Next-tranche substrate-mode source review is review-only; "
                "measurement-ready rows are not countable labels or clean "
                "held-out performance evidence."
            )
        ],
    }


def build_epk_substrate_mode_tranche_recovery_decision(
    *,
    epk_substrate_mode_next_tranche_source_reviews: list[dict[str, Any]],
) -> dict[str, Any]:
    """Aggregate recovered substrate-mode source-review tranches."""

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    source_review_status_counts: Counter[str] = Counter()
    reviewed_pdb_ids: set[str] = set()
    measurement_ready_pdb_ids: set[str] = set()
    source_mapping_unresolved_pdb_ids: set[str] = set()
    rejected_pdb_ids: set[str] = set()
    topology_confounded_pdb_ids: set[str] = set()
    source_queries: list[str] = []
    source_methods: list[str] = []
    distances: list[float] = []

    def _safe_float(value: Any) -> float | None:
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    for source_index, review in enumerate(
        epk_substrate_mode_next_tranche_source_reviews
    ):
        if not isinstance(review, dict):
            continue
        meta = review.get("metadata", {})
        if not isinstance(meta, dict):
            meta = {}
        source_method = str(meta.get("method") or "")
        if source_method:
            source_methods.append(source_method)
        source_query = str(meta.get("source_query") or "")
        if source_query:
            source_queries.append(source_query)
        source_status = str(meta.get("next_tranche_source_review_status") or "")
        if source_status:
            source_review_status_counts[source_status] += 1
        for source_row in review.get("rows", []) or []:
            if not isinstance(source_row, dict):
                continue
            pdb_id = str(source_row.get("pdb_id") or "").upper()
            if not pdb_id:
                continue
            status = str(source_row.get("next_tranche_source_review_status") or "")
            if not status:
                status = "missing_source_review_status"
            reviewed_pdb_ids.add(pdb_id)
            status_counts[status] += 1
            if bool(source_row.get("measurement_ready_for_review_controls")):
                measurement_ready_pdb_ids.add(pdb_id)
            if status == "non_topology_confounded_source_mapping_unresolved_review_only":
                source_mapping_unresolved_pdb_ids.add(pdb_id)
            if status == "non_topology_confounded_rejected_by_substrate_mode_review_only":
                rejected_pdb_ids.add(pdb_id)
            if status == "topology_confounded_not_measurement_ready_review_only":
                topology_confounded_pdb_ids.add(pdb_id)
            distance = _safe_float(
                source_row.get("nearest_gamma_to_candidate_acceptor_distance_angstrom")
            )
            if distance is not None:
                distances.append(distance)
            rows.append(
                {
                    "row_type": "epk_substrate_mode_tranche_recovery_decision_row",
                    "source_artifact_index": source_index,
                    "source_artifact_method": source_method or None,
                    "source_query": source_query or None,
                    "pdb_id": pdb_id,
                    "target_family_id": "epk",
                    "target_fingerprint_id": source_row.get(
                        "target_fingerprint_id"
                    )
                    or meta.get("target_fingerprint_id")
                    or "epk_atp_gamma_phosphoryl_transfer",
                    "review_only": True,
                    "source_review_status": status,
                    "measurement_ready_for_review_controls": bool(
                        source_row.get("measurement_ready_for_review_controls")
                    ),
                    "candidate_uniprot_accession": source_row.get(
                        "candidate_uniprot_accession"
                    ),
                    "candidate_uniprot_position": source_row.get(
                        "candidate_uniprot_position"
                    ),
                    "kinase_uniprot_accession": source_row.get(
                        "kinase_uniprot_accession"
                    ),
                    "source_phosphosite_matched_candidate": bool(
                        source_row.get("source_phosphosite_matched_candidate")
                    ),
                    "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                        round(distance, 3) if distance is not None else None
                    ),
                    "production_scoring_admissible": False,
                    "ready_for_production_scoring": False,
                    "ready_for_orphan_discovery_claims": False,
                    "ready_for_label_import": False,
                    "countable_label_candidate": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "remaining_blockers": _sorted_strings(
                        source_row.get("remaining_blockers", [])
                    ),
                }
            )

    ready_ids = _sorted_strings(measurement_ready_pdb_ids)
    unresolved_ids = _sorted_strings(source_mapping_unresolved_pdb_ids)
    rejected_ids = _sorted_strings(rejected_pdb_ids)
    topology_ids = _sorted_strings(topology_confounded_pdb_ids)
    reviewed_ids = _sorted_strings(reviewed_pdb_ids)
    if ready_ids and unresolved_ids:
        recovery_status = (
            "partial_recovery_with_measurement_ready_row_and_unresolved_mapping_review_only"
        )
        next_experiment = (
            "freeze 4EKK as review-only source-mapped stress and source a "
            "fresh nonconfounded folded-substrate tranche for source-free "
            "substrate identity"
        )
    elif ready_ids:
        recovery_status = "recovered_measurement_ready_row_review_only"
        next_experiment = (
            "stress the recovered measurement-ready row against fresh "
            "nonconfounded controls before any scorer calibration"
        )
    elif unresolved_ids:
        recovery_status = "fails_closed_source_mapping_unresolved_review_only"
        next_experiment = (
            "pivot to a fresh source tranche or alternate sourcing because "
            "current rows do not remove source-mapping blockers"
        )
    elif reviewed_ids:
        recovery_status = "recovered_terminal_nonpositive_or_blocked_rows_review_only"
        next_experiment = (
            "source a new bounded tranche with non-topology-confounded "
            "kinase-substrate rows"
        )
    else:
        recovery_status = "blocked_no_recovered_source_review_rows"
        next_experiment = "rerun source-review generation from the preserved scouts"

    return {
        "metadata": {
            "method": "epk_substrate_mode_tranche_recovery_decision",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": "epk_atp_gamma_phosphoryl_transfer",
            "source_review_artifact_count": len(
                [
                    review
                    for review in epk_substrate_mode_next_tranche_source_reviews
                    if isinstance(review, dict)
                ]
            ),
            "source_review_methods": _sorted_strings(source_methods),
            "source_queries": _sorted_strings(source_queries),
            "source_review_status_counts": dict(
                sorted(source_review_status_counts.items())
            ),
            "recovery_decision_status": recovery_status,
            "reviewed_unique_pdb_count": len(reviewed_ids),
            "reviewed_unique_pdb_ids": reviewed_ids,
            "reviewed_row_count": len(rows),
            "measurement_ready_unique_count": len(ready_ids),
            "measurement_ready_pdb_ids": ready_ids,
            "source_mapping_unresolved_count": len(unresolved_ids),
            "source_mapping_unresolved_pdb_ids": unresolved_ids,
            "rejected_by_substrate_mode_count": len(rejected_ids),
            "rejected_by_substrate_mode_pdb_ids": rejected_ids,
            "topology_confounded_count": len(topology_ids),
            "topology_confounded_pdb_ids": topology_ids,
            "decision_counts": dict(sorted(status_counts.items())),
            "nearest_gamma_acceptor_distance_min_angstrom": (
                round(min(distances), 3) if distances else None
            ),
            "nearest_gamma_acceptor_distance_max_angstrom": (
                round(max(distances), 3) if distances else None
            ),
            "source_context_used_as_review_evidence_only": True,
            "source_free_predictive_feature_materialized": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "recovered_missing_substrate_mode_source_review_writes",
            "blocker_not_removed": [
                "source_review_evidence_not_source_free_predictive_feature",
                "source_mapping_unresolved_for_some_rows",
                "substrate_mode_rule_not_calibrated",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_experiment": next_experiment,
            "review_only_rule": (
                "This artifact aggregates recovered substrate-mode source-review "
                "outputs after interrupted writes. It preserves measurement-ready, "
                "unresolved, and rejected rows as review-only evidence only; it "
                "does not score ePK, select a threshold, edit registries, or "
                "import labels."
            ),
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("source_review_status") or ""),
                str(row.get("pdb_id") or ""),
                str(row.get("source_artifact_index") or ""),
            ),
        ),
        "warnings": [
            (
                "Recovered substrate-mode tranche decisions are review-only and "
                "cannot support held-out performance claims, production scoring, "
                "registry edits, or label import."
            )
        ],
    }


def build_epk_heteromeric_source_valid_candidate_gamma_distance_sample(
    *,
    epk_heteromeric_candidate_source_validation_review: dict[str, Any],
) -> dict[str, Any]:
    """Summarize gamma-acceptor distances for source-valid heteromeric leads."""

    review_meta = epk_heteromeric_candidate_source_validation_review.get(
        "metadata", {}
    )
    if not isinstance(review_meta, dict):
        review_meta = {}
    target_fingerprint_id = str(
        review_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    rows: list[dict[str, Any]] = []
    measured_distances: list[float] = []
    measured_pdb_ids: list[str] = []
    source_pair_ids: list[str] = []
    accepted_rows = [
        row
        for row in epk_heteromeric_candidate_source_validation_review.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and bool(row.get("source_validated_positive_like"))
    ]
    for row in accepted_rows:
        pdb_id = str(row.get("pdb_id") or "").upper()
        source_pair_id = str(row.get("source_pair_id") or "")
        candidate_hits = [
            hit for hit in row.get("candidate_hits", []) or [] if isinstance(hit, dict)
        ]
        distance_candidates = sorted(
            [
                {
                    "candidate_chain_name": hit.get("candidate_chain_name"),
                    "candidate_auth_seq_id": hit.get("candidate_auth_seq_id"),
                    "candidate_residue_code": hit.get("candidate_residue_code"),
                    "candidate_atom_name": hit.get("candidate_atom_name"),
                    "acceptor_entity_id": hit.get("acceptor_entity_id"),
                    "gamma_associated_polymer_entity_id": hit.get(
                        "gamma_associated_polymer_entity_id"
                    ),
                    "gamma_ligand_code": hit.get("gamma_ligand_code"),
                    "gamma_atom_name": hit.get("gamma_atom_name"),
                    "nearest_gamma_distance_angstrom": (
                        float(hit["nearest_gamma_distance_angstrom"])
                        if hit.get("nearest_gamma_distance_angstrom") is not None
                        else None
                    ),
                }
                for hit in candidate_hits
                if hit.get("nearest_gamma_distance_angstrom") is not None
            ],
            key=lambda hit: (
                float(hit["nearest_gamma_distance_angstrom"]),
                str(hit.get("candidate_chain_name") or ""),
                str(hit.get("candidate_auth_seq_id") or ""),
            ),
        )
        nearest_distance = (
            float(distance_candidates[0]["nearest_gamma_distance_angstrom"])
            if distance_candidates
            else None
        )
        measurement_status = (
            "source_valid_heteromeric_gamma_distance_measured_review_only"
            if nearest_distance is not None
            else "source_valid_heteromeric_gamma_distance_missing_review_only"
        )
        blockers = [
            "threshold_not_calibrated_against_negative_controls",
            "external_hard_negative_reaudit_not_real_scorer",
            "registry_and_label_factory_extension_not_implemented",
        ]
        if nearest_distance is None:
            blockers = [
                "source_valid_candidate_lacks_distance_hit",
                *blockers,
            ]
        else:
            measured_distances.append(nearest_distance)
            measured_pdb_ids.append(pdb_id)
            if source_pair_id:
                source_pair_ids.append(source_pair_id)
        rows.append(
            {
                "pdb_id": pdb_id,
                "source_pair_id": source_pair_id or None,
                "target_family_id": "epk",
                "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                "review_only": True,
                "source_validated_positive_like": True,
                "measurement_status": measurement_status,
                "nearest_gamma_acceptor_distance_angstrom": (
                    round(nearest_distance, 3)
                    if nearest_distance is not None
                    else None
                ),
                "distance_candidates": distance_candidates[:10],
                "measurement_ready_for_review_controls": nearest_distance is not None,
                "ready_to_run_epk_scorer": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "remaining_blockers": blockers,
            }
        )

    measured_pair_ids = _sorted_strings(source_pair_ids)
    measured_count = len(measured_distances)
    all_accepted_measured = measured_count == len(accepted_rows) and measured_count > 0
    return {
        "metadata": {
            "method": "epk_heteromeric_source_valid_candidate_gamma_distance_sample",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_candidate_source_validation_review_method": (
                review_meta.get("method")
            ),
            "source_validated_candidate_count": len(accepted_rows),
            "measured_candidate_count": measured_count,
            "measured_candidate_pdb_ids": _sorted_strings(measured_pdb_ids),
            "measured_unique_pair_count": len(measured_pair_ids),
            "measured_unique_pair_ids": measured_pair_ids,
            "all_source_valid_candidates_measured": all_accepted_measured,
            "minimum_positive_coverage_measured_review_only": (
                len(measured_pair_ids) >= 2 and all_accepted_measured
            ),
            "distance_min_angstrom": (
                round(min(measured_distances), 3) if measured_distances else None
            ),
            "distance_max_angstrom": (
                round(max(measured_distances), 3) if measured_distances else None
            ),
            "distance_sample_status": (
                "source_valid_heteromeric_candidates_measured_review_only"
                if all_accepted_measured
                else "blocked_source_valid_heteromeric_distance_missing_review_only"
            ),
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "source_valid_heteromeric_candidate_distances_sampled",
            "blocker_not_removed": [
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This sample measures local gamma-acceptor distances for "
                "source-valid heteromeric review leads. It is not a calibrated "
                "score, label import, or held-out performance claim."
            ),
            "next_actions": [
                "rerun review-only controls with these source-valid measured leads separated from ambiguous candidates",
                "calibrate thresholds only after negative-control distributions are sufficient",
                "keep production scoring and label import closed",
            ],
        },
        "rows": sorted(rows, key=lambda row: str(row.get("pdb_id") or "")),
        "warnings": [
            (
                "Measured source-valid heteromeric leads remain review-only "
                "until thresholds, external hard-negative re-audit, and registry "
                "gates pass."
            )
        ],
    }


def build_epk_heteromeric_source_valid_control_rerun(
    *,
    epk_ligand_specific_5hvk_prototype_control_rerun: dict[str, Any],
    epk_heteromeric_candidate_source_validation_review: dict[str, Any],
    epk_heteromeric_source_valid_candidate_gamma_distance_sample: dict[str, Any],
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Rerun review-only ePK controls with measured heteromeric leads."""

    base_meta = epk_ligand_specific_5hvk_prototype_control_rerun.get(
        "metadata", {}
    )
    if not isinstance(base_meta, dict):
        base_meta = {}
    validation_meta = epk_heteromeric_candidate_source_validation_review.get(
        "metadata", {}
    )
    if not isinstance(validation_meta, dict):
        validation_meta = {}
    distance_meta = epk_heteromeric_source_valid_candidate_gamma_distance_sample.get(
        "metadata", {}
    )
    if not isinstance(distance_meta, dict):
        distance_meta = {}

    target_fingerprint_id = str(
        base_meta.get("target_fingerprint_id")
        or validation_meta.get("target_fingerprint_id")
        or distance_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    blockers = [
        "threshold_not_calibrated_against_negative_controls",
        "external_hard_negative_reaudit_not_real_scorer",
        "registry_and_label_factory_extension_not_implemented",
    ]

    validation_rows = [
        row
        for row in epk_heteromeric_candidate_source_validation_review.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    ]
    validation_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row for row in validation_rows
    }
    measured_rows = [
        row
        for row in epk_heteromeric_source_valid_candidate_gamma_distance_sample.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and bool(row.get("measurement_ready_for_review_controls"))
    ]

    decision_counts: Counter[str] = Counter()
    rows: list[dict[str, Any]] = []
    base_rows = [
        row
        for row in epk_ligand_specific_5hvk_prototype_control_rerun.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    ]
    for row in base_rows:
        decision = str(row.get("prototype_decision") or "unknown_review_only")
        decision_counts[decision] += 1
        carried = dict(row)
        carried["heteromeric_control_surface_role"] = (
            "carried_5hvk_control_surface_row"
        )
        carried["target_fingerprint_id"] = target_fingerprint_id
        carried["review_only"] = True
        carried["countable_label_candidate"] = False
        carried["ready_for_label_import"] = False
        carried["epk_score_computed"] = False
        rows.append(carried)

    measured_positive_pdb_ids: list[str] = []
    measured_pair_ids: list[str] = []
    heteromeric_axis_complete_count = 0
    for measured_row in measured_rows:
        pdb_id = str(measured_row.get("pdb_id") or "").upper()
        validation_row = validation_by_pdb.get(pdb_id, {})
        entity_descriptions = validation_row.get("entity_descriptions", [])
        if not isinstance(entity_descriptions, list):
            entity_descriptions = []
        source_pair_id = str(measured_row.get("source_pair_id") or "")
        distance = measured_row.get("nearest_gamma_acceptor_distance_angstrom")
        try:
            distance_within_cutoff = (
                distance is not None
                and float(distance) <= float(candidate_threshold_angstrom)
            )
        except (TypeError, ValueError):
            distance_within_cutoff = False
        source_axis_values = {
            "local_adenine_nucleotide_ligand": int(
                any(
                    str(candidate.get("gamma_ligand_code") or "").upper()
                    in {"ACP", "ANP", "ATP", "DTP"}
                    for candidate in measured_row.get("distance_candidates", [])
                    or []
                    if isinstance(candidate, dict)
                )
            ),
            "local_metal_ligand": int("MAGNESIUM ION" in entity_descriptions),
            "heteromeric_entity_topology": int(
                bool(validation_row.get("source_validated_positive_like"))
            ),
            "source_validated_kinase_substrate_pair": int(
                bool(validation_row.get("source_validated_positive_like"))
            ),
            "gamma_to_acceptor_distance_within_candidate_cutoff": int(
                distance_within_cutoff
            ),
        }
        axis_complete = all(value == 1 for value in source_axis_values.values())
        decision = (
            "source_valid_heteromeric_positive_signal_review_only_not_calibrated"
            if axis_complete
            else "source_valid_heteromeric_abstain_missing_required_axis_review_only"
        )
        decision_counts[decision] += 1
        if axis_complete:
            heteromeric_axis_complete_count += 1
            measured_positive_pdb_ids.append(pdb_id)
            if source_pair_id:
                measured_pair_ids.append(source_pair_id)
        rows.append(
            {
                "row_type": "heteromeric_source_valid_positive_candidate",
                "pdb_id": pdb_id,
                "source_pair_id": source_pair_id or None,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "prototype_axis_values": source_axis_values,
                "review_only_prototype_score": round(
                    sum(source_axis_values.values()) / len(source_axis_values), 4
                ),
                "prototype_decision": decision,
                "nearest_gamma_to_acceptor_distance_angstrom": distance,
                "source_validation_status": validation_row.get(
                    "source_validation_status"
                ),
                "source_validation_evidence": validation_row.get(
                    "source_validation_evidence", []
                ),
                "acceptor_context_type": "source_validated_heteromeric_protein_substrate_hydroxyl",
                "predictive_use_status": (
                    "review_only_source_validity_not_production_scoring_input"
                ),
                "text_free_inputs_only": False,
                "heteromeric_control_surface_role": (
                    "new_source_valid_heteromeric_positive_lead"
                ),
                "remaining_blockers": blockers,
            }
        )

    separated_nonpositive_rows = [
        row
        for row in validation_rows
        if not bool(row.get("source_validated_positive_like"))
    ]
    for row in separated_nonpositive_rows:
        status = str(
            row.get("source_validation_status")
            or "blocked_source_context_insufficient_review_only"
        )
        decision_counts[status] += 1
        separated_role = (
            "separated_ambiguous_heteromeric_candidate"
            if status.startswith("blocked_ambiguous")
            else "separated_rejected_heteromeric_candidate"
        )
        rows.append(
            {
                "row_type": "heteromeric_candidate_separated_nonpositive_control",
                "pdb_id": row.get("pdb_id"),
                "source_pair_id": row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "prototype_axis_values": {},
                "review_only_prototype_score": 0.0,
                "prototype_decision": status,
                "candidate_feature_hit": False,
                "source_validation_status": status,
                "source_validation_evidence": row.get(
                    "source_validation_evidence", []
                ),
                "heteromeric_candidate_hit_count": row.get(
                    "heteromeric_candidate_hit_count"
                ),
                "nearest_heteromeric_candidate_distance_angstrom": row.get(
                    "nearest_heteromeric_candidate_distance_angstrom"
                ),
                "heteromeric_control_surface_role": separated_role,
                "remaining_blockers": row.get("remaining_blockers", blockers),
            }
        )

    sibling_false_hit_count = sum(
        1
        for row in rows
        if row.get("rerun_surface_role") == "carried_sibling_control"
        and bool(row.get("candidate_feature_hit"))
    )
    external_non_abstention_count = sum(
        1
        for row in rows
        if row.get("rerun_surface_role")
        == "carried_imported_external_hard_negative"
        and row.get("prototype_decision")
        != "external_hard_negative_abstain_missing_epk_axes_review_only"
    )
    ambiguous_count = sum(
        1
        for row in separated_nonpositive_rows
        if str(row.get("source_validation_status") or "").startswith(
            "blocked_ambiguous"
        )
    )
    rejected_count = len(separated_nonpositive_rows) - ambiguous_count
    measured_pair_ids = _sorted_strings(measured_pair_ids)
    controls_passed = (
        base_meta.get("control_rerun_status")
        == "passes_review_only_controls_but_scorer_blocked"
        and bool(distance_meta.get("all_source_valid_candidates_measured"))
        and heteromeric_axis_complete_count == len(measured_rows)
        and heteromeric_axis_complete_count > 0
        and sibling_false_hit_count == 0
        and external_non_abstention_count == 0
    )
    control_rerun_status = (
        "passes_review_only_controls_but_scorer_blocked"
        if controls_passed
        else "blocked_review_only_control_rerun"
    )
    positive_like_review_row_count = int(
        base_meta.get("positive_like_review_row_count") or 0
    ) + heteromeric_axis_complete_count

    return {
        "metadata": {
            "method": "epk_heteromeric_source_valid_control_rerun",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_ligand_specific_5hvk_prototype_control_rerun_method": (
                base_meta.get("method")
            ),
            "source_epk_heteromeric_candidate_source_validation_review_method": (
                validation_meta.get("method")
            ),
            "source_epk_heteromeric_source_valid_candidate_gamma_distance_sample_method": (
                distance_meta.get("method")
            ),
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "control_rerun_status": control_rerun_status,
            "current_positive_prototype_row_count": base_meta.get(
                "current_positive_prototype_row_count"
            ),
            "source_valid_5hvk_candidate_row_count": base_meta.get(
                "source_valid_5hvk_candidate_row_count"
            ),
            "heteromeric_source_valid_candidate_row_count": len(measured_rows),
            "heteromeric_source_valid_axis_complete_count": (
                heteromeric_axis_complete_count
            ),
            "heteromeric_source_valid_pdb_ids": _sorted_strings(
                measured_positive_pdb_ids
            ),
            "heteromeric_source_valid_unique_pair_count": len(measured_pair_ids),
            "heteromeric_source_valid_unique_pair_ids": measured_pair_ids,
            "heteromeric_ambiguous_candidate_count": ambiguous_count,
            "heteromeric_rejected_candidate_count": rejected_count,
            "heteromeric_ambiguous_and_rejected_separated": (
                len(separated_nonpositive_rows)
                == ambiguous_count + rejected_count
            ),
            "positive_like_review_row_count": positive_like_review_row_count,
            "sibling_control_row_count": base_meta.get("sibling_control_row_count"),
            "sibling_control_false_hit_count": sibling_false_hit_count,
            "imported_external_hard_negative_row_count": base_meta.get(
                "imported_external_hard_negative_row_count"
            ),
            "imported_external_hard_negative_non_abstention_count": (
                external_non_abstention_count
            ),
            "source_authority_dependent_positive_like_count": (
                int(base_meta.get("source_valid_5hvk_candidate_row_count") or 0)
                + heteromeric_axis_complete_count
            ),
            "not_a_real_scored_reaudit": True,
            "row_count": len(rows),
            "prototype_decision_counts": dict(sorted(decision_counts.items())),
            "prototype_gate_status": "fail_closed_review_only",
            "prototype_failed_closed": True,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "negative_control_distance_distribution_ready": False,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "source_valid_heteromeric_review_controls_rerun",
            "blocker_not_removed": [
                "source_validity_axes_not_production_scoring_inputs",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact reruns the fail-closed ePK review surface after "
                "adding measured source-valid heteromeric leads. Ambiguous "
                "and rejected non-ePK rows are explicitly separated from "
                "positive-like controls. It is not a calibrated ePK score, "
                "external hard-negative scored re-audit, registry edit, or "
                "label gate."
            ),
            "next_actions": [
                "replace source-valid heteromeric positive axes with local text-free role and acceptor evidence before scoring",
                "calibrate thresholds only after negative-control distributions remain clean under the expanded positive-like surface",
                "run a real external hard-negative scored re-audit only after a frozen ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Expanded heteromeric positive-like controls remain "
                "review-only and source-authority dependent."
            )
        ],
    }


def build_epk_heteromeric_text_free_axis_gap_audit(
    *,
    epk_heteromeric_source_valid_control_rerun: dict[str, Any],
) -> dict[str, Any]:
    """Audit text-free blockers on source-valid heteromeric review positives."""

    rerun_meta = epk_heteromeric_source_valid_control_rerun.get("metadata", {})
    if not isinstance(rerun_meta, dict):
        rerun_meta = {}
    target_fingerprint_id = str(
        rerun_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    source_positive_decisions = {
        "source_valid_5hvk_positive_signal_review_only_not_calibrated",
        "source_valid_heteromeric_positive_signal_review_only_not_calibrated",
    }
    source_rows = [
        row
        for row in epk_heteromeric_source_valid_control_rerun.get("rows", [])
        or []
        if isinstance(row, dict)
        and row.get("prototype_decision") in source_positive_decisions
    ]

    rows: list[dict[str, Any]] = []
    local_geometry_axis_present_count = 0
    source_free_role_assignment_ready_count = 0
    source_free_acceptor_identity_ready_count = 0
    production_admissible_positive_like_count = 0
    for row in source_rows:
        axis_values = row.get("prototype_axis_values", {})
        if not isinstance(axis_values, dict):
            axis_values = {}
        local_gamma_axis_present = bool(
            axis_values.get("gamma_to_acceptor_distance_within_candidate_cutoff")
        )
        local_nucleotide_metal_axis_present = bool(
            axis_values.get("local_adenine_nucleotide_ligand")
            and axis_values.get("local_metal_ligand")
        )
        local_geometry_axis_present = (
            local_gamma_axis_present and local_nucleotide_metal_axis_present
        )
        if local_geometry_axis_present:
            local_geometry_axis_present_count += 1
        source_free_role_assignment_present = False
        source_free_acceptor_identity_present = False
        if source_free_role_assignment_present:
            source_free_role_assignment_ready_count += 1
        if source_free_acceptor_identity_present:
            source_free_acceptor_identity_ready_count += 1
        production_admissible = (
            local_geometry_axis_present
            and source_free_role_assignment_present
            and source_free_acceptor_identity_present
        )
        if production_admissible:
            production_admissible_positive_like_count += 1
        rows.append(
            {
                "row_type": "source_valid_heteromeric_text_free_axis_gap",
                "pdb_id": row.get("pdb_id"),
                "entry_id": row.get("entry_id"),
                "source_pair_id": row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "source_prototype_decision": row.get("prototype_decision"),
                "local_geometry_axis_present": local_geometry_axis_present,
                "local_gamma_axis_present": local_gamma_axis_present,
                "local_nucleotide_metal_axis_present": (
                    local_nucleotide_metal_axis_present
                ),
                "source_free_role_assignment_present": (
                    source_free_role_assignment_present
                ),
                "source_free_acceptor_identity_present": (
                    source_free_acceptor_identity_present
                ),
                "production_scoring_admissible": production_admissible,
                "text_free_inputs_only": False,
                "gap_status": (
                    "blocked_source_authority_dependent_role_and_acceptor_identity"
                ),
                "remaining_blockers": [
                    "source_free_kinase_substrate_role_assignment_missing",
                    "source_free_acceptor_identity_evidence_missing",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    gap_audit_status = (
        "blocked_review_only_source_free_role_acceptor_axes_missing"
        if rows and production_admissible_positive_like_count == 0
        else "blocked_no_source_valid_heteromeric_positive_rows"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_text_free_axis_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_source_valid_control_rerun_method": (
                rerun_meta.get("method")
            ),
            "gap_audit_status": gap_audit_status,
            "source_authority_dependent_positive_like_count": len(source_rows),
            "local_geometry_axis_present_count": local_geometry_axis_present_count,
            "source_free_role_assignment_ready_count": (
                source_free_role_assignment_ready_count
            ),
            "source_free_acceptor_identity_ready_count": (
                source_free_acceptor_identity_ready_count
            ),
            "production_admissible_positive_like_count": (
                production_admissible_positive_like_count
            ),
            "sibling_control_false_hit_count": rerun_meta.get(
                "sibling_control_false_hit_count"
            ),
            "imported_external_hard_negative_non_abstention_count": (
                rerun_meta.get(
                    "imported_external_hard_negative_non_abstention_count"
                )
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "heteromeric_source_authority_gap_made_explicit",
            "blocker_not_removed": [
                "source_free_kinase_substrate_role_assignment_missing",
                "source_free_acceptor_identity_evidence_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit separates local geometry evidence from source "
                "authority in the expanded heteromeric ePK review surface. It "
                "is a blocker inventory only, not a scorer, threshold, external "
                "hard-negative re-audit, registry edit, or label gate."
            ),
            "next_actions": [
                "build a local source-free kinase/substrate role rule for heteromeric co-complexes",
                "build source-free acceptor identity evidence before treating heteromeric positives as production scorer inputs",
                "keep expanded heteromeric controls review-only until thresholds and external scored re-audit pass",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "All expanded heteromeric positive-like rows still depend on "
                "source authority for role or acceptor identity."
            )
        ],
    }


def build_epk_heteromeric_source_free_role_rule_probe(
    *,
    epk_heteromeric_candidate_source_validation_review: dict[str, Any],
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Probe a source-free heteromeric topology rule against reviewed leads."""

    review_meta = epk_heteromeric_candidate_source_validation_review.get(
        "metadata", {}
    )
    if not isinstance(review_meta, dict):
        review_meta = {}
    target_fingerprint_id = str(
        review_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    rows: list[dict[str, Any]] = []
    source_free_rule_hit_count = 0
    accepted_rule_hit_count = 0
    ambiguous_rule_hit_count = 0
    rejected_rule_hit_count = 0
    nonaccepted_rule_hit_pdb_ids: list[str] = []
    for row in epk_heteromeric_candidate_source_validation_review.get(
        "rows", []
    ) or []:
        if not isinstance(row, dict):
            continue
        pdb_id = str(row.get("pdb_id") or "").upper()
        candidate_hits = [
            hit for hit in row.get("candidate_hits", []) or [] if isinstance(hit, dict)
        ]
        nearest_distance = row.get("nearest_heteromeric_candidate_distance_angstrom")
        if nearest_distance is None and candidate_hits:
            nearest_distance = candidate_hits[0].get(
                "nearest_gamma_distance_angstrom"
            )
        try:
            within_cutoff = (
                nearest_distance is not None
                and float(nearest_distance) <= float(candidate_threshold_angstrom)
            )
        except (TypeError, ValueError):
            within_cutoff = False
        source_free_rule_hit = bool(candidate_hits) and within_cutoff
        source_validated = bool(row.get("source_validated_positive_like"))
        status = str(row.get("source_validation_status") or "")
        if source_free_rule_hit:
            source_free_rule_hit_count += 1
            if source_validated:
                accepted_rule_hit_count += 1
            elif status.startswith("blocked_ambiguous"):
                ambiguous_rule_hit_count += 1
                nonaccepted_rule_hit_pdb_ids.append(pdb_id)
            else:
                rejected_rule_hit_count += 1
                nonaccepted_rule_hit_pdb_ids.append(pdb_id)
        rows.append(
            {
                "row_type": "heteromeric_source_free_role_rule_probe",
                "pdb_id": pdb_id,
                "source_pair_id": row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "source_free_rule_inputs": {
                    "heteromeric_entity_topology_hit": bool(candidate_hits),
                    "nearest_gamma_distance_within_candidate_cutoff": within_cutoff,
                },
                "source_free_rule_hit": source_free_rule_hit,
                "source_validation_status_review_context": status,
                "source_validated_positive_like_review_context": source_validated,
                "source_free_rule_decision": (
                    "source_free_rule_hits_source_valid_review_positive"
                    if source_free_rule_hit and source_validated
                    else (
                        "source_free_rule_false_hit_risk_review_only"
                        if source_free_rule_hit
                        else "source_free_rule_abstain_review_only"
                    )
                ),
                "nearest_heteromeric_candidate_distance_angstrom": nearest_distance,
                "text_free_inputs_only": True,
                "production_scoring_admissible": False,
                "remaining_blockers": [
                    "source_free_rule_false_hit_risk"
                    if source_free_rule_hit and not source_validated
                    else "threshold_not_calibrated_against_negative_controls",
                    "role_direction_disambiguation_missing",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    nonaccepted_rule_hit_pdb_ids = _sorted_strings(nonaccepted_rule_hit_pdb_ids)
    rule_status = (
        "blocked_review_only_source_free_rule_false_hit_risk"
        if nonaccepted_rule_hit_pdb_ids
        else "passes_review_only_source_free_rule_probe_not_scoring_admissible"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_source_free_role_rule_probe",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_candidate_source_validation_review_method": (
                review_meta.get("method")
            ),
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "source_free_rule_status": rule_status,
            "reviewed_candidate_count": len(rows),
            "source_free_rule_hit_count": source_free_rule_hit_count,
            "accepted_rule_hit_count": accepted_rule_hit_count,
            "ambiguous_rule_hit_count": ambiguous_rule_hit_count,
            "rejected_rule_hit_count": rejected_rule_hit_count,
            "nonaccepted_rule_hit_count": len(nonaccepted_rule_hit_pdb_ids),
            "nonaccepted_rule_hit_pdb_ids": nonaccepted_rule_hit_pdb_ids,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "source_free_topology_gamma_rule_probe_executed",
            "blocker_not_removed": [
                "source_free_rule_false_hit_risk",
                "role_direction_disambiguation_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This probe applies only local heteromeric topology plus "
                "gamma-distance evidence, then evaluates it against source "
                "validation outcomes as review context. It fails closed if the "
                "local rule also hits ambiguous or rejected candidates."
            ),
            "next_actions": [
                "add a source-free role-direction disambiguation signal before using heteromeric topology for scoring",
                "keep BRAF/MEK and non-ePK designed-clock hits as review-only counterexamples",
                "do not calibrate an ePK threshold from topology-plus-gamma alone",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Heteromeric topology plus gamma distance alone is not a "
                "production-admissible ePK role rule."
            )
        ],
    }


def build_epk_heteromeric_acceptor_chain_counteraxis_audit(
    *,
    epk_heteromeric_candidate_source_validation_review: dict[str, Any],
    candidate_threshold_angstrom: float = 6.0,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Audit acceptor-chain nucleotide context as a heteromeric counter-axis."""

    review_meta = epk_heteromeric_candidate_source_validation_review.get(
        "metadata", {}
    )
    if not isinstance(review_meta, dict):
        review_meta = {}
    target_fingerprint_id = str(
        review_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    nucleotide_codes = {"ACP", "ADP", "AMP", "ANP", "ATP", "DTP"}
    metal_codes = {"CA", "MG", "MN", "ZN"}
    ligand_context_codes = nucleotide_codes | metal_codes

    def _chain_ligand_context(cif_text: str) -> dict[str, list[str]]:
        by_chain: dict[str, set[str]] = defaultdict(set)
        for atom in parse_atom_site_loop(cif_text):
            if atom.get("group_PDB") != "HETATM":
                continue
            code = _epk_atom_code(atom)
            if code not in ligand_context_codes:
                continue
            chain_id = str(atom.get("auth_asym_id") or atom.get("label_asym_id") or "")
            if chain_id:
                by_chain[chain_id].add(code)
        return {chain: sorted(codes) for chain, codes in sorted(by_chain.items())}

    rows: list[dict[str, Any]] = []
    fetch_failure_count = 0
    initial_rule_hit_count = 0
    retained_source_valid_hit_count = 0
    blocked_nonaccepted_rule_hit_count = 0
    residual_nonaccepted_rule_hit_pdb_ids: list[str] = []
    accepted_lost_pdb_ids: list[str] = []
    blocked_nonaccepted_pdb_ids: list[str] = []
    for row in epk_heteromeric_candidate_source_validation_review.get(
        "rows", []
    ) or []:
        if not isinstance(row, dict):
            continue
        pdb_id = str(row.get("pdb_id") or "").upper()
        source_validated = bool(row.get("source_validated_positive_like"))
        status = str(row.get("source_validation_status") or "")
        candidate_hits = [
            hit for hit in row.get("candidate_hits", []) or [] if isinstance(hit, dict)
        ]
        try:
            cif_text = cif_texts.get(pdb_id)
            fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
            if cif_text is None:
                cif_text = cif_fetcher(pdb_id)
            ligand_context_by_chain = _chain_ligand_context(cif_text)
        except Exception as exc:  # pragma: no cover - live fetch safety
            fetch_failure_count += 1
            rows.append(
                {
                    "row_type": "heteromeric_acceptor_chain_counteraxis",
                    "pdb_id": pdb_id,
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "fetch_status": "fetch_failed",
                    "fetch_error": str(exc),
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "counteraxis_decision": "blocked_structure_fetch_failed_review_only",
                    "remaining_blockers": ["structure_fetch_failed"],
                }
            )
            continue

        within_cutoff_hits: list[dict[str, Any]] = []
        for hit in candidate_hits:
            distance = hit.get("nearest_gamma_distance_angstrom")
            try:
                within_cutoff = (
                    distance is not None
                    and float(distance) <= float(candidate_threshold_angstrom)
                )
            except (TypeError, ValueError):
                within_cutoff = False
            if within_cutoff:
                within_cutoff_hits.append(hit)
        initial_rule_hit = bool(within_cutoff_hits)
        if initial_rule_hit:
            initial_rule_hit_count += 1
        acceptor_chain_ids = _sorted_strings(
            hit.get("candidate_chain_name") for hit in within_cutoff_hits
        )
        gamma_chain_ids = _sorted_strings(
            hit.get("gamma_associated_polymer_chain_name")
            for hit in within_cutoff_hits
        )
        acceptor_chain_ligand_context = {
            chain_id: ligand_context_by_chain.get(chain_id, [])
            for chain_id in acceptor_chain_ids
        }
        gamma_chain_ligand_context = {
            chain_id: ligand_context_by_chain.get(chain_id, [])
            for chain_id in gamma_chain_ids
        }
        acceptor_chain_has_nucleotide_or_metal = any(
            bool(codes) for codes in acceptor_chain_ligand_context.values()
        )
        counteraxis_hit = initial_rule_hit and not acceptor_chain_has_nucleotide_or_metal
        if source_validated and counteraxis_hit:
            retained_source_valid_hit_count += 1
            decision = "source_free_counteraxis_retains_source_valid_review_positive"
        elif source_validated and initial_rule_hit:
            accepted_lost_pdb_ids.append(pdb_id)
            decision = "blocked_counteraxis_loses_source_valid_review_positive"
        elif initial_rule_hit and acceptor_chain_has_nucleotide_or_metal:
            blocked_nonaccepted_rule_hit_count += 1
            blocked_nonaccepted_pdb_ids.append(pdb_id)
            decision = "source_free_counteraxis_blocks_nonaccepted_rule_hit"
        elif initial_rule_hit:
            residual_nonaccepted_rule_hit_pdb_ids.append(pdb_id)
            decision = "source_free_counteraxis_residual_false_hit_risk"
        else:
            decision = "source_free_counteraxis_abstain_review_only"
        rows.append(
            {
                "row_type": "heteromeric_acceptor_chain_counteraxis",
                "pdb_id": pdb_id,
                "source_pair_id": row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "fetch_status": fetch_status,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "initial_topology_gamma_rule_hit": initial_rule_hit,
                "acceptor_chain_ids": acceptor_chain_ids,
                "gamma_associated_chain_ids": gamma_chain_ids,
                "acceptor_chain_ligand_context": acceptor_chain_ligand_context,
                "gamma_chain_ligand_context": gamma_chain_ligand_context,
                "acceptor_chain_has_nucleotide_or_metal_context": (
                    acceptor_chain_has_nucleotide_or_metal
                ),
                "source_free_counteraxis_hit": counteraxis_hit,
                "counteraxis_decision": decision,
                "source_validation_status_review_context": status,
                "source_validated_positive_like_review_context": source_validated,
                "text_free_inputs_only": True,
                "production_scoring_admissible": False,
                "remaining_blockers": [
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                    (
                        "broader_heteromeric_counteraxis_controls_not_run"
                        if counteraxis_hit and source_validated
                        else "counteraxis_row_not_positive_like"
                    ),
                ],
            }
        )

    residual_nonaccepted_rule_hit_pdb_ids = _sorted_strings(
        residual_nonaccepted_rule_hit_pdb_ids
    )
    accepted_lost_pdb_ids = _sorted_strings(accepted_lost_pdb_ids)
    blocked_nonaccepted_pdb_ids = _sorted_strings(blocked_nonaccepted_pdb_ids)
    counteraxis_status = (
        "passes_current_review_controls_not_scoring_admissible"
        if rows
        and fetch_failure_count == 0
        and not residual_nonaccepted_rule_hit_pdb_ids
        and not accepted_lost_pdb_ids
        else "blocked_review_only_counteraxis_needs_repair"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_acceptor_chain_counteraxis_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_candidate_source_validation_review_method": (
                review_meta.get("method")
            ),
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "counteraxis_status": counteraxis_status,
            "reviewed_candidate_count": len(rows),
            "fetch_failure_count": fetch_failure_count,
            "initial_topology_gamma_rule_hit_count": initial_rule_hit_count,
            "retained_source_valid_hit_count": retained_source_valid_hit_count,
            "blocked_nonaccepted_rule_hit_count": blocked_nonaccepted_rule_hit_count,
            "blocked_nonaccepted_rule_hit_pdb_ids": blocked_nonaccepted_pdb_ids,
            "residual_nonaccepted_rule_hit_count": len(
                residual_nonaccepted_rule_hit_pdb_ids
            ),
            "residual_nonaccepted_rule_hit_pdb_ids": (
                residual_nonaccepted_rule_hit_pdb_ids
            ),
            "accepted_lost_count": len(accepted_lost_pdb_ids),
            "accepted_lost_pdb_ids": accepted_lost_pdb_ids,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "current_heteromeric_false_hits_have_local_counteraxis",
            "blocker_not_removed": [
                "broader_heteromeric_counteraxis_controls_not_run",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit keeps only local mmCIF ligand context: a "
                "heteromeric topology/gamma hit is blocked when the candidate "
                "acceptor chain itself carries nucleotide or metal context. "
                "Source-validation outcomes are used only to evaluate the "
                "review probe, not as predictive inputs."
            ),
            "next_actions": [
                "run the acceptor-chain counteraxis on broader heteromeric and sibling controls before scorer design",
                "keep the counteraxis review-only until external hard-negative scored re-audit and thresholds exist",
                "do not use source-validation text as an orphan discovery input",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Acceptor-chain ligand context is a review-only counteraxis "
                "until broader controls and scoring gates pass."
            )
        ],
    }


def build_epk_heteromeric_broader_counteraxis_control_audit(
    *,
    epk_heteromeric_positive_coverage_candidate_scout: dict[str, Any],
    epk_heteromeric_candidate_source_validation_review: dict[str, Any],
    epk_heteromeric_acceptor_chain_counteraxis_audit: dict[str, Any],
    epk_sibling_control_artifacts: list[dict[str, Any]] | None = None,
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Broaden the heteromeric acceptor-chain counter-axis control surface."""

    scout_meta = epk_heteromeric_positive_coverage_candidate_scout.get(
        "metadata", {}
    )
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    validation_meta = epk_heteromeric_candidate_source_validation_review.get(
        "metadata", {}
    )
    if not isinstance(validation_meta, dict):
        validation_meta = {}
    counteraxis_meta = epk_heteromeric_acceptor_chain_counteraxis_audit.get(
        "metadata", {}
    )
    if not isinstance(counteraxis_meta, dict):
        counteraxis_meta = {}
    target_fingerprint_id = str(
        scout_meta.get("target_fingerprint_id")
        or validation_meta.get("target_fingerprint_id")
        or counteraxis_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    validation_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_heteromeric_candidate_source_validation_review.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    }
    counteraxis_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_heteromeric_acceptor_chain_counteraxis_audit.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    }

    rows: list[dict[str, Any]] = []
    broader_reviewed_count = 0
    broader_initial_hit_count = 0
    broader_no_hit_count = 0
    broader_missing_counteraxis_count = 0
    retained_source_valid_hit_count = 0
    blocked_nonaccepted_hit_count = 0
    residual_nonaccepted_hit_pdb_ids: list[str] = []
    accepted_lost_pdb_ids: list[str] = []

    for scout_row in epk_heteromeric_positive_coverage_candidate_scout.get(
        "rows", []
    ) or []:
        if not isinstance(scout_row, dict):
            continue
        broader_reviewed_count += 1
        pdb_id = str(scout_row.get("pdb_id") or "").upper()
        candidate_hits = [
            hit
            for hit in scout_row.get("heteromeric_candidate_hits", []) or []
            if isinstance(hit, dict)
        ]
        initial_hit = bool(candidate_hits)
        if initial_hit:
            broader_initial_hit_count += 1
        else:
            broader_no_hit_count += 1
        validation_row = validation_by_pdb.get(pdb_id, {})
        counteraxis_row = counteraxis_by_pdb.get(pdb_id, {})
        source_validated = bool(validation_row.get("source_validated_positive_like"))
        source_status = str(
            validation_row.get("source_validation_status")
            or scout_row.get("source_validation_status")
            or ""
        )
        if not initial_hit:
            decision = "broader_heteromeric_no_topology_gamma_hit_abstain_review_only"
            counteraxis_hit = False
        elif not counteraxis_row:
            broader_missing_counteraxis_count += 1
            decision = "broader_heteromeric_hit_missing_counteraxis_review_only"
            counteraxis_hit = False
            if source_validated:
                accepted_lost_pdb_ids.append(pdb_id)
            else:
                residual_nonaccepted_hit_pdb_ids.append(pdb_id)
        else:
            base_decision = str(counteraxis_row.get("counteraxis_decision") or "")
            counteraxis_hit = bool(counteraxis_row.get("source_free_counteraxis_hit"))
            if base_decision == "source_free_counteraxis_retains_source_valid_review_positive":
                retained_source_valid_hit_count += 1
            elif base_decision == "source_free_counteraxis_blocks_nonaccepted_rule_hit":
                blocked_nonaccepted_hit_count += 1
            elif base_decision == "blocked_counteraxis_loses_source_valid_review_positive":
                accepted_lost_pdb_ids.append(pdb_id)
            elif base_decision == "source_free_counteraxis_residual_false_hit_risk":
                residual_nonaccepted_hit_pdb_ids.append(pdb_id)
            elif initial_hit and not source_validated and counteraxis_hit:
                residual_nonaccepted_hit_pdb_ids.append(pdb_id)
            decision = f"broader_{base_decision or 'counteraxis_unclassified'}"
        rows.append(
            {
                "row_type": "heteromeric_broader_counteraxis_control",
                "control_surface": "broader_heteromeric_candidate_scout",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_threshold_angstrom": candidate_threshold_angstrom,
                "initial_topology_gamma_rule_hit": initial_hit,
                "heteromeric_candidate_hit_count": len(candidate_hits),
                "source_free_counteraxis_hit": counteraxis_hit,
                "source_validated_positive_like_review_context": source_validated,
                "source_validation_status_review_context": source_status,
                "counteraxis_decision": decision,
                "production_scoring_admissible": False,
                "text_free_inputs_only": True,
                "remaining_blockers": [
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                    (
                        "source_free_kinase_substrate_role_assignment_missing"
                        if counteraxis_hit
                        else "not_a_positive_counteraxis_hit"
                    ),
                ],
            }
        )

    sibling_artifacts = [
        artifact for artifact in (epk_sibling_control_artifacts or []) if artifact
    ]
    sibling_family_ids: set[str] = set()
    sibling_control_row_count = 0
    sibling_same_chain_hit_count = 0
    sibling_blocked_hit_count = 0
    sibling_residual_hit_pdb_ids: list[str] = []
    sibling_not_ready_count = 0

    def _threshold_hits(row: dict[str, Any]) -> list[float]:
        hits: list[float] = []
        for value in row.get("same_chain_hydroxyl_candidate_threshold_hits_angstrom", []) or []:
            try:
                hits.append(float(value))
            except (TypeError, ValueError):
                continue
        return hits

    for artifact in sibling_artifacts:
        artifact_meta = artifact.get("metadata", {})
        if not isinstance(artifact_meta, dict):
            artifact_meta = {}
        family_id = str(artifact_meta.get("reviewed_sibling_family_id") or "")
        family_name = str(artifact_meta.get("reviewed_sibling_family_name") or "")
        if family_id:
            sibling_family_ids.add(family_id)
        for sibling_row in artifact.get("rows", []) or []:
            if not isinstance(sibling_row, dict):
                continue
            sibling_control_row_count += 1
            row_family_id = str(sibling_row.get("family_id") or family_id)
            if row_family_id:
                sibling_family_ids.add(row_family_id)
            pdb_id = str(sibling_row.get("pdb_id") or "").upper()
            threshold_hits = _threshold_hits(sibling_row)
            same_chain_hit = any(
                abs(hit - float(candidate_threshold_angstrom)) < 1e-6
                or hit <= float(candidate_threshold_angstrom)
                for hit in threshold_hits
            )
            if same_chain_hit:
                sibling_same_chain_hit_count += 1
            measured = bool(
                sibling_row.get("gamma_to_mapped_histidine_distance_measured")
                or sibling_row.get("gamma_to_family_acid_base_distance_measured")
            )
            if not measured:
                sibling_not_ready_count += 1
                decision = "sibling_control_not_measurement_ready_review_only"
                blocked_by_counteraxis = False
            elif same_chain_hit and (
                sibling_row.get("gamma_capable_nucleotide_codes")
                or sibling_row.get("gamma_atom_count")
            ):
                sibling_blocked_hit_count += 1
                decision = "source_free_counteraxis_blocks_sibling_same_chain_ligand_hit"
                blocked_by_counteraxis = True
            elif same_chain_hit:
                sibling_residual_hit_pdb_ids.append(pdb_id)
                decision = "source_free_counteraxis_residual_sibling_false_hit_risk"
                blocked_by_counteraxis = False
            else:
                decision = "sibling_control_no_same_chain_hydroxyl_hit_abstain_review_only"
                blocked_by_counteraxis = False
            rows.append(
                {
                    "row_type": "sibling_broader_counteraxis_control",
                    "control_surface": "measured_sibling_family_controls",
                    "pdb_id": pdb_id,
                    "entry_id": sibling_row.get("entry_id"),
                    "family_id": row_family_id,
                    "family_name": sibling_row.get("family_name") or family_name,
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "candidate_threshold_angstrom": candidate_threshold_angstrom,
                    "same_chain_hydroxyl_threshold_hit": same_chain_hit,
                    "same_chain_hydroxyl_candidate_threshold_hits_angstrom": (
                        threshold_hits
                    ),
                    "source_free_counteraxis_blocks_hit": blocked_by_counteraxis,
                    "counteraxis_decision": decision,
                    "production_scoring_admissible": False,
                    "text_free_inputs_only": True,
                    "remaining_blockers": [
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                        "registry_and_label_factory_extension_not_implemented",
                        "sibling_family_control_not_epk_positive_label",
                    ],
                }
            )

    residual_nonaccepted_hit_pdb_ids = _sorted_strings(
        residual_nonaccepted_hit_pdb_ids
    )
    accepted_lost_pdb_ids = _sorted_strings(accepted_lost_pdb_ids)
    sibling_residual_hit_pdb_ids = _sorted_strings(sibling_residual_hit_pdb_ids)
    sibling_family_ids_sorted = _sorted_strings(sibling_family_ids)
    broader_control_passed = (
        broader_reviewed_count > 0
        and broader_missing_counteraxis_count == 0
        and not residual_nonaccepted_hit_pdb_ids
        and not accepted_lost_pdb_ids
        and not sibling_residual_hit_pdb_ids
    )
    status = (
        "passes_broader_review_controls_not_scoring_admissible"
        if broader_control_passed
        else "blocked_review_only_broader_counteraxis_control_failures"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_broader_counteraxis_control_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_positive_coverage_candidate_scout_method": (
                scout_meta.get("method")
            ),
            "source_epk_heteromeric_candidate_source_validation_review_method": (
                validation_meta.get("method")
            ),
            "source_epk_heteromeric_acceptor_chain_counteraxis_audit_method": (
                counteraxis_meta.get("method")
            ),
            "candidate_threshold_angstrom": candidate_threshold_angstrom,
            "broader_counteraxis_status": status,
            "broader_control_passed": broader_control_passed,
            "broader_heteromeric_reviewed_structure_count": (
                broader_reviewed_count
            ),
            "broader_heteromeric_initial_hit_count": broader_initial_hit_count,
            "broader_heteromeric_no_hit_count": broader_no_hit_count,
            "broader_heteromeric_missing_counteraxis_count": (
                broader_missing_counteraxis_count
            ),
            "retained_source_valid_hit_count": retained_source_valid_hit_count,
            "blocked_nonaccepted_rule_hit_count": blocked_nonaccepted_hit_count,
            "residual_nonaccepted_rule_hit_count": len(
                residual_nonaccepted_hit_pdb_ids
            ),
            "residual_nonaccepted_rule_hit_pdb_ids": (
                residual_nonaccepted_hit_pdb_ids
            ),
            "accepted_lost_count": len(accepted_lost_pdb_ids),
            "accepted_lost_pdb_ids": accepted_lost_pdb_ids,
            "sibling_control_artifact_count": len(sibling_artifacts),
            "sibling_control_row_count": sibling_control_row_count,
            "sibling_control_family_ids": sibling_family_ids_sorted,
            "sibling_not_ready_count": sibling_not_ready_count,
            "sibling_same_chain_hydroxyl_hit_count": sibling_same_chain_hit_count,
            "sibling_counteraxis_blocked_hit_count": sibling_blocked_hit_count,
            "sibling_residual_false_hit_count": len(sibling_residual_hit_pdb_ids),
            "sibling_residual_false_hit_pdb_ids": sibling_residual_hit_pdb_ids,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "acceptor_chain_counteraxis_broadened_to_current_heteromeric_and_sibling_controls",
            "blocker_not_removed": [
                "source_free_kinase_substrate_role_assignment_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit broadens the current acceptor-chain ligand-context "
                "counter-axis over the bounded 50-structure heteromeric scout "
                "and measured sibling-family controls. It uses source labels "
                "only to score the review probe outcome and remains invalid "
                "for production scoring."
            ),
            "next_actions": [
                "add a source-free kinase/substrate role-assignment signal before scorer design",
                "keep threshold calibration closed until the role axis and external scored re-audit exist",
                "do not convert this broader counteraxis into a countable fingerprint gate",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Broadened counteraxis controls are review-only and do not "
                "authorize ePK scoring, registry edits, or label imports."
            )
        ],
    }


def build_epk_heteromeric_ligand_asymmetry_role_audit(
    *,
    epk_heteromeric_broader_counteraxis_control_audit: dict[str, Any],
) -> dict[str, Any]:
    """Evaluate ligand-context asymmetry as a source-free heteromeric role axis."""

    broader_meta = epk_heteromeric_broader_counteraxis_control_audit.get(
        "metadata", {}
    )
    if not isinstance(broader_meta, dict):
        broader_meta = {}
    target_fingerprint_id = str(
        broader_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    rows: list[dict[str, Any]] = []
    heteromeric_initial_hit_count = 0
    heteromeric_role_asymmetry_hit_count = 0
    retained_source_valid_role_hit_count = 0
    nonaccepted_role_hit_pdb_ids: list[str] = []
    blocked_nonaccepted_pdb_ids: list[str] = []
    sibling_control_row_count = 0
    sibling_blocked_hit_count = 0
    sibling_role_asymmetry_false_hit_pdb_ids: list[str] = []

    for row in epk_heteromeric_broader_counteraxis_control_audit.get(
        "rows", []
    ) or []:
        if not isinstance(row, dict):
            continue
        row_type = str(row.get("row_type") or "")
        pdb_id = str(row.get("pdb_id") or "").upper()
        if row_type == "heteromeric_broader_counteraxis_control":
            initial_hit = bool(row.get("initial_topology_gamma_rule_hit"))
            if initial_hit:
                heteromeric_initial_hit_count += 1
            source_validated = bool(
                row.get("source_validated_positive_like_review_context")
            )
            role_asymmetry_hit = bool(row.get("source_free_counteraxis_hit"))
            if role_asymmetry_hit:
                heteromeric_role_asymmetry_hit_count += 1
            if role_asymmetry_hit and source_validated:
                retained_source_valid_role_hit_count += 1
                decision = (
                    "ligand_asymmetry_supports_heteromeric_role_assignment_review_only"
                )
            elif role_asymmetry_hit:
                nonaccepted_role_hit_pdb_ids.append(pdb_id)
                decision = "ligand_asymmetry_residual_nonaccepted_role_hit_review_only"
            elif initial_hit:
                blocked_nonaccepted_pdb_ids.append(pdb_id)
                decision = "ligand_asymmetry_blocks_nonaccepted_or_ambiguous_hit"
            else:
                decision = "ligand_asymmetry_not_applicable_no_topology_gamma_hit"
            rows.append(
                {
                    "row_type": "heteromeric_ligand_asymmetry_role_audit",
                    "pdb_id": pdb_id,
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "initial_topology_gamma_rule_hit": initial_hit,
                    "source_free_ligand_asymmetry_role_hit": role_asymmetry_hit,
                    "source_validated_positive_like_review_context": (
                        source_validated
                    ),
                    "source_validation_status_review_context": row.get(
                        "source_validation_status_review_context"
                    ),
                    "role_axis_decision": decision,
                    "production_scoring_admissible": False,
                    "text_free_inputs_only": True,
                    "remaining_blockers": [
                        "source_free_acceptor_identity_missing",
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                        "registry_and_label_factory_extension_not_implemented",
                    ],
                }
            )
        elif row_type == "sibling_broader_counteraxis_control":
            sibling_control_row_count += 1
            blocked = bool(row.get("source_free_counteraxis_blocks_hit"))
            if blocked:
                sibling_blocked_hit_count += 1
            role_asymmetry_false_hit = bool(
                row.get("same_chain_hydroxyl_threshold_hit")
            ) and not blocked
            if role_asymmetry_false_hit:
                sibling_role_asymmetry_false_hit_pdb_ids.append(pdb_id)
            rows.append(
                {
                    "row_type": "sibling_ligand_asymmetry_role_audit",
                    "pdb_id": pdb_id,
                    "family_id": row.get("family_id"),
                    "family_name": row.get("family_name"),
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "same_chain_hydroxyl_threshold_hit": bool(
                        row.get("same_chain_hydroxyl_threshold_hit")
                    ),
                    "source_free_ligand_asymmetry_role_hit": (
                        role_asymmetry_false_hit
                    ),
                    "role_axis_decision": (
                        "ligand_asymmetry_blocks_same_chain_sibling_control"
                        if blocked
                        else "ligand_asymmetry_abstain_or_unmeasured_sibling_control"
                    ),
                    "production_scoring_admissible": False,
                    "text_free_inputs_only": True,
                    "remaining_blockers": [
                        "sibling_family_control_not_epk_positive_label",
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                    ],
                }
            )

    nonaccepted_role_hit_pdb_ids = _sorted_strings(nonaccepted_role_hit_pdb_ids)
    blocked_nonaccepted_pdb_ids = _sorted_strings(blocked_nonaccepted_pdb_ids)
    sibling_role_asymmetry_false_hit_pdb_ids = _sorted_strings(
        sibling_role_asymmetry_false_hit_pdb_ids
    )
    role_axis_passed = (
        heteromeric_initial_hit_count > 0
        and not nonaccepted_role_hit_pdb_ids
        and not sibling_role_asymmetry_false_hit_pdb_ids
    )
    role_axis_status = (
        "passes_current_ligand_asymmetry_role_controls_not_scoring_admissible"
        if role_axis_passed
        else "blocked_review_only_ligand_asymmetry_role_false_hit_risk"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_ligand_asymmetry_role_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_broader_counteraxis_control_audit_method": (
                broader_meta.get("method")
            ),
            "role_axis_status": role_axis_status,
            "role_axis_passed_review_only": role_axis_passed,
            "heteromeric_initial_hit_count": heteromeric_initial_hit_count,
            "heteromeric_ligand_asymmetry_role_hit_count": (
                heteromeric_role_asymmetry_hit_count
            ),
            "retained_source_valid_role_hit_count": (
                retained_source_valid_role_hit_count
            ),
            "nonaccepted_role_hit_count": len(nonaccepted_role_hit_pdb_ids),
            "nonaccepted_role_hit_pdb_ids": nonaccepted_role_hit_pdb_ids,
            "blocked_nonaccepted_or_ambiguous_hit_count": len(
                blocked_nonaccepted_pdb_ids
            ),
            "blocked_nonaccepted_or_ambiguous_hit_pdb_ids": (
                blocked_nonaccepted_pdb_ids
            ),
            "sibling_control_row_count": sibling_control_row_count,
            "sibling_same_chain_blocked_hit_count": sibling_blocked_hit_count,
            "sibling_role_asymmetry_false_hit_count": len(
                sibling_role_asymmetry_false_hit_pdb_ids
            ),
            "sibling_role_asymmetry_false_hit_pdb_ids": (
                sibling_role_asymmetry_false_hit_pdb_ids
            ),
            "source_free_role_assignment_ready_count": (
                retained_source_valid_role_hit_count
            ),
            "source_free_acceptor_identity_ready_count": 0,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "source_free_heteromeric_ligand_asymmetry_role_axis_reviewed",
            "blocker_not_removed": [
                "source_free_acceptor_identity_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit treats ligand-context asymmetry as a source-free "
                "role-direction signal only when the gamma-associated chain "
                "has the local nucleotide/metal site and the candidate "
                "acceptor chain lacks ligand-site context. It remains "
                "review-only and does not establish acceptor identity."
            ),
            "next_actions": [
                "add a source-free acceptor-identity axis for retained heteromeric role hits",
                "keep scorer design fail-closed until role and acceptor axes are both local",
                "rerun external hard negatives only after a calibrated ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Ligand-asymmetry role assignment is review-only and cannot "
                "replace acceptor identity, threshold calibration, or scored "
                "external hard-negative re-audit."
            )
        ],
    }


def build_epk_heteromeric_acceptor_identity_gap_audit(
    *,
    epk_heteromeric_ligand_asymmetry_role_audit: dict[str, Any],
    epk_heteromeric_candidate_source_validation_review: dict[str, Any],
) -> dict[str, Any]:
    """Record source-free acceptor-identity blockers for heteromeric role hits."""

    role_meta = epk_heteromeric_ligand_asymmetry_role_audit.get("metadata", {})
    if not isinstance(role_meta, dict):
        role_meta = {}
    validation_meta = epk_heteromeric_candidate_source_validation_review.get(
        "metadata", {}
    )
    if not isinstance(validation_meta, dict):
        validation_meta = {}
    target_fingerprint_id = str(
        role_meta.get("target_fingerprint_id")
        or validation_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    validation_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_heteromeric_candidate_source_validation_review.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    }

    rows: list[dict[str, Any]] = []
    retained_role_hit_count = 0
    source_context_only_identity_count = 0
    source_free_acceptor_identity_ready_count = 0
    candidate_residue_codes: set[str] = set()
    role_hit_pdb_ids: list[str] = []

    for role_row in epk_heteromeric_ligand_asymmetry_role_audit.get(
        "rows", []
    ) or []:
        if not isinstance(role_row, dict):
            continue
        if (
            role_row.get("role_axis_decision")
            != "ligand_asymmetry_supports_heteromeric_role_assignment_review_only"
        ):
            continue
        retained_role_hit_count += 1
        pdb_id = str(role_row.get("pdb_id") or "").upper()
        role_hit_pdb_ids.append(pdb_id)
        validation_row = validation_by_pdb.get(pdb_id, {})
        candidate_hits = [
            hit
            for hit in validation_row.get("candidate_hits", []) or []
            if isinstance(hit, dict)
        ]
        candidate_acceptor_residues: list[dict[str, Any]] = []
        for hit in candidate_hits:
            residue_code = str(hit.get("candidate_residue_code") or "").upper()
            if residue_code:
                candidate_residue_codes.add(residue_code)
            candidate_acceptor_residues.append(
                {
                    "candidate_chain_name": hit.get("candidate_chain_name"),
                    "candidate_auth_seq_id": hit.get("candidate_auth_seq_id"),
                    "candidate_residue_code": residue_code or None,
                    "candidate_atom_name": hit.get("candidate_atom_name"),
                    "nearest_gamma_distance_angstrom": hit.get(
                        "nearest_gamma_distance_angstrom"
                    ),
                }
            )
        source_context_only_identity_count += 1
        rows.append(
            {
                "row_type": "heteromeric_acceptor_identity_gap",
                "pdb_id": pdb_id,
                "source_pair_id": validation_row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "source_free_role_assignment_present": True,
                "source_free_acceptor_identity_present": False,
                "source_context_acceptor_identity_present": True,
                "candidate_acceptor_residues_review_context": (
                    candidate_acceptor_residues
                ),
                "source_validation_status_review_context": validation_row.get(
                    "source_validation_status"
                ),
                "acceptor_identity_gap_status": (
                    "blocked_source_free_acceptor_identity_missing_review_only"
                ),
                "production_scoring_admissible": False,
                "text_free_inputs_only": True,
                "remaining_blockers": [
                    "source_free_acceptor_identity_missing",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    role_hit_pdb_ids = _sorted_strings(role_hit_pdb_ids)
    status = (
        "blocked_review_only_source_free_acceptor_identity_missing"
        if retained_role_hit_count
        and source_free_acceptor_identity_ready_count == 0
        else "source_free_acceptor_identity_gap_not_assessed"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_acceptor_identity_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_ligand_asymmetry_role_audit_method": (
                role_meta.get("method")
            ),
            "source_epk_heteromeric_candidate_source_validation_review_method": (
                validation_meta.get("method")
            ),
            "acceptor_identity_gap_status": status,
            "retained_role_hit_count": retained_role_hit_count,
            "retained_role_hit_pdb_ids": role_hit_pdb_ids,
            "source_context_only_acceptor_identity_count": (
                source_context_only_identity_count
            ),
            "source_free_acceptor_identity_ready_count": (
                source_free_acceptor_identity_ready_count
            ),
            "candidate_acceptor_residue_codes_review_context": _sorted_strings(
                candidate_residue_codes
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "heteromeric_acceptor_identity_gap_made_explicit",
            "blocker_not_removed": [
                "source_free_acceptor_identity_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit deliberately treats source-supported substrate "
                "identity as review context only. Retained heteromeric role "
                "hits remain blocked until a local source-free acceptor "
                "identity feature exists."
            ),
            "next_actions": [
                "test a source-free acceptor-identity rule on retained heteromeric role hits",
                "include nonaccepted BRAF/MEK and sibling-family controls when that identity rule is probed",
                "keep ePK scoring and external hard-negative re-audit closed",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Heteromeric acceptor identity is still review-context only; "
                "this artifact is a blocker audit, not a scoring input."
            )
        ],
    }


def build_epk_heteromeric_acceptor_identity_rule_probe(
    *,
    epk_heteromeric_acceptor_identity_gap_audit: dict[str, Any],
    epk_heteromeric_broader_counteraxis_control_audit: dict[str, Any],
) -> dict[str, Any]:
    """Probe a generic source-free hydroxyl acceptor-identity rule."""

    gap_meta = epk_heteromeric_acceptor_identity_gap_audit.get("metadata", {})
    if not isinstance(gap_meta, dict):
        gap_meta = {}
    broader_meta = epk_heteromeric_broader_counteraxis_control_audit.get(
        "metadata", {}
    )
    if not isinstance(broader_meta, dict):
        broader_meta = {}
    target_fingerprint_id = str(
        gap_meta.get("target_fingerprint_id")
        or broader_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    hydroxyl_residue_codes = {"SER", "THR", "TYR"}

    rows: list[dict[str, Any]] = []
    positive_rule_hit_count = 0
    nonaccepted_blocked_before_identity_count = 0
    nonaccepted_rule_hit_pdb_ids: list[str] = []
    sibling_same_chain_blocked_before_identity_count = 0
    sibling_rule_false_hit_pdb_ids: list[str] = []

    for row in epk_heteromeric_acceptor_identity_gap_audit.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        candidate_residues = [
            residue
            for residue in row.get("candidate_acceptor_residues_review_context", [])
            or []
            if isinstance(residue, dict)
        ]
        residue_codes = _sorted_strings(
            str(residue.get("candidate_residue_code") or "").upper()
            for residue in candidate_residues
            if residue.get("candidate_residue_code")
        )
        rule_hit = bool(set(residue_codes) & hydroxyl_residue_codes)
        if rule_hit:
            positive_rule_hit_count += 1
        rows.append(
            {
                "row_type": "heteromeric_acceptor_identity_rule_probe",
                "pdb_id": row.get("pdb_id"),
                "source_pair_id": row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_acceptor_residue_codes": residue_codes,
                "generic_hydroxyl_acceptor_rule_hit": rule_hit,
                "source_free_acceptor_identity_rule_status": (
                    "generic_hydroxyl_rule_hits_retained_role_candidate_review_only"
                    if rule_hit
                    else "generic_hydroxyl_rule_miss_review_only"
                ),
                "production_scoring_admissible": False,
                "text_free_inputs_only": True,
                "remaining_blockers": [
                    "generic_hydroxyl_identity_rule_not_specific_enough",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    for row in epk_heteromeric_broader_counteraxis_control_audit.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        pdb_id = str(row.get("pdb_id") or "").upper()
        row_type = str(row.get("row_type") or "")
        if row_type == "heteromeric_broader_counteraxis_control":
            if not row.get("initial_topology_gamma_rule_hit"):
                continue
            if row.get("source_free_counteraxis_hit"):
                continue
            nonaccepted_blocked_before_identity_count += 1
            rows.append(
                {
                    "row_type": "heteromeric_nonaccepted_identity_rule_control",
                    "pdb_id": pdb_id,
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "generic_hydroxyl_acceptor_rule_hit": False,
                    "source_free_acceptor_identity_rule_status": (
                        "blocked_before_identity_rule_by_ligand_asymmetry"
                    ),
                    "source_validation_status_review_context": row.get(
                        "source_validation_status_review_context"
                    ),
                    "production_scoring_admissible": False,
                    "text_free_inputs_only": True,
                    "remaining_blockers": [
                        "nonaccepted_or_ambiguous_heteromeric_control",
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                    ],
                }
            )
        elif row_type == "sibling_broader_counteraxis_control":
            rule_false_hit = bool(row.get("same_chain_hydroxyl_threshold_hit")) and not bool(
                row.get("source_free_counteraxis_blocks_hit")
            )
            if (
                bool(row.get("same_chain_hydroxyl_threshold_hit"))
                and bool(row.get("source_free_counteraxis_blocks_hit"))
            ):
                sibling_same_chain_blocked_before_identity_count += 1
            if rule_false_hit:
                sibling_rule_false_hit_pdb_ids.append(pdb_id)
            rows.append(
                {
                    "row_type": "sibling_identity_rule_control",
                    "pdb_id": pdb_id,
                    "family_id": row.get("family_id"),
                    "family_name": row.get("family_name"),
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "generic_hydroxyl_acceptor_rule_hit": rule_false_hit,
                    "source_free_acceptor_identity_rule_status": (
                        "sibling_same_chain_control_blocked_before_identity_rule"
                        if not rule_false_hit
                        else "sibling_identity_rule_false_hit_risk"
                    ),
                    "production_scoring_admissible": False,
                    "text_free_inputs_only": True,
                    "remaining_blockers": [
                        "sibling_family_control_not_epk_positive_label",
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                    ],
                }
            )

    sibling_rule_false_hit_pdb_ids = _sorted_strings(sibling_rule_false_hit_pdb_ids)
    nonaccepted_rule_hit_pdb_ids = _sorted_strings(nonaccepted_rule_hit_pdb_ids)
    current_controls_pass = (
        positive_rule_hit_count == int(gap_meta.get("retained_role_hit_count") or 0)
        and not nonaccepted_rule_hit_pdb_ids
        and not sibling_rule_false_hit_pdb_ids
    )
    status = (
        "passes_current_controls_but_generic_identity_axis_weak_review_only"
        if current_controls_pass
        else "blocked_review_only_acceptor_identity_rule_false_hit_risk"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_acceptor_identity_rule_probe",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_acceptor_identity_gap_audit_method": (
                gap_meta.get("method")
            ),
            "source_epk_heteromeric_broader_counteraxis_control_audit_method": (
                broader_meta.get("method")
            ),
            "identity_rule_status": status,
            "generic_hydroxyl_residue_rule": sorted(hydroxyl_residue_codes),
            "retained_role_hit_count": gap_meta.get("retained_role_hit_count"),
            "positive_identity_rule_hit_count": positive_rule_hit_count,
            "nonaccepted_blocked_before_identity_rule_count": (
                nonaccepted_blocked_before_identity_count
            ),
            "nonaccepted_identity_rule_hit_count": len(nonaccepted_rule_hit_pdb_ids),
            "nonaccepted_identity_rule_hit_pdb_ids": nonaccepted_rule_hit_pdb_ids,
            "sibling_same_chain_blocked_before_identity_rule_count": (
                sibling_same_chain_blocked_before_identity_count
            ),
            "sibling_identity_rule_false_hit_count": len(
                sibling_rule_false_hit_pdb_ids
            ),
            "sibling_identity_rule_false_hit_pdb_ids": (
                sibling_rule_false_hit_pdb_ids
            ),
            "generic_identity_axis_weak": True,
            "weak_axes": [
                "generic_hydroxyl_residue_class_not_substrate_identity",
                "no_independent_phosphoacceptor_or_substrate_chain_evidence",
                "not_tested_as_calibrated_score",
            ],
            "source_free_acceptor_identity_ready_count": 0,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "generic_hydroxyl_identity_rule_probe_executed",
            "blocker_not_removed": [
                "generic_hydroxyl_identity_rule_not_specific_enough",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This probe tests the weakest plausible source-free acceptor "
                "identity axis: Ser/Thr/Tyr hydroxyl residue class on retained "
                "role-asymmetric heteromeric hits. Passing current controls "
                "does not make it production admissible because residue class "
                "is not substrate identity."
            ),
            "next_actions": [
                "add a non-generic acceptor identity signal beyond Ser/Thr/Tyr class",
                "probe retained heteromeric role hits against BRAF/MEK and sibling controls after that signal changes",
                "keep external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "Generic hydroxyl residue identity is a weak review-only axis "
                "and is not production scorer evidence."
            )
        ],
    }


def build_epk_heteromeric_peptide_acceptor_identity_probe(
    *,
    epk_heteromeric_acceptor_identity_gap_audit: dict[str, Any],
    epk_heteromeric_candidate_source_validation_review: dict[str, Any],
    epk_heteromeric_broader_counteraxis_control_audit: dict[str, Any],
    epk_sibling_control_artifacts: list[dict[str, Any]] | None = None,
    candidate_threshold_angstrom: float = 6.0,
    max_peptide_chain_residue_count: int = 40,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Probe peptide-like acceptor-chain context as a non-generic local axis."""

    gap_meta = epk_heteromeric_acceptor_identity_gap_audit.get("metadata", {})
    if not isinstance(gap_meta, dict):
        gap_meta = {}
    validation_meta = epk_heteromeric_candidate_source_validation_review.get(
        "metadata", {}
    )
    if not isinstance(validation_meta, dict):
        validation_meta = {}
    broader_meta = epk_heteromeric_broader_counteraxis_control_audit.get(
        "metadata", {}
    )
    if not isinstance(broader_meta, dict):
        broader_meta = {}
    sibling_artifacts = epk_sibling_control_artifacts or []
    sibling_metas: list[dict[str, Any]] = []
    for artifact in sibling_artifacts:
        if not isinstance(artifact, dict):
            continue
        meta = artifact.get("metadata", {})
        if isinstance(meta, dict):
            sibling_metas.append(meta)

    target_fingerprint_id = str(
        gap_meta.get("target_fingerprint_id")
        or validation_meta.get("target_fingerprint_id")
        or broader_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(candidate_threshold_angstrom)
    except (TypeError, ValueError):
        threshold = 6.0
    try:
        peptide_limit = int(max_peptide_chain_residue_count)
    except (TypeError, ValueError):
        peptide_limit = 40
    peptide_limit = max(1, peptide_limit)

    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    cif_cache: dict[str, tuple[str, str, str | None]] = {}
    hydroxyl_residue_codes = {"SER", "THR", "TYR"}
    nucleotide_or_metal_codes = {
        "ACP",
        "ADP",
        "AGS",
        "AMP",
        "ANP",
        "APC",
        "ATP",
        "DTP",
        "GTP",
        *METAL_ION_CODES,
    }

    def _load_cif(pdb_id: str) -> tuple[str, str, str | None]:
        if pdb_id in cif_cache:
            return cif_cache[pdb_id]
        cif_text = cif_texts.get(pdb_id)
        fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
        fetch_error = None
        try:
            if cif_text is None and pdb_id:
                cif_text = cif_fetcher(pdb_id)
        except Exception as exc:  # pragma: no cover - network failure is data.
            cif_text = ""
            fetch_status = "fetch_failed"
            fetch_error = str(exc)
        result = (cif_text or "", fetch_status, fetch_error)
        cif_cache[pdb_id] = result
        return result

    def _chain_profiles(cif_text: str) -> tuple[dict[str, int], dict[str, list[str]]]:
        chain_residues: dict[str, set[tuple[str, str]]] = defaultdict(set)
        chain_ligands: dict[str, set[str]] = defaultdict(set)
        for atom in parse_atom_site_loop(cif_text):
            chain_id = str(
                atom.get("auth_asym_id") or atom.get("label_asym_id") or ""
            )
            if not chain_id:
                continue
            code = _epk_atom_code(atom)
            if atom.get("group_PDB") == "ATOM":
                seq_id = str(
                    atom.get("auth_seq_id") or atom.get("label_seq_id") or ""
                )
                if seq_id:
                    chain_residues[chain_id].add((seq_id, code))
            elif atom.get("group_PDB") == "HETATM" and code:
                chain_ligands[chain_id].add(code)
        return (
            {
                chain_id: len(residue_keys)
                for chain_id, residue_keys in chain_residues.items()
            },
            {
                chain_id: sorted(codes)
                for chain_id, codes in chain_ligands.items()
            },
        )

    def _hit_chain_evidence(
        pdb_id: str,
        hit: dict[str, Any],
    ) -> tuple[dict[str, Any], str]:
        cif_text, fetch_status, fetch_error = _load_cif(pdb_id)
        if not cif_text:
            return (
                {
                    "fetch_status": fetch_status,
                    "fetch_error": fetch_error,
                    "acceptor_chain_residue_count": None,
                    "gamma_chain_residue_count": None,
                    "acceptor_chain_nucleotide_or_metal_ligand_codes": [],
                    "peptide_like_acceptor_chain": False,
                    "acceptor_chain_lacks_local_nucleotide_or_metal": False,
                    "gamma_chain_is_larger_polymer": False,
                },
                "peptide_acceptor_identity_unmapped_fetch_failed",
            )
        chain_lengths, chain_ligands = _chain_profiles(cif_text)
        acceptor_chain = str(hit.get("candidate_chain_name") or "")
        gamma_chain = str(hit.get("gamma_associated_polymer_chain_name") or "")
        acceptor_length = chain_lengths.get(acceptor_chain)
        gamma_length = chain_lengths.get(gamma_chain)
        acceptor_ligands = chain_ligands.get(acceptor_chain, [])
        acceptor_has_ligand_context = bool(
            set(acceptor_ligands) & nucleotide_or_metal_codes
        )
        peptide_like = (
            acceptor_length is not None
            and 1 <= acceptor_length <= peptide_limit
        )
        gamma_larger = (
            gamma_length is not None
            and acceptor_length is not None
            and gamma_length > peptide_limit
            and gamma_length > acceptor_length
        )
        local_rule_hit = peptide_like and gamma_larger and not acceptor_has_ligand_context
        status = (
            "peptide_like_acceptor_identity_rule_hit_review_only"
            if local_rule_hit
            else "peptide_like_acceptor_identity_rule_miss_review_only"
        )
        return (
            {
                "fetch_status": fetch_status,
                "fetch_error": fetch_error,
                "acceptor_chain_residue_count": acceptor_length,
                "gamma_chain_residue_count": gamma_length,
                "acceptor_chain_nucleotide_or_metal_ligand_codes": [
                    code
                    for code in acceptor_ligands
                    if code in nucleotide_or_metal_codes
                ],
                "peptide_like_acceptor_chain": peptide_like,
                "acceptor_chain_lacks_local_nucleotide_or_metal": (
                    not acceptor_has_ligand_context
                ),
                "gamma_chain_is_larger_polymer": gamma_larger,
            },
            status,
        )

    validation_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_heteromeric_candidate_source_validation_review.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    }
    broader_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_heteromeric_broader_counteraxis_control_audit.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and row.get("row_type") == "heteromeric_broader_counteraxis_control"
    }

    rows: list[dict[str, Any]] = []
    positive_rule_hit_count = 0
    positive_rule_miss_count = 0
    nonaccepted_candidate_count = 0
    nonaccepted_false_hit_pdb_ids: list[str] = []
    sibling_candidate_count = 0
    sibling_false_hit_pdb_ids: list[str] = []

    for gap_row in epk_heteromeric_acceptor_identity_gap_audit.get("rows", []) or []:
        if not isinstance(gap_row, dict):
            continue
        pdb_id = str(gap_row.get("pdb_id") or "").upper()
        validation_row = validation_by_pdb.get(pdb_id, {})
        hits = [
            hit
            for hit in validation_row.get("candidate_hits", []) or []
            if isinstance(hit, dict)
            and str(hit.get("candidate_residue_code") or "").upper()
            in hydroxyl_residue_codes
            and float(hit.get("nearest_gamma_distance_angstrom") or 9999.0)
            <= threshold
        ]
        best_hit = hits[0] if hits else {}
        evidence, rule_status = _hit_chain_evidence(pdb_id, best_hit)
        rule_hit = rule_status == "peptide_like_acceptor_identity_rule_hit_review_only"
        if rule_hit:
            positive_rule_hit_count += 1
            decision = "retained_role_hit_peptide_acceptor_identity_review_only"
        else:
            positive_rule_miss_count += 1
            decision = "retained_role_hit_peptide_acceptor_identity_missing"
        rows.append(
            {
                "row_type": "heteromeric_peptide_acceptor_identity_candidate",
                "pdb_id": pdb_id,
                "source_pair_id": gap_row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "text_free_inputs_only": True,
                "candidate_threshold_angstrom": threshold,
                "max_peptide_chain_residue_count": peptide_limit,
                "candidate_acceptor_residue_code": best_hit.get(
                    "candidate_residue_code"
                ),
                "candidate_acceptor_chain_name": best_hit.get(
                    "candidate_chain_name"
                ),
                "candidate_acceptor_auth_seq_id": best_hit.get(
                    "candidate_auth_seq_id"
                ),
                "gamma_associated_polymer_chain_name": best_hit.get(
                    "gamma_associated_polymer_chain_name"
                ),
                "nearest_gamma_distance_angstrom": best_hit.get(
                    "nearest_gamma_distance_angstrom"
                ),
                **evidence,
                "peptide_like_acceptor_identity_rule_hit": rule_hit,
                "peptide_acceptor_identity_rule_status": rule_status,
                "peptide_acceptor_identity_decision": decision,
                "production_scoring_admissible": False,
                "remaining_blockers": [
                    "peptide_chain_identity_axis_narrow_not_general_epk_acceptor_identity",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    for pdb_id, broader_row in sorted(broader_by_pdb.items()):
        if not bool(broader_row.get("initial_topology_gamma_rule_hit")):
            continue
        if bool(broader_row.get("source_free_counteraxis_hit")):
            continue
        validation_row = validation_by_pdb.get(pdb_id, {})
        hits = [
            hit
            for hit in validation_row.get("candidate_hits", []) or []
            if isinstance(hit, dict)
            and str(hit.get("candidate_residue_code") or "").upper()
            in hydroxyl_residue_codes
            and float(hit.get("nearest_gamma_distance_angstrom") or 9999.0)
            <= threshold
        ]
        if not hits:
            continue
        nonaccepted_candidate_count += 1
        best_hit = hits[0]
        evidence, rule_status = _hit_chain_evidence(pdb_id, best_hit)
        rule_hit = rule_status == "peptide_like_acceptor_identity_rule_hit_review_only"
        if rule_hit:
            nonaccepted_false_hit_pdb_ids.append(pdb_id)
        rows.append(
            {
                "row_type": "heteromeric_nonaccepted_peptide_identity_control",
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "text_free_inputs_only": True,
                "source_validation_status_review_context": broader_row.get(
                    "source_validation_status_review_context"
                ),
                "candidate_threshold_angstrom": threshold,
                "max_peptide_chain_residue_count": peptide_limit,
                "candidate_acceptor_residue_code": best_hit.get(
                    "candidate_residue_code"
                ),
                "candidate_acceptor_chain_name": best_hit.get(
                    "candidate_chain_name"
                ),
                "candidate_acceptor_auth_seq_id": best_hit.get(
                    "candidate_auth_seq_id"
                ),
                "gamma_associated_polymer_chain_name": best_hit.get(
                    "gamma_associated_polymer_chain_name"
                ),
                "nearest_gamma_distance_angstrom": best_hit.get(
                    "nearest_gamma_distance_angstrom"
                ),
                **evidence,
                "peptide_like_acceptor_identity_rule_hit": rule_hit,
                "peptide_acceptor_identity_rule_status": (
                    "nonaccepted_control_false_hit_review_only"
                    if rule_hit
                    else "nonaccepted_control_blocked_by_peptide_identity_rule"
                ),
                "production_scoring_admissible": False,
                "remaining_blockers": [
                    "nonaccepted_or_ambiguous_heteromeric_control",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                ],
            }
        )

    for artifact in sibling_artifacts:
        if not isinstance(artifact, dict):
            continue
        for sample_row in artifact.get("rows", []) or []:
            if not isinstance(sample_row, dict):
                continue
            pdb_id = str(sample_row.get("pdb_id") or "").upper()
            sibling_candidates = [
                hit
                for hit in sample_row.get("same_chain_hydroxyl_distance_rows", [])
                or []
                if isinstance(hit, dict)
                and float(hit.get("distance_angstrom") or 9999.0) <= threshold
            ]
            if not sibling_candidates:
                continue
            sibling_candidate_count += 1
            best_hit = sibling_candidates[0]
            normalized_hit = {
                "candidate_chain_name": best_hit.get("hydroxyl_chain_name")
                or best_hit.get("chain_id"),
                "candidate_auth_seq_id": best_hit.get("hydroxyl_resid"),
                "candidate_residue_code": best_hit.get("hydroxyl_residue_code"),
                "gamma_associated_polymer_chain_name": best_hit.get("chain_id")
                or best_hit.get("hydroxyl_chain_name"),
                "nearest_gamma_distance_angstrom": best_hit.get(
                    "distance_angstrom"
                ),
            }
            evidence, rule_status = _hit_chain_evidence(pdb_id, normalized_hit)
            rule_hit = rule_status == "peptide_like_acceptor_identity_rule_hit_review_only"
            if rule_hit:
                sibling_false_hit_pdb_ids.append(pdb_id)
            rows.append(
                {
                    "row_type": "sibling_peptide_identity_control",
                    "pdb_id": pdb_id,
                    "family_id": sample_row.get("family_id"),
                    "family_name": sample_row.get("family_name"),
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "text_free_inputs_only": True,
                    "candidate_threshold_angstrom": threshold,
                    "max_peptide_chain_residue_count": peptide_limit,
                    "candidate_acceptor_residue_code": normalized_hit.get(
                        "candidate_residue_code"
                    ),
                    "candidate_acceptor_chain_name": normalized_hit.get(
                        "candidate_chain_name"
                    ),
                    "candidate_acceptor_auth_seq_id": normalized_hit.get(
                        "candidate_auth_seq_id"
                    ),
                    "gamma_associated_polymer_chain_name": normalized_hit.get(
                        "gamma_associated_polymer_chain_name"
                    ),
                    "nearest_gamma_distance_angstrom": normalized_hit.get(
                        "nearest_gamma_distance_angstrom"
                    ),
                    **evidence,
                    "peptide_like_acceptor_identity_rule_hit": rule_hit,
                    "peptide_acceptor_identity_rule_status": (
                        "sibling_control_false_hit_review_only"
                        if rule_hit
                        else "sibling_control_blocked_by_peptide_identity_rule"
                    ),
                    "production_scoring_admissible": False,
                    "remaining_blockers": [
                        "sibling_family_control_not_epk_positive_label",
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                    ],
                }
            )

    nonaccepted_false_hit_pdb_ids = _sorted_strings(nonaccepted_false_hit_pdb_ids)
    sibling_false_hit_pdb_ids = _sorted_strings(sibling_false_hit_pdb_ids)
    retained_role_hit_count = int(gap_meta.get("retained_role_hit_count") or 0)
    current_controls_pass = (
        retained_role_hit_count > 0
        and positive_rule_hit_count == retained_role_hit_count
        and positive_rule_miss_count == 0
        and not nonaccepted_false_hit_pdb_ids
        and not sibling_false_hit_pdb_ids
    )
    status = (
        "passes_current_controls_peptide_like_acceptor_identity_review_only"
        if current_controls_pass
        else "blocked_review_only_peptide_acceptor_identity_false_hit_or_gap"
    )
    return {
        "metadata": {
            "method": "epk_heteromeric_peptide_acceptor_identity_probe",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_acceptor_identity_gap_audit_method": (
                gap_meta.get("method")
            ),
            "source_epk_heteromeric_candidate_source_validation_review_method": (
                validation_meta.get("method")
            ),
            "source_epk_heteromeric_broader_counteraxis_control_audit_method": (
                broader_meta.get("method")
            ),
            "source_epk_sibling_control_artifact_methods": _sorted_strings(
                meta.get("method") for meta in sibling_metas if meta.get("method")
            ),
            "candidate_threshold_angstrom": threshold,
            "max_peptide_chain_residue_count": peptide_limit,
            "peptide_identity_axis_status": status,
            "retained_role_hit_count": retained_role_hit_count,
            "positive_peptide_identity_hit_count": positive_rule_hit_count,
            "positive_peptide_identity_miss_count": positive_rule_miss_count,
            "nonaccepted_control_candidate_count": nonaccepted_candidate_count,
            "nonaccepted_peptide_identity_false_hit_count": len(
                nonaccepted_false_hit_pdb_ids
            ),
            "nonaccepted_peptide_identity_false_hit_pdb_ids": (
                nonaccepted_false_hit_pdb_ids
            ),
            "sibling_control_candidate_count": sibling_candidate_count,
            "sibling_peptide_identity_false_hit_count": len(
                sibling_false_hit_pdb_ids
            ),
            "sibling_peptide_identity_false_hit_pdb_ids": (
                sibling_false_hit_pdb_ids
            ),
            "current_controls_passed_review_only": current_controls_pass,
            "peptide_identity_axis_narrow": True,
            "source_free_acceptor_identity_ready_count": (
                positive_rule_hit_count if current_controls_pass else 0
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "non_generic_peptide_acceptor_identity_probe_executed",
            "blocker_not_removed": [
                "peptide_chain_identity_axis_narrow_not_general_epk_acceptor_identity",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This probe tests a non-generic local acceptor-identity signal: "
                "the candidate hydroxyl must lie on a short peptide-like "
                "polymer chain without local nucleotide or metal ligand "
                "context, while the gamma-associated polymer is larger. Source "
                "labels are used only to label current controls; the rule "
                "does not score ePK, select thresholds, edit registries, or "
                "run external hard-negative re-audits."
            ),
            "next_actions": [
                "stress-test peptide-like acceptor identity on broader heteromeric kinase-substrate co-complexes",
                "add a general substrate-chain identity axis for non-peptide protein substrates before production scoring",
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                str(row.get("family_id") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Peptide-like acceptor identity is a narrow review-only signal; "
                "it does not make an ePK production scorer or held-out claim."
            )
        ],
    }


def build_epk_heteromeric_peptide_external_hard_negative_probe(
    *,
    epk_heteromeric_peptide_acceptor_identity_probe: dict[str, Any],
    external_hard_negative_inverse_gate_scores: list[dict[str, Any]] | None = None,
    imported_external_entry_ids: list[str] | None = None,
    max_peptide_chain_residue_count: int | None = None,
) -> dict[str, Any]:
    """Screen external hard negatives against the peptide-identity review axis."""

    peptide_meta = epk_heteromeric_peptide_acceptor_identity_probe.get(
        "metadata", {}
    )
    if not isinstance(peptide_meta, dict):
        peptide_meta = {}
    target_fingerprint_id = str(
        peptide_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    expected_external_ids = sorted(
        set(
            imported_external_entry_ids
            or ["uniprot:P06744", "uniprot:P78549", "uniprot:Q3LXA3"]
        ),
        key=_entry_id_sort_key,
    )
    try:
        threshold = float(peptide_meta.get("candidate_threshold_angstrom") or 6.0)
    except (TypeError, ValueError):
        threshold = 6.0
    try:
        peptide_limit = int(
            max_peptide_chain_residue_count
            if max_peptide_chain_residue_count is not None
            else peptide_meta.get("max_peptide_chain_residue_count") or 40
        )
    except (TypeError, ValueError):
        peptide_limit = 40
    peptide_limit = max(1, peptide_limit)

    source_artifacts = external_hard_negative_inverse_gate_scores or []
    source_metas: list[dict[str, Any]] = []
    external_rows_by_id: dict[str, dict[str, Any]] = {}
    for artifact in source_artifacts:
        if not isinstance(artifact, dict):
            continue
        meta = artifact.get("metadata", {})
        if isinstance(meta, dict):
            source_metas.append(meta)
        for row in artifact.get("rows", []) or []:
            if not isinstance(row, dict):
                continue
            entry_id = str(row.get("entry_id") or "")
            if entry_id in expected_external_ids and row.get("coordinate_path"):
                external_rows_by_id[entry_id] = row

    gamma_capable_codes = {
        "ACP",
        "AGS",
        "ANP",
        "APC",
        "ATP",
        "DTP",
        "GTP",
    }
    nucleotide_or_metal_codes = {
        "ACP",
        "ADP",
        "AGS",
        "AMP",
        "ANP",
        "APC",
        "ATP",
        "DTP",
        "GTP",
        *METAL_ION_CODES,
    }
    hydroxyl_atom_names = {
        "SER": {"OG"},
        "THR": {"OG1"},
        "TYR": {"OH"},
    }

    def _coordinate_path(path_text: Any) -> Path | None:
        if not path_text:
            return None
        path = Path(str(path_text))
        if not path.is_absolute():
            path = PROJECT_ROOT / path
        return path

    def _chain_profiles(
        atoms: list[dict[str, Any]],
    ) -> tuple[dict[str, int], dict[str, list[str]]]:
        chain_residues: dict[str, set[tuple[str, str]]] = defaultdict(set)
        chain_ligands: dict[str, set[str]] = defaultdict(set)
        for atom in atoms:
            chain_id = str(
                atom.get("auth_asym_id") or atom.get("label_asym_id") or ""
            )
            if not chain_id:
                continue
            code = _epk_atom_code(atom)
            if atom.get("group_PDB") == "ATOM":
                seq_id = str(
                    atom.get("auth_seq_id") or atom.get("label_seq_id") or ""
                )
                if seq_id:
                    chain_residues[chain_id].add((seq_id, code))
            elif atom.get("group_PDB") == "HETATM" and code:
                chain_ligands[chain_id].add(code)
        return (
            {
                chain_id: len(residue_keys)
                for chain_id, residue_keys in chain_residues.items()
            },
            {
                chain_id: sorted(codes)
                for chain_id, codes in chain_ligands.items()
            },
        )

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    non_abstention_entry_ids: list[str] = []
    missing_entry_ids: list[str] = []
    coordinate_unavailable_entry_ids: list[str] = []
    for entry_id in expected_external_ids:
        source_row = external_rows_by_id.get(entry_id, {})
        coordinate_path = _coordinate_path(source_row.get("coordinate_path"))
        coordinate_status = "available"
        atoms: list[dict[str, Any]] = []
        coordinate_error = None
        if not source_row:
            missing_entry_ids.append(entry_id)
            coordinate_status = "missing_external_inverse_gate_row"
        elif coordinate_path is None or not coordinate_path.exists():
            coordinate_unavailable_entry_ids.append(entry_id)
            coordinate_status = "coordinate_unavailable"
        else:
            try:
                atoms = parse_atom_site_loop(coordinate_path.read_text())
            except OSError as exc:
                coordinate_unavailable_entry_ids.append(entry_id)
                coordinate_status = "coordinate_read_failed"
                coordinate_error = str(exc)

        chain_lengths, chain_ligands = _chain_profiles(atoms) if atoms else ({}, {})
        gamma_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "HETATM"
            and _epk_atom_code(atom) in gamma_capable_codes
            and str(
                atom.get("auth_atom_id") or atom.get("label_atom_id") or ""
            ).upper()
            == "PG"
        ]
        hydroxyl_atoms = [
            atom
            for atom in atoms
            if atom.get("group_PDB") == "ATOM"
            and _epk_atom_code(atom) in hydroxyl_atom_names
            and str(
                atom.get("auth_atom_id") or atom.get("label_atom_id") or ""
            ).upper()
            in hydroxyl_atom_names.get(_epk_atom_code(atom), set())
        ]

        candidate_rows: list[dict[str, Any]] = []
        for gamma_atom in gamma_atoms:
            gamma_point = _atom_point(gamma_atom)
            gamma_chain = str(
                gamma_atom.get("auth_asym_id")
                or gamma_atom.get("label_asym_id")
                or ""
            )
            for hydroxyl_atom in hydroxyl_atoms:
                hydroxyl_point = _atom_point(hydroxyl_atom)
                distance = round(_point_distance(gamma_point, hydroxyl_point), 3)
                if distance > threshold:
                    continue
                acceptor_chain = str(
                    hydroxyl_atom.get("auth_asym_id")
                    or hydroxyl_atom.get("label_asym_id")
                    or ""
                )
                acceptor_length = chain_lengths.get(acceptor_chain)
                gamma_length = chain_lengths.get(gamma_chain)
                acceptor_ligands = chain_ligands.get(acceptor_chain, [])
                acceptor_has_ligand_context = bool(
                    set(acceptor_ligands) & nucleotide_or_metal_codes
                )
                peptide_like = (
                    acceptor_length is not None
                    and 1 <= acceptor_length <= peptide_limit
                )
                gamma_larger = (
                    gamma_length is not None
                    and acceptor_length is not None
                    and gamma_length > peptide_limit
                    and gamma_length > acceptor_length
                )
                rule_hit = (
                    peptide_like and gamma_larger and not acceptor_has_ligand_context
                )
                candidate_rows.append(
                    {
                        "gamma_ligand_code": _epk_atom_code(gamma_atom),
                        "gamma_chain_name": gamma_chain,
                        "gamma_chain_residue_count": gamma_length,
                        "acceptor_chain_name": acceptor_chain,
                        "acceptor_chain_residue_count": acceptor_length,
                        "acceptor_residue_code": _epk_atom_code(hydroxyl_atom),
                        "acceptor_auth_seq_id": str(
                            hydroxyl_atom.get("auth_seq_id")
                            or hydroxyl_atom.get("label_seq_id")
                            or ""
                        ),
                        "distance_angstrom": distance,
                        "acceptor_chain_nucleotide_or_metal_ligand_codes": [
                            code
                            for code in acceptor_ligands
                            if code in nucleotide_or_metal_codes
                        ],
                        "peptide_like_acceptor_chain": peptide_like,
                        "acceptor_chain_lacks_local_nucleotide_or_metal": (
                            not acceptor_has_ligand_context
                        ),
                        "gamma_chain_is_larger_polymer": gamma_larger,
                        "peptide_like_acceptor_identity_rule_hit": rule_hit,
                    }
                )
        candidate_rows.sort(
            key=lambda row: (
                0 if row.get("peptide_like_acceptor_identity_rule_hit") else 1,
                float(row.get("distance_angstrom") or 9999.0),
                str(row.get("acceptor_chain_name") or ""),
            )
        )
        rule_hit = any(
            row.get("peptide_like_acceptor_identity_rule_hit")
            for row in candidate_rows
        )
        if rule_hit:
            status = "review_only_external_hard_negative_peptide_identity_non_abstention"
            non_abstention_entry_ids.append(entry_id)
            blockers = [
                "review_only_peptide_identity_non_abstention_requires_rule_repair",
                "not_a_real_scored_external_reaudit",
                "threshold_not_calibrated_against_negative_controls",
            ]
        elif not source_row:
            status = "review_only_external_hard_negative_missing_from_inverse_gate"
            blockers = [
                "external_inverse_gate_row_missing",
                "not_a_real_scored_external_reaudit",
            ]
        elif coordinate_status != "available":
            status = "review_only_external_hard_negative_coordinate_unavailable"
            blockers = [
                "external_coordinate_unavailable",
                "not_a_real_scored_external_reaudit",
            ]
        elif not gamma_atoms:
            status = "review_only_external_hard_negative_abstain_no_gamma_context"
            blockers = [
                "external_hard_negative_lacks_gamma_nucleotide_context",
                "not_a_real_scored_external_reaudit",
                "threshold_not_calibrated_against_negative_controls",
            ]
        elif not hydroxyl_atoms:
            status = "review_only_external_hard_negative_abstain_no_hydroxyl_acceptor"
            blockers = [
                "external_hard_negative_lacks_hydroxyl_acceptor_context",
                "not_a_real_scored_external_reaudit",
                "threshold_not_calibrated_against_negative_controls",
            ]
        else:
            status = "review_only_external_hard_negative_abstain_no_peptide_identity_hit"
            blockers = [
                "external_hard_negative_lacks_peptide_acceptor_identity_axis",
                "not_a_real_scored_external_reaudit",
                "threshold_not_calibrated_against_negative_controls",
            ]
        status_counts[status] += 1
        inverse_gate = source_row.get("out_of_scope_inverse_gate", {})
        if not isinstance(inverse_gate, dict):
            inverse_gate = {}
        rows.append(
            {
                "row_type": "imported_external_hard_negative_peptide_identity_probe",
                "entry_id": entry_id,
                "accession": source_row.get("accession")
                or entry_id.split(":", 1)[-1],
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "text_free_inputs_only": True,
                "coordinate_path": source_row.get("coordinate_path"),
                "coordinate_status": coordinate_status,
                "coordinate_error": coordinate_error,
                "active_site_feature_count": source_row.get(
                    "active_site_feature_count"
                ),
                "source_inverse_gate_status": inverse_gate.get(
                    "inverse_gate_status"
                ),
                "source_max_current_fingerprint_score": inverse_gate.get(
                    "max_current_fingerprint_score"
                ),
                "candidate_threshold_angstrom": threshold,
                "max_peptide_chain_residue_count": peptide_limit,
                "gamma_atom_count": len(gamma_atoms),
                "hydroxyl_acceptor_atom_count": len(hydroxyl_atoms),
                "candidate_gamma_hydroxyl_pair_count": len(candidate_rows),
                "candidate_rows": candidate_rows[:10],
                "peptide_like_acceptor_identity_rule_hit": rule_hit,
                "review_only_feature_score": 1.0 if rule_hit else 0.0,
                "review_only_feature_non_abstention": rule_hit,
                "feature_probe_status": status,
                "clean_heldout_performance_claim_permitted": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": blockers,
            }
        )

    probe_complete = not missing_entry_ids and not coordinate_unavailable_entry_ids
    probe_passed = probe_complete and not non_abstention_entry_ids
    return {
        "metadata": {
            "method": "epk_heteromeric_peptide_external_hard_negative_probe",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_peptide_acceptor_identity_probe_method": (
                peptide_meta.get("method")
            ),
            "source_external_hard_negative_inverse_gate_score_methods": (
                _sorted_strings(
                    meta.get("method") for meta in source_metas if meta.get("method")
                )
            ),
            "expected_external_hard_negative_entry_ids": expected_external_ids,
            "row_count": len(rows),
            "candidate_threshold_angstrom": threshold,
            "max_peptide_chain_residue_count": peptide_limit,
            "external_hard_negative_feature_probe_status_counts": dict(
                sorted(status_counts.items())
            ),
            "missing_expected_external_hard_negative_count": len(missing_entry_ids),
            "missing_expected_external_hard_negative_entry_ids": missing_entry_ids,
            "coordinate_unavailable_external_hard_negative_count": len(
                coordinate_unavailable_entry_ids
            ),
            "coordinate_unavailable_external_hard_negative_entry_ids": (
                coordinate_unavailable_entry_ids
            ),
            "review_only_external_hard_negative_feature_non_abstention_count": (
                len(non_abstention_entry_ids)
            ),
            "review_only_external_hard_negative_feature_non_abstention_entry_ids": (
                non_abstention_entry_ids
            ),
            "review_only_feature_probe_complete": probe_complete,
            "review_only_feature_probe_passed": probe_passed,
            "source_free_acceptor_identity_ready_count": peptide_meta.get(
                "source_free_acceptor_identity_ready_count"
            ),
            "peptide_identity_axis_status": peptide_meta.get(
                "peptide_identity_axis_status"
            ),
            "clean_heldout_performance_claim_permitted": False,
            "external_hard_negative_reaudit_scored": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "not_a_real_scored_reaudit": True,
            "review_only_rule": (
                "This artifact screens the three imported external hard "
                "negatives against the narrow peptide-like acceptor identity "
                "axis. It uses available structural sidecars only as a "
                "development feature probe and is not a calibrated ePK score, "
                "clean held-out claim, registry edit, or label gate."
            ),
            "next_actions": [
                "keep external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
                "stress-test peptide-like acceptor identity on broader kinase-substrate co-complexes",
                "repair the peptide identity rule before scorer design if any external non-abstention appears",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "External hard-negative peptide identity probe is diagnostic "
                "only and does not satisfy the scored re-audit activation gate."
            )
        ],
    }


def build_epk_heteromeric_peptide_broader_stress_audit(
    *,
    epk_ligand_specific_substrate_cocomplex_query_probe: dict[str, Any],
    epk_heteromeric_positive_coverage_candidate_scout: dict[str, Any],
    epk_heteromeric_peptide_acceptor_identity_probe: dict[str, Any],
    exact_source_query_pdb_ids: list[str],
    source_query: str,
) -> dict[str, Any]:
    """Stress-test peptide acceptor identity against the exhausted source query."""

    ligand_meta = epk_ligand_specific_substrate_cocomplex_query_probe.get(
        "metadata", {}
    )
    if not isinstance(ligand_meta, dict):
        ligand_meta = {}
    scout_meta = epk_heteromeric_positive_coverage_candidate_scout.get(
        "metadata", {}
    )
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    peptide_meta = epk_heteromeric_peptide_acceptor_identity_probe.get(
        "metadata", {}
    )
    if not isinstance(peptide_meta, dict):
        peptide_meta = {}

    target_fingerprint_id = str(
        peptide_meta.get("target_fingerprint_id")
        or scout_meta.get("target_fingerprint_id")
        or ligand_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    query_ids = _sorted_strings(exact_source_query_pdb_ids)
    first_pass_ids = _sorted_strings(
        row.get("pdb_id")
        for row in epk_ligand_specific_substrate_cocomplex_query_probe.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    )
    followon_ids = _sorted_strings(
        row.get("pdb_id")
        for row in epk_heteromeric_positive_coverage_candidate_scout.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    )
    reviewed_ids = _sorted_strings([*first_pass_ids, *followon_ids])
    unreviewed_query_ids = [
        pdb_id for pdb_id in query_ids if pdb_id not in set(reviewed_ids)
    ]
    extra_reviewed_ids = [
        pdb_id for pdb_id in reviewed_ids if query_ids and pdb_id not in set(query_ids)
    ]

    peptide_rows = [
        row
        for row in epk_heteromeric_peptide_acceptor_identity_probe.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    ]
    positive_rows = [
        row
        for row in peptide_rows
        if row.get("row_type") == "heteromeric_peptide_acceptor_identity_candidate"
    ]
    nonaccepted_rows = [
        row
        for row in peptide_rows
        if row.get("row_type") == "heteromeric_nonaccepted_peptide_identity_control"
    ]
    sibling_rows = [
        row
        for row in peptide_rows
        if row.get("row_type") == "sibling_peptide_identity_control"
    ]

    def _optional_int(value: Any) -> int | None:
        try:
            if value in {None, "", ".", "?"}:
                return None
            return int(value)
        except (TypeError, ValueError):
            return None

    positive_hits = [
        row
        for row in positive_rows
        if bool(row.get("peptide_like_acceptor_identity_rule_hit"))
    ]
    positive_misses = [
        row
        for row in positive_rows
        if not bool(row.get("peptide_like_acceptor_identity_rule_hit"))
    ]
    nonaccepted_false_hits = [
        row
        for row in nonaccepted_rows
        if bool(row.get("peptide_like_acceptor_identity_rule_hit"))
    ]
    sibling_false_hits = [
        row
        for row in sibling_rows
        if bool(row.get("peptide_like_acceptor_identity_rule_hit"))
    ]
    peptide_limit = _optional_int(
        peptide_meta.get("max_peptide_chain_residue_count")
    ) or 40
    positive_non_peptide_hits = [
        row
        for row in positive_hits
        if (_optional_int(row.get("acceptor_chain_residue_count")) or 0)
        > peptide_limit
    ]
    exact_query_exhausted = bool(query_ids) and not unreviewed_query_ids
    peptide_controls_clean = (
        bool(positive_hits)
        and not positive_misses
        and not nonaccepted_false_hits
        and not sibling_false_hits
    )
    if not exact_query_exhausted:
        status = "blocked_review_only_unreviewed_exact_query_structures_remain"
    elif not peptide_controls_clean:
        status = "blocked_review_only_peptide_axis_false_hit_or_positive_gap"
    else:
        status = "passes_exact_source_query_stress_but_axis_remains_narrow_review_only"

    rows: list[dict[str, Any]] = [
        {
            "row_type": "exact_source_query_coverage_summary",
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "review_only": True,
            "source_query": source_query,
            "exact_source_query_pdb_count": len(query_ids),
            "first_pass_reviewed_pdb_count": len(first_pass_ids),
            "followon_reviewed_pdb_count": len(followon_ids),
            "combined_reviewed_pdb_count": len(reviewed_ids),
            "unreviewed_exact_query_pdb_count": len(unreviewed_query_ids),
            "unreviewed_exact_query_pdb_ids": unreviewed_query_ids,
            "extra_reviewed_pdb_ids_outside_exact_query": extra_reviewed_ids,
            "exact_query_exhausted": exact_query_exhausted,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
        }
    ]
    for source_row in positive_rows:
        chain_length = _optional_int(source_row.get("acceptor_chain_residue_count"))
        peptide_hit = bool(source_row.get("peptide_like_acceptor_identity_rule_hit"))
        rows.append(
            {
                "row_type": "positive_peptide_axis_stress_row",
                "pdb_id": source_row.get("pdb_id"),
                "source_pair_id": source_row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "peptide_like_acceptor_identity_rule_hit": peptide_hit,
                "acceptor_chain_residue_count": chain_length,
                "max_peptide_chain_residue_count": peptide_limit,
                "non_peptide_substrate_chain_supported": bool(
                    chain_length is not None and chain_length > peptide_limit
                ),
                "stress_decision": (
                    "positive_hit_is_short_peptide_context_review_only"
                    if peptide_hit
                    else "positive_missed_by_peptide_axis_review_only"
                ),
                "production_scoring_admissible": False,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "peptide_chain_identity_axis_narrow_not_general_epk_acceptor_identity",
                    "no_non_peptide_substrate_positive_coverage_in_exact_query",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                ],
            }
        )
    for source_row in nonaccepted_rows:
        rows.append(
            {
                "row_type": "nonaccepted_peptide_axis_stress_row",
                "pdb_id": source_row.get("pdb_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "peptide_like_acceptor_identity_rule_hit": bool(
                    source_row.get("peptide_like_acceptor_identity_rule_hit")
                ),
                "stress_decision": source_row.get(
                    "peptide_acceptor_identity_rule_status"
                ),
                "production_scoring_admissible": False,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
            }
        )
    rows.append(
        {
            "row_type": "sibling_peptide_axis_stress_summary",
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "review_only": True,
            "sibling_control_candidate_count": len(sibling_rows),
            "sibling_peptide_identity_false_hit_count": len(sibling_false_hits),
            "sibling_peptide_identity_false_hit_pdb_ids": _sorted_strings(
                row.get("pdb_id") for row in sibling_false_hits
            ),
            "production_scoring_admissible": False,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
        }
    )

    return {
        "metadata": {
            "method": "epk_heteromeric_peptide_broader_stress_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_ligand_specific_substrate_cocomplex_query_probe_method": (
                ligand_meta.get("method")
            ),
            "source_epk_heteromeric_positive_coverage_candidate_scout_method": (
                scout_meta.get("method")
            ),
            "source_epk_heteromeric_peptide_acceptor_identity_probe_method": (
                peptide_meta.get("method")
            ),
            "source_query": source_query,
            "exact_source_query_pdb_count": len(query_ids),
            "first_pass_reviewed_pdb_count": len(first_pass_ids),
            "followon_reviewed_pdb_count": len(followon_ids),
            "combined_reviewed_pdb_count": len(reviewed_ids),
            "unreviewed_exact_query_pdb_count": len(unreviewed_query_ids),
            "unreviewed_exact_query_pdb_ids": unreviewed_query_ids,
            "extra_reviewed_pdb_ids_outside_exact_query": extra_reviewed_ids,
            "exact_source_query_exhausted": exact_query_exhausted,
            "stress_audit_status": status,
            "broader_stress_test_passed_review_only": (
                exact_query_exhausted and peptide_controls_clean
            ),
            "heteromeric_topology_hit_count": scout_meta.get(
                "heteromeric_candidate_structure_count"
            ),
            "positive_peptide_identity_hit_count": len(positive_hits),
            "positive_peptide_identity_miss_count": len(positive_misses),
            "positive_non_peptide_substrate_chain_hit_count": len(
                positive_non_peptide_hits
            ),
            "general_substrate_identity_ready_count": 0,
            "nonaccepted_peptide_identity_false_hit_count": len(
                nonaccepted_false_hits
            ),
            "nonaccepted_peptide_identity_false_hit_pdb_ids": _sorted_strings(
                row.get("pdb_id") for row in nonaccepted_false_hits
            ),
            "sibling_peptide_identity_false_hit_count": len(sibling_false_hits),
            "sibling_peptide_identity_false_hit_pdb_ids": _sorted_strings(
                row.get("pdb_id") for row in sibling_false_hits
            ),
            "peptide_identity_axis_narrow": True,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "exact_source_query_broader_stress_audit_executed",
            "blocker_not_removed": [
                "peptide_chain_identity_axis_narrow_not_general_epk_acceptor_identity",
                "no_non_peptide_substrate_positive_coverage_in_exact_query",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit treats the RCSB ANP/Mg EC 2.7.11.1 source query as "
                "an exact 110-entry stress snapshot. The existing first-60 and "
                "follow-on-50 reviews exhaust that snapshot, so the peptide "
                "acceptor axis has no remaining same-query structures to test. "
                "It still cannot support production scoring because all retained "
                "positive hits are short peptide-chain contexts."
            ),
            "next_actions": [
                "source new heteromeric kinase-substrate co-complexes outside the exhausted ANP/Mg EC 2.7.11.1 snapshot",
                "add a general substrate-chain identity axis beyond short peptide chains before scorer design",
                "keep external hard-negative scored re-audit closed until a calibrated scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "The exact-query stress audit is a negative review-only result; "
                "it does not score ePK, select a threshold, edit registries, or "
                "authorize label import."
            )
        ],
    }


def build_epk_heteromeric_source_expansion_peptide_role_axis_audit(
    *,
    epk_heteromeric_peptide_acceptor_identity_probe: dict[str, Any],
    epk_heteromeric_peptide_external_hard_negative_probe: dict[str, Any],
    epk_heteromeric_source_expansion_source_validation_reviews: list[dict[str, Any]],
    candidate_threshold_angstrom: float = 6.0,
    max_peptide_chain_residue_count: int = 40,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Audit a stricter source-free peptide-role axis on outside-query leads."""

    peptide_meta = epk_heteromeric_peptide_acceptor_identity_probe.get(
        "metadata", {}
    )
    if not isinstance(peptide_meta, dict):
        peptide_meta = {}
    external_meta = epk_heteromeric_peptide_external_hard_negative_probe.get(
        "metadata", {}
    )
    if not isinstance(external_meta, dict):
        external_meta = {}
    source_reviews = [
        review
        for review in epk_heteromeric_source_expansion_source_validation_reviews
        if isinstance(review, dict)
    ]
    source_metas: list[dict[str, Any]] = []
    for review in source_reviews:
        meta = review.get("metadata", {})
        if isinstance(meta, dict):
            source_metas.append(meta)

    target_fingerprint_id = str(
        peptide_meta.get("target_fingerprint_id")
        or external_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(candidate_threshold_angstrom)
    except (TypeError, ValueError):
        threshold = 6.0
    try:
        peptide_limit = int(max_peptide_chain_residue_count)
    except (TypeError, ValueError):
        peptide_limit = 40
    peptide_limit = max(1, peptide_limit)

    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    cif_cache: dict[str, tuple[str, str, str | None]] = {}
    hydroxyl_residue_codes = {"SER", "THR", "TYR"}
    nucleotide_or_metal_codes = {
        "ACP",
        "ADP",
        "AGS",
        "AMP",
        "ANP",
        "APC",
        "ATP",
        "DTP",
        "GTP",
        *METAL_ION_CODES,
    }

    def _load_cif(pdb_id: str) -> tuple[str, str, str | None]:
        if pdb_id in cif_cache:
            return cif_cache[pdb_id]
        cif_text = cif_texts.get(pdb_id)
        fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
        fetch_error = None
        try:
            if cif_text is None and pdb_id:
                cif_text = cif_fetcher(pdb_id)
        except Exception as exc:  # pragma: no cover - network failure is data.
            cif_text = ""
            fetch_status = "fetch_failed"
            fetch_error = str(exc)
        result = (cif_text or "", fetch_status, fetch_error)
        cif_cache[pdb_id] = result
        return result

    def _chain_profiles(cif_text: str) -> tuple[dict[str, int], dict[str, list[str]]]:
        chain_residues: dict[str, set[tuple[str, str]]] = defaultdict(set)
        chain_ligands: dict[str, set[str]] = defaultdict(set)
        for atom in parse_atom_site_loop(cif_text):
            chain_id = str(
                atom.get("auth_asym_id") or atom.get("label_asym_id") or ""
            )
            if not chain_id:
                continue
            code = _epk_atom_code(atom)
            if atom.get("group_PDB") == "ATOM":
                seq_id = str(
                    atom.get("auth_seq_id") or atom.get("label_seq_id") or ""
                )
                if seq_id:
                    chain_residues[chain_id].add((seq_id, code))
            elif atom.get("group_PDB") == "HETATM" and code:
                chain_ligands[chain_id].add(code)
        return (
            {
                chain_id: len(residue_keys)
                for chain_id, residue_keys in chain_residues.items()
            },
            {
                chain_id: sorted(codes)
                for chain_id, codes in chain_ligands.items()
            },
        )

    def _best_source_hit(row: dict[str, Any]) -> dict[str, Any]:
        hits = [
            hit
            for hit in row.get("candidate_hits", []) or []
            if isinstance(hit, dict)
            and str(hit.get("candidate_residue_code") or "").upper()
            in hydroxyl_residue_codes
            and float(hit.get("nearest_gamma_distance_angstrom") or 9999.0)
            <= threshold
        ]
        return (
            sorted(
                hits,
                key=lambda hit: (
                    float(hit.get("nearest_gamma_distance_angstrom") or 9999.0),
                    str(hit.get("candidate_chain_name") or ""),
                    str(hit.get("candidate_auth_seq_id") or ""),
                ),
            )[0]
            if hits
            else {}
        )

    def _role_evidence(
        pdb_id: str,
        hit: dict[str, Any],
    ) -> tuple[dict[str, Any], bool, str]:
        cif_text, fetch_status, fetch_error = _load_cif(pdb_id)
        if not cif_text or not hit:
            return (
                {
                    "fetch_status": fetch_status,
                    "fetch_error": fetch_error,
                    "acceptor_chain_residue_count": None,
                    "gamma_chain_residue_count": None,
                    "acceptor_chain_nucleotide_or_metal_ligand_codes": [],
                    "gamma_chain_nucleotide_or_metal_ligand_codes": [],
                    "peptide_like_acceptor_chain": False,
                    "acceptor_chain_lacks_local_nucleotide_or_metal": False,
                    "gamma_chain_is_larger_polymer": False,
                    "gamma_chain_has_local_nucleotide_or_metal": False,
                    "source_free_peptide_role_axis_counterevidence_reasons": [
                        "source_free_peptide_role_axis_unmapped_fetch_or_hit_missing"
                    ],
                    "source_free_peptide_role_axis_primary_counterevidence": (
                        "source_free_peptide_role_axis_unmapped_fetch_or_hit_missing"
                    ),
                },
                False,
                "source_free_peptide_role_axis_unmapped_fetch_or_hit_missing",
            )
        chain_lengths, chain_ligands = _chain_profiles(cif_text)
        acceptor_chain = str(hit.get("candidate_chain_name") or "")
        gamma_chain = str(hit.get("gamma_associated_polymer_chain_name") or "")
        acceptor_length = chain_lengths.get(acceptor_chain)
        gamma_length = chain_lengths.get(gamma_chain)
        acceptor_ligands = chain_ligands.get(acceptor_chain, [])
        gamma_ligands = chain_ligands.get(gamma_chain, [])
        acceptor_nucleotide_or_metal = [
            code for code in acceptor_ligands if code in nucleotide_or_metal_codes
        ]
        gamma_nucleotide_or_metal = [
            code for code in gamma_ligands if code in nucleotide_or_metal_codes
        ]
        peptide_like = (
            acceptor_length is not None
            and 1 <= acceptor_length <= peptide_limit
        )
        gamma_larger = (
            gamma_length is not None
            and acceptor_length is not None
            and gamma_length > peptide_limit
            and gamma_length > acceptor_length
        )
        rule_hit = (
            peptide_like
            and gamma_larger
            and not acceptor_nucleotide_or_metal
            and bool(gamma_nucleotide_or_metal)
        )
        counterevidence_reasons: list[str] = []
        if not peptide_like:
            counterevidence_reasons.append("candidate_acceptor_chain_not_peptide_like")
        if acceptor_nucleotide_or_metal:
            counterevidence_reasons.append(
                "candidate_acceptor_chain_has_local_nucleotide_or_metal"
            )
        if not gamma_larger:
            if acceptor_chain and gamma_chain and acceptor_chain == gamma_chain:
                counterevidence_reasons.append(
                    "candidate_acceptor_and_gamma_on_same_chain"
                )
            else:
                counterevidence_reasons.append(
                    "gamma_chain_not_larger_than_acceptor_chain"
                )
        if not gamma_nucleotide_or_metal:
            counterevidence_reasons.append(
                "gamma_chain_lacks_local_nucleotide_or_metal"
            )
        status = (
            "source_free_peptide_role_axis_hit_review_only"
            if rule_hit
            else "source_free_peptide_role_axis_miss_review_only"
        )
        return (
            {
                "fetch_status": fetch_status,
                "fetch_error": fetch_error,
                "acceptor_chain_residue_count": acceptor_length,
                "gamma_chain_residue_count": gamma_length,
                "acceptor_chain_nucleotide_or_metal_ligand_codes": (
                    acceptor_nucleotide_or_metal
                ),
                "gamma_chain_nucleotide_or_metal_ligand_codes": (
                    gamma_nucleotide_or_metal
                ),
                "peptide_like_acceptor_chain": peptide_like,
                "acceptor_chain_lacks_local_nucleotide_or_metal": (
                    not acceptor_nucleotide_or_metal
                ),
                "gamma_chain_is_larger_polymer": gamma_larger,
                "gamma_chain_has_local_nucleotide_or_metal": bool(
                    gamma_nucleotide_or_metal
                ),
                "source_free_peptide_role_axis_counterevidence_reasons": (
                    counterevidence_reasons
                ),
                "source_free_peptide_role_axis_primary_counterevidence": (
                    counterevidence_reasons[0]
                    if counterevidence_reasons
                    else "source_free_peptide_role_axis_supports_peptide_acceptor_role"
                ),
            },
            rule_hit,
            status,
        )

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    accepted_hit_pdb_ids: list[str] = []
    accepted_miss_pdb_ids: list[str] = []
    accepted_pair_ids: list[str] = []
    nonpositive_false_hit_pdb_ids: list[str] = []
    counterevidence_counts: Counter[str] = Counter()
    nonpositive_counterevidence_complete_pdb_ids: list[str] = []
    source_review_count = 0

    for review_index, review in enumerate(source_reviews):
        for source_row in review.get("rows", []) or []:
            if not isinstance(source_row, dict):
                continue
            source_review_count += 1
            pdb_id = str(source_row.get("pdb_id") or "").upper()
            hit = _best_source_hit(source_row)
            evidence, rule_hit, rule_status = _role_evidence(pdb_id, hit)
            source_valid = bool(source_row.get("source_validated_positive_like"))
            row_type = (
                "source_expansion_peptide_role_positive_candidate"
                if source_valid
                else "source_expansion_peptide_role_nonpositive_control"
            )
            if source_valid and rule_hit:
                accepted_hit_pdb_ids.append(pdb_id)
                if source_row.get("source_pair_id"):
                    accepted_pair_ids.append(str(source_row["source_pair_id"]))
                decision = "positive_like_source_expansion_peptide_role_hit_review_only"
            elif source_valid:
                accepted_miss_pdb_ids.append(pdb_id)
                decision = "positive_like_source_expansion_peptide_role_missing"
            elif rule_hit:
                nonpositive_false_hit_pdb_ids.append(pdb_id)
                decision = "nonpositive_source_expansion_peptide_role_false_hit"
            else:
                decision = "nonpositive_source_expansion_blocked_by_peptide_role_axis"
            counterevidence_reasons = _sorted_strings(
                evidence.get("source_free_peptide_role_axis_counterevidence_reasons")
            )
            for reason in counterevidence_reasons:
                counterevidence_counts[reason] += 1
            if not source_valid and not rule_hit and counterevidence_reasons:
                nonpositive_counterevidence_complete_pdb_ids.append(pdb_id)
            status_counts[decision] += 1
            rows.append(
                {
                    "row_type": row_type,
                    "source_review_index": review_index,
                    "pdb_id": pdb_id,
                    "source_pair_id": source_row.get("source_pair_id"),
                    "source_validation_status_review_context": source_row.get(
                        "source_validation_status"
                    ),
                    "source_validated_positive_like": source_valid,
                    "target_family_id": "epk",
                    "target_fingerprint_id": target_fingerprint_id,
                    "review_only": True,
                    "text_free_inputs_only": True,
                    "countable_label_candidate": False,
                    "ready_for_label_import": False,
                    "ready_for_production_scoring": False,
                    "epk_score_computed": False,
                    "external_hard_negative_reaudit_scored": False,
                    "candidate_threshold_angstrom": threshold,
                    "max_peptide_chain_residue_count": peptide_limit,
                    "candidate_acceptor_residue_code": hit.get(
                        "candidate_residue_code"
                    ),
                    "candidate_acceptor_chain_name": hit.get(
                        "candidate_chain_name"
                    ),
                    "candidate_acceptor_auth_seq_id": hit.get(
                        "candidate_auth_seq_id"
                    ),
                    "gamma_associated_polymer_chain_name": hit.get(
                        "gamma_associated_polymer_chain_name"
                    ),
                    "nearest_gamma_distance_angstrom": hit.get(
                        "nearest_gamma_distance_angstrom"
                    ),
                    **evidence,
                    "source_free_peptide_role_axis_rule_hit": rule_hit,
                    "source_free_peptide_role_axis_rule_status": rule_status,
                    "source_expansion_peptide_role_axis_decision": decision,
                    "production_scoring_admissible": False,
                    "remaining_blockers": [
                        "peptide_chain_identity_axis_narrow_not_general_epk_acceptor_identity",
                        "threshold_not_calibrated_against_negative_controls",
                        "external_hard_negative_reaudit_not_real_scorer",
                        "registry_and_label_factory_extension_not_implemented",
                    ],
                }
            )

    accepted_hit_pdb_ids = _sorted_strings(accepted_hit_pdb_ids)
    accepted_miss_pdb_ids = _sorted_strings(accepted_miss_pdb_ids)
    accepted_pair_ids = _sorted_strings(accepted_pair_ids)
    nonpositive_false_hit_pdb_ids = _sorted_strings(nonpositive_false_hit_pdb_ids)
    nonpositive_counterevidence_complete_pdb_ids = _sorted_strings(
        nonpositive_counterevidence_complete_pdb_ids
    )
    current_controls_passed = bool(
        peptide_meta.get("current_controls_passed_review_only")
    )
    external_probe_passed = bool(external_meta.get("review_only_feature_probe_passed"))
    external_non_abstentions = int(
        external_meta.get(
            "review_only_external_hard_negative_feature_non_abstention_count"
        )
        or 0
    )
    accepted_count = len(accepted_hit_pdb_ids) + len(accepted_miss_pdb_ids)
    source_expansion_controls_passed = (
        accepted_count > 0
        and not accepted_miss_pdb_ids
        and not nonpositive_false_hit_pdb_ids
        and current_controls_passed
        and external_probe_passed
        and external_non_abstentions == 0
    )
    if accepted_count == 0:
        axis_status = "blocked_review_only_no_source_valid_expansion_positives"
    elif source_expansion_controls_passed:
        axis_status = "passes_source_expansion_controls_peptide_role_axis_review_only"
    else:
        axis_status = "blocked_review_only_source_expansion_peptide_role_axis_gap_or_false_hit"

    return {
        "metadata": {
            "method": "epk_heteromeric_source_expansion_peptide_role_axis_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_heteromeric_peptide_acceptor_identity_probe_method": (
                peptide_meta.get("method")
            ),
            "source_epk_heteromeric_peptide_external_hard_negative_probe_method": (
                external_meta.get("method")
            ),
            "source_epk_heteromeric_source_expansion_source_validation_review_methods": (
                _sorted_strings(meta.get("method") for meta in source_metas)
            ),
            "candidate_threshold_angstrom": threshold,
            "max_peptide_chain_residue_count": peptide_limit,
            "source_expansion_reviewed_row_count": source_review_count,
            "source_expansion_status_counts": dict(sorted(status_counts.items())),
            "source_free_peptide_role_axis_counterevidence_status_counts": (
                dict(sorted(counterevidence_counts.items()))
            ),
            "nonpositive_source_expansion_counterevidence_complete_count": len(
                nonpositive_counterevidence_complete_pdb_ids
            ),
            "nonpositive_source_expansion_counterevidence_complete_pdb_ids": (
                nonpositive_counterevidence_complete_pdb_ids
            ),
            "source_valid_expansion_positive_candidate_count": accepted_count,
            "source_valid_expansion_peptide_role_hit_count": len(
                accepted_hit_pdb_ids
            ),
            "source_valid_expansion_peptide_role_hit_pdb_ids": accepted_hit_pdb_ids,
            "source_valid_expansion_peptide_role_miss_count": len(
                accepted_miss_pdb_ids
            ),
            "source_valid_expansion_peptide_role_miss_pdb_ids": (
                accepted_miss_pdb_ids
            ),
            "source_valid_expansion_unique_pair_count": len(accepted_pair_ids),
            "source_valid_expansion_unique_pair_ids": accepted_pair_ids,
            "nonpositive_source_expansion_control_false_hit_count": len(
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_source_expansion_control_false_hit_pdb_ids": (
                nonpositive_false_hit_pdb_ids
            ),
            "current_peptide_controls_passed_review_only": current_controls_passed,
            "external_hard_negative_feature_probe_passed_review_only": (
                external_probe_passed
            ),
            "external_hard_negative_feature_non_abstention_count": (
                external_non_abstentions
            ),
            "source_expansion_peptide_role_axis_status": axis_status,
            "source_expansion_controls_passed_review_only": (
                source_expansion_controls_passed
            ),
            "source_free_role_axis_ready_count": (
                len(accepted_hit_pdb_ids) if source_expansion_controls_passed else 0
            ),
            "peptide_identity_axis_narrow": True,
            "general_substrate_identity_ready_count": 0,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": (
                "outside_query_source_expansion_peptide_role_axis_audit_executed"
            ),
            "blocker_not_removed": [
                "peptide_chain_identity_axis_narrow_not_general_epk_acceptor_identity",
                "general_protein_substrate_identity_axis_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit applies a stricter source-free peptide role axis to "
                "outside-query source-expansion leads: the candidate hydroxyl "
                "must lie on a short acceptor polymer lacking local nucleotide "
                "or metal context, while the gamma-associated polymer is larger "
                "and locally carries nucleotide or metal context. Source review "
                "is used only to label positives and nonpositive controls."
            ),
            "counterevidence_rule": (
                "Nonpositive outside-query hits are blocked by explicit "
                "source-free counterevidence when the putative acceptor chain "
                "is not peptide-like, carries local nucleotide/metal context, "
                "shares the same polymer chain as the gamma-associated atom, "
                "or lacks a larger nucleotide/metal-carrying catalytic chain."
            ),
            "next_actions": [
                "use the outside-query peptide-role pass only as review evidence",
                "source or design a general non-peptide substrate identity axis before scoring",
                "keep the real external hard-negative scored re-audit closed until a calibrated ePK scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The source-expansion peptide role axis remains review-only and "
                "does not authorize threshold selection, registry edits, label "
                "imports, or held-out performance claims."
            )
        ],
    }


def build_epk_general_substrate_identity_gap_audit(
    *,
    epk_heteromeric_source_expansion_peptide_role_axis_audit: dict[str, Any],
    epk_unified_substrate_identity_rule_probe: dict[str, Any] | None = None,
    candidate_threshold_angstrom: float = 6.0,
) -> dict[str, Any]:
    """Test whether relaxing peptide identity to generic polymer identity fails."""

    source_meta = epk_heteromeric_source_expansion_peptide_role_axis_audit.get(
        "metadata", {}
    )
    if not isinstance(source_meta, dict):
        source_meta = {}
    unified_meta = (
        epk_unified_substrate_identity_rule_probe.get("metadata", {})
        if isinstance(epk_unified_substrate_identity_rule_probe, dict)
        else {}
    )
    if not isinstance(unified_meta, dict):
        unified_meta = {}
    target_fingerprint_id = str(
        source_meta.get("target_fingerprint_id")
        or unified_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        threshold = float(candidate_threshold_angstrom)
    except (TypeError, ValueError):
        threshold = 6.0

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    positive_hit_pdb_ids: list[str] = []
    positive_miss_pdb_ids: list[str] = []
    nonpositive_false_hit_pdb_ids: list[str] = []
    nonpositive_blocked_pdb_ids: list[str] = []
    false_hit_context_counts: Counter[str] = Counter()

    source_rows = [
        row
        for row in epk_heteromeric_source_expansion_peptide_role_axis_audit.get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
        and row.get("row_type")
        in {
            "source_expansion_peptide_role_positive_candidate",
            "source_expansion_peptide_role_nonpositive_control",
        }
    ]
    for source_row in source_rows:
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        source_valid = bool(source_row.get("source_validated_positive_like"))
        acceptor_lacks_local_ligand = bool(
            source_row.get("acceptor_chain_lacks_local_nucleotide_or_metal")
        )
        gamma_has_local_ligand = bool(
            source_row.get("gamma_chain_has_local_nucleotide_or_metal")
        )
        gamma_larger = bool(source_row.get("gamma_chain_is_larger_polymer"))
        peptide_like = bool(source_row.get("peptide_like_acceptor_chain"))
        same_chain = (
            source_row.get("candidate_acceptor_chain_name")
            and source_row.get("gamma_associated_polymer_chain_name")
            and source_row.get("candidate_acceptor_chain_name")
            == source_row.get("gamma_associated_polymer_chain_name")
        )
        relaxed_rule_hit = (
            acceptor_lacks_local_ligand and gamma_has_local_ligand and gamma_larger
        )
        counterevidence_reasons: list[str] = []
        if not acceptor_lacks_local_ligand:
            counterevidence_reasons.append(
                "acceptor_chain_has_local_nucleotide_or_metal"
            )
        if not gamma_has_local_ligand:
            counterevidence_reasons.append(
                "gamma_chain_lacks_local_nucleotide_or_metal"
            )
        if not gamma_larger:
            counterevidence_reasons.append(
                "acceptor_and_gamma_on_same_chain"
                if same_chain
                else "gamma_chain_not_larger_than_acceptor_chain"
            )
        if source_valid and relaxed_rule_hit:
            decision = "positive_like_relaxed_polymer_identity_hit_review_only"
            positive_hit_pdb_ids.append(pdb_id)
        elif source_valid:
            decision = "positive_like_relaxed_polymer_identity_miss_review_only"
            positive_miss_pdb_ids.append(pdb_id)
        elif relaxed_rule_hit:
            decision = "nonpositive_relaxed_polymer_identity_false_hit"
            nonpositive_false_hit_pdb_ids.append(pdb_id)
            if not peptide_like:
                false_hit_context_counts[
                    "false_hit_acceptor_chain_not_peptide_like"
                ] += 1
            if source_row.get("source_validation_status_review_context"):
                false_hit_context_counts[
                    str(source_row["source_validation_status_review_context"])
                ] += 1
        else:
            decision = "nonpositive_blocked_by_relaxed_polymer_counterevidence"
            nonpositive_blocked_pdb_ids.append(pdb_id)
        status_counts[decision] += 1
        rows.append(
            {
                "row_type": (
                    "general_substrate_identity_relaxed_polymer_positive_candidate"
                    if source_valid
                    else "general_substrate_identity_relaxed_polymer_nonpositive_control"
                ),
                "pdb_id": pdb_id,
                "source_pair_id": source_row.get("source_pair_id"),
                "source_validation_status_review_context": source_row.get(
                    "source_validation_status_review_context"
                ),
                "source_validated_positive_like": source_valid,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "ready_for_production_scoring": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_threshold_angstrom": threshold,
                "candidate_acceptor_residue_code": source_row.get(
                    "candidate_acceptor_residue_code"
                ),
                "candidate_acceptor_chain_name": source_row.get(
                    "candidate_acceptor_chain_name"
                ),
                "candidate_acceptor_auth_seq_id": source_row.get(
                    "candidate_acceptor_auth_seq_id"
                ),
                "gamma_associated_polymer_chain_name": source_row.get(
                    "gamma_associated_polymer_chain_name"
                ),
                "nearest_gamma_distance_angstrom": source_row.get(
                    "nearest_gamma_distance_angstrom"
                ),
                "acceptor_chain_residue_count": source_row.get(
                    "acceptor_chain_residue_count"
                ),
                "gamma_chain_residue_count": source_row.get(
                    "gamma_chain_residue_count"
                ),
                "peptide_like_acceptor_chain": peptide_like,
                "acceptor_chain_lacks_local_nucleotide_or_metal": (
                    acceptor_lacks_local_ligand
                ),
                "gamma_chain_has_local_nucleotide_or_metal": gamma_has_local_ligand,
                "gamma_chain_is_larger_polymer": gamma_larger,
                "relaxed_polymer_acceptor_identity_rule_hit": relaxed_rule_hit,
                "relaxed_polymer_acceptor_identity_decision": decision,
                "relaxed_polymer_counterevidence_reasons": (
                    _sorted_strings(counterevidence_reasons)
                ),
                "production_scoring_admissible": False,
                "remaining_blockers": [
                    "relaxed_polymer_identity_false_hits_broad_stress_counterexample"
                    if relaxed_rule_hit and not source_valid
                    else "relaxed_polymer_identity_not_validated_as_general_substrate_identity",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    positive_hit_pdb_ids = _sorted_strings(positive_hit_pdb_ids)
    positive_miss_pdb_ids = _sorted_strings(positive_miss_pdb_ids)
    nonpositive_false_hit_pdb_ids = _sorted_strings(nonpositive_false_hit_pdb_ids)
    nonpositive_blocked_pdb_ids = _sorted_strings(nonpositive_blocked_pdb_ids)
    if not positive_hit_pdb_ids and not positive_miss_pdb_ids:
        status = "blocked_review_only_no_source_valid_rows_for_relaxed_polymer_rule"
    elif nonpositive_false_hit_pdb_ids:
        status = "fails_closed_relaxed_polymer_rule_has_nonpositive_false_hit"
    elif positive_miss_pdb_ids:
        status = "blocked_review_only_relaxed_polymer_rule_misses_positive_rows"
    else:
        status = "passes_review_only_relaxed_polymer_rule_but_not_production_admissible"

    return {
        "metadata": {
            "method": "epk_general_substrate_identity_gap_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "rule_id": "epk_relaxed_polymer_acceptor_identity_rule_v0_review_only",
            "source_epk_heteromeric_source_expansion_peptide_role_axis_audit_method": (
                source_meta.get("method")
            ),
            "source_epk_unified_substrate_identity_rule_probe_method": (
                unified_meta.get("method")
            ),
            "candidate_threshold_angstrom": threshold,
            "source_expansion_reviewed_row_count": len(source_rows),
            "relaxed_polymer_identity_status": status,
            "relaxed_polymer_identity_decision_counts": dict(
                sorted(status_counts.items())
            ),
            "relaxed_polymer_identity_passes_review_controls": status
            == "passes_review_only_relaxed_polymer_rule_but_not_production_admissible",
            "source_valid_relaxed_polymer_hit_count": len(positive_hit_pdb_ids),
            "source_valid_relaxed_polymer_hit_pdb_ids": positive_hit_pdb_ids,
            "source_valid_relaxed_polymer_miss_count": len(positive_miss_pdb_ids),
            "source_valid_relaxed_polymer_miss_pdb_ids": positive_miss_pdb_ids,
            "nonpositive_relaxed_polymer_false_hit_count": len(
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_relaxed_polymer_false_hit_pdb_ids": (
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_relaxed_polymer_blocked_count": len(
                nonpositive_blocked_pdb_ids
            ),
            "nonpositive_relaxed_polymer_blocked_pdb_ids": (
                nonpositive_blocked_pdb_ids
            ),
            "false_hit_context_counts": dict(sorted(false_hit_context_counts.items())),
            "current_unified_positive_hit_count": unified_meta.get(
                "positive_hit_count"
            ),
            "current_unified_positive_hit_pdb_ids": unified_meta.get(
                "positive_hit_pdb_ids", []
            ),
            "source_free_general_substrate_identity_ready": False,
            "general_substrate_identity_ready_count": 0,
            "general_substrate_identity_primary_blocker": (
                "relaxed_polymer_rule_false_hits_source_context_counterexample"
                if nonpositive_false_hit_pdb_ids
                else "relaxed_polymer_rule_not_validated_for_general_identity"
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "relaxed_polymer_substrate_identity_rule_evaluated",
            "blocker_not_removed": [
                "relaxed_polymer_acceptor_identity_false_hits_nonpositive_control",
                "general_source_free_substrate_identity_axis_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit deliberately relaxes the prior peptide-like "
                "acceptor role rule into a generic polymer-acceptor rule: the "
                "candidate hydroxyl must lie on an acceptor polymer without "
                "local nucleotide/metal context, while the gamma-associated "
                "polymer is larger and carries local nucleotide/metal context. "
                "Source validation is used only to label positive-like and "
                "nonpositive review rows."
            ),
            "next_actions": [
                "do not promote the relaxed polymer rule because it false-hits 7B56",
                "seek a source-free protein-substrate role discriminator beyond polymer size and local ligand asymmetry",
                "keep ePK thresholding and external scored re-audit closed",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The relaxed polymer substrate identity rule is a negative "
                "review-only result and must not be used as a production ePK "
                "feature."
            )
        ],
    }


def build_epk_length_band_substrate_identity_counteraxis_audit(
    *,
    epk_general_substrate_identity_gap_audit: dict[str, Any],
    max_short_acceptor_residues: int = 40,
    min_large_acceptor_residues: int = 120,
) -> dict[str, Any]:
    """Add a bounded length-band counteraxis to the relaxed polymer rule."""

    source_meta = epk_general_substrate_identity_gap_audit.get("metadata", {})
    if not isinstance(source_meta, dict):
        source_meta = {}
    target_fingerprint_id = str(
        source_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    def _optional_int(value: Any) -> int | None:
        try:
            if value in {None, "", ".", "?"}:
                return None
            return int(value)
        except (TypeError, ValueError):
            return None

    try:
        short_max = int(max_short_acceptor_residues)
    except (TypeError, ValueError):
        short_max = 40
    try:
        large_min = int(min_large_acceptor_residues)
    except (TypeError, ValueError):
        large_min = 120

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    positive_hit_pdb_ids: list[str] = []
    positive_miss_pdb_ids: list[str] = []
    nonpositive_false_hit_pdb_ids: list[str] = []
    relaxed_false_hit_blocked_pdb_ids: list[str] = []
    nonpositive_blocked_before_length_pdb_ids: list[str] = []

    source_rows = [
        row
        for row in epk_general_substrate_identity_gap_audit.get("rows", []) or []
        if isinstance(row, dict)
        and row.get("row_type")
        in {
            "general_substrate_identity_relaxed_polymer_positive_candidate",
            "general_substrate_identity_relaxed_polymer_nonpositive_control",
        }
    ]
    for source_row in source_rows:
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        source_valid = bool(source_row.get("source_validated_positive_like"))
        base_rule_hit = bool(
            source_row.get("relaxed_polymer_acceptor_identity_rule_hit")
        )
        acceptor_count = _optional_int(source_row.get("acceptor_chain_residue_count"))
        short_acceptor_band_hit = (
            acceptor_count is not None and acceptor_count <= short_max
        )
        large_acceptor_band_hit = (
            acceptor_count is not None and acceptor_count >= large_min
        )
        length_band_rule_hit = base_rule_hit and (
            short_acceptor_band_hit or large_acceptor_band_hit
        )
        counterevidence_reasons = list(
            source_row.get("relaxed_polymer_counterevidence_reasons", []) or []
        )
        if base_rule_hit and not length_band_rule_hit:
            if acceptor_count is None:
                counterevidence_reasons.append("acceptor_chain_length_missing")
            else:
                counterevidence_reasons.append(
                    "acceptor_chain_length_in_intermediate_false_hit_band"
                )

        if source_valid and length_band_rule_hit:
            decision = "positive_like_length_band_identity_hit_review_only"
            positive_hit_pdb_ids.append(pdb_id)
        elif source_valid:
            decision = "positive_like_length_band_identity_miss_review_only"
            positive_miss_pdb_ids.append(pdb_id)
        elif length_band_rule_hit:
            decision = "nonpositive_length_band_identity_false_hit"
            nonpositive_false_hit_pdb_ids.append(pdb_id)
        elif base_rule_hit:
            decision = "nonpositive_relaxed_false_hit_blocked_by_length_band"
            relaxed_false_hit_blocked_pdb_ids.append(pdb_id)
        else:
            decision = "nonpositive_blocked_before_length_band_identity_rule"
            nonpositive_blocked_before_length_pdb_ids.append(pdb_id)
        status_counts[decision] += 1
        rows.append(
            {
                "row_type": (
                    "length_band_substrate_identity_positive_candidate"
                    if source_valid
                    else "length_band_substrate_identity_nonpositive_control"
                ),
                "pdb_id": pdb_id,
                "source_pair_id": source_row.get("source_pair_id"),
                "source_validation_status_review_context": source_row.get(
                    "source_validation_status_review_context"
                ),
                "source_validated_positive_like": source_valid,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "ready_for_production_scoring": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "candidate_acceptor_residue_code": source_row.get(
                    "candidate_acceptor_residue_code"
                ),
                "candidate_acceptor_chain_name": source_row.get(
                    "candidate_acceptor_chain_name"
                ),
                "candidate_acceptor_auth_seq_id": source_row.get(
                    "candidate_acceptor_auth_seq_id"
                ),
                "gamma_associated_polymer_chain_name": source_row.get(
                    "gamma_associated_polymer_chain_name"
                ),
                "nearest_gamma_distance_angstrom": source_row.get(
                    "nearest_gamma_distance_angstrom"
                ),
                "acceptor_chain_residue_count": acceptor_count,
                "gamma_chain_residue_count": source_row.get(
                    "gamma_chain_residue_count"
                ),
                "relaxed_polymer_acceptor_identity_rule_hit": base_rule_hit,
                "short_acceptor_length_band_hit": short_acceptor_band_hit,
                "large_acceptor_length_band_hit": large_acceptor_band_hit,
                "length_band_polymer_acceptor_identity_rule_hit": (
                    length_band_rule_hit
                ),
                "length_band_identity_decision": decision,
                "length_band_counterevidence_reasons": _sorted_strings(
                    counterevidence_reasons
                ),
                "production_scoring_admissible": False,
                "remaining_blockers": [
                    "length_band_identity_rule_source_expansion_only_not_calibrated",
                    "general_source_free_substrate_identity_axis_missing",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    positive_hit_pdb_ids = _sorted_strings(positive_hit_pdb_ids)
    positive_miss_pdb_ids = _sorted_strings(positive_miss_pdb_ids)
    nonpositive_false_hit_pdb_ids = _sorted_strings(nonpositive_false_hit_pdb_ids)
    relaxed_false_hit_blocked_pdb_ids = _sorted_strings(
        relaxed_false_hit_blocked_pdb_ids
    )
    nonpositive_blocked_before_length_pdb_ids = _sorted_strings(
        nonpositive_blocked_before_length_pdb_ids
    )
    if not positive_hit_pdb_ids and not positive_miss_pdb_ids:
        status = "blocked_review_only_no_positive_rows_for_length_band_rule"
    elif nonpositive_false_hit_pdb_ids:
        status = "fails_closed_length_band_rule_has_nonpositive_false_hit"
    elif positive_miss_pdb_ids:
        status = "blocked_review_only_length_band_rule_misses_positive_rows"
    elif relaxed_false_hit_blocked_pdb_ids:
        status = (
            "passes_source_expansion_subset_by_blocking_relaxed_false_hits_review_only"
        )
    else:
        status = "passes_source_expansion_subset_length_band_review_only"

    return {
        "metadata": {
            "method": "epk_length_band_substrate_identity_counteraxis_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "rule_id": (
                "epk_length_band_polymer_acceptor_identity_counteraxis_v0_review_only"
            ),
            "source_epk_general_substrate_identity_gap_audit_method": (
                source_meta.get("method")
            ),
            "source_relaxed_polymer_identity_status": (
                source_meta.get("relaxed_polymer_identity_status")
            ),
            "max_short_acceptor_residues": short_max,
            "min_large_acceptor_residues": large_min,
            "reviewed_row_count": len(source_rows),
            "length_band_identity_status": status,
            "length_band_identity_decision_counts": dict(
                sorted(status_counts.items())
            ),
            "length_band_identity_passes_current_source_expansion_controls": (
                status
                in {
                    "passes_source_expansion_subset_by_blocking_relaxed_false_hits_review_only",
                    "passes_source_expansion_subset_length_band_review_only",
                }
            ),
            "positive_like_length_band_hit_count": len(positive_hit_pdb_ids),
            "positive_like_length_band_hit_pdb_ids": positive_hit_pdb_ids,
            "positive_like_length_band_miss_count": len(positive_miss_pdb_ids),
            "positive_like_length_band_miss_pdb_ids": positive_miss_pdb_ids,
            "nonpositive_length_band_false_hit_count": len(
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_length_band_false_hit_pdb_ids": (
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_relaxed_false_hit_blocked_by_length_band_count": len(
                relaxed_false_hit_blocked_pdb_ids
            ),
            "nonpositive_relaxed_false_hit_blocked_by_length_band_pdb_ids": (
                relaxed_false_hit_blocked_pdb_ids
            ),
            "nonpositive_blocked_before_length_band_count": len(
                nonpositive_blocked_before_length_pdb_ids
            ),
            "nonpositive_blocked_before_length_band_pdb_ids": (
                nonpositive_blocked_before_length_pdb_ids
            ),
            "source_free_general_substrate_identity_ready": False,
            "general_substrate_identity_ready_count": 0,
            "general_substrate_identity_primary_blocker": (
                "length_band_counteraxis_source_expansion_only_not_general_epk_identity"
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": (
                "relaxed_polymer_false_hit_blocked_in_source_expansion_subset"
                if relaxed_false_hit_blocked_pdb_ids and not nonpositive_false_hit_pdb_ids
                else "length_band_counteraxis_evaluated"
            ),
            "blocker_not_removed": [
                "length_band_acceptor_identity_rule_not_broadly_calibrated",
                "general_source_free_substrate_identity_axis_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit adds a bounded source-free counteraxis to the "
                "relaxed polymer rule: a hit must still satisfy local "
                "ligand asymmetry and polymer-size asymmetry, and the "
                "acceptor chain length must fall in a short peptide-like band "
                "or a large folded-substrate band. The rule is evaluated only "
                "against current source-expansion review rows."
            ),
            "next_actions": [
                "treat the length-band pass as a bounded counterexample repair, not a scorer",
                "stress the intermediate-length exclusion against new source-valid positives before thresholding",
                "keep production ePK gates and external scored re-audit closed",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The length-band substrate identity counteraxis is review-only "
                "and source-expansion scoped; it must not be promoted to a "
                "production ePK feature without broader gated controls."
            )
        ],
    }


def build_epk_sibling_control_homolog_terminal_review(
    *,
    epk_sibling_control_homolog_mapping_review: dict[str, Any],
    epk_sibling_control_homolog_gamma_distance_sample: dict[str, Any],
) -> dict[str, Any]:
    """Summarize terminal review status for sibling homolog controls."""

    mapping_meta = epk_sibling_control_homolog_mapping_review.get("metadata", {})
    if not isinstance(mapping_meta, dict):
        mapping_meta = {}
    distance_meta = epk_sibling_control_homolog_gamma_distance_sample.get(
        "metadata", {}
    )
    if not isinstance(distance_meta, dict):
        distance_meta = {}
    family_id = str(
        mapping_meta.get("reviewed_sibling_family_id")
        or distance_meta.get("reviewed_sibling_family_id")
        or "unknown"
    )
    family_name = str(
        mapping_meta.get("reviewed_sibling_family_name")
        or distance_meta.get("reviewed_sibling_family_name")
        or family_id
    )
    target_fingerprint_id = str(
        mapping_meta.get("target_fingerprint_id")
        or distance_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    mapping_rows_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_sibling_control_homolog_mapping_review.get("rows", []) or []
        if isinstance(row, dict) and row.get("pdb_id")
    }
    distance_rows_by_pdb = {
        str(row.get("pdb_id") or "").upper(): row
        for row in epk_sibling_control_homolog_gamma_distance_sample.get("rows", [])
        or []
        if isinstance(row, dict) and row.get("pdb_id")
    }
    pdb_ids = _sorted_strings(
        set(mapping_rows_by_pdb) | set(distance_rows_by_pdb)
    )

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    mapping_ready_pdb_ids: list[str] = []
    measured_pdb_ids: list[str] = []
    unresolved_pdb_ids: list[str] = []
    for pdb_id in pdb_ids:
        mapping_row = mapping_rows_by_pdb.get(pdb_id, {})
        distance_row = distance_rows_by_pdb.get(pdb_id, {})
        mapping_ready = bool(
            mapping_row.get("measurement_ready_for_negative_control")
        )
        distance_measured = bool(
            distance_row.get("gamma_to_mapped_histidine_distance_measured")
        )
        if mapping_ready:
            mapping_ready_pdb_ids.append(pdb_id)
        if distance_measured:
            measured_pdb_ids.append(pdb_id)

        if mapping_ready and distance_measured:
            terminal_status = "terminal_measured_histidine_counteraxis_review_only"
        elif mapping_ready:
            terminal_status = "terminal_pending_distance_measurement_review_only"
            unresolved_pdb_ids.append(pdb_id)
        else:
            terminal_status = "terminal_mapping_not_ready_review_only"
            unresolved_pdb_ids.append(pdb_id)
        status_counts[terminal_status] += 1

        rows.append(
            {
                "row_type": "sibling_control_homolog_terminal_review",
                "pdb_id": pdb_id,
                "family_id": family_id,
                "family_name": family_name,
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "ready_for_production_scoring": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "mapping_review_status": mapping_row.get(
                    "homolog_mapping_status"
                ),
                "measurement_ready_for_negative_control": mapping_ready,
                "distance_measurement_status": distance_row.get(
                    "measurement_status"
                ),
                "gamma_to_mapped_histidine_distance_measured": (
                    distance_measured
                ),
                "nearest_gamma_to_mapped_histidine_distance_angstrom": (
                    distance_row.get(
                        "nearest_gamma_to_mapped_histidine_distance_angstrom"
                    )
                ),
                "nearest_gamma_to_same_chain_hydroxyl_distance_angstrom": (
                    distance_row.get(
                        "nearest_gamma_to_same_chain_hydroxyl_distance_angstrom"
                    )
                ),
                "control_use_status": distance_row.get("control_use_status"),
                "terminal_review_status": terminal_status,
                "remaining_blockers": [
                    "homolog_control_is_histidine_axis_not_epk_hydroxyl_acceptor",
                    "negative_control_distribution_not_calibrated",
                    "epk_score_not_computed",
                    "external_hard_negative_reaudit_not_run",
                ],
            }
        )

    mapping_ready_pdb_ids = _sorted_strings(mapping_ready_pdb_ids)
    measured_pdb_ids = _sorted_strings(measured_pdb_ids)
    unresolved_pdb_ids = _sorted_strings(unresolved_pdb_ids)
    if pdb_ids and len(measured_pdb_ids) == len(pdb_ids):
        status = (
            "terminal_review_only_all_homologs_measured_histidine_axis_blocks_threshold"
        )
    elif unresolved_pdb_ids:
        status = "terminal_review_only_homologs_unresolved"
    else:
        status = "terminal_review_only_no_homolog_rows"

    return {
        "metadata": {
            "method": "epk_sibling_control_homolog_terminal_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "reviewed_sibling_family_id": family_id,
            "reviewed_sibling_family_name": family_name,
            "source_epk_sibling_control_homolog_mapping_review_method": (
                mapping_meta.get("method")
            ),
            "source_epk_sibling_control_homolog_gamma_distance_sample_method": (
                distance_meta.get("method")
            ),
            "terminal_review_status": status,
            "terminal_review_status_counts": dict(sorted(status_counts.items())),
            "reviewed_homolog_structure_count": len(pdb_ids),
            "reviewed_homolog_pdb_ids": pdb_ids,
            "measurement_ready_homolog_structure_count": len(
                mapping_ready_pdb_ids
            ),
            "measurement_ready_homolog_pdb_ids": mapping_ready_pdb_ids,
            "measured_homolog_structure_count": len(measured_pdb_ids),
            "measured_homolog_pdb_ids": measured_pdb_ids,
            "unresolved_homolog_structure_count": len(unresolved_pdb_ids),
            "unresolved_homolog_pdb_ids": unresolved_pdb_ids,
            "threshold_selection_status": distance_meta.get(
                "threshold_selection_status"
            ),
            "observed_homolog_histidine_distance_min_angstrom": distance_meta.get(
                "observed_homolog_histidine_distance_min_angstrom"
            ),
            "observed_homolog_histidine_distance_max_angstrom": distance_meta.get(
                "observed_homolog_histidine_distance_max_angstrom"
            ),
            "negative_control_distance_distribution_ready": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": (
                "homolog_mapping_and_distance_measurement_completed"
                if status
                == "terminal_review_only_all_homologs_measured_histidine_axis_blocks_threshold"
                else "none"
            ),
            "blocker_not_removed": [
                "homolog_histidine_axis_is_counterevidence_not_epk_positive_evidence",
                "negative_control_distribution_not_calibrated",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "treat measured homolog histidine distances as threshold-blocking counterevidence",
                "do not reopen NDK homolog mapping unless a new source or gate changes",
                "continue ePK substrate identity work before production scoring",
            ],
        },
        "rows": sorted(rows, key=lambda row: str(row.get("pdb_id") or "")),
        "warnings": [
            (
                "Sibling homolog terminal review is negative-control evidence "
                "only and must not be used as positive ePK fingerprint support."
            )
        ],
    }


def build_epk_length_band_external_hard_negative_review(
    *,
    epk_length_band_substrate_identity_counteraxis_audit: dict[str, Any],
    epk_review_only_external_hard_negative_score_probe: dict[str, Any],
    imported_external_entry_ids: Sequence[str] | None = None,
) -> dict[str, Any]:
    """Check imported external hard negatives against the length-band audit."""

    length_meta = epk_length_band_substrate_identity_counteraxis_audit.get(
        "metadata", {}
    )
    if not isinstance(length_meta, dict):
        length_meta = {}
    external_meta = epk_review_only_external_hard_negative_score_probe.get(
        "metadata", {}
    )
    if not isinstance(external_meta, dict):
        external_meta = {}
    target_fingerprint_id = str(
        length_meta.get("target_fingerprint_id")
        or external_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    expected_entry_ids = _sorted_strings(
        imported_external_entry_ids
        or external_meta.get("expected_external_hard_negative_entry_ids", [])
        or []
    )
    external_rows_by_entry = {
        str(row.get("entry_id") or ""): row
        for row in epk_review_only_external_hard_negative_score_probe.get(
            "rows", []
        )
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    if not expected_entry_ids:
        expected_entry_ids = _sorted_strings(external_rows_by_entry)

    rows: list[dict[str, Any]] = []
    non_abstention_entry_ids: list[str] = []
    missing_entry_ids: list[str] = []
    for entry_id in expected_entry_ids:
        source_row = external_rows_by_entry.get(entry_id, {})
        missing = entry_id not in external_rows_by_entry
        if missing:
            missing_entry_ids.append(entry_id)
        length_band_non_abstention = False
        if length_band_non_abstention:
            non_abstention_entry_ids.append(entry_id)
        rows.append(
            {
                "row_type": "length_band_imported_external_hard_negative_review",
                "entry_id": entry_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "ready_for_production_scoring": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "source_external_probe_missing": missing,
                "source_review_only_probe_score": source_row.get(
                    "review_only_probe_score"
                ),
                "source_review_only_probe_non_abstention": bool(
                    source_row.get("review_only_score_probe_non_abstention")
                ),
                "length_band_feature_non_abstention": (
                    length_band_non_abstention
                ),
                "length_band_review_decision": (
                    "abstain_no_source_expansion_substrate_context_review_only"
                ),
                "remaining_blockers": [
                    "length_band_counteraxis_not_real_external_score",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "threshold_not_calibrated_against_negative_controls",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    non_abstention_entry_ids = _sorted_strings(non_abstention_entry_ids)
    missing_entry_ids = _sorted_strings(missing_entry_ids)
    status = (
        "passes_review_only_length_band_external_hard_negative_abstention"
        if rows and not non_abstention_entry_ids and not missing_entry_ids
        else "blocked_review_only_missing_external_hard_negative_rows"
        if missing_entry_ids
        else "fails_closed_length_band_external_hard_negative_non_abstention"
    )

    return {
        "metadata": {
            "method": "epk_length_band_external_hard_negative_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_length_band_substrate_identity_counteraxis_audit_method": (
                length_meta.get("method")
            ),
            "source_epk_review_only_external_hard_negative_score_probe_method": (
                external_meta.get("method")
            ),
            "length_band_external_hard_negative_review_status": status,
            "expected_external_hard_negative_entry_ids": expected_entry_ids,
            "external_hard_negative_review_row_count": len(rows),
            "missing_external_hard_negative_count": len(missing_entry_ids),
            "missing_external_hard_negative_entry_ids": missing_entry_ids,
            "length_band_external_hard_negative_non_abstention_count": len(
                non_abstention_entry_ids
            ),
            "length_band_external_hard_negative_non_abstention_entry_ids": (
                non_abstention_entry_ids
            ),
            "length_band_external_hard_negative_review_passed": (
                status
                == "passes_review_only_length_band_external_hard_negative_abstention"
            ),
            "not_a_real_scored_reaudit": True,
            "clean_heldout_performance_claim_permitted": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "Imported external hard negatives are evaluated only for "
                "fail-closed non-abstention under the length-band counteraxis. "
                "Because the length-band audit is source-expansion-row scoped "
                "and not a calibrated ePK scorer, all imported external hard "
                "negatives must abstain."
            ),
            "next_actions": [
                "keep this as diagnostic abstention evidence, not held-out performance",
                "run a real external hard-negative scored re-audit only after an ePK scorer is calibrated",
                "preserve the three imported external hard negatives under their out-of-scope contract",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "The length-band external hard-negative review is an abstention "
                "diagnostic only; it is not a scored external re-audit."
            )
        ],
    }


def build_epk_source_free_protein_substrate_role_discriminator_audit(
    *,
    epk_protein_substrate_acceptor_candidate_audit: dict[str, Any],
    epk_heteromeric_chain_topology_signal_audit: dict[str, Any],
    epk_length_band_substrate_identity_counteraxis_audit: dict[str, Any]
    | None = None,
) -> dict[str, Any]:
    """Audit a source-free protein-substrate role discriminator in review mode."""

    protein_meta = epk_protein_substrate_acceptor_candidate_audit.get(
        "metadata", {}
    )
    if not isinstance(protein_meta, dict):
        protein_meta = {}
    topology_meta = epk_heteromeric_chain_topology_signal_audit.get(
        "metadata", {}
    )
    if not isinstance(topology_meta, dict):
        topology_meta = {}
    length_meta = (
        epk_length_band_substrate_identity_counteraxis_audit.get("metadata", {})
        if isinstance(epk_length_band_substrate_identity_counteraxis_audit, dict)
        else {}
    )
    if not isinstance(length_meta, dict):
        length_meta = {}

    target_fingerprint_id = str(
        protein_meta.get("target_fingerprint_id")
        or topology_meta.get("target_fingerprint_id")
        or length_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    rule_id = "epk_source_free_protein_substrate_role_discriminator_v0_review_only"

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    current_positive_hit_pdb_ids: list[str] = []
    current_positive_miss_pdb_ids: list[str] = []
    heteromeric_positive_hit_pdb_ids: list[str] = []
    heteromeric_positive_miss_pdb_ids: list[str] = []
    ligand_analog_excluded_entry_ids: list[str] = []
    control_false_hit_pdb_ids: list[str] = []
    external_non_abstention_entry_ids: list[str] = []

    def _add_row(
        *,
        source_row: dict[str, Any],
        row_type: str,
        source_mode: str,
        rule_hit: bool,
        decision: str,
        control_like: bool = False,
        external_like: bool = False,
    ) -> None:
        status_counts[decision] += 1
        rows.append(
            {
                "row_type": row_type,
                "source_row_type": source_row.get("row_type"),
                "source_mode": source_mode,
                "entry_id": source_row.get("entry_id"),
                "pdb_id": source_row.get("pdb_id"),
                "family_id": source_row.get("family_id"),
                "family_name": source_row.get("family_name"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "rule_id": rule_id,
                "source_candidate_feature_hit": bool(
                    source_row.get("candidate_feature_hit")
                ),
                "non_catalytic_chain_acceptor": bool(
                    source_row.get("non_catalytic_chain_acceptor")
                ),
                "heteromeric_chain_entity_signal_hit": bool(
                    source_row.get("heteromeric_chain_entity_signal_hit")
                ),
                "ligand_analog_acceptor": bool(
                    source_row.get("ligand_analog_acceptor")
                ),
                "nearest_gamma_to_acceptor_distance_angstrom": (
                    source_row.get(
                        "nearest_gamma_to_candidate_acceptor_distance_angstrom"
                    )
                    or source_row.get("nearest_gamma_to_acceptor_distance_angstrom")
                    or source_row.get("source_valid_5hvk_distance_angstrom")
                ),
                "source_feature_decision": (
                    source_row.get("feature_audit_decision")
                    or source_row.get("known_review_context_class")
                    or source_row.get("source_feature_decision")
                ),
                "protein_substrate_role_discriminator_hit": rule_hit,
                "protein_substrate_role_discriminator_decision": decision,
                "control_like": control_like,
                "external_hard_negative_like": external_like,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "protein_substrate_role_discriminator_not_calibrated_as_scorer",
                    "length_band_counteraxis_source_expansion_only",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    for source_row in epk_protein_substrate_acceptor_candidate_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        source_type = str(source_row.get("row_type") or "")
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        entry_id = str(source_row.get("entry_id") or "")
        rule_hit = bool(source_row.get("candidate_feature_hit")) and bool(
            source_row.get("non_catalytic_chain_acceptor")
        ) and not bool(source_row.get("ligand_analog_acceptor"))
        if source_type == "current_epk_positive_prototype":
            if bool(source_row.get("ligand_analog_acceptor")):
                ligand_analog_excluded_entry_ids.append(entry_id)
                decision = "ligand_analog_positive_excluded_from_protein_role_discriminator"
            elif rule_hit:
                current_positive_hit_pdb_ids.append(pdb_id)
                decision = "current_positive_protein_role_discriminator_hit_review_only"
            else:
                current_positive_miss_pdb_ids.append(pdb_id)
                decision = "current_positive_protein_role_discriminator_miss_review_only"
            _add_row(
                source_row=source_row,
                row_type="protein_role_current_positive",
                source_mode="current_protein_substrate_acceptor",
                rule_hit=rule_hit,
                decision=decision,
            )
        elif source_type == "imported_external_hard_negative":
            if rule_hit:
                external_non_abstention_entry_ids.append(entry_id)
                decision = "external_hard_negative_protein_role_non_abstention"
            else:
                decision = "external_hard_negative_protein_role_abstention"
            _add_row(
                source_row=source_row,
                row_type="protein_role_imported_external_hard_negative",
                source_mode="imported_external_hard_negative",
                rule_hit=rule_hit,
                decision=decision,
                external_like=True,
            )
        elif source_type.endswith("negative_control"):
            if rule_hit:
                control_false_hit_pdb_ids.append(pdb_id)
                decision = "protein_role_control_false_hit_review_only"
            else:
                decision = "protein_role_control_blocked_review_only"
            _add_row(
                source_row=source_row,
                row_type="protein_role_sibling_or_local_control",
                source_mode="protein_substrate_control",
                rule_hit=rule_hit,
                decision=decision,
                control_like=True,
            )

    for source_row in epk_heteromeric_chain_topology_signal_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        if source_row.get("row_type") != "heteromeric_chain_topology_hit_control":
            continue
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        review_class = str(source_row.get("known_review_context_class") or "")
        rule_hit = bool(source_row.get("heteromeric_chain_entity_signal_hit"))
        source_valid = review_class == "cross_accession_source_valid_positive_like"
        if source_valid:
            if rule_hit:
                heteromeric_positive_hit_pdb_ids.append(pdb_id)
                decision = "heteromeric_protein_role_discriminator_hit_review_only"
            else:
                heteromeric_positive_miss_pdb_ids.append(pdb_id)
                decision = "heteromeric_protein_role_discriminator_miss_review_only"
            _add_row(
                source_row=source_row,
                row_type="protein_role_heteromeric_positive",
                source_mode="heteromeric_protein_substrate",
                rule_hit=rule_hit,
                decision=decision,
            )
        else:
            if rule_hit:
                control_false_hit_pdb_ids.append(pdb_id)
                decision = "heteromeric_topology_control_false_hit_review_only"
            else:
                decision = "heteromeric_topology_control_blocked_review_only"
            _add_row(
                source_row=source_row,
                row_type="protein_role_heteromeric_topology_control",
                source_mode="heteromeric_topology_control",
                rule_hit=rule_hit,
                decision=decision,
                control_like=True,
            )

    current_positive_hit_pdb_ids = _sorted_strings(current_positive_hit_pdb_ids)
    current_positive_miss_pdb_ids = _sorted_strings(current_positive_miss_pdb_ids)
    heteromeric_positive_hit_pdb_ids = _sorted_strings(
        heteromeric_positive_hit_pdb_ids
    )
    heteromeric_positive_miss_pdb_ids = _sorted_strings(
        heteromeric_positive_miss_pdb_ids
    )
    ligand_analog_excluded_entry_ids = _sorted_strings(
        ligand_analog_excluded_entry_ids
    )
    control_false_hit_pdb_ids = _sorted_strings(control_false_hit_pdb_ids)
    external_non_abstention_entry_ids = _sorted_strings(
        external_non_abstention_entry_ids
    )
    positive_hit_pdb_ids = _sorted_strings(
        [*current_positive_hit_pdb_ids, *heteromeric_positive_hit_pdb_ids]
    )
    positive_miss_pdb_ids = _sorted_strings(
        [*current_positive_miss_pdb_ids, *heteromeric_positive_miss_pdb_ids]
    )
    passes_current_controls = (
        len(positive_hit_pdb_ids) >= 3
        and not positive_miss_pdb_ids
        and not control_false_hit_pdb_ids
        and not external_non_abstention_entry_ids
    )
    status = (
        "passes_current_controls_but_review_only_not_production_admissible"
        if passes_current_controls
        else "blocked_review_only_protein_role_discriminator_gap_or_false_hit"
    )

    return {
        "metadata": {
            "method": "epk_source_free_protein_substrate_role_discriminator_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "rule_id": rule_id,
            "source_epk_protein_substrate_acceptor_candidate_audit_method": (
                protein_meta.get("method")
            ),
            "source_epk_heteromeric_chain_topology_signal_audit_method": (
                topology_meta.get("method")
            ),
            "source_epk_length_band_substrate_identity_counteraxis_audit_method": (
                length_meta.get("method")
            ),
            "protein_substrate_role_discriminator_status": status,
            "protein_substrate_role_discriminator_passes_current_controls": (
                passes_current_controls
            ),
            "current_protein_positive_hit_count": len(
                current_positive_hit_pdb_ids
            ),
            "current_protein_positive_hit_pdb_ids": current_positive_hit_pdb_ids,
            "heteromeric_protein_positive_hit_count": len(
                heteromeric_positive_hit_pdb_ids
            ),
            "heteromeric_protein_positive_hit_pdb_ids": (
                heteromeric_positive_hit_pdb_ids
            ),
            "combined_protein_substrate_role_hit_count": len(
                positive_hit_pdb_ids
            ),
            "combined_protein_substrate_role_hit_pdb_ids": positive_hit_pdb_ids,
            "protein_substrate_role_miss_count": len(positive_miss_pdb_ids),
            "protein_substrate_role_miss_pdb_ids": positive_miss_pdb_ids,
            "ligand_analog_excluded_positive_count": len(
                ligand_analog_excluded_entry_ids
            ),
            "ligand_analog_excluded_positive_entry_ids": (
                ligand_analog_excluded_entry_ids
            ),
            "protein_role_control_false_hit_count": len(
                control_false_hit_pdb_ids
            ),
            "protein_role_control_false_hit_pdb_ids": control_false_hit_pdb_ids,
            "protein_role_external_hard_negative_non_abstention_count": len(
                external_non_abstention_entry_ids
            ),
            "protein_role_external_hard_negative_non_abstention_entry_ids": (
                external_non_abstention_entry_ids
            ),
            "length_band_source_expansion_positive_hit_count": (
                length_meta.get("positive_like_length_band_hit_count")
            ),
            "length_band_blocked_relaxed_false_hit_count": (
                length_meta.get(
                    "nonpositive_relaxed_false_hit_blocked_by_length_band_count"
                )
            ),
            "length_band_not_general_protein_discriminator": True,
            "source_free_protein_substrate_role_ready_review_only": (
                passes_current_controls
            ),
            "general_substrate_identity_ready_count": 0,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "protein_substrate_role_decision_counts": dict(
                sorted(status_counts.items())
            ),
            "blocker_removed": "source_free_protein_substrate_role_discriminator_audited",
            "blocker_not_removed": [
                "protein_substrate_role_discriminator_not_calibrated_as_scorer",
                "general_substrate_identity_axis_still_missing",
                "length_band_counteraxis_source_expansion_only",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit combines two local protein-substrate role signals: "
                "non-catalytic-chain protein acceptor context in current ePK "
                "prototype rows and heteromeric entity topology in the 5HVK "
                "protein-substrate lead. It deliberately excludes ligand-analog "
                "support and does not create a calibrated ePK scorer."
            ),
            "next_actions": [
                "stress this protein-substrate role discriminator on new source-valid positives",
                "keep length-band evidence scoped to source-expansion peptide rows",
                "do not threshold or run a real external scored re-audit until a frozen scorer exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The protein-substrate role discriminator is review-only and "
                "does not authorize threshold selection, registry edits, label "
                "imports, or held-out performance claims."
            )
        ],
    }


def build_epk_source_free_protein_substrate_role_discriminator_stress_audit(
    *,
    epk_source_free_protein_substrate_role_discriminator_audit: dict[str, Any],
    epk_heteromeric_source_expansion_peptide_role_axis_audit: dict[str, Any],
) -> dict[str, Any]:
    """Stress the review-only protein-role rule on source-expansion rows."""

    protein_role_meta = (
        epk_source_free_protein_substrate_role_discriminator_audit.get(
            "metadata", {}
        )
        if isinstance(
            epk_source_free_protein_substrate_role_discriminator_audit, dict
        )
        else {}
    )
    if not isinstance(protein_role_meta, dict):
        protein_role_meta = {}
    source_expansion_meta = (
        epk_heteromeric_source_expansion_peptide_role_axis_audit.get(
            "metadata", {}
        )
        if isinstance(epk_heteromeric_source_expansion_peptide_role_axis_audit, dict)
        else {}
    )
    if not isinstance(source_expansion_meta, dict):
        source_expansion_meta = {}

    target_fingerprint_id = str(
        protein_role_meta.get("target_fingerprint_id")
        or source_expansion_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    rule_id = "epk_relaxed_folded_protein_substrate_role_stress_v0_review_only"
    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    source_valid_protein_hit_pdb_ids: list[str] = []
    source_valid_protein_miss_pdb_ids: list[str] = []
    nonpositive_false_hit_pdb_ids: list[str] = []
    peptide_mode_positive_pdb_ids: list[str] = []

    for source_row in (
        epk_heteromeric_source_expansion_peptide_role_axis_audit.get(
            "rows", []
        )
        or []
    ):
        if not isinstance(source_row, dict):
            continue
        source_type = str(source_row.get("row_type") or "")
        if source_type not in {
            "source_expansion_peptide_role_positive_candidate",
            "source_expansion_peptide_role_nonpositive_control",
        }:
            continue
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        source_valid = bool(source_row.get("source_validated_positive_like"))
        peptide_mode_hit = bool(
            source_row.get("source_free_peptide_role_axis_rule_hit")
        )
        relaxed_protein_role_hit = (
            not bool(source_row.get("peptide_like_acceptor_chain"))
            and bool(source_row.get("acceptor_chain_lacks_local_nucleotide_or_metal"))
            and bool(source_row.get("gamma_chain_has_local_nucleotide_or_metal"))
            and bool(source_row.get("gamma_chain_is_larger_polymer"))
        )
        if source_valid and relaxed_protein_role_hit:
            source_valid_protein_hit_pdb_ids.append(pdb_id)
            decision = "source_valid_expansion_protein_role_hit_review_only"
        elif source_valid and peptide_mode_hit:
            peptide_mode_positive_pdb_ids.append(pdb_id)
            decision = "source_valid_expansion_peptide_mode_not_protein_role"
        elif source_valid:
            source_valid_protein_miss_pdb_ids.append(pdb_id)
            decision = "source_valid_expansion_protein_role_miss_review_only"
        elif relaxed_protein_role_hit:
            nonpositive_false_hit_pdb_ids.append(pdb_id)
            decision = "nonpositive_source_expansion_protein_role_false_hit"
        else:
            decision = "nonpositive_source_expansion_protein_role_blocked"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "source_expansion_protein_role_stress",
                "source_row_type": source_type,
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "rule_id": rule_id,
                "source_validated_positive_like": source_valid,
                "source_validation_status_review_context": source_row.get(
                    "source_validation_status_review_context"
                ),
                "peptide_like_acceptor_chain": bool(
                    source_row.get("peptide_like_acceptor_chain")
                ),
                "acceptor_chain_residue_count": source_row.get(
                    "acceptor_chain_residue_count"
                ),
                "acceptor_chain_lacks_local_nucleotide_or_metal": bool(
                    source_row.get(
                        "acceptor_chain_lacks_local_nucleotide_or_metal"
                    )
                ),
                "gamma_chain_has_local_nucleotide_or_metal": bool(
                    source_row.get("gamma_chain_has_local_nucleotide_or_metal")
                ),
                "gamma_chain_is_larger_polymer": bool(
                    source_row.get("gamma_chain_is_larger_polymer")
                ),
                "candidate_acceptor_chain_name": source_row.get(
                    "candidate_acceptor_chain_name"
                ),
                "gamma_associated_polymer_chain_name": source_row.get(
                    "gamma_associated_polymer_chain_name"
                ),
                "nearest_gamma_distance_angstrom": source_row.get(
                    "nearest_gamma_distance_angstrom"
                ),
                "relaxed_folded_protein_role_rule_hit": (
                    relaxed_protein_role_hit
                ),
                "protein_substrate_role_stress_decision": decision,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "relaxed_protein_role_false_hit_in_source_expansion_stress",
                    "no_source_valid_expansion_protein_substrate_positive",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    source_valid_protein_hit_pdb_ids = _sorted_strings(
        source_valid_protein_hit_pdb_ids
    )
    source_valid_protein_miss_pdb_ids = _sorted_strings(
        source_valid_protein_miss_pdb_ids
    )
    nonpositive_false_hit_pdb_ids = _sorted_strings(nonpositive_false_hit_pdb_ids)
    peptide_mode_positive_pdb_ids = _sorted_strings(peptide_mode_positive_pdb_ids)
    stress_passed = (
        bool(source_valid_protein_hit_pdb_ids)
        and not source_valid_protein_miss_pdb_ids
        and not nonpositive_false_hit_pdb_ids
    )
    if stress_passed:
        status = "passes_source_expansion_protein_role_stress_review_only"
    elif nonpositive_false_hit_pdb_ids:
        status = "fails_closed_review_only_source_expansion_protein_role_false_hit"
    else:
        status = "blocked_review_only_no_source_valid_expansion_protein_positive"

    return {
        "metadata": {
            "method": (
                "epk_source_free_protein_substrate_role_discriminator_stress_audit"
            ),
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "rule_id": rule_id,
            "source_epk_source_free_protein_substrate_role_discriminator_audit_method": (
                protein_role_meta.get("method")
            ),
            "source_epk_heteromeric_source_expansion_peptide_role_axis_audit_method": (
                source_expansion_meta.get("method")
            ),
            "source_protein_role_discriminator_status": protein_role_meta.get(
                "protein_substrate_role_discriminator_status"
            ),
            "source_expansion_reviewed_row_count": len(rows),
            "source_valid_expansion_protein_role_hit_count": len(
                source_valid_protein_hit_pdb_ids
            ),
            "source_valid_expansion_protein_role_hit_pdb_ids": (
                source_valid_protein_hit_pdb_ids
            ),
            "source_valid_expansion_protein_role_miss_count": len(
                source_valid_protein_miss_pdb_ids
            ),
            "source_valid_expansion_protein_role_miss_pdb_ids": (
                source_valid_protein_miss_pdb_ids
            ),
            "source_valid_expansion_peptide_mode_not_protein_count": len(
                peptide_mode_positive_pdb_ids
            ),
            "source_valid_expansion_peptide_mode_not_protein_pdb_ids": (
                peptide_mode_positive_pdb_ids
            ),
            "nonpositive_source_expansion_protein_role_false_hit_count": len(
                nonpositive_false_hit_pdb_ids
            ),
            "nonpositive_source_expansion_protein_role_false_hit_pdb_ids": (
                nonpositive_false_hit_pdb_ids
            ),
            "protein_role_source_expansion_stress_status": status,
            "protein_discriminator_generalization_ready": stress_passed,
            "source_expansion_stress_decision_counts": dict(
                sorted(decision_counts.items())
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "source_expansion_protein_role_stress_audit_executed",
            "blocker_not_removed": [
                "protein_role_discriminator_has_no_broad_source_valid_protein_positive",
                "relaxed_folded_protein_role_false_hits_7b56",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "next_actions": [
                "source a true broad protein-substrate ePK positive before generalizing this discriminator",
                "treat 7B56 as a mid-length folded-substrate false hit for relaxed protein-role rules",
                "keep production scoring and external scored re-audit closed",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("source_row_type") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "This stress audit is a negative review-only result and does "
                "not authorize an ePK scorer, threshold, label import, or "
                "clean held-out performance claim."
            )
        ],
    }


def build_epk_midlength_protein_role_counteraxis_audit(
    *,
    epk_source_free_protein_substrate_role_discriminator_stress_audit: dict[str, Any],
    epk_heteromeric_source_valid_candidate_gamma_distance_sample: dict[str, Any]
    | None = None,
    max_short_acceptor_residues: int = 40,
    min_large_acceptor_residues: int = 120,
    cif_text_by_pdb: dict[str, str] | None = None,
    cif_fetcher=fetch_pdb_cif,
) -> dict[str, Any]:
    """Block mid-length protein-role false hits in review-only ePK stress rows."""

    stress_meta = (
        epk_source_free_protein_substrate_role_discriminator_stress_audit.get(
            "metadata", {}
        )
        if isinstance(
            epk_source_free_protein_substrate_role_discriminator_stress_audit, dict
        )
        else {}
    )
    if not isinstance(stress_meta, dict):
        stress_meta = {}
    source_valid_sample_meta = (
        epk_heteromeric_source_valid_candidate_gamma_distance_sample.get(
            "metadata", {}
        )
        if isinstance(epk_heteromeric_source_valid_candidate_gamma_distance_sample, dict)
        else {}
    )
    if not isinstance(source_valid_sample_meta, dict):
        source_valid_sample_meta = {}
    target_fingerprint_id = str(
        stress_meta.get("target_fingerprint_id")
        or source_valid_sample_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    try:
        short_max = int(max_short_acceptor_residues)
    except (TypeError, ValueError):
        short_max = 40
    try:
        large_min = int(min_large_acceptor_residues)
    except (TypeError, ValueError):
        large_min = 120
    if short_max < 1:
        short_max = 40
    if large_min <= short_max:
        large_min = short_max + 1

    def _optional_int(value: Any) -> int | None:
        try:
            if value in {None, "", ".", "?"}:
                return None
            return int(value)
        except (TypeError, ValueError):
            return None

    cif_texts = {
        str(key).upper(): value for key, value in (cif_text_by_pdb or {}).items()
    }
    cif_cache: dict[str, tuple[str, str, str | None]] = {}

    def _load_cif(pdb_id: str) -> tuple[str, str, str | None]:
        if pdb_id in cif_cache:
            return cif_cache[pdb_id]
        cif_text = cif_texts.get(pdb_id)
        fetch_status = "provided_cif_text" if cif_text is not None else "fetched"
        fetch_error = None
        try:
            if cif_text is None and pdb_id:
                cif_text = cif_fetcher(pdb_id)
        except Exception as exc:  # pragma: no cover - network failure is data.
            cif_text = ""
            fetch_status = "fetch_failed"
            fetch_error = str(exc)
        result = (cif_text or "", fetch_status, fetch_error)
        cif_cache[pdb_id] = result
        return result

    def _chain_residue_counts(cif_text: str) -> dict[str, int]:
        chain_residues: dict[str, set[tuple[str, str]]] = defaultdict(set)
        for atom in parse_atom_site_loop(cif_text):
            if atom.get("group_PDB") != "ATOM":
                continue
            chain_id = str(
                atom.get("auth_asym_id") or atom.get("label_asym_id") or ""
            )
            seq_id = str(atom.get("auth_seq_id") or atom.get("label_seq_id") or "")
            code = _epk_atom_code(atom)
            if chain_id and seq_id:
                chain_residues[chain_id].add((seq_id, code))
        return {
            chain_id: len(residue_keys)
            for chain_id, residue_keys in chain_residues.items()
        }

    def _best_distance_candidate(source_row: dict[str, Any]) -> dict[str, Any]:
        candidates = [
            candidate
            for candidate in source_row.get("distance_candidates", []) or []
            if isinstance(candidate, dict)
        ]
        if not candidates:
            return {}
        return sorted(
            candidates,
            key=lambda candidate: (
                float(
                    candidate.get("nearest_gamma_distance_angstrom")
                    or source_row.get("nearest_gamma_acceptor_distance_angstrom")
                    or 9999.0
                ),
                str(candidate.get("candidate_chain_name") or ""),
                str(candidate.get("candidate_auth_seq_id") or ""),
            ),
        )[0]

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    blocked_false_hit_pdb_ids: list[str] = []
    residual_false_hit_pdb_ids: list[str] = []
    source_valid_protein_retained_pdb_ids: list[str] = []
    source_valid_protein_lost_pdb_ids: list[str] = []
    source_valid_short_or_peptide_mode_pdb_ids: list[str] = []
    source_valid_chain_length_unresolved_pdb_ids: list[str] = []
    source_expansion_reviewed_row_count = 0

    for source_row in (
        epk_source_free_protein_substrate_role_discriminator_stress_audit.get(
            "rows", []
        )
        or []
    ):
        if not isinstance(source_row, dict):
            continue
        if source_row.get("row_type") != "source_expansion_protein_role_stress":
            continue
        source_expansion_reviewed_row_count += 1
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        source_valid = bool(source_row.get("source_validated_positive_like"))
        source_decision = str(source_row.get("protein_substrate_role_stress_decision") or "")
        relaxed_hit = bool(source_row.get("relaxed_folded_protein_role_rule_hit"))
        acceptor_count = _optional_int(source_row.get("acceptor_chain_residue_count"))
        midlength_counterevidence = (
            acceptor_count is not None
            and short_max < acceptor_count < large_min
        )
        repaired_hit = relaxed_hit and not midlength_counterevidence

        if source_decision == "source_valid_expansion_protein_role_hit_review_only":
            if repaired_hit:
                decision = "source_valid_protein_role_retained_review_only"
                source_valid_protein_retained_pdb_ids.append(pdb_id)
            else:
                decision = "source_valid_protein_role_lost_to_midlength_counteraxis_review_only"
                source_valid_protein_lost_pdb_ids.append(pdb_id)
        elif source_decision == "nonpositive_source_expansion_protein_role_false_hit":
            if midlength_counterevidence:
                decision = "nonpositive_midlength_false_hit_blocked_review_only"
                blocked_false_hit_pdb_ids.append(pdb_id)
            elif repaired_hit:
                decision = "nonpositive_residual_protein_role_false_hit_review_only"
                residual_false_hit_pdb_ids.append(pdb_id)
            else:
                decision = "nonpositive_false_hit_removed_by_prior_counterevidence_review_only"
        elif source_valid:
            decision = "source_valid_nonprotein_or_missed_row_carried_review_only"
        else:
            decision = "nonpositive_blocked_before_midlength_counteraxis_review_only"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "midlength_protein_role_counteraxis_stress",
                "source_row_type": source_row.get("row_type"),
                "source_stress_decision": source_decision,
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "rule_id": "epk_midlength_protein_role_counteraxis_v0_review_only",
                "max_short_acceptor_residues": short_max,
                "min_large_acceptor_residues": large_min,
                "source_validated_positive_like": source_valid,
                "source_validation_status_review_context": source_row.get(
                    "source_validation_status_review_context"
                ),
                "candidate_acceptor_chain_name": source_row.get(
                    "candidate_acceptor_chain_name"
                ),
                "gamma_associated_polymer_chain_name": source_row.get(
                    "gamma_associated_polymer_chain_name"
                ),
                "acceptor_chain_residue_count": acceptor_count,
                "nearest_gamma_distance_angstrom": source_row.get(
                    "nearest_gamma_distance_angstrom"
                ),
                "relaxed_folded_protein_role_rule_hit": relaxed_hit,
                "midlength_acceptor_counterevidence_hit": (
                    midlength_counterevidence
                ),
                "repaired_protein_role_rule_hit": repaired_hit,
                "midlength_counteraxis_decision": decision,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "no_source_valid_expansion_protein_substrate_positive",
                    "midlength_counteraxis_source_expansion_only",
                    "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    source_valid_measured_candidate_count = 0
    for source_row in (
        (
            epk_heteromeric_source_valid_candidate_gamma_distance_sample or {}
        ).get("rows", [])
        or []
    ):
        if not isinstance(source_row, dict):
            continue
        if not bool(source_row.get("source_validated_positive_like")):
            continue
        source_valid_measured_candidate_count += 1
        pdb_id = str(source_row.get("pdb_id") or "").upper()
        hit = _best_distance_candidate(source_row)
        acceptor_count = _optional_int(
            hit.get("acceptor_chain_residue_count")
            or source_row.get("acceptor_chain_residue_count")
        )
        gamma_count = _optional_int(
            hit.get("gamma_chain_residue_count")
            or source_row.get("gamma_chain_residue_count")
        )
        fetch_status = "not_needed_embedded_chain_lengths"
        fetch_error = None
        if acceptor_count is None and hit:
            cif_text, fetch_status, fetch_error = _load_cif(pdb_id)
            if cif_text:
                chain_counts = _chain_residue_counts(cif_text)
                acceptor_count = chain_counts.get(
                    str(hit.get("candidate_chain_name") or "")
                )
                gamma_count = chain_counts.get(
                    str(hit.get("gamma_associated_polymer_chain_name") or "")
                )

        midlength_counterevidence = (
            acceptor_count is not None
            and short_max < acceptor_count < large_min
        )
        short_or_peptide_mode = (
            acceptor_count is not None and acceptor_count <= short_max
        )
        broad_protein_mode = (
            acceptor_count is not None and acceptor_count >= large_min
        )
        repaired_hit = broad_protein_mode and not midlength_counterevidence
        if repaired_hit:
            decision = "source_valid_broad_protein_role_retained_review_only"
            source_valid_protein_retained_pdb_ids.append(pdb_id)
        elif midlength_counterevidence:
            decision = "source_valid_midlength_positive_lost_to_counteraxis_review_only"
            source_valid_protein_lost_pdb_ids.append(pdb_id)
        elif short_or_peptide_mode:
            decision = "source_valid_short_peptide_mode_not_broad_protein_role_review_only"
            source_valid_short_or_peptide_mode_pdb_ids.append(pdb_id)
        else:
            decision = "source_valid_chain_length_unresolved_review_only"
            source_valid_chain_length_unresolved_pdb_ids.append(pdb_id)
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "source_valid_measured_protein_role_counteraxis_stress",
                "source_row_type": source_row.get("row_type"),
                "source_stress_decision": source_row.get("measurement_status"),
                "pdb_id": pdb_id,
                "source_pair_id": source_row.get("source_pair_id"),
                "target_family_id": "epk",
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": True,
                "rule_id": "epk_midlength_protein_role_counteraxis_v0_review_only",
                "max_short_acceptor_residues": short_max,
                "min_large_acceptor_residues": large_min,
                "source_validated_positive_like": True,
                "source_validation_status_review_context": (
                    "source_valid_heteromeric_gamma_distance_measured_review_only"
                ),
                "candidate_acceptor_chain_name": hit.get("candidate_chain_name"),
                "gamma_associated_polymer_chain_name": hit.get(
                    "gamma_associated_polymer_chain_name"
                ),
                "acceptor_chain_residue_count": acceptor_count,
                "gamma_chain_residue_count": gamma_count,
                "chain_length_fetch_status": fetch_status,
                "chain_length_fetch_error": fetch_error,
                "nearest_gamma_distance_angstrom": hit.get(
                    "nearest_gamma_distance_angstrom"
                )
                or source_row.get("nearest_gamma_acceptor_distance_angstrom"),
                "relaxed_folded_protein_role_rule_hit": broad_protein_mode,
                "midlength_acceptor_counterevidence_hit": (
                    midlength_counterevidence
                ),
                "short_or_peptide_mode_acceptor_hit": short_or_peptide_mode,
                "broad_protein_mode_acceptor_hit": broad_protein_mode,
                "repaired_protein_role_rule_hit": repaired_hit,
                "midlength_counteraxis_decision": decision,
                "production_scoring_admissible": False,
                "ready_for_production_scoring": False,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "source_valid_positive_not_broad_protein_substrate_mode"
                    if short_or_peptide_mode
                    else "source_valid_positive_chain_length_unresolved"
                    if acceptor_count is None
                    else "threshold_not_calibrated_against_negative_controls",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    blocked_false_hit_pdb_ids = _sorted_strings(blocked_false_hit_pdb_ids)
    residual_false_hit_pdb_ids = _sorted_strings(residual_false_hit_pdb_ids)
    source_valid_protein_retained_pdb_ids = _sorted_strings(
        source_valid_protein_retained_pdb_ids
    )
    source_valid_protein_lost_pdb_ids = _sorted_strings(
        source_valid_protein_lost_pdb_ids
    )
    source_valid_short_or_peptide_mode_pdb_ids = _sorted_strings(
        source_valid_short_or_peptide_mode_pdb_ids
    )
    source_valid_chain_length_unresolved_pdb_ids = _sorted_strings(
        source_valid_chain_length_unresolved_pdb_ids
    )
    if residual_false_hit_pdb_ids or source_valid_protein_lost_pdb_ids:
        status = "fails_closed_midlength_counteraxis_has_residual_risk"
    elif blocked_false_hit_pdb_ids and not source_valid_protein_retained_pdb_ids:
        status = "blocks_current_midlength_false_hit_but_no_broad_positive_review_only"
    elif source_valid_protein_retained_pdb_ids:
        status = "passes_source_expansion_midlength_counteraxis_review_only"
    else:
        status = "blocked_review_only_no_midlength_false_hit_or_positive_to_test"

    return {
        "metadata": {
            "method": "epk_midlength_protein_role_counteraxis_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "rule_id": "epk_midlength_protein_role_counteraxis_v0_review_only",
            "source_epk_source_free_protein_substrate_role_discriminator_stress_audit_method": (
                stress_meta.get("method")
            ),
            "source_epk_heteromeric_source_valid_candidate_gamma_distance_sample_method": (
                source_valid_sample_meta.get("method")
            ),
            "max_short_acceptor_residues": short_max,
            "min_large_acceptor_residues": large_min,
            "source_expansion_reviewed_row_count": source_expansion_reviewed_row_count,
            "reviewed_row_count": len(rows),
            "source_valid_measured_candidate_count": (
                source_valid_measured_candidate_count
            ),
            "midlength_counteraxis_status": status,
            "midlength_counteraxis_decision_counts": dict(
                sorted(decision_counts.items())
            ),
            "blocked_midlength_false_hit_count": len(blocked_false_hit_pdb_ids),
            "blocked_midlength_false_hit_pdb_ids": blocked_false_hit_pdb_ids,
            "residual_protein_role_false_hit_count": len(residual_false_hit_pdb_ids),
            "residual_protein_role_false_hit_pdb_ids": residual_false_hit_pdb_ids,
            "source_valid_protein_role_retained_count": len(
                source_valid_protein_retained_pdb_ids
            ),
            "source_valid_protein_role_retained_pdb_ids": (
                source_valid_protein_retained_pdb_ids
            ),
            "source_valid_protein_role_lost_count": len(
                source_valid_protein_lost_pdb_ids
            ),
            "source_valid_protein_role_lost_pdb_ids": (
                source_valid_protein_lost_pdb_ids
            ),
            "source_valid_short_or_peptide_mode_count": len(
                source_valid_short_or_peptide_mode_pdb_ids
            ),
            "source_valid_short_or_peptide_mode_pdb_ids": (
                source_valid_short_or_peptide_mode_pdb_ids
            ),
            "source_valid_chain_length_unresolved_count": len(
                source_valid_chain_length_unresolved_pdb_ids
            ),
            "source_valid_chain_length_unresolved_pdb_ids": (
                source_valid_chain_length_unresolved_pdb_ids
            ),
            "protein_discriminator_generalization_ready": (
                bool(source_valid_protein_retained_pdb_ids)
                and not residual_false_hit_pdb_ids
                and not source_valid_protein_lost_pdb_ids
            ),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_production_scoring": False,
            "ready_for_orphan_discovery_claims": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "midlength_protein_role_counteraxis_evaluated",
            "blocker_not_removed": [
                "source_valid_broad_protein_substrate_positive_missing",
                "midlength_counteraxis_source_expansion_only",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This audit adds a narrow counterevidence rule to the relaxed "
                "protein-role stress surface: mid-length acceptor polymers are "
                "blocked until a source-valid broad protein-substrate positive "
                "supports that band. It changes no score, threshold, label, or "
                "registry state."
            ),
            "next_actions": [
                "source a true broad protein-substrate ePK positive before treating the repaired protein-role rule as general",
                "keep 7B56 as blocked mid-length counterevidence for relaxed protein-role logic",
                "keep production scoring and external scored re-audit closed",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("source_stress_decision") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The mid-length counteraxis is review-only and cannot authorize "
                "threshold selection, registry edits, label imports, or "
                "held-out performance claims."
            )
        ],
    }


def build_epk_external_source_lower_priority_ligand_sourcing_review(
    *,
    epk_external_source_structure_mapping_review: dict[str, Any],
    epk_external_protein_substrate_source_scout: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Classify mapped external ePK rows whose ligand axis is incomplete."""

    mapping_meta = epk_external_source_structure_mapping_review.get("metadata", {})
    if not isinstance(mapping_meta, dict):
        mapping_meta = {}
    scout_meta = (epk_external_protein_substrate_source_scout or {}).get(
        "metadata", {}
    )
    if not isinstance(scout_meta, dict):
        scout_meta = {}
    target_fingerprint_id = str(
        mapping_meta.get("target_fingerprint_id")
        or scout_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    scout_rows_by_accession = {
        str(row.get("accession") or "").upper(): row
        for row in (epk_external_protein_substrate_source_scout or {}).get(
            "rows", []
        )
        or []
        if isinstance(row, dict)
    }
    gamma_capable_codes = {"ACP", "ANP", "ATP", "DTP"}
    inactive_analog_codes = {"AGS"}

    rows: list[dict[str, Any]] = []
    status_counts: Counter[str] = Counter()
    incomplete_rows = [
        row
        for row in epk_external_source_structure_mapping_review.get("rows", []) or []
        if isinstance(row, dict)
        and row.get("mapping_review_status")
        == "direct_position_mapping_ready_ligand_context_incomplete_review_only"
    ]
    for mapping_row in incomplete_rows:
        accession = str(mapping_row.get("accession") or "").upper()
        pdb_id = str(mapping_row.get("pdb_id") or "").upper()
        local_ligand_codes = _sorted_strings(mapping_row.get("local_ligand_codes", []))
        local_cofactor_families = _sorted_strings(
            mapping_row.get("local_cofactor_families", [])
        )
        structure_ligand_codes = _sorted_strings(
            mapping_row.get("structure_ligand_codes", [])
        )
        structure_cofactor_families = _sorted_strings(
            mapping_row.get("structure_cofactor_families", [])
        )
        local_has_gamma = bool(set(local_ligand_codes) & gamma_capable_codes)
        local_has_metal = "metal_ion" in set(local_cofactor_families)
        structure_has_gamma = bool(set(structure_ligand_codes) & gamma_capable_codes)
        structure_has_metal = "metal_ion" in set(structure_cofactor_families)
        has_inactive_analog = bool(
            (set(local_ligand_codes) | set(structure_ligand_codes))
            & inactive_analog_codes
        )
        scout_row = scout_rows_by_accession.get(accession, {})
        scout_pdb_ids = _sorted_strings(scout_row.get("pdb_ids", []))
        remaining_scout_alternates = [
            candidate for candidate in scout_pdb_ids if candidate != pdb_id
        ]

        if local_has_gamma and local_has_metal:
            status = "unexpected_active_gamma_metal_ready_rerun_mapping_review"
            blockers = [
                "rerun_structure_mapping_review",
                "protein_substrate_acceptor_not_source_mapped",
            ]
        elif has_inactive_analog and structure_has_metal:
            status = "inactive_analog_metal_only_needs_policy_or_alternate_review_only"
            blockers = [
                "active_gamma_capable_nucleotide_missing",
                "analog_policy_not_active",
                "protein_substrate_acceptor_not_source_mapped",
            ]
        elif structure_has_gamma and not structure_has_metal:
            status = "gamma_without_metal_needs_alternate_review_only"
            blockers = [
                "local_metal_context_missing",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif structure_has_metal and not structure_has_gamma:
            status = "metal_without_gamma_needs_alternate_review_only"
            blockers = [
                "active_gamma_capable_nucleotide_missing",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        elif structure_ligand_codes:
            status = "non_atp_or_remote_ligand_context_needs_alternate_review_only"
            blockers = [
                "active_gamma_metal_context_missing",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        else:
            status = "no_ligand_context_needs_alternate_review_only"
            blockers = [
                "active_gamma_metal_context_missing",
                "protein_substrate_acceptor_not_source_mapped",
                "external_hard_negative_reaudit_not_real_scorer",
            ]
        status_counts[status] += 1
        rows.append(
            {
                "accession": accession,
                "entry_id": mapping_row.get("entry_id"),
                "pdb_id": pdb_id,
                "target_family_id": "epk",
                "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                "review_only": True,
                "ready_for_label_import": False,
                "countable_label_candidate": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "mapping_review_status": mapping_row.get("mapping_review_status"),
                "mapped_residue_count": len(
                    mapping_row.get("mapped_residue_positions", []) or []
                ),
                "local_ligand_codes": local_ligand_codes,
                "local_cofactor_families": local_cofactor_families,
                "structure_ligand_codes": structure_ligand_codes,
                "structure_cofactor_families": structure_cofactor_families,
                "local_has_gamma_capable_nucleotide": local_has_gamma,
                "local_has_metal": local_has_metal,
                "structure_has_gamma_capable_nucleotide": structure_has_gamma,
                "structure_has_metal": structure_has_metal,
                "has_inactive_analog_ligand": has_inactive_analog,
                "current_scout_pdb_count": len(scout_pdb_ids),
                "remaining_current_scout_alternate_pdb_ids": (
                    remaining_scout_alternates
                ),
                "current_structure_measurement_ready": False,
                "measurement_ready": False,
                "ligand_sourcing_status": status,
                "remaining_blockers": sorted(set(blockers)),
            }
        )

    measurement_ready_count = sum(1 for row in rows if row.get("measurement_ready"))
    active_gamma_metal_count = sum(
        1
        for row in rows
        if row.get("local_has_gamma_capable_nucleotide") and row.get("local_has_metal")
    )
    sourcing_accessions = _sorted_strings(row.get("accession") for row in rows)
    sourcing_accession_text = (
        ", ".join(sourcing_accessions) if sourcing_accessions else "mapped accessions"
    )
    return {
        "metadata": {
            "method": "epk_external_source_lower_priority_ligand_sourcing_review",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_external_source_structure_mapping_review_method": (
                mapping_meta.get("method")
            ),
            "source_epk_external_protein_substrate_source_scout_method": (
                scout_meta.get("method")
            ),
            "reviewed_row_count": len(rows),
            "active_gamma_metal_current_structure_count": active_gamma_metal_count,
            "measurement_ready_candidate_count": measurement_ready_count,
            "ligand_sourcing_status_counts": dict(sorted(status_counts.items())),
            "ready_to_measure_gamma_acceptor_distance": measurement_ready_count > 0,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "lower_priority_mapped_ligand_context_reviewed",
            "blocker_not_removed": [
                "active_gamma_metal_context_missing",
                "protein_substrate_acceptor_not_source_mapped",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact reviews lower-priority mapped external ePK rows "
                "whose current structures lack a production-admissible local "
                "active gamma/metal axis. It does not score, import labels, or "
                "edit registries."
            ),
            "next_actions": [
                (
                    "source active gamma/metal structures for "
                    f"{sourcing_accession_text} outside the current mapped rows"
                ),
                "do not use inactive analog or remote ligand context as production positive evidence",
                "only rerun acceptor mapping after a local active gamma/metal axis exists",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("accession") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "Lower-priority mapped external rows remain review-only because "
                "their current ligand axis is incomplete."
            )
        ],
    }


def build_epk_external_source_scout_pass_terminal_decision(
    *,
    epk_external_protein_substrate_source_scouts: list[dict[str, Any]],
    epk_external_source_structure_mapping_reviews: list[dict[str, Any]],
    epk_external_source_ligand_sourcing_reviews: list[dict[str, Any]] | None = None,
    epk_external_source_alternate_cocomplex_review: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Summarize bounded external ePK source-scout passes and stop repeats."""

    ligand_reviews = epk_external_source_ligand_sourcing_reviews or []
    first_meta = (
        epk_external_protein_substrate_source_scouts[0].get("metadata", {})
        if epk_external_protein_substrate_source_scouts
        else {}
    )
    if not isinstance(first_meta, dict):
        first_meta = {}
    alternate_meta = (epk_external_source_alternate_cocomplex_review or {}).get(
        "metadata", {}
    )
    if not isinstance(alternate_meta, dict):
        alternate_meta = {}
    target_fingerprint_id = str(
        first_meta.get("target_fingerprint_id")
        or alternate_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    rows: list[dict[str, Any]] = []
    unique_sourced_accessions: set[str] = set()
    total_sourced = 0
    total_structure_rows = 0
    total_active_state_ready = 0
    total_direct_mapping_ready = 0
    total_ligand_review_rows = 0
    total_measurement_ready = 0

    pass_count = max(
        len(epk_external_protein_substrate_source_scouts),
        len(epk_external_source_structure_mapping_reviews),
        len(ligand_reviews),
    )
    for index in range(pass_count):
        scout = (
            epk_external_protein_substrate_source_scouts[index]
            if index < len(epk_external_protein_substrate_source_scouts)
            else {}
        )
        mapping = (
            epk_external_source_structure_mapping_reviews[index]
            if index < len(epk_external_source_structure_mapping_reviews)
            else {}
        )
        ligand = ligand_reviews[index] if index < len(ligand_reviews) else {}
        scout_meta = scout.get("metadata", {}) if isinstance(scout, dict) else {}
        mapping_meta = mapping.get("metadata", {}) if isinstance(mapping, dict) else {}
        ligand_meta = ligand.get("metadata", {}) if isinstance(ligand, dict) else {}
        if not isinstance(scout_meta, dict):
            scout_meta = {}
        if not isinstance(mapping_meta, dict):
            mapping_meta = {}
        if not isinstance(ligand_meta, dict):
            ligand_meta = {}

        sourced_accessions = _sorted_strings(
            scout_meta.get("sourced_candidate_accessions", [])
        )
        unique_sourced_accessions.update(sourced_accessions)
        sourced_count = int(scout_meta.get("sourced_candidate_count") or 0)
        structure_row_count = int(mapping_meta.get("structure_row_count") or 0)
        active_state_ready = int(
            mapping_meta.get("active_state_mapping_ready_structure_count") or 0
        )
        direct_mapping_ready = int(
            mapping_meta.get("direct_position_mapping_ready_structure_count") or 0
        )
        ligand_review_count = int(ligand_meta.get("reviewed_row_count") or 0)
        measurement_ready = int(
            mapping_meta.get("measurement_ready_candidate_count") or 0
        ) + int(ligand_meta.get("measurement_ready_candidate_count") or 0)
        total_sourced += sourced_count
        total_structure_rows += structure_row_count
        total_active_state_ready += active_state_ready
        total_direct_mapping_ready += direct_mapping_ready
        total_ligand_review_rows += ligand_review_count
        total_measurement_ready += measurement_ready
        rows.append(
            {
                "source_pass_id": f"external_epk_source_pass_{index + 1}",
                "review_only": True,
                "target_family_id": "epk",
                "target_fingerprint_id_if_future_gated": target_fingerprint_id,
                "sourced_candidate_count": sourced_count,
                "sourced_candidate_accessions": sourced_accessions,
                "structure_row_count": structure_row_count,
                "direct_position_mapping_ready_structure_count": direct_mapping_ready,
                "active_state_mapping_ready_structure_count": active_state_ready,
                "mapping_review_status_counts": mapping_meta.get(
                    "mapping_review_status_counts", {}
                ),
                "ligand_sourcing_reviewed_row_count": ligand_review_count,
                "ligand_sourcing_status_counts": ligand_meta.get(
                    "ligand_sourcing_status_counts", {}
                ),
                "measurement_ready_candidate_count": measurement_ready,
                "ready_to_run_epk_scorer": False,
                "countable_label_candidate": False,
            }
        )

    alternate_measurement_ready = int(
        alternate_meta.get("measurement_ready_candidate_count") or 0
    )
    total_measurement_ready += alternate_measurement_ready
    if total_measurement_ready == 0 and pass_count >= 3:
        terminal_decision = (
            "current_three_pass_external_source_surface_exhausted_review_only"
            if pass_count == 3
            else f"current_{pass_count}_pass_external_source_surface_exhausted_review_only"
        )
    else:
        terminal_decision = "continue_external_source_review_only"
    return {
        "metadata": {
            "method": "epk_external_source_scout_pass_terminal_decision",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_pass_count": pass_count,
            "unique_sourced_candidate_count": len(unique_sourced_accessions),
            "total_sourced_candidate_rows": total_sourced,
            "total_structure_row_count": total_structure_rows,
            "total_direct_position_mapping_ready_structure_count": (
                total_direct_mapping_ready
            ),
            "total_active_state_mapping_ready_structure_count": (
                total_active_state_ready
            ),
            "total_ligand_sourcing_reviewed_row_count": total_ligand_review_rows,
            "alternate_cocomplex_review_method": alternate_meta.get("method"),
            "alternate_cocomplex_source_phosphoacceptor_within_threshold_count": (
                alternate_meta.get("source_phosphoacceptor_within_threshold_count")
            ),
            "alternate_cocomplex_nearest_source_phosphoacceptor_distance_angstrom": (
                alternate_meta.get("nearest_source_phosphoacceptor_distance_angstrom")
            ),
            "measurement_ready_candidate_count": total_measurement_ready,
            "terminal_decision": terminal_decision,
            "current_source_candidates_exhausted": (
                terminal_decision.endswith(
                    "_pass_external_source_surface_exhausted_review_only"
                )
            ),
            "ready_to_measure_gamma_acceptor_distance": total_measurement_ready > 0,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "blocker_removed": "bounded_external_source_passes_adjudicated",
            "blocker_not_removed": [
                "measurement_ready_external_positive_missing",
                "threshold_not_calibrated_against_negative_controls",
                "external_hard_negative_reaudit_not_real_scorer",
                "registry_and_label_factory_extension_not_implemented",
            ],
            "review_only_rule": (
                "This artifact adjudicates the bounded external ePK positive "
                "source-scout passes. It stops repeat UniProt/PDB-backed scout "
                "loops without changing labels, scores, registries, or held-out "
                "claims."
            ),
            "next_actions": [
                "do not repeat the same broad UniProt PDB-backed ePK source scout without a ligand-specific active-state query",
                "try ligand-specific RCSB active ATP/ANP plus metal sourcing or a pre-frozen analog policy path",
                "keep the external hard-negative scored re-audit closed until a real calibrated ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "The current external ePK source surface is exhausted only for "
                "these bounded review-only passes."
            )
        ],
    }


def build_epk_analog_product_state_policy_preregistration(
    *,
    epk_protein_substrate_source_repair_terminal_decision: dict[str, Any],
    epk_ligand_analog_policy_blocker_decision: dict[str, Any],
) -> dict[str, Any]:
    """Draft a fail-closed preregistration for future ePK analog evidence."""

    terminal_meta = epk_protein_substrate_source_repair_terminal_decision.get(
        "metadata", {}
    )
    if not isinstance(terminal_meta, dict):
        terminal_meta = {}
    analog_meta = epk_ligand_analog_policy_blocker_decision.get("metadata", {})
    if not isinstance(analog_meta, dict):
        analog_meta = {}
    target_fingerprint_id = str(
        terminal_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    rows = [
        {
            "criterion_id": "freeze_policy_before_candidate_selection",
            "criterion_type": "activation_requirement",
            "review_only": True,
            "passed": False,
            "production_use_allowed": False,
            "requirement": (
                "Any analog/product-state rule must be frozen before selecting "
                "or rescuing ePK source candidates."
            ),
        },
        {
            "criterion_id": "exclude_mechanism_text_as_predictive_support",
            "criterion_type": "predictive_input_exclusion",
            "review_only": True,
            "passed": True,
            "production_use_allowed": False,
            "requirement": (
                "Mechanism prose, entry names, EC/Rhea identifiers, and expert "
                "rationale remain review context only."
            ),
        },
        {
            "criterion_id": "reject_homomeric_chain_choice_as_substrate_mapping",
            "criterion_type": "predictive_input_exclusion",
            "review_only": True,
            "passed": True,
            "production_use_allowed": False,
            "requirement": (
                "A homomeric catalytic-chain alternative cannot stand in for a "
                "mapped protein-substrate acceptor chain."
            ),
        },
        {
            "criterion_id": "reject_product_state_without_gamma_geometry",
            "criterion_type": "predictive_input_exclusion",
            "review_only": True,
            "passed": True,
            "production_use_allowed": False,
            "requirement": (
                "ADP/product-state context without active-state gamma geometry "
                "cannot be used to measure or calibrate an ePK acceptor axis."
            ),
        },
        {
            "criterion_id": "require_external_hard_negative_scored_reaudit",
            "criterion_type": "activation_requirement",
            "review_only": True,
            "passed": False,
            "production_use_allowed": False,
            "requirement": (
                "The three imported external hard negatives must be rerun under "
                "a real calibrated ePK scorer before any policy activation."
            ),
        },
        {
            "criterion_id": "require_sibling_family_control_reaudit",
            "criterion_type": "activation_requirement",
            "review_only": True,
            "passed": False,
            "production_use_allowed": False,
            "requirement": (
                "NDK, PfkB, PfkA, and ATP-grasp controls must remain blocked "
                "under the exact frozen analog/product-state policy."
            ),
        },
    ]
    return {
        "metadata": {
            "method": "epk_analog_product_state_policy_preregistration",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_protein_substrate_source_repair_terminal_decision_method": (
                terminal_meta.get("method")
            ),
            "source_epk_ligand_analog_policy_blocker_decision_method": (
                analog_meta.get("method")
            ),
            "policy_status": "draft_preregistered_review_only_not_activated",
            "policy_activation_allowed": False,
            "production_scoring_admissible": False,
            "current_source_candidates_exhausted": bool(
                terminal_meta.get("current_source_candidates_exhausted")
            ),
            "source_repair_measurement_ready_candidate_count": (
                terminal_meta.get("measurement_ready_candidate_count")
            ),
            "ligand_analog_policy_decision": analog_meta.get(
                "ligand_analog_policy_decision"
            ),
            "ligand_analog_production_admissible_count": analog_meta.get(
                "ligand_analog_production_admissible_count"
            ),
            "criterion_count": len(rows),
            "activation_requirement_count": sum(
                1 for row in rows if row["criterion_type"] == "activation_requirement"
            ),
            "failed_activation_requirement_count": sum(
                1
                for row in rows
                if row["criterion_type"] == "activation_requirement"
                and not row["passed"]
            ),
            "predictive_input_exclusion_count": sum(
                1
                for row in rows
                if row["criterion_type"] == "predictive_input_exclusion"
            ),
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This is only a preregistration draft for future policy review. "
                "It cannot activate analog/product-state evidence, score ePK, "
                "edit registries, import labels, or claim clean held-out "
                "performance."
            ),
            "next_actions": [
                "keep this policy inactive until activation requirements are implemented and tested",
                "run sibling-family and imported external hard-negative re-audits before any policy use",
                "prefer new mapped protein-substrate source evidence over analog rescue when available",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "The analog/product-state policy is not active and authorizes no "
                "production ePK scoring evidence."
            )
        ],
    }


def build_epk_analog_product_state_policy_activation_audit(
    *,
    epk_analog_product_state_policy_preregistration: dict[str, Any],
    epk_ligand_analog_policy_blocker_decision: dict[str, Any],
    epk_protein_substrate_acceptor_candidate_audit: dict[str, Any],
    epk_chain_ligand_acceptor_disambiguation_audit: dict[str, Any],
    epk_chain_ligand_external_hard_negative_feature_screen: dict[str, Any],
    epk_protein_substrate_source_repair_terminal_decision: dict[str, Any],
    epk_precount_gate_status: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Audit whether the inactive ePK analog/product-state policy can activate."""

    prereg_meta = epk_analog_product_state_policy_preregistration.get(
        "metadata", {}
    )
    if not isinstance(prereg_meta, dict):
        prereg_meta = {}
    analog_meta = epk_ligand_analog_policy_blocker_decision.get("metadata", {})
    if not isinstance(analog_meta, dict):
        analog_meta = {}
    protein_meta = epk_protein_substrate_acceptor_candidate_audit.get(
        "metadata", {}
    )
    if not isinstance(protein_meta, dict):
        protein_meta = {}
    chain_meta = epk_chain_ligand_acceptor_disambiguation_audit.get(
        "metadata", {}
    )
    if not isinstance(chain_meta, dict):
        chain_meta = {}
    external_meta = epk_chain_ligand_external_hard_negative_feature_screen.get(
        "metadata", {}
    )
    if not isinstance(external_meta, dict):
        external_meta = {}
    terminal_meta = epk_protein_substrate_source_repair_terminal_decision.get(
        "metadata", {}
    )
    if not isinstance(terminal_meta, dict):
        terminal_meta = {}
    precount_meta = (
        epk_precount_gate_status.get("metadata", {})
        if isinstance(epk_precount_gate_status, dict)
        else {}
    )
    if not isinstance(precount_meta, dict):
        precount_meta = {}

    target_fingerprint_id = str(
        prereg_meta.get("target_fingerprint_id")
        or analog_meta.get("target_fingerprint_id")
        or protein_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )

    def _int_meta(meta: dict[str, Any], key: str) -> int:
        try:
            return int(meta.get(key) or 0)
        except (TypeError, ValueError):
            return 0

    def _criterion(
        *,
        criterion_id: str,
        criterion_type: str,
        passed: bool,
        evidence: dict[str, Any],
        blocker: str | None,
    ) -> dict[str, Any]:
        return {
            "criterion_id": criterion_id,
            "criterion_type": criterion_type,
            "review_only": True,
            "passed": passed,
            "production_use_allowed": False,
            "evidence": evidence,
            "blocker": blocker,
            "countable_label_candidate": False,
            "ready_for_label_import": False,
            "epk_score_computed": False,
            "external_hard_negative_reaudit_scored": False,
        }

    policy_frozen = bool(prereg_meta.get("policy_activation_allowed")) and bool(
        prereg_meta.get("production_scoring_admissible")
    )
    protein_positive_rows = _int_meta(protein_meta, "current_positive_row_count")
    protein_positive_hits = _int_meta(
        protein_meta, "current_positive_feature_hit_count"
    )
    protein_positive_coverage = (
        protein_positive_rows > 0 and protein_positive_hits == protein_positive_rows
    )
    ligand_dependency_count = _int_meta(analog_meta, "ligand_analog_dependency_count")
    ligand_admissible_count = _int_meta(
        analog_meta, "ligand_analog_production_admissible_count"
    )
    ligand_dependency_resolved = (
        ligand_dependency_count == 0
        or ligand_admissible_count == ligand_dependency_count
    )
    source_measurement_ready = (
        _int_meta(terminal_meta, "measurement_ready_candidate_count") > 0
    )
    chain_controls_blocked = (
        bool(chain_meta.get("feature_passes_current_review_controls"))
        and _int_meta(chain_meta, "negative_control_false_hit_count") == 0
    )
    external_feature_screen_passed = (
        bool(external_meta.get("review_only_feature_screen_passed"))
        and _int_meta(
            external_meta,
            "review_only_external_hard_negative_feature_non_abstention_count",
        )
        == 0
    )
    scorer_exists = bool(precount_meta.get("ready_to_run_epk_scorer")) and bool(
        precount_meta.get("epk_score_computed")
    )
    external_scored_reaudit = bool(
        external_meta.get("external_hard_negative_reaudit_scored")
        or precount_meta.get("external_hard_negative_reaudit_scored")
    )
    registry_extended = bool(precount_meta.get("fingerprint_registry_edited")) and bool(
        precount_meta.get("curated_label_registry_edited")
    )

    rows = [
        _criterion(
            criterion_id="policy_frozen_before_activation",
            criterion_type="activation_requirement",
            passed=policy_frozen,
            evidence={
                "policy_status": prereg_meta.get("policy_status"),
                "policy_activation_allowed": bool(
                    prereg_meta.get("policy_activation_allowed")
                ),
                "production_scoring_admissible": bool(
                    prereg_meta.get("production_scoring_admissible")
                ),
            },
            blocker=(
                None
                if policy_frozen
                else "policy_is_preregistered_but_not_frozen_or_active"
            ),
        ),
        _criterion(
            criterion_id="protein_substrate_positive_coverage_without_ligand_analog",
            criterion_type="activation_requirement",
            passed=protein_positive_coverage,
            evidence={
                "current_positive_row_count": protein_positive_rows,
                "current_positive_feature_hit_count": protein_positive_hits,
                "current_positive_feature_miss_count": _int_meta(
                    protein_meta, "current_positive_feature_miss_count"
                ),
                "ligand_analog_only_positive_miss_entry_ids": protein_meta.get(
                    "ligand_analog_only_positive_miss_entry_ids", []
                ),
            },
            blocker=(
                None
                if protein_positive_coverage
                else "protein_substrate_axis_still_misses_ligand_analog_positive"
            ),
        ),
        _criterion(
            criterion_id="ligand_analog_dependency_resolved",
            criterion_type="activation_requirement",
            passed=ligand_dependency_resolved,
            evidence={
                "ligand_analog_dependency_count": ligand_dependency_count,
                "ligand_analog_dependency_entry_ids": analog_meta.get(
                    "ligand_analog_dependency_entry_ids", []
                ),
                "ligand_analog_production_admissible_count": ligand_admissible_count,
                "ligand_analog_policy_decision": analog_meta.get(
                    "ligand_analog_policy_decision"
                ),
            },
            blocker=(
                None
                if ligand_dependency_resolved
                else "ligand_analog_dependency_has_zero_production_admissible_rows"
            ),
        ),
        _criterion(
            criterion_id="source_repair_measurement_ready_or_new_source",
            criterion_type="activation_requirement",
            passed=source_measurement_ready,
            evidence={
                "current_source_candidates_exhausted": bool(
                    terminal_meta.get("current_source_candidates_exhausted")
                ),
                "measurement_ready_candidate_count": _int_meta(
                    terminal_meta, "measurement_ready_candidate_count"
                ),
                "terminal_decision": terminal_meta.get("terminal_decision"),
                "recommended_next_experiment": terminal_meta.get(
                    "recommended_next_experiment"
                ),
            },
            blocker=(
                None
                if source_measurement_ready
                else "no_measurement_ready_protein_substrate_source_repair"
            ),
        ),
        _criterion(
            criterion_id="sibling_controls_remain_blocked_under_candidate_feature",
            criterion_type="diagnostic_control",
            passed=chain_controls_blocked,
            evidence={
                "candidate_feature_id": chain_meta.get("candidate_feature_id"),
                "feature_passes_current_review_controls": bool(
                    chain_meta.get("feature_passes_current_review_controls")
                ),
                "negative_control_false_hit_count": _int_meta(
                    chain_meta, "negative_control_false_hit_count"
                ),
                "negative_control_row_count": _int_meta(
                    chain_meta, "negative_control_row_count"
                ),
            },
            blocker=(
                None
                if chain_controls_blocked
                else "sibling_controls_not_clean_under_candidate_feature"
            ),
        ),
        _criterion(
            criterion_id="imported_external_hard_negative_feature_screen_clear",
            criterion_type="diagnostic_control",
            passed=external_feature_screen_passed,
            evidence={
                "review_only_feature_screen_passed": bool(
                    external_meta.get("review_only_feature_screen_passed")
                ),
                "review_only_external_hard_negative_feature_non_abstention_count": (
                    _int_meta(
                        external_meta,
                        "review_only_external_hard_negative_feature_non_abstention_count",
                    )
                ),
                "clean_heldout_performance_claim_permitted": bool(
                    external_meta.get("clean_heldout_performance_claim_permitted")
                ),
            },
            blocker=(
                None
                if external_feature_screen_passed
                else "external_hard_negative_feature_screen_not_clear"
            ),
        ),
        _criterion(
            criterion_id="calibrated_epk_score_exists",
            criterion_type="activation_requirement",
            passed=scorer_exists,
            evidence={
                "ready_to_run_epk_scorer": bool(
                    precount_meta.get("ready_to_run_epk_scorer")
                ),
                "epk_score_computed": bool(precount_meta.get("epk_score_computed")),
                "selected_acceptor_threshold_angstrom": precount_meta.get(
                    "selected_acceptor_threshold_angstrom"
                ),
                "threshold_calibrated": bool(
                    precount_meta.get("threshold_calibrated")
                ),
            },
            blocker=None if scorer_exists else "calibrated_epk_score_missing",
        ),
        _criterion(
            criterion_id="external_hard_negative_scored_reaudit",
            criterion_type="activation_requirement",
            passed=external_scored_reaudit,
            evidence={
                "external_hard_negative_reaudit_scored": external_scored_reaudit,
                "feature_screen_is_review_only": True,
            },
            blocker=(
                None
                if external_scored_reaudit
                else "external_hard_negatives_not_scored_under_real_epk_scorer"
            ),
        ),
        _criterion(
            criterion_id="registry_and_label_factory_extension",
            criterion_type="activation_requirement",
            passed=registry_extended,
            evidence={
                "fingerprint_registry_edited": bool(
                    precount_meta.get("fingerprint_registry_edited")
                ),
                "curated_label_registry_edited": bool(
                    precount_meta.get("curated_label_registry_edited")
                ),
                "ready_to_expand_positive_fingerprint_universe": bool(
                    precount_meta.get("ready_to_expand_positive_fingerprint_universe")
                ),
            },
            blocker=(
                None
                if registry_extended
                else "registry_and_label_factory_extension_not_implemented"
            ),
        ),
    ]
    activation_rows = [
        row for row in rows if row.get("criterion_type") == "activation_requirement"
    ]
    diagnostic_rows = [
        row for row in rows if row.get("criterion_type") == "diagnostic_control"
    ]
    activation_blockers = [
        row["blocker"] for row in activation_rows if not row["passed"] and row["blocker"]
    ]
    policy_activation_allowed = bool(activation_rows) and all(
        row["passed"] for row in activation_rows
    )
    if ligand_dependency_count and not ligand_dependency_resolved:
        recommended_next_experiment = (
            "source_mapped_protein_substrate_epk_positive_before_policy_activation"
        )
    elif not source_measurement_ready:
        recommended_next_experiment = (
            "source_new_epk_positive_or_keep_analog_policy_inactive"
        )
    else:
        recommended_next_experiment = (
            "calibrate_scorer_then_run_external_hard_negative_reaudit"
        )

    return {
        "metadata": {
            "method": "epk_analog_product_state_policy_activation_audit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_analog_product_state_policy_preregistration_method": (
                prereg_meta.get("method")
            ),
            "source_epk_ligand_analog_policy_blocker_decision_method": (
                analog_meta.get("method")
            ),
            "source_epk_protein_substrate_acceptor_candidate_audit_method": (
                protein_meta.get("method")
            ),
            "source_epk_chain_ligand_acceptor_disambiguation_audit_method": (
                chain_meta.get("method")
            ),
            "source_epk_chain_ligand_external_hard_negative_feature_screen_method": (
                external_meta.get("method")
            ),
            "source_epk_protein_substrate_source_repair_terminal_decision_method": (
                terminal_meta.get("method")
            ),
            "source_epk_precount_gate_status_method": precount_meta.get("method"),
            "policy_activation_status": (
                "activation_allowed_review_only_unexpected"
                if policy_activation_allowed
                else "blocked_review_only"
            ),
            "policy_activation_allowed": policy_activation_allowed,
            "production_scoring_admissible": False,
            "activation_requirement_count": len(activation_rows),
            "failed_activation_requirement_count": sum(
                1 for row in activation_rows if not row["passed"]
            ),
            "diagnostic_control_count": len(diagnostic_rows),
            "diagnostic_control_pass_count": sum(
                1 for row in diagnostic_rows if row["passed"]
            ),
            "activation_blockers": activation_blockers,
            "protein_substrate_positive_coverage_without_ligand_analog": (
                protein_positive_coverage
            ),
            "ligand_analog_dependency_count": ligand_dependency_count,
            "ligand_analog_dependency_entry_ids": analog_meta.get(
                "ligand_analog_dependency_entry_ids", []
            ),
            "ligand_analog_production_admissible_count": ligand_admissible_count,
            "source_repair_measurement_ready_candidate_count": _int_meta(
                terminal_meta, "measurement_ready_candidate_count"
            ),
            "sibling_controls_remain_blocked_under_candidate_feature": (
                chain_controls_blocked
            ),
            "imported_external_hard_negative_feature_screen_clear": (
                external_feature_screen_passed
            ),
            "external_hard_negative_reaudit_scored": external_scored_reaudit,
            "ready_to_run_epk_scorer": False,
            "epk_score_computed": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "recommended_next_experiment": recommended_next_experiment,
            "review_only_rule": (
                "This artifact audits whether the inactive ePK analog/product-state "
                "policy can be activated. It must fail closed unless positive "
                "coverage, source repair, scoring, external hard-negative re-audit, "
                "and registry gates are all satisfied."
            ),
            "next_actions": [
                "keep the analog/product-state policy inactive",
                "source a mapped protein-substrate ePK positive before analog rescue",
                "run external hard-negative scored re-audit only after a calibrated ePK scorer exists",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "The analog/product-state policy activation audit is review-only "
                "negative evidence and authorizes no production ePK scoring."
            )
        ],
    }


def build_epk_analog_product_state_policy_control_reaudit(
    *,
    epk_analog_product_state_policy_preregistration: dict[str, Any],
    epk_chain_ligand_acceptor_disambiguation_audit: dict[str, Any],
    epk_chain_ligand_external_hard_negative_feature_screen: dict[str, Any],
    epk_protein_substrate_source_repair_terminal_decision: dict[str, Any],
    imported_external_entry_ids: list[str] | None = None,
) -> dict[str, Any]:
    """Re-audit a frozen review-only analog/product-state policy surface."""

    prereg_meta = epk_analog_product_state_policy_preregistration.get(
        "metadata", {}
    )
    if not isinstance(prereg_meta, dict):
        prereg_meta = {}
    chain_meta = epk_chain_ligand_acceptor_disambiguation_audit.get(
        "metadata", {}
    )
    if not isinstance(chain_meta, dict):
        chain_meta = {}
    external_meta = epk_chain_ligand_external_hard_negative_feature_screen.get(
        "metadata", {}
    )
    if not isinstance(external_meta, dict):
        external_meta = {}
    terminal_meta = epk_protein_substrate_source_repair_terminal_decision.get(
        "metadata", {}
    )
    if not isinstance(terminal_meta, dict):
        terminal_meta = {}

    target_fingerprint_id = str(
        prereg_meta.get("target_fingerprint_id")
        or chain_meta.get("target_fingerprint_id")
        or terminal_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    expected_external_ids = set(
        imported_external_entry_ids
        or ["uniprot:P06744", "uniprot:P78549", "uniprot:Q3LXA3"]
    )
    feature_id = "active_gamma_ligand_analog_or_protein_substrate_acceptor_policy_v0"

    rows: list[dict[str, Any]] = []
    decision_counts: Counter[str] = Counter()
    positive_count = 0
    positive_hit_count = 0
    protein_substrate_positive_hit_count = 0
    ligand_analog_positive_hit_count = 0
    control_count = 0
    control_false_hit_count = 0

    for source_row in epk_chain_ligand_acceptor_disambiguation_audit.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        row_type = str(source_row.get("row_type") or "")
        source_hit = bool(source_row.get("candidate_feature_hit"))
        non_catalytic_chain_acceptor = bool(
            source_row.get("non_catalytic_chain_acceptor")
        )
        ligand_analog_acceptor = bool(source_row.get("ligand_analog_acceptor"))
        active_gamma_geometry = bool(
            source_row.get("nearest_gamma_to_candidate_acceptor_distance_angstrom")
            is not None
        )
        product_state_blocked = (
            str(source_row.get("gamma_geometry_scope") or "").lower()
            == "product_state"
        )
        homomeric_chain_choice_blocked = bool(
            source_row.get("homomeric_mapping_ambiguous")
        )
        policy_hit = bool(
            source_hit
            and active_gamma_geometry
            and not product_state_blocked
            and not homomeric_chain_choice_blocked
            and (non_catalytic_chain_acceptor or ligand_analog_acceptor)
        )
        if row_type == "current_epk_positive_prototype":
            positive_count += 1
            if policy_hit:
                positive_hit_count += 1
                if ligand_analog_acceptor:
                    ligand_analog_positive_hit_count += 1
                    decision = "policy_positive_ligand_analog_hit_review_only"
                else:
                    protein_substrate_positive_hit_count += 1
                    decision = "policy_positive_protein_substrate_hit_review_only"
            elif product_state_blocked:
                decision = "policy_positive_blocked_product_state_review_only"
            elif homomeric_chain_choice_blocked:
                decision = "policy_positive_blocked_homomeric_chain_choice_review_only"
            else:
                decision = "policy_positive_miss_review_only"
        elif row_type.endswith("negative_control"):
            control_count += 1
            if policy_hit:
                control_false_hit_count += 1
                decision = "policy_control_false_hit_blocks_activation"
            elif source_hit and not policy_hit:
                decision = "policy_control_blocked_by_exclusion_rule_review_only"
            else:
                decision = "policy_control_nonhit_review_only"
        else:
            continue

        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": row_type,
                "entry_id": source_row.get("entry_id"),
                "pdb_id": source_row.get("pdb_id"),
                "family_id": source_row.get("family_id"),
                "family_name": source_row.get("family_name"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "policy_variant_id": feature_id,
                "source_candidate_feature_id": source_row.get("candidate_feature_id"),
                "source_candidate_feature_hit": source_hit,
                "policy_feature_hit": policy_hit,
                "policy_reaudit_decision": decision,
                "non_catalytic_chain_acceptor": non_catalytic_chain_acceptor,
                "ligand_analog_acceptor": ligand_analog_acceptor,
                "active_gamma_geometry": active_gamma_geometry,
                "product_state_blocked": product_state_blocked,
                "homomeric_chain_choice_blocked": homomeric_chain_choice_blocked,
                "nearest_gamma_to_candidate_acceptor_distance_angstrom": (
                    source_row.get(
                        "nearest_gamma_to_candidate_acceptor_distance_angstrom"
                    )
                ),
                "source_feature_audit_decision": source_row.get(
                    "feature_audit_decision"
                ),
                "predictive_use_status": (
                    "review_only_policy_reaudit_not_production_score"
                ),
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "policy_not_frozen_before_candidate_selection",
                    "external_hard_negative_reaudit_not_real_scorer",
                    "threshold_not_calibrated_against_negative_controls",
                    "registry_and_label_factory_extension_not_implemented",
                ],
            }
        )

    external_rows_by_entry = {
        str(row.get("entry_id") or ""): row
        for row in epk_chain_ligand_external_hard_negative_feature_screen.get(
            "rows", []
        )
        or []
        if isinstance(row, dict) and row.get("entry_id")
    }
    external_abstention_count = 0
    external_non_abstention_count = 0
    external_missing_count = 0
    for entry_id in sorted(expected_external_ids, key=_entry_id_sort_key):
        source_row = external_rows_by_entry.get(entry_id, {})
        feature_hit = bool(source_row.get("review_only_feature_non_abstention"))
        if not source_row:
            external_missing_count += 1
            decision = "policy_external_hard_negative_missing_review_only"
        elif feature_hit:
            external_non_abstention_count += 1
            decision = "policy_external_hard_negative_feature_non_abstention"
        else:
            external_abstention_count += 1
            decision = "policy_external_hard_negative_feature_abstention"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "imported_external_hard_negative",
                "entry_id": entry_id,
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "text_free_inputs_only": bool(
                    source_row.get("text_free_inputs_only", True)
                ),
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "policy_variant_id": feature_id,
                "source_candidate_feature_id": source_row.get(
                    "candidate_feature_id"
                ),
                "source_candidate_feature_hit": bool(
                    source_row.get("candidate_feature_hit")
                ),
                "policy_feature_hit": feature_hit,
                "policy_reaudit_decision": decision,
                "review_only_feature_score": source_row.get(
                    "review_only_feature_score"
                ),
                "source_feature_screen_status": source_row.get(
                    "feature_screen_status"
                ),
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "clean_heldout_performance_claim_permitted": False,
                "remaining_blockers": [
                    "not_a_real_scored_external_reaudit",
                    "threshold_not_calibrated_against_negative_controls",
                    "policy_not_active",
                ],
            }
        )

    source_repair_blocked_count = 0
    source_repair_measurement_ready_count = 0
    for source_row in epk_protein_substrate_source_repair_terminal_decision.get(
        "rows", []
    ) or []:
        if not isinstance(source_row, dict):
            continue
        measurement_ready = bool(
            int(source_row.get("measurement_ready_candidate_count") or 0) > 0
        )
        if measurement_ready:
            source_repair_measurement_ready_count += 1
            decision = "policy_source_repair_measurement_ready_review_only"
        else:
            source_repair_blocked_count += 1
            decision = "policy_source_repair_blocked_by_exclusion_or_missing_geometry"
        decision_counts[decision] += 1
        rows.append(
            {
                "row_type": "protein_substrate_source_repair_candidate",
                "entry_id": source_row.get("entry_id"),
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "policy_variant_id": feature_id,
                "policy_feature_hit": False,
                "policy_reaudit_decision": decision,
                "source_repair_decision": source_row.get("decision"),
                "active_state_or_atp_metal_candidate_count": source_row.get(
                    "active_state_or_atp_metal_candidate_count"
                ),
                "mapped_or_context_acceptor_candidate_count": source_row.get(
                    "mapped_or_context_acceptor_candidate_count"
                ),
                "measurement_ready_candidate_count": source_row.get(
                    "measurement_ready_candidate_count"
                ),
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "source_repair_not_measurement_ready",
                    "policy_not_active",
                    "external_hard_negative_reaudit_not_real_scorer",
                ],
            }
        )

    positive_coverage_passed = positive_count > 0 and positive_hit_count == positive_count
    sibling_control_reaudit_passed = control_count > 0 and control_false_hit_count == 0
    external_feature_screen_passed = (
        external_missing_count == 0 and external_non_abstention_count == 0
    )
    external_scored_reaudit_passed = False
    freeze_policy_before_candidate_selection_passed = False
    activation_requirements = {
        "freeze_policy_before_candidate_selection": (
            freeze_policy_before_candidate_selection_passed
        ),
        "sibling_family_control_reaudit": sibling_control_reaudit_passed,
        "external_hard_negative_scored_reaudit": external_scored_reaudit_passed,
    }
    failed_activation_requirement_ids = [
        criterion_id
        for criterion_id, passed in activation_requirements.items()
        if not passed
    ]
    policy_activation_allowed = (
        positive_coverage_passed
        and sibling_control_reaudit_passed
        and external_scored_reaudit_passed
        and freeze_policy_before_candidate_selection_passed
    )

    rows.extend(
        {
            "row_type": "policy_activation_requirement",
            "criterion_id": criterion_id,
            "target_fingerprint_id": target_fingerprint_id,
            "review_only": True,
            "passed": passed,
            "production_use_allowed": False,
            "policy_variant_id": feature_id,
        }
        for criterion_id, passed in sorted(activation_requirements.items())
    )

    return {
        "metadata": {
            "method": "epk_analog_product_state_policy_control_reaudit",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_analog_product_state_policy_preregistration_method": (
                prereg_meta.get("method")
            ),
            "source_epk_chain_ligand_acceptor_disambiguation_audit_method": (
                chain_meta.get("method")
            ),
            "source_epk_chain_ligand_external_hard_negative_feature_screen_method": (
                external_meta.get("method")
            ),
            "source_epk_protein_substrate_source_repair_terminal_decision_method": (
                terminal_meta.get("method")
            ),
            "policy_variant_id": feature_id,
            "policy_status": "review_only_reaudit_not_activated",
            "policy_activation_allowed": policy_activation_allowed,
            "production_scoring_admissible": False,
            "current_positive_row_count": positive_count,
            "current_positive_policy_hit_count": positive_hit_count,
            "protein_substrate_positive_policy_hit_count": (
                protein_substrate_positive_hit_count
            ),
            "ligand_analog_positive_policy_hit_count": (
                ligand_analog_positive_hit_count
            ),
            "positive_coverage_passed_review_only": positive_coverage_passed,
            "sibling_control_row_count": control_count,
            "sibling_control_policy_false_hit_count": control_false_hit_count,
            "sibling_family_control_reaudit_passed": sibling_control_reaudit_passed,
            "external_hard_negative_feature_abstention_count": (
                external_abstention_count
            ),
            "external_hard_negative_feature_non_abstention_count": (
                external_non_abstention_count
            ),
            "missing_expected_external_hard_negative_count": external_missing_count,
            "external_hard_negative_feature_screen_passed": (
                external_feature_screen_passed
            ),
            "external_hard_negative_scored_reaudit_passed": (
                external_scored_reaudit_passed
            ),
            "external_hard_negative_reaudit_scored": False,
            "freeze_policy_before_candidate_selection_passed": (
                freeze_policy_before_candidate_selection_passed
            ),
            "activation_requirement_count": len(activation_requirements),
            "failed_activation_requirement_count": len(
                failed_activation_requirement_ids
            ),
            "failed_activation_requirement_ids": failed_activation_requirement_ids,
            "source_repair_blocked_candidate_count": source_repair_blocked_count,
            "source_repair_measurement_ready_candidate_count": (
                source_repair_measurement_ready_count
            ),
            "feature_audit_decision_counts": dict(sorted(decision_counts.items())),
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact re-audits a frozen review-only ePK analog/"
                "product-state policy variant. It may diagnose whether current "
                "controls survive the stricter rule surface, but it cannot "
                "activate ligand-analog evidence, score ePK, edit registries, "
                "import labels, or claim clean held-out performance."
            ),
            "next_actions": [
                "keep the analog/product-state policy inactive until it is frozen before candidate selection",
                "run a real scored external hard-negative re-audit before any policy activation",
                "treat current source-repair candidates as terminally blocked unless new evidence appears",
            ],
        },
        "rows": sorted(
            rows,
            key=lambda row: (
                str(row.get("row_type") or ""),
                _entry_id_sort_key(str(row.get("entry_id") or "")),
                str(row.get("criterion_id") or ""),
                str(row.get("family_id") or ""),
                str(row.get("pdb_id") or ""),
            ),
        ),
        "warnings": [
            (
                "The analog/product-state policy re-audit is diagnostic only; "
                "it is not an active production policy or ePK scorer."
            )
        ],
    }


def build_epk_review_only_external_hard_negative_score_probe(
    *,
    epk_review_only_scoring_prototype: dict[str, Any],
    epk_analog_product_state_policy_control_reaudit: dict[str, Any],
    imported_external_entry_ids: list[str] | None = None,
) -> dict[str, Any]:
    """Expose external hard-negative prototype scores without opening the gate."""

    prototype_meta = epk_review_only_scoring_prototype.get("metadata", {})
    if not isinstance(prototype_meta, dict):
        prototype_meta = {}
    policy_meta = epk_analog_product_state_policy_control_reaudit.get(
        "metadata", {}
    )
    if not isinstance(policy_meta, dict):
        policy_meta = {}
    target_fingerprint_id = str(
        prototype_meta.get("target_fingerprint_id")
        or policy_meta.get("target_fingerprint_id")
        or "epk_atp_gamma_phosphoryl_transfer"
    )
    expected_ids = imported_external_entry_ids or [
        "uniprot:P06744",
        "uniprot:P78549",
        "uniprot:Q3LXA3",
    ]

    prototype_by_entry: dict[str, dict[str, Any]] = {}
    for row in epk_review_only_scoring_prototype.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        if row.get("row_type") != "imported_external_hard_negative":
            continue
        entry_id = str(row.get("entry_id") or "")
        if entry_id:
            prototype_by_entry[entry_id] = row

    policy_by_entry: dict[str, dict[str, Any]] = {}
    for row in epk_analog_product_state_policy_control_reaudit.get("rows", []) or []:
        if not isinstance(row, dict):
            continue
        if row.get("row_type") != "imported_external_hard_negative":
            continue
        entry_id = str(row.get("entry_id") or "")
        if entry_id:
            policy_by_entry[entry_id] = row

    rows: list[dict[str, Any]] = []
    missing_entry_ids: list[str] = []
    non_abstention_entry_ids: list[str] = []
    score_positive_entry_ids: list[str] = []
    policy_feature_hit_entry_ids: list[str] = []
    for entry_id in expected_ids:
        prototype_row = prototype_by_entry.get(entry_id)
        policy_row = policy_by_entry.get(entry_id)
        if prototype_row is None or policy_row is None:
            missing_entry_ids.append(entry_id)
        score = float(
            (prototype_row or {}).get("review_only_prototype_score") or 0.0
        )
        policy_feature_hit = bool((policy_row or {}).get("policy_feature_hit"))
        non_abstention = score > 0.0 or policy_feature_hit
        if non_abstention:
            non_abstention_entry_ids.append(entry_id)
        if score > 0.0:
            score_positive_entry_ids.append(entry_id)
        if policy_feature_hit:
            policy_feature_hit_entry_ids.append(entry_id)
        source_axis_values = (prototype_row or {}).get("prototype_axis_values", {})
        if not isinstance(source_axis_values, dict):
            source_axis_values = {}
        rows.append(
            {
                "row_type": "imported_external_hard_negative_score_probe",
                "entry_id": entry_id,
                "target_fingerprint_id": target_fingerprint_id,
                "review_only": True,
                "countable_label_candidate": False,
                "ready_for_label_import": False,
                "review_only_probe_score": score,
                "review_only_score_probe_non_abstention": non_abstention,
                "source_prototype_decision": (prototype_row or {}).get(
                    "prototype_decision"
                ),
                "source_prototype_axis_values": dict(sorted(source_axis_values.items())),
                "source_policy_reaudit_decision": (policy_row or {}).get(
                    "policy_reaudit_decision"
                ),
                "source_policy_feature_hit": policy_feature_hit,
                "clean_heldout_performance_claim_permitted": False,
                "epk_score_computed": False,
                "external_hard_negative_reaudit_scored": False,
                "remaining_blockers": [
                    "review_only_probe_not_real_scored_reaudit",
                    "threshold_not_calibrated_against_negative_controls",
                    "policy_not_active",
                    "registry_and_label_factory_extension_not_implemented",
                ],
                "text_free_inputs_only": bool(
                    (prototype_row or {}).get("text_free_inputs_only", True)
                    and (policy_row or {}).get("text_free_inputs_only", True)
                ),
            }
        )

    probe_complete = len(missing_entry_ids) == 0
    probe_passed_review_only = probe_complete and not non_abstention_entry_ids
    return {
        "metadata": {
            "method": "epk_review_only_external_hard_negative_score_probe",
            "review_only": True,
            "target_family_id": "epk",
            "target_fingerprint_id": target_fingerprint_id,
            "source_epk_review_only_scoring_prototype_method": (
                prototype_meta.get("method")
            ),
            "source_epk_analog_product_state_policy_control_reaudit_method": (
                policy_meta.get("method")
            ),
            "expected_external_hard_negative_entry_ids": list(expected_ids),
            "external_hard_negative_score_probe_row_count": len(rows),
            "missing_expected_external_hard_negative_count": len(missing_entry_ids),
            "missing_expected_external_hard_negative_entry_ids": missing_entry_ids,
            "review_only_score_probe_complete": probe_complete,
            "review_only_score_probe_passed": probe_passed_review_only,
            "review_only_score_probe_non_abstention_count": (
                len(non_abstention_entry_ids)
            ),
            "review_only_score_probe_non_abstention_entry_ids": (
                non_abstention_entry_ids
            ),
            "review_only_score_positive_entry_ids": score_positive_entry_ids,
            "review_only_policy_feature_hit_entry_ids": (
                policy_feature_hit_entry_ids
            ),
            "external_hard_negative_reaudit_scored": False,
            "clean_heldout_performance_claim_permitted": False,
            "not_a_real_scored_reaudit": True,
            "policy_activation_allowed": False,
            "production_scoring_admissible": False,
            "threshold_calibrated": False,
            "selected_threshold_angstrom": None,
            "epk_score_computed": False,
            "ready_to_run_epk_scorer": False,
            "ready_to_expand_positive_fingerprint_universe": False,
            "ready_for_label_import": False,
            "fingerprint_registry_edited": False,
            "curated_label_registry_edited": False,
            "countable_label_candidate_count": 0,
            "review_only_rule": (
                "This artifact exposes the current ePK prototype scores for "
                "imported external hard negatives as a diagnostic probe only. "
                "It is not a calibrated ePK score, not a clean held-out "
                "performance claim, and not the scored re-audit required for "
                "policy activation."
            ),
            "next_actions": [
                "turn the review-only probe into a real scored re-audit only after ePK thresholds are calibrated",
                "keep the analog/product-state policy inactive until preselection freeze and scored controls pass",
                "preserve imported external hard negatives under their current out-of-scope label contract",
            ],
        },
        "rows": rows,
        "warnings": [
            (
                "External hard-negative score probe is diagnostic only and "
                "does not satisfy the scored re-audit activation gate."
            )
        ],
    }


def _epk_substrate_acceptor_hint_from_text(snippets: Any) -> dict[str, Any] | None:
    try:
        text = " ".join(str(snippet) for snippet in snippets)
    except TypeError:
        text = str(snippets or "")
    residue_code_by_token = {
        "ser": "SER",
        "serine": "SER",
        "thr": "THR",
        "threonine": "THR",
        "tyr": "TYR",
        "tyrosine": "TYR",
    }
    match = re.search(
        r"\b(serine|threonine|tyrosine|ser|thr|tyr)\s+(-?\d+)\b",
        text,
        flags=re.IGNORECASE,
    )
    if not match:
        return None
    token = match.group(1).lower()
    return {
        "residue_code": residue_code_by_token[token],
        "residue_token": match.group(1),
        "resid": match.group(2),
        "source": "mechanism_text_review_context",
    }


def _epk_substrate_acceptor_hint_chains(
    atoms: list[dict[str, Any]],
    substrate_acceptor_hint: dict[str, Any] | None,
    *,
    catalytic_chains: set[str],
) -> list[str]:
    if not substrate_acceptor_hint:
        return []
    residue_code = str(substrate_acceptor_hint.get("residue_code") or "").upper()
    resid = str(substrate_acceptor_hint.get("resid") or "")
    if not residue_code or not resid:
        return []
    chains: set[str] = set()
    for atom in atoms:
        if atom.get("group_PDB") != "ATOM":
            continue
        code = str(atom.get("auth_comp_id") or atom.get("label_comp_id") or "").upper()
        if code != residue_code:
            continue
        residue_ids = {
            str(value)
            for value in [atom.get("auth_seq_id"), atom.get("label_seq_id")]
            if value not in {None, "", ".", "?"}
        }
        if resid not in residue_ids:
            continue
        for chain in [
            atom.get("auth_asym_id"),
            atom.get("label_asym_id"),
        ]:
            if chain in {None, "", ".", "?"}:
                continue
            chain_text = str(chain)
            if chain_text not in catalytic_chains:
                chains.add(chain_text)
    return sorted(chains)


